window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26612471"]={"book":{"id":26612471,"title":"搞定I：无压工作的艺术(最新版)","author":"[美]戴维·艾伦","translator":"张静","publisher":"中信出版社","pubdate":"2015-9","isbn":"9787508654799","tags":["时间管理","GTD","个人管理","自我管理","方法论","自我成长","搞定I：无压工作的艺术(最新版)","管理"],"memCount":13},"np":1,"pb":[38],"idx":[{"i":20105,"t":"搞定Ⅰ_无压工作的艺术","l":"TF1-1","c":"wang哈哈","g":1,"p":1},{"i":18542,"t":"管理承诺三步法&自然计划法四个步骤","l":"TF2-4","c":"paul1216","g":1,"p":1},{"i":18255,"t":"管理承诺三步法&自然计划法四个步骤","l":"TF2-4","c":"paul1216","g":1,"p":1},{"i":18025,"t":"清空大脑","l":"TF3-1","c":"拆大侠","g":1,"p":1},{"i":17968,"t":"管理承诺三步法&自然计划法四个步骤","l":"TF2-4","c":"paul1216","g":1,"p":1},{"i":17452,"t":"释放大脑压力、有效规划下一步，让你轻松活在当下，稳步推进梦想","l":"TF2-4","c":"1405-吴先昇教练-庄宇亮","g":1,"p":1},{"i":17397,"t":"学习自然计划模式   ","l":"TF3-2","c":"宁静@微光","g":1,"p":1},{"i":17206,"t":"管理承诺的三个原则","l":"TF2-2","c":"深圳林歌","g":1,"p":1},{"i":16501,"t":"原则：有效地处理内心的承诺","l":"TF2-1","c":"文子飞飞","g":1,"p":1},{"i":15359,"t":"释放大脑压力、有效规划下一步，让你轻松活在当下，稳步推进梦想","l":"TF2-4","c":"1405-吴先昇教练-庄宇亮","g":1,"p":1},{"i":13591,"t":"规划具体行动四标准法","l":"TF1-2","c":"Amandadada","g":1,"p":1},{"i":13162,"t":"确定某一时记得具体行动的“四标准法”","l":"TF1-1","c":"蓓蕾绽放","g":1,"p":1},{"i":12908,"t":"如何选择下一步行动  让时间利用更高效？","l":"TF1-2","c":"青青2015","g":1,"p":1},{"i":12553,"t":"工作优先级排序","l":"TF1-2","c":"徐徐","g":1,"p":1},{"i":11990,"t":"如何更好的管理你的承诺？逃离忙碌且盲目的陷阱！","l":"TF2-2","c":"清风不二","g":1,"p":1},{"i":11433,"t":"如何清理工作篮","l":"TF2-2","c":"谭亭亭","g":1,"p":1},{"i":11325,"t":"时间管理","l":"TF1-1","c":"谭亭亭","g":1,"p":1},{"i":9638,"t":"龙卷风TF2-4过级","l":"TF2-4","c":"龙卷风","g":1,"p":1},{"i":8912,"t":"消除负面情绪 ","l":"TF2-1","c":"竹本1314","g":1,"p":1},{"i":8911,"t":"自我管理类——消除负面情绪","l":"TF1-2","c":"竹本1314","g":0,"p":1},{"i":8787,"t":"控制项目：纵向管理项目的5个阶段","l":"TF1-2","c":"竹本1314","g":1,"p":1},{"i":8786,"t":"自我管理类——掌控工作和生活","l":"TF1-1","c":"竹本1314","g":1,"p":1},{"i":8118,"t":"破解焦虑烦恼，用有效计划实现无压工作","l":"TF2-4","c":"littledl2019","g":0,"p":1},{"i":7877,"t":"用清单搞定身边事以及如何高效利用碎片时间","l":"TF2-3","c":"薛锦聪","g":1,"p":1},{"i":7866,"t":"用超前的规划代替超前的焦虑","l":"TF3-3","c":"徐雪艳","g":1,"p":1},{"i":7528,"t":"用清单记录和四标准法高效做事","l":"TF2-3","c":"薛锦聪","g":1,"p":1},{"i":6815,"t":"影响大脑成功收集有效信息的3个条件","l":"TF1-1","c":"机小灵z","g":1,"p":1},{"i":5519,"t":"如何正确决定下一步行动","l":"TF2-1","c":"餐盘上的桃乐丝","g":0,"p":1},{"i":4851,"t":"自然计划模式","l":"TF1-2","c":"熊熊2040","g":1,"p":1},{"i":4843,"t":"确定某一时刻的具体行动","l":"TF2-2","c":"涂乐","g":1,"p":1},{"i":4564,"t":"学会关注结果","l":"TF1-1","c":"邱小猫","g":1,"p":1},{"i":4042,"t":"掌控生活的横向管理工作流程","l":"TF1-1","c":"孙晶晶","g":1,"p":1},{"i":3773,"t":"《搞定1——无压力的工作艺术》","l":"TF3-3","c":"果粒","g":1,"p":1},{"i":3772,"t":"解除精神负担，高效工作","l":"TF3-3","c":"果粒","g":1,"p":1},{"i":1601,"t":"如何建立组织整理系统","l":"TF3-1","c":"郑先鹏","g":1,"p":1},{"i":1007,"t":"高效2分钟！","l":"TF2-1","c":"大唐","g":1,"p":1},{"i":644,"t":"确定某一时刻具体行动的“四标准法”","l":"TF2-1","c":"兰","g":1,"p":1},{"i":455,"t":"2分钟思考带来的平和","l":"TF1-1","c":"熊媛","g":1,"p":1}],"ms":[{"id":20105,"topic":"搞定Ⅰ_无压工作的艺术","learn_goal":"","remark":"轻松掌控知识工作的核心方法，是熟练掌握工作流程管理的5个阶段：（1）收集引起我们注意的事务和信息；​\n（2）理清每个项目的意义和相关措施；​\n（3）组织整理结果，提出选项；​\n（4）进行思考回顾；​\n（5）选择行动。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"wang哈哈","city":"哈尔滨市"},"club":{"name":"哈尔滨索菲亚分舵","city":"哈尔滨"},"prologue":"\u003cp>\u003cstrong>拆解书目\u003c/strong>：《搞定Ⅰ：无压工作的艺术》\u003cbr>\u003cstrong>拆解片段\u003c/strong>：横向管理工作流程的5个步骤\u003c/p>\u003ch2>【Step 1：发拆页】（约30秒）\u003c/h2>\u003cp>大家好，先把手里的拆页发给大家，人手一份。拿到之后可以瞄一眼，但先不用细读，我待会儿会给大家专门的阅读时间。\u003c/p>\u003cp>（发拆页）\u003c/p>\u003ch2>【Step 2：自我介绍】（约1分钟）\u003c/h2>\u003cp>大家好，我叫哈哈，今天很开心站在这里，和大家分享我在拆书帮训练营学到的内容。\u003c/p>\u003cp>先说说我的两个标签。\u003c/p>\u003cp>第一个：我特别爱读书。什么书都读，最近在读的是《搞定I》和《沧浪之水》。\u003c/p>\u003cp>第二个：我读了两个研究生，工科转管理。很多人问我：&quot;读了七年工科，又读管理，你在想什么？&quot;实话实说——我是一个闲不住的人，很多事是做着做着才想清楚的。关于&quot;工作之后提升学历&quot;或者&quot;在职研究生备考&quot;这类问题，我不敢说我有一套成熟的方法论，但我踩过的坑、纠结过的点，一定可以分享给大家。如果大家或身边朋友正在纠结这些问题，欢迎结束后找我聊。\u003c/p>\u003cp>好，这就是我。下面进入正题。\u003c/p>\u003ch2>【Step 3：讲解拆书和拆书帮】（约2分钟）\u003c/h2>\u003cp>正式进入主题之前，我简单介绍一下&quot;拆书&quot;和&quot;拆书帮&quot;。\u003c/p>\u003cp>“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。\u003c/p>\u003cp>拆书分两种形式：\u003c/p>\u003cp>1. 个人学习——叫RIA便签法。R（Reading）阅读原文、I（Interpretation）重述知识、A（Appropriation）拆为己用，A1激活经验、A2规划应用。\u003c/p>\u003cp>2. 组织学习——一位拆书家拿一本书的一个拆页，引导一群人把知识“拆为己用”。\u003c/p>\u003cp>拆书帮是公益性组织，使命很简单：帮助更多学习者成长为拆书家。\u003c/p>\u003cp>有人会问：&quot;拆书帮跟普通读书会有什么区别？&quot;\u003c/p>\u003cp>普通读书会是大家读同一本书，交流读后感。\u003c/p>\u003cp>拆书帮不一样。拆书是一种以学习者为中心的学习方法论，核心只有一句话：不对书负责，只对自己的问题负责。\u003c/p>\u003ch2>【Step 4：请大家阅读拆页】（约2分钟）\u003c/h2>\u003cp>好，现在请大家花2分钟阅读手里的拆页。\u003c/p>\u003cp>（等待约1.5-2分钟，观察阅读进度）\u003c/p>\u003ch2>【Step 5：表达三张便签】（约9分钟）\u003c/h2>\u003cp>好，我看大部分朋友读完了，我们直接开始。\u003c/p>\u003ch3>\u003c/h3>","ratings_count":1,"texts":[{"id":24555,"quote":"\u003cp>轻松掌控知识工作的核心方法，是熟练掌握工作流程管理的5个阶段，这5个阶段也是我们经验的总结和体现。我即将描述的这些阶段应该作为一个整体发挥作用，它们所产生结果的便利性和挑战性将出乎你的意料。​\u003cbr>（1）收集引起我们注意的事务和信息；​\u003cbr>（2）理清每个项目的意义和相关措施；​\u003cbr>（3）组织整理结果，提出选项；​\u003cbr>（4）进行思考回顾；​\u003cbr>（5）选择行动。\u003cbr>这些阶段共同构成了我们生活中的横向管理系统，而且我们还可以随时向其中添加需要考虑的新事项。\u003c/p>\u003cp>这些并非主观或纯粹理论性的建议，当我们想控制并稳定某些事情，令其发挥建设性作用时，大家都会这么做。如果你打算为朋友做顿饭，但到家时发现厨房一团糟，你会怎样处理？首先要确认摆放不到位的所有东西（收集）​；决定保留什么，扔掉什么（理清）​；把东西归位——放回冰箱、扔进垃圾箱，或放进水池（整理）​；然后核对你的食谱，以及已有的食材和厨具（回顾）​，然后把黄油放进锅里融化，开始做饭（行动）​。\u003c/p>\u003cp>这几个步骤的原理很简单。可能你没有察觉到，不过这确实就是我们习以为常的处理事情的方法。但是根据我的经验，大多数人在这5个阶段中，都还有很大的效率提升空间。我们对工作流程的管理包括了5个环节，并且管理的效果通常取决于这5个环节中最薄弱的一环。因此，除非所有环节都紧密结合，并按统一标准加以管理，否则，其最终效果将难以保证。\u003c/p>\u003cp>在生活和工作大背景下，大多数人都在管理工作的过程中效率严重低下，不过，在这个新世界带来的种种压力面前，这些不足之处正变得没那么突出。就在你阅读本书的时候，唾手可得的信息和不断发生的变化，使你的生活和工作变得更加复杂。只需打理杂乱的厨房，就能起到缓解作用！随着压力的增加，小疏漏会变成大问题。错过电子邮件、不履行承诺或是避免做决定都会扩大后果的影响力。由于相关待办事项数量不减，新任务的增加速度亦无放缓，如果不能掌握工作流程控制方法的话，无异于自讨苦吃。\u003c/p>\u003cp>大多数人在收集阶段存在着诸多纰漏。他们的大多数行动承诺只是想想罢了。人们的大脑会记录各种事务，包括必须做、应该做和想要做的事情，其数量之多超过了他们在其他任何地方所做的记录。\u003c/p>\u003cp>许多人收集了大量信息，但未能真正理清其中的内涵，也没能对于采取何种针对性行动（如果必要的话）做出决定。随处可见的随机清单，会议记录，以及贴在冰箱上、显示在电脑屏幕上或数字设备“任务”功能项下含糊的项目清单，实际上，这些清单上的待办事项并未付诸行动，并且会使人们变得麻木。这些清单本身制造的压力往往超过它们所能缓解的压力。\u003c/p>\u003cp>另一些人虽然及时做出了妥善的决定，但因未能有效组织整理相关成果，从而使其决定丧失了预想价值。他们确定应将某事告知老板，但这个决定只停留在他们的大脑深处，无法在适当的情形下以可靠的形式加以施展。\u003c/p>\u003cp>还有一些人虽然拥有良好的管理系统，但却未能持续回顾相关内容，以使其发挥作用。他们可能拥有各种有效的清单、计划和备忘录（通过收集、理清和组织生成）​，但未能及时对其进行更新或充分利用。许多人并不能持续跟进所要处理的重大事项，不能及时更新待办事项和截止日期，难免变成最后一分钟焦虑的受害人。\u003c/p>","explains":"\u003ch3>【I便签：重述知识】（约2.5分钟）\u003c/h3>\u003cp>\u003cstrong>What\u003c/strong>：这段原文的核心就一件事：处理复杂事务，可以拆成五个步骤——收集、理清、整理、回顾、行动。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>：我们做事效率低，往往不是因为能力不够，而是因为启动前没有规划——脑子里同时塞了多件事，注意力跳来跳去，每件事都在消耗能量，但没有一件事被真正推进。GTD就是让你把&quot;应该做什么&quot;从脑子里转移到纸上，大脑从&quot;存储模式&quot;切换到&quot;思考模式&quot;。\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>：原文给出了五个步骤的定义：\u003c/p>\u003cblockquote>\u003cstrong>第一步，收集\u003c/strong>：把一切引起我们注意的事务，全部收集起来，放进一个&quot;收集篮&quot;里。不判断、不分类、不排序——先全部倒出来。\u003cbr>\u003cstrong>第二步，理清\u003c/strong>：逐条判断每件事是什么、是否需要采取行动。如果可行动，下一步的具体动作是什么？\u003cbr>\u003cstrong>第三步，整理\u003c/strong>：这一步不是去干活，而是排布时间表。把每件事放到具体的时间段里，让冲突提前暴露出来。\u003cbr>\u003cstrong>第四步，回顾\u003c/strong>：定期审视清单，检查有没有遗漏、有没有不合理的地方。\u003cbr>\u003cstrong>第五步，行动\u003c/strong>：按排好的时间表执行。前面四步是&quot;想&quot;，这一步是&quot;干&quot;。\u003c/blockquote>\u003cp>原文有一句话特别戳我：&quot;管理的效果取决于5个环节中最薄弱的一环。&quot;——这5步只要有一环是短板，整个事情就很难做好。\u003c/p>\u003cp>我自己的教训是什么？我总是跳过理清和回顾，直接行动，干到一半才发现误判了时间，或者遗漏了重要事项，后面全乱套。\u003c/p>\u003cp>\u003cstrong>Where\u003c/strong>：这个方法适合需要&quot;收心&quot;的场景：工作规划、日程安排、复习备考。不适合&quot;干中学&quot;和&quot;放神&quot;的场景：比如学游泳，规划再多不下水也学不会；比如文艺创作，硬套步骤反而破坏灵感。\u003c/p>","interaction":"\u003ch3>【A1便签：关联经验】（约3.5分钟）\u003c/h3>\u003cp>好，下面分享一个我自己的故事。\u003c/p>\u003cp>半个月前，我负责组织一次导师团建。但我是全场唯一一个迟到的，迟到了10分钟。导师看了我一眼，那一瞬间我真的很难受。\u003c/p>\u003cp>为什么迟到？不是偷懒——恰恰相反，是把自己安排得太满了。前一天没休息好。第二天从早到晚排满了课、活动、健身，还想着抽空收拾宿舍——换床品、清杂物……一直收拾到该出发了，才发现来不及了。最后匆忙出门，还是迟到了。\u003c/p>\u003cp>我回头用GTD五步骤复盘，发现每一步都在踩坑：\u003c/p>\u003cp>\u003cstrong>第一个问题：第一步&quot;收集&quot;没做好。\u003c/strong> 我脑子里同时塞了好几件事，但没有写下来，更没有把&quot;收拾宿舍&quot;这个耗时的大工程考虑进去。我以为&quot;半小时就够了&quot;，实际上至少2个小时。导致后面的行程全被打乱。\u003c/p>\u003cp>\u003cstrong>第二个问题：第二步&quot;理清&quot;过于简略。\u003c/strong> 我没问自己：收拾宿舍具体要做什么？需要多久？真的必须今天做吗？如果当时我理清了，就会发现这不是&quot;顺手小事&quot;，而是一个项目。但因为没理清，我直接一头扎进去了。\u003c/p>\u003cp>\u003cstrong>第三个问题：后四步同时进行，导致混乱。\u003c/strong> 原文教我们：先想清楚、再排时间表、再检查、再行动。可我掺和在一起了——抓起衣服想&quot;放哪？&quot;就放下，看到书想&quot;留不留？&quot;就往垃圾桶走——越收拾越乱，越乱越焦虑。等我终于收拾出个样子，距离出发只剩10分钟。\u003c/p>\u003cp>如果当时我按GTD五步骤处理，可能会在&quot;收集&quot;时发现时间不够，在&quot;理清&quot;时决定放弃收拾，或者在&quot;整理&quot;时决定&quot;今天只清掉看过的书籍&quot;，然后从容出门。但我什么都没做，凭着直觉往前冲。\u003c/p>\u003cp>这件事让我意识到：我不是懒，是&quot;急于行动&quot;——因为思考比行动累，所以我选择直接干，然后在混乱中后悔。\u003c/p>\u003ch3>【A2便签：规划应用】（约2.5分钟）\u003c/h3>\u003cp>好，故事讲完了。接下来是我给自己定的行动方案。\u003c/p>\u003cp>\u003cstrong>目标\u003c/strong>：本周末所有有时限的活动——包括拆书过级、健身、练字、读书、朋友见面——全部做到提前到达，不迟到哪怕1分钟。如果接下来的两个月全部按时到达，我就奖励自己去三亚玩！如果有1次迟到，就给迟到现场的小伙伴买星巴克。\u003c/p>\u003cp>\u003cstrong>行动方案\u003c/strong>（按GTD五步骤执行）：\u003c/p>\u003cp>\u003cstrong>第一步，收集\u003c/strong>：今天中午12点10分前，把所有周末事项写在纸上——不判断、不分类，先全部倒出来。\u003c/p>\u003cp>\u003cstrong>第二步，理清\u003c/strong>：12点20分前，逐项写出每件事的出门时间和准备时间。比如聚餐：提前半小时出门加一小时准备，一个半小时前就得开始动。同时问自己：这件事真的必须今天做吗？如果不是，移出清单。\u003c/p>\u003cp>\u003cstrong>第三步，整理\u003c/strong>：12点半前，把安排写进日历，设提前15分钟和提前5分钟两个闹钟。把要带的物品放到第二天出门背的包里。\u003c/p>\u003cp>完成前三步，我就有了一张&quot;周六作战地图&quot;——什么时间做什么、提前多久准备、冲突点在哪，一目了然。\u003c/p>\u003cp>\u003cstrong>第四步，回顾\u003c/strong>：每晚睡前，检查第二天第一件事的准备情况——衣服备好了吗？文件带了吗？\u003c/p>\u003cp>\u003cstrong>第五步，行动\u003c/strong>：第二天按计划执行。如果还是迟到了，24小时内复盘——哪个环节预估失误了？修正后续安排。\u003c/p>\u003cp>\u003cstrong>B计划\u003c/strong>：遇到不可控突发情况——第一时间告知对方，真诚道歉，承担后果，不找借口。\u003c/p>\u003ch3>【结尾】（约30秒）\u003c/h3>\u003cp>好，今天分享的是GTD五步骤——收集、理清、整理、回顾、行动。\u003c/p>\u003cp>它不是高深的理论，就是在行动之前，先花10分钟想清楚。\u003c/p>\u003cp>希望今天这个片段对大家有启发。谢谢大家！\u003c/p>\u003cp>（鞠躬，结束）\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1788774578000,"updated_at":1789042988000,"ria":true},{"id":18542,"topic":"管理承诺三步法&自然计划法四个步骤","learn_goal":"","remark":"当你被大量事务缠身的时候，是不是感到事情太多做不完，无法专心做好手上重要的事情;领导委任你去做一个重要项目，由于缺乏经验，搞的自己身心俱疲，每天加班，仍然没有进展;如果你也遇到这样的问题，那快来跟我学习管理承诺三步法，清空大脑，减轻焦虑;学会运用自然计划法的四个步骤，制订具体的项目计划，轻松掌控项目进展。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"paul1216","city":""},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>【个人介绍】\u003c/p>\u003cp>大家好，我叫陈舜尧，我有三个标签，第一个标签我是一名资深软件工程师，从事安卓手机软件研发有12年了，具有丰富的软件研发经验；第二个标签我是易效能时间管理践行者，从2021年开始学习GTD时间管理知识，在工作和生活中一直践行高能要事的法则。第三个标签我是一名终身学习者，每年至少会阅读15本书，目前在学习AI写作，AI提示词相关的技能。有对这方面感兴趣的同学欢迎和我链接。\u003c/p>\u003cp>【总学习目标】\u003c/p>\u003cp>欢迎大家来到我的小课堂，今天我要拆解的书籍是《搞定I：无压工作的艺术》，希望大家通过今天的学习，可以学会运用两个方法。一个是你正在专心学习，突然脑中想到一件事或有人找你处理另外一件事的时候，你能运用管理承诺的3个步骤，将事情记录下来，提醒自己稍后再去处理。另一个是你能运用自然计划法的4个步骤，在后面的现场演练中，为生活中的一件复杂的事情制订一份具体的行动计划。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>为了帮助大家更好地掌握，吸收今天的学习内容，我设置了分组讨论和演练环节。现在我先给大家分一下组，按照就近、方便讨论的原则，左边的两位同学一组，中间的两位同学一组，可以吗？\u003c/p>\u003cp> 【FAB法介绍图书】\u003c/p>\u003cp>F特征： 本书是一本提高工作效率的书，作者是戴维.艾伦，是一位享誉全球的时间管理大师，该书提供了一整套系统化的方法来帮助大家提高工作效率，减少工作压力，系统讲解了GTD（Getting Things Done）的时间管理方法，帮助全球千万读者掌握它搞定个人事务和工作，书中内容都是作者20多年在时间管理实战方面的宝贵经验提炼。\u003c/p>\u003cp>A优势： 这本书已在33个国家出版，风靡全球十余年，与其他同类书籍相比，书中介绍的GTD法则更加系统全面，已成为全球千万读者用来轻松高效完成工作与个人事务的优秀工具，方法实用，简单易行，提供的案例生动、真实，给人很好的启发。\u003c/p>\u003cp>B1利益： 读完这本书，你将能够学会如何清空大脑，将所有任务和想法都记录下来，掌握如何有效地组织和管理任务列表，确保每项任务都能得到适当的关注和完成。\u003c/p>\u003cp>B2：通过学习第一个拆页管理承诺三步法 ，可以帮助大家在日常工作中专注做自己想做的事情，排除干扰，减轻焦虑。学习第二个拆页自然计划法四个步骤，教你如何在错综复杂的环境中理清思路，制订行动计划，助你轻松应对项目或复杂的事情。\u003c/p>\u003cp>这两个拆页，第一个方法是当你被大量事务缠身的时候，将大脑中的想法记录下来，保存到一个笔记本或手机备忘录里，在某个时间提醒自己去行动，帮你减轻做事的焦虑；当你要做一件需要多个步骤才能完成的事情的时候，可以采用第二个方法，通过制订具体的行动计划，来提高做事的效率，减轻你的压力（两个方法是由面到点，是递进的关系）。\u003c/p>\u003cp>下面，我们正式进入学习环节。请大家阅读拆页1\u003c/p>\u003cp>【设定拆页1的学习目标】\u003c/p>\u003cp>学完这个拆页，大家能够说出管理承诺三步法，并使用该方法将想要做的一件事情记录下来，再通过日历，便签或闹钟提醒自己在某个时间去做。给大家1分钟的时间，看完后抬头示意我一下，谢谢。\u003c/p>","ratings_count":1,"texts":[{"id":22852,"quote":"\u003cp>\u003cstrong>拆页一《搞定I：无压工作的艺术》页码（P22-23）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>为什么有些事情总是萦绕在你的心头\u003c/strong>\u003c/p>\u003cp>在通常情况下，你对一些事情总是念念不忘，这是因为你希望它们的状况能有所改善，另外：\u003c/p>\u003cp>\u003cstrong>·你还没有明确地认定它们的预期结果是什么。\u003c/strong>\u003c/p>\u003cp>\u003cstrong> ·你还没有确定你下一步的具体行动到底是什么。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>·你还没有把关于预期结果和即将采取行动的提示信息存入你所依赖的系统中去。\u003c/strong>\u003c/p>\u003cp>这就是为什么你忘不掉这些事情的原因了。直到你澄清了所有问题，做出一切必要的决定，并把预期结果保存到那个系统中去（同时要确保你能在必要情况下随时访问和查询这个系统），你的大脑才会放松下来。你可以骗过别人，但是你却无法愚弄自己的大脑。它能够明察秋毫：你是否已经做出了必要的决定，是否已经把有关预期结果和行动的提示信息寄存于一个安全可靠的地方，以便这些信息能在恰当的时候提醒你采取行动。如果你没有做好这些工作，那么，你的大脑就一分钟也不会停止运转。通常情况下，当你对某件事还没有依照上述的处理方法处理时，你的某根神经仍然会持续不断地对你施加压力，这只会增加你的精神负担。\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>好，我看大家都看完拆页了，还是由我先来和大家分享。\u003c/p>\u003cp>（What）管理承诺是一种高效处理事情的方法，教大家学会记录大脑中的所有想法，排除干扰，专注做好当下重要的事情。\u003c/p>\u003cp>(Why，不这么做的坏处）\u003c/p>\u003cp>（一般做法）一个人的注意力通常就是30～45分钟，当你在专注做一件事的时候，突然脑子想到另外一件重要的事情或者被外部打断，你就很容易分心或走神，可能会停止做手上的事情，立马就去做其他事情去了。\u003c/p>\u003cp>（坏处）往往这些干扰的因素，不是特别重要紧急的事，却一直留在大脑里，让你做事无法专注，你就会很容易忽略手上更重要的事情要完成，一旦事情多了后，就容易产生焦虑。\u003c/p>\u003cp>（反例）给大家举个我自己的例子，已经放暑假了，老婆想带孩子出去旅游几天，跟我说要带孩子去看海，问我什么时候有时间一起去沿海城市玩几天，我跟她说最近工作有点忙，等到月底不忙了再安排。这段时间我就会一直想着这件事，偶尔也会心生焦虑。\u003c/p>\u003cp>【How细化行动步骤】\u003c/p>\u003cp>作者只告诉了我们事情萦绕在心头的原因，如何管理承诺，并没有给出具体步骤，我根据片段内容，梳理了以下3个步骤：\u003c/p>\u003cp>1.明确预期结果。你希望得到的理想结果是什么？怎样才算是完成了呢，将你想要的结果写在一张纸上，或者手机备忘录里。例如发朋友圈文案获得13个赞。\u003c/p>\u003cp>2.确定下一步行动。为了推进事情的进展，你需要采取下一步具体行动。例如写一篇50字的文案。\u003c/p>\u003cp>3.存放行动清单。首先记录，人的大脑是CPU，不是硬盘，将要采取的行动写在一张便签上，或者保存到手机备忘录里；其次提示，把便签放在一个固定的位置，提示自己去行动，最好定个闹钟提醒自己在某个时间去做。例如定个晚上8点的闹钟，将写好的文案发到朋友圈。\u003c/p>\u003cp>（正例）回到刚才想和家人出去旅游的场景，我会这样运用管理承诺三步法，明确预期的结果是带家人去海边看日出，下一步行动是在周五的下午跟领导请2天假，存放行动清单，我会在手机日历上设置个周五下午5点的闹钟，提醒自己跟领导请假。通过这三步，我就不会一直想着这件事，让我专心做好眼前的事情。\u003c/p>\u003cp>（Where）在我们的工作和生活中，如果你正在专注做一件事，大脑突然想到其他事情要做，或者你的同事或家人有事找你，需要你帮忙处理下，可以使用这个方法。但需要注意，我们要根据当时的情况具体地分析，如果事情特别复杂，需要很多个步骤才能完成，或者事情特别简单，可以在2分钟以内解决的，就不能采用此方法。这一点，大家清楚了吗？\u003c/p>","interaction":"\u003cp>【A1激活经验】\u003c/p>\u003cp>想不想现场练习一下这个方法呢？请大家回想一下，过去你的生活和工作中，有没有遇到过你正在做一件重要的事情，突然有人找你有事，你不假思索地答应了对方。或者突然脑子里想到另外一件没有完成的事情，就去做其他事情去了。请大家在小组内分享一下事件发生的经过，只需要分享你遇到了一件什么事情，当时是怎么处理的。这里有个例子给大家：在什么时间，在哪个地方，我正在做什么事情，突然想到某某事还未完成，或者有个人找我帮忙做其他事情。\u003c/p>\u003cp>给大家每人1分钟的时间，2分钟以后，我会请一位小伙伴和大家分享他的经历。\u003c/p>\u003cp>回应：好，大家分享得很热烈。现在，请一个小伙伴来分享一下她刚才想到的经历。大家鼓掌，请mok同学来分享一下。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>这个月开始接到一个项目，要出一个文档和相关海报的宣传，我其实是没有什么经验，于是把所有相关的资料都查了一遍，然后写了个文案，是个半成品，又有点不清楚，不知道这件事的意义，亮点和价值到底应该怎么描述会比较好，但是同时我也熬了一整个晚上，到早上5:30才做完了10份，就是宣传的海报，我觉得还可以，但交过去了之后反馈不是很好，然后和同事沟通完了之后就说做的还不错，我就不知道到底我的结果要做成什么样子，然后下一步再怎么样去调整，就这个事情一直放着，但是我也在做运营的动作，所以我就很惆怅，反正感到有压力。\u003c/p>\u003cp>【拆书家回应】\u003c/p>\u003cp>感谢mok同学的分享\u003c/p>\u003cp>【A1+】反思加工\u003c/p>\u003cp>那如果用到今天我们学的管理承诺的三个步骤，再回到刚才大家提到的场景中，我们怎么可以更好地处理呢？大家可以试着把方法运用一遍，对比感受一下这个方法的好处。给大家2分钟时间，把结合管理承诺三个步骤以后的做法写下来。然后我会请一位小伙伴分享她是怎么做的。\u003c/p>\u003cp>回应：好，我们现在再请仁丹来分享一下，针对刚才的经历，她反思后的做法。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>第一步明确预期结果，我跟我的家庭成员之间，关于孩子要上学或者在他幼儿园阶段希望达成什么样的目标，我们把这块明确下来，选一个最核心的点，最后我们达成一致，相对教育质量差不多的情况下，选择稍近的学校。第二步确定下一步行动，我们就在家附近，把几个幼儿园都走访了一遍，我们去看一看，在近的情况下，做一个环境的对比，然后我们就开始去跑学校了。第三步存放行动清单，给自己定了一个时间，大概每周能去一到两家，加了学校老师的微信，会定期提醒我们什么时间去，最后的话大概是七八月份的时候把这个事情就定下来了。\u003c/p>\u003cp>【拆书家回应】\u003c/p>\u003cp>好，非常感谢仁丹同学的分享。\u003c/p>\u003cp>（拆页过渡）刚才我们学习的是，当你想要做一件简单的事情，用管理承诺三个步骤，将事情记录下来，并设置了提醒，清空了大脑，减轻了焦虑。假设，你要做一件需要多个步骤才能完成的复杂的事情，只知道截止日期是在1个月后，你是不是感到有点压力山大？那这时候，我们怎样应对比较好呢？拆页2就给大家提供了方法。\u003c/p>\u003cp>【设定拆页2的学习目标】\u003c/p>\u003cp>希望大家学完拆页2，当你做一件需要多个步骤才能完成的复杂事情之前，能熟练运用自然计划法的4个步骤，理清思路，制定一个具体的行动计划。在后面的现场演练中，通过运用自然计划法的4个步骤，为一件生活中的事情制订一个行动计划。给大家2分钟的时间阅读第2个拆页。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":22853,"quote":"\u003cp>\u003cstrong>拆页二 R原文片段：P84-86\u003c/strong>\u003c/p>\u003cp>你上一次出去吃饭时，最初的动机是什么？原因可能有很多： 因为饥肠辘辘，或是朋友之间的社交活动，为了庆祝某一个特殊的日子，签订一笔生意的合同，又或是为了谈情说爱。只要是出于上述的某一个原因，你就可以马上开始进行计划了。你的意愿就是你的目标， 它自然而然地启动了你内心深处的计划过程。同时，你的原则规定了你所做计划的界限。可能你自己并未意识到外出就餐原则的存在，但是你的思维却从来没有逾越这些原则：食物和服务的标准、支付能力、方便程度以及舒适度。无论如何，在制订计划时，你的目标就是你的动机，而原则又限定了你的计划。 \u003c/p>\u003cp>一旦做出决定要实现这一目标，那么首先进入你脑海的实质性问题是什么呢？恐怕不是“计划、第二部分、第1点、第3小点”吧。你的第一批想法很可能是这样的事情，如“在餐厅吃意大利风味的晚餐”，或者“在比斯特罗咖啡馆街边的桌旁坐一坐”。 你很可能还会想象出晚餐时的一些美好体验，或者设想一下晚餐的结局，也许你还想到了共同吃饭的人、就餐气氛什么的，这就是你的结果展望。当外出就餐的原因成为你的目标时，对晚餐进行的种种想象就是你的展望。 \u003c/p>\u003cp>一旦认同了这种展望，你的大脑便会自然而然地开始想一些问题：我们应该几点出发？这家餐馆今天晚上营业吗？人会不会很多？天气怎么样？是不是应该换身衣服？汽油还够吗？现在饿不饿？这就是头脑风暴。一旦承诺要达到某一目标，那么在达到之前，你就会身不由己地向自己接二连三地发问。这些问题是这个创造性过程的一个组成部分。\u003c/p>\u003cp>一旦头脑里装满了大量的想法和细节，你也就不由自主地开始了组织整理的工作。你可能会这样想，“首先，我们需要弄清楚那家餐厅是否营业”，或者“我们给安德森一家打个电话，看看他们是否愿意同我们一起出去吃晚饭”。一旦你对相关的结果产生了各式各样的想法，大脑就将自动根据事情的组成要素、重要程度和事件发展的先后顺序，分门别类地进行归纳整理。组成要素是指“我们要考虑出行、人员和地点方面的事宜”，重要程度是指“搞清楚大家是否愿意外出就餐是非常关键的”，先后顺序是指“首先，我们需要确认那家餐厅是否营业，然后给安德森一家打电话，接着更衣准备外出”。\u003c/p>\u003cp>最后（假如你决定要进行这个项目——以出去吃晚饭为例），为了确认首要的因素，你需要把注意力放在具体的下一步行动上。“给巴黎红咖啡馆打个电话，问问那里是否开门，然后预订一下座位。”\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>好，我看大家都看完拆页了，还是由我先来和大家分享。\u003c/p>\u003cp>（What）刚才片段中所运用的方法，是一种制订计划的思考方式 ，可以帮助我们理清事情的要素，以及要素之间的相互关联和重要程度，进而明确下一步具体行动。\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp>你上一次准备面试时，最初的动机是什么？原因可能有很多：因为对现有工作不满意，或是想要更高的薪资待遇，或者为了尝试一个新的发展方向，寻找更好的发展平台，又或是想换一个离家更近的工作地点。只要是出于上述的某一个原因，你就会着手准备了。[目标]你的意愿就是你的目标，它自然而然地启动了你内心深处的准备过程。同时，你的原则规定了你求职的界限。可能你自己并未意识到求职原则的存在，但是你的思维却从来没有逾越这些原则：薪资水平、通勤距离、工作强度以及发展空间[原则]。一旦做出决定要参加面试，首先进入你脑海的实质性问题是什么呢？恐怕不是&quot;简历、自我介绍、答题技巧&quot;这些具体条件。你的第一个想法很可能是这样的画面，如&quot;坐在宽敞明亮的办公室里工作&quot;，或者&quot;和新同事愉快地交流&quot;。[期望的结果]你很可能还会想象入职后的美好生活，或者设想一下职业发展前景，这就是你展望的结果。\u003c/p>\u003cp>一旦想到了这种结果，你的大脑便会自然而然地开始思考一些问题：这家公司的背景如何？面试官会问些什么？我的优势在哪里？要不要准备一份作品集？着装要怎么搭配？这就是头脑风暴。这些问题会不断涌现，推动你去寻找答案。[思考整理]接着，你会开始组织这些想法：要准备一份合适的简历，了解下公司的信息，看下常见的面试问题。你的大脑会自动按照重要程度和先后顺序来安排：了解公司业务是关键，准备得体的着装很重要，提前熟悉路线必不可少。最后，[下一步行动]你会把注意力集中在具体的下一步行动上：&quot;先修改简历，突出相关的工作经验，然后在网上搜索这家公司的招聘信息。&quot;\u003c/p>\u003cp>(过渡语)大家是否注意到了，在计划准备面试的过程中，经过了哪几个步骤呢？是不是自然就想到了目标，原则，期望的结果，思考整理要做的事情，下一步行动。\u003c/p>\u003cp>(Why，不这么做的坏处）\u003c/p>\u003cp>（一般做法）一般人要做一件需要多个步骤才能完成的复杂事情的时候，会按部就班地想到哪就做哪，把容易做的先完成，再期望想个好点子来完成剩余的事情。\u003c/p>\u003cp>（坏处）这样做，往往会让我们忙于处理各种各样的问题，容易造成混乱不清、压力平添的局面。当你陷入最后1小时紧急状态时，就会使自己手忙脚乱，出错的概率就会更大。\u003c/p>\u003cp>（反例）给大家举个我自己的例子，有一次我被公司委派为一个新项目的负责人，要在三个月交付一个重要的软件项目，由于没有明确的计划，我只是简单地分配了任务给团队成员，没有定期检查进度。结果，在项目截止日期临近时，我发现许多关键功能还存在问题，赶紧要求开发人员加班加点地修改Bug，最终导致项目延期。事后经过复盘，我发现缺少一个详细的项目计划，一次偶然的机会看到了这个片段，学习了自然计划法。\u003c/p>\u003cp>(How)\u003c/p>\u003cp>制订一个好的项目计划，只需要下面4个步骤：\u003c/p>\u003cp>1.定义目标和原则。明确你的目标是什么，以及你遵循的原则，这将是你计划的出发点和归宿。例如我的目标是在七月底举办一场隆重的同学聚会，原则是在武汉市，预算不超过1W元。\u003c/p>\u003cp>2.展望结果。想象任务完成后的理想状态，这有助于激发你的动力和创造力。例如来自五湖四海的同学们都聚在一起交流学习的经验和收获，在欢声笑语中度过了愉快的上午。\u003c/p>\u003cp>3.思考整理。首先，集思广益，和团队成员一起发散思考，收集所有可能的行动方案。也可以和其他人头脑风暴，尽可能多地列出行动点；其次，对想出来的行动点进行分类和排序，形成一个清晰的行动清单。比如先调查下哪些场地适合聚会，有哪些外地的同学，需要准备什么礼物，再对活动事项进行优先级排序等。\u003c/p>\u003cp>4.明确下一步的行动。从整理后的行动清单中，确定下一步具体要执行的行动。例如打电话通知所有同学，确定有哪些同学可以到场等。\u003c/p>\u003cp>（反例变正例）回到刚才我那次项目管理失败的场景，如何运用自然计划法来制订项目计划呢？首先，我会明确项目成功交付的目标，并确立团队协作和沟通的原则。其次，我会想象项目按时交付后，客户满意和团队庆祝的场景；再次，我会收集团队成员的想法，并组织他们进行头脑风暴，列出所有可能的开发任务和风险点，将任务进行分类，明确每个任务的负责人，开始和结束时间；最后，我会确定每个任务负责人的下一步行动。通过这四个步骤，一个清晰的项目计划跃然纸上，极大地减轻了我们的焦虑。\u003c/p>\u003cp>（Where）这个方法适合于制订项目开发计划，或需要多个步骤才能完成的复杂事情的行动计划。不适合简单的或短时间就可以完成的事情。\u003c/p>\u003cp>（预防异议）可能有人会有这样的疑问，是不是所有的事情都要按照这几个步骤来做，是不是太复杂了？我的建议是过程要按这个操作，至于详细程度，根据事情的不同来进行调整和取舍。标准就是能够让我们的大脑保持轻松的状态，基本上就足够了，能够缓解我们的压力就可以了。\u003c/p>","interaction":"\u003cp>【A3促动参与】\u003c/p>\u003cp>学完了自然计划法的4个步骤，现在请大家在我设定的场景里进行一次现场演练，假设我们现在处于这样的场景：\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>马上要过春节了，小王的老婆想带孩子去海滨城市玩几天，问小王计划什么时候可以出去，然而最近工作有点忙，由于整天忙于项目就忽略了这件事。偶然有一次，看到同事老李的朋友圈晒旅游照片，觉得老李是一个很会计划的人，于是他私下请教老李，问老李如何制订家庭旅游计划。\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>现在请每两人一组，进行演练。一人扮演老李，一个扮演小王。为了能把今天学习的4个步骤做一个完整的练习，请扮演老李的同学务必给小王完整地使用4个步骤的机会。演练时间为7～10分钟。稍后，我会请其中一组来到前面为大家现场演绎。\u003c/p>\u003cp>【角色扮演】\u003c/p>\u003cp>好，我看到大家都演练完了，我们现在请mok和小丁上来给大家演绎下。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>小王：你好，我看你很会做旅行规划，我们全家准备去三亚玩一周，预算是2万，你觉得我们应该怎么去做这个旅行计划呢？\u003c/p>\u003cp>老李：我上个星期刚刚去了三亚，你看到我拍的照片吗？你期望的结果是什么呢？\u003c/p>\u003cp>小王：我们去的话就主要是看日出，然后拍照，那我们该怎样去操作呢？\u003c/p>\u003cp>老李：建议你和家人先商量下，想要去游玩那些景点，根据景点预定附近的酒店，再排一个优先级，你们打算什么时间出去，可以提前把酒店和机票订一下。\u003c/p>\u003cp>小王：我们计划下一周就去，首先去订机票，然后马上找个人帮我们做一个行程规划，再根据他的规划把住宿订下来，最后我们就订下来要去哪些热门景点，，准备一份美食清单，看下附近的夜市。回到家里后，还要和家人商量下，做一个行动清单。\u003c/p>\u003cp>老李：建议先规划行程，再预定景点附近的酒店，打车或者租车都可以，根据你们自身的情况进行安排，最后记得带上这个物品，了解下行前须知。那你下一步行动是做什么呢？\u003c/p>\u003cp>小王：那我下一步行动就是把机票订一下，然后回去按照这个顺序再准备下，非常感谢。\u003c/p>\u003cp>【拆书家回应】\u003c/p>\u003cp>感谢两位的精彩演绎，生动形象。\u003c/p>\u003cp>（环节过渡）\u003c/p>\u003cp>刚刚我们完成了一次现场演练，现在请大家把关注点放到自己身上，规划一下未来我们要怎么去运用今天学到的自然计划法的四个步骤。\u003c/p>\u003cp>【A2分步催化应用之经验激活】\u003c/p>\u003cp>请大家思考一下，未来一个月或半年内，在工作和生活中，要做一件什么复杂的事情呢？可能是领导安排的一个项目，需要跨部门协作，和其他组员一起合作完成；可能是要给家里装修房子，和家人一起协商完成；请想一想，给大家3分钟的时间在小组内分享，只需要分享可能遇到的情景，不需要说具体怎么做。\u003c/p>\u003cp>回应：请mok来分享一下自己的未来一个月或半年内想要做的一个项目或一件复杂的事情。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>在未来一个学期内，要陪孩子一起提升课业成绩。三年级上学期我基本上是丢担子，没有管他，就想看看在不管的情况下，他还能完成到什么程度。果然不出所望就是不行啊，为什么要这么做呢？不是证明我的价值感，是因为让爸爸要参与进来，如果全部我来做的话，他会觉得我做的都是应该的，有爸爸的参与跟陪伴很重要。\u003c/p>\u003cp>【拆书家回应】\u003c/p>\u003cp>谢谢mok的分享。\u003c/p>\u003cp>【A2分步催化应用之催化应用】\u003c/p>\u003cp>刚才每个人都说出自己将来可能遇到的情景，现在请你想象一下，在这样的场景中，你会如何应用今天学习的自然计划法的四个步骤呢？请大家把自己要做的步骤都写下来，写完后可以在小组内分享，这样可以帮助大家提前预演一下。给到大家3分钟时间，结束之后请一位小伙伴给大家分享。\u003c/p>\u003cp>回应：好，我看大家都很认真在写便签，差不多都已经写完了，现在我们再请mok来分享一下。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>目标和原则就是和爱人一起陪孩子提升课业成绩；展望结果是在规定时间内完成作业，因为他现在告诉我们的是作业都在学校里做完了，然后我们是没有检查的，其实有很多作业都没有完成；思考整理，先和爱人聊一聊，每个人带孩子的方式是不一样的，如果是我带的话，肯定是最基本的语数外放在前面的，写字和阅读放在后面的。作为我来说，一直重视阅读，但是我老公并不认为是这样子，所以会有冲突，那先要把做的事情做完吧，保证最基本的，其他的东西再顺其自然；明确下一步行动，在他身边不看书，高质量地陪伴孩子，督促他完成每一次的作业。\u003c/p>\u003cp>【拆书家回应】：\u003c/p>\u003cp>感谢mok的分享，看来他已经完全掌握了这个方法，大家为他的表现鼓掌。\u003c/p>\u003cp>【简短有力结语】\u003c/p>\u003cp>今天我们学习了《搞定I：无压工作的艺术》这本书中的两个拆页，学习了管理承诺的三个步骤和自然计划法的四个步骤。管理承诺的三个步骤，让我们清空大脑，排除干扰，减轻焦虑。自然计划法的四个步骤可以帮助我们在做一个项目或复杂事情之前，理清思路，制订一个具体的行动计划。 \u003c/p>\u003cp>【强有力的结语】\u003c/p>\u003cp>相信大家通过今天的学习，体会到GTD方法强大之处了。想过上无压高效的生活，来读这本书就对了。今天的学习，到这里就结束了，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1736062369000,"updated_at":1737431031000,"ria":true},{"id":18255,"topic":"管理承诺三步法&自然计划法四个步骤","learn_goal":"","remark":"当你被大量事务缠身的时候，是不是感到事情太多做不完，无法专心做好手上重要的事情;领导委任你去做一个重要项目，由于缺乏经验，搞的自己身心俱疲，每天加班，仍然没有进展;如果你也遇到这样的问题，那快来跟我学习管理承诺三步法，清空大脑，减轻焦虑，学会运用自然计划法的四个步骤，制订具体的项目计划，轻松掌控项目进展。","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"paul1216","city":""},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>【个人介绍和分组】\u003c/p>\u003cp>大家好，我叫陈舜尧，我有三个标签，第一个标签我是一名资深软件工程师，从事安卓手机软件研发有12年了，具有丰富的软件研发经验；第二个标签我是易效能时间管理践行者，从2021年开始学习GTD时间管理知识，在工作和生活中一直践行高能要事的法则。第三个标签我是一名终身学习者，每年至少会阅读15本书，目前在学习AI写作，AI提示词相关的技能。有对这方面感兴趣的同学欢迎和我链接。\u003c/p>\u003cp>【总学习目标】欢迎大家来到我的小课堂，今天我要拆解的书籍是《搞定I：无压工作的艺术》，希望大家通过今天的学习，可以学会运用两个方法。一个是你正在专心学习，突然脑中想到一件事或有人找你处理另外一件事的时候，你能运用管理承诺的3个步骤，将事情记录下来，提醒自己稍后再去处理。另一个是你能运用自然计划法的4个步骤，在后面的现场演练中，为生活中的一件复杂的事情制订一份具体的行动计划。\u003c/p>\u003cp>【分组】为了帮助大家更好地掌握，吸收今天的学习内容，我设置了分组讨论和演练环节。现在我先给大家分一下组，由于今天到场学习者比较少，我们就分一组。\u003c/p>\u003cp>【FAB介绍图书】\u003c/p>\u003cp>F特征： 本书是一本提高工作效率的书，作者是戴维.艾伦，是一位享誉全球的时间管理大师，该书提供了一整套系统化的方法来帮助大家提高工作效率，减少工作压力，系统讲解了GTD（Getting Things Done）的时间管理方法，帮助全球千万读者掌握它搞定个人事务和工作，书中内容都是作者20多年在时间管理实战方面的宝贵经验提炼。\u003c/p>\u003cp>A优势： 这本书已在33个国家出版，风靡全球十余年，与其它同类书籍相比，书中介绍的GTD法则更加系统全面，已成为全球干万读者用来轻松高效完成工作与个人事务的优秀工具，方法实用，简单易行，提供的案例生动、真实，给人很好的启发。\u003c/p>\u003cp>B1利益： 读完这本书，你将能够学会如何清空大脑，将所有任务和想法都记录下来，掌握如何有效地组织和管理任务列表，确保每项任务都能得到适当的关注和完成。\u003c/p>\u003cp>B2：通过学习第一个拆页管理承诺三步法 ，可以帮助大家在日常工作中专注做自己想做的事情，排除干扰，减轻焦虑。学习第二个拆页自然计划法四个步骤，教你如何在错综复杂的环境中理清思路，制订行动计划，助你轻松应对项目或复杂的事情。\u003c/p>\u003cp>这两个拆页，第一个方法是当你被大量事务缠身的时候，将大脑中的想法记录下来，保存到一个笔记本或手机备忘录里，在某个时间提醒自己去行动，帮你减轻做事的焦虑；当你要做一件需要多个步骤才能完成的事情的时候，可以采用第二个方法，通过制订具体的行动计划，来提高做事的效率，减轻你的压力(两个方法是由面到点，是递进的关系)。\u003c/p>\u003cp>下面，我们正式进入学习环节。请大家阅读拆页1\u003c/p>\u003cp>【设定学习目标】\u003c/p>\u003cp>学完这个拆页，大家能够说出管理承诺三步法，并使用该方法将想要做的一件事情记录下来，再通过日历，便签或闹钟提醒自己在某个时间去做。给大家1分钟的时间，看完后抬头示意我一下，谢谢。\u003c/p>","ratings_count":1,"texts":[{"id":22535,"quote":"\u003cp>\u003cstrong>拆页一《搞定I：无压工作的艺术》页码（P22-23）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>为什么有些事情总是萦绕在你的心头\u003c/strong>\u003c/p>\u003cp>在通常情况下，你对一些事情总是念念不忘，这是因为你希望它们的状况能有所改善，另外：\u003c/p>\u003cp>\u003cstrong>·你还没有明确地认定它们的预期结果是什么。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>·\u003c/strong>\u003c/p>\u003cp>\u003cstrong> .你还没有确定你下一步的具体行动到底是什么。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>·你还没有把关于预期结果和即将采取行动的提示信息存入你所依赖的系统中去。\u003c/strong>\u003c/p>\u003cp>这就是为什么你忘不掉这些事情的原因了。直到你澄清了所有问题，做出一切必要的决定，并把预期结果保存到那个系统中去（同时要确保你能在必要情况下随时访问和查询这个系统），你的大脑才会放松下来。你可以骗过别人，但是你却无法愚弄自己的大脑。它能够明察秋毫：你是否已经做出了必要的决定，是否已经把有关预期结果和行动的提示信息寄存于一个安全可靠的地方，以便这些信息能在恰当的时候提醒你采取行动。如果你没有做好这些工作，那么，你的大脑就一分钟也不会停止运转。通常情况下，当你对某件事还没有依照上述的处理方法处理时，你的某根神经仍然会持续不断地对你施加压力，这只会增加你的精神负担。\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>好，我看大家都看完拆页了，还是由我先来和大家分享。\u003c/p>\u003cp>（What）管理承诺是一种高效处理事情的方法，教大家学会记录大脑中的所有想法，排除干扰，专注做好当下重要的事情。\u003c/p>\u003cp>(Why，不这么做的坏处)\u003c/p>\u003cp>一个人的注意力通常就是30—45分钟，当你在专注做一件事的时候，突然脑子想到另外一件重要的事情或者被外部打断，你就很容易分心或走神，可能会停止做手上的事情，立马就去做其他事情去了。\u003c/p>\u003cp>往往这些干扰的因素，不是特别重要紧急的事，却一直留在大脑里，让你做事无法专注，你就会很容易忽略手上更重要的事情要完成，一旦事情多了后，就容易产生焦虑。\u003c/p>\u003cp>给大家举个我自己的例子，已经放暑假了，老婆想带孩子出去旅游几天，跟我说要带孩子去看海，问我什么时候有时间一起去沿海城市玩几天，我跟她说最近工作有点忙，等到月底不忙了再安排。这段时间我就会一直想着这件事，偶尔也会心生焦虑。\u003c/p>\u003cp>【How细化行动步骤】\u003c/p>\u003cp>作者只告诉了我们事情萦绕在心头的原因，如何管理承诺，并没有给出具体步骤，我根据片段内容，梳理了以下3个步骤：\u003c/p>\u003cp>1.明确预期结果。你希望得到的理想结果是什么？怎样才算是完成了呢，将你想要的结果写在一张纸上，或者手机备忘录里。例如发朋友圈文案获得13个赞。\u003c/p>\u003cp>2.确定下一步行动。为了推进事情的进展，你需要采取下一步具体行动。例如写一篇50字的文案。\u003c/p>\u003cp>3.存放行动清单。人的大脑是CPU，不是硬盘，将要采取的行动写在一张便签上，把便签放在一个固定的地方，提示自己去行动。或者保存到手机备忘录里，定个闹钟提醒自己在某个时间去行动。例如定个晚上8点的闹钟，将写好的文案发到朋友圈。\u003c/p>\u003cp>回到刚才想和家人出去旅游的场景，我会这样运用管理承诺三步法，明确预期的结果是带家人去海边看日出，下一步行动是在周五的下午跟领导请2天假，存放行动清单，我会在手机日历上设置个周五下午5点的闹钟，提醒自己跟领导请假。通过这三步，我就不会一直想着这件事，让我专心做好眼前的事情。\u003c/p>\u003cp>（Where）在我们的工作和生活中，如果你正在专注做一件事，大脑突然想到其他事情要做，或者你的同事或家人有事找你，需要你帮忙处理下，可以使用这个方法。但需要注意，我们要根据当时的情况具体地分析，如果事情特别复杂，需要很多个步骤才能完成，或者事情特别简单，可以在2分钟以内解决的，就不能采用此方法。这一点，大家清楚了吗？\u003c/p>","interaction":"\u003cp>【A1激活经验-拆为已用】\u003c/p>\u003cp>想不想现场练习一下这个方法呢？请大家回想一下，最近你的生活和工作中，有没有遇到过你正在做一件重要的事情，突然有人找你有事，你不假思索地答应了对方。或者突然脑子里想到另外一件没有完成的事情，就去做其他事情去了。请大家在小组内分享一下事件发生的经过，只需要分享你遇到了一件什么事情，当时是怎么处理的。这里有个例子给到大家：在什么时间，在哪个地方，我正在做什么事情，突然想到某某事还未完成，或者有个人找我帮忙做其他事情。\u003c/p>\u003cp>给大家每人1分钟的时间，2分钟以后，我会请一位小伙伴和大家分享他的经历。\u003c/p>\u003cp>回应：好，大家讨论分享得很热烈。现在，请一个小伙伴来分享一下她刚才想到的经历。大家鼓掌，请叶雨同学来分享一下。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>在晚上陪小孩子写作业的过程中，我一边在给这个小孩子讲题目的时候，另外一个小朋友可能会来跟我说，老师，你什么时候给我兑积分呢？我昨天的积分还没有兑呢？我说你等一会儿，然后等一会儿之后，我讲完这个题可能不太记得了，就忘了这个事情。\u003c/p>\u003cp>【拆书家回应】\u003c/p>\u003cp>感谢叶雨同学的分享\u003c/p>\u003cp>【A1+】反思加工\u003c/p>\u003cp>那如果用到今天我们学的管理承诺的三个步骤，再回到刚才大家提到的场景中，我们怎么可以更好地处理呢？大家可以试着把方法运用一遍，对比感受一下这个方法的好处。给大家2分钟时间，把结合管理承诺三个步骤以后的做法写下来。然后我会请一位小伙伴分享她是怎么做的。\u003c/p>\u003cp>好，我们现在再请叶雨来分享一下，针对刚才的经历，她反思后的做法。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>预期结果就是，要完成承诺就是给孩子兑积分；下一步行动就是他过来打扰我的时候，我就给他写个纸条，比如我先给他写个纸条，待会你记得来找我。存放行动清单就是就是把纸条放在显示器下面，等我把手头上的事情做完了之后，我再去看我的纸条，给他兑积分。\u003c/p>\u003cp>【拆书家回应】\u003c/p>\u003cp>好，非常感谢叶雨同学的分享。\u003c/p>\u003cp>（拆页过渡）刚才我们学习的是，用管理承诺三个步骤，将要做的事情记录下来，并设置了提醒。假设，你要做一件需要多个步骤才能完成的事情，只知道截止日期是在1个月后，你是不是感到有点压力山大？那这时候，我们怎样应对比较好呢？拆页2就给大家提供了方法。\u003c/p>\u003cp>【设定拆页2的学习目标】\u003c/p>\u003cp>希望大家学完拆页2，当你做一件需要多个步骤才能完成的复杂事情之前，能熟练运用自然计划法的4个步骤，理清思路，制定一个具体的行动计划。在后面的现场演练中，通过运用自然计划法的4个步骤，为一件生活中的事情制订一个行动计划。给大家1分钟的时间阅读第2个拆页。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":22536,"quote":"\u003cp>\u003cstrong>拆页二 R原文片段：P83-84\u003c/strong>\u003c/p>\u003cp>好消息是，有那么一种思考方式，在面对各种工作、环境和主题时，都能以最小的消耗创造最高的价值。当我们为了达到预期结果而试图控制或执行某个项目时，我们通常都会采用这种自然计划模式。根据我的经验，人们计划得越深入，形式越随意自然，效果就越理想，同时，也越能释放更多的压力。\u003c/p>\u003cp>\u003cstrong>自然式计划模式\u003c/strong>\u003c/p>\u003cp>世界上那个才华横溢、最具创造力的计划者，就是与你朝夕相处的大脑。实际上，你自己就是一台生产计划的机器。当你穿衣、吃午饭、购物，或者是在与人侃侃而谈时，你的大脑都在一刻不停地盘算着。尽管其过程可能毫无章法可言，但事实上在大脑闪现出任何一个具体的方案之前，一些相当复杂的步骤就已经抢先登场了。人的大脑在面对任何一项任务的时候，都要经过5个步骤：\u003c/p>\u003cp>\u003cstrong>1.定义目标和原则。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.展望结果。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3.头脑风暴/集思广益。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4.组织整理。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>5.明确下一步的行动方案。\u003c/strong>\u003c/p>","explains":"\u003cp>【I】拆书家讲解引导\u003c/p>\u003cp>好，我看大家都看完拆页了，还是由我先来和大家分享。\u003c/p>\u003cp>（What）自然计划法，是一种制订计划的思考方式 ，可以帮助我们理清事情的要素，及要素之间的相互关联和重要程度，进而明确下一步具体行动。\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp>值得庆幸的是，这种方法可以帮你在面对工作或生活中的各种事情时，让你以最小的消耗创造最高的价值。以我计划办一个生日宴会为例，[目标]是想为父母举办一个喜庆的七十岁生日宴会，[原则]是食物和服务的标准在三星级以上，预算不超过1W，酒店要离家近。对宴会进行种种想象就是你的[期望的结果]，比如需要什么样的包间，亲戚朋友围着桌子吹蜡烛，唱生日歌等。一旦你想到了期望的结果，大脑便会自然开始想一些问题：我们应该几点出发？这家餐厅有大的包间吗？需要点哪些菜品？这就是自然式计划模式，一旦承诺要办一个喜庆的生日宴会，头脑里装满了大量的想法和细节，你就会和家人讨论相关的细节，不由自主地开始了[思考整理]的工作，“首先，我要打电话给亲戚朋友，逐一邀请他们在某个时间赴宴；其次，要预定一个带大包间的酒店；再次要准备什么酒水和零食等等”，大脑将自动根据事情的组成要素、重要程度和事情发展的先后顺序，分门别类地进行归纳整理，最后，你需要把注意力放在具体的[下一步行动]上，给酒店前台打电话，询问有没有能坐下20人的大包间，然后预定一个好的酒店。\u003c/p>\u003cp>你们是否注意到了，在制订计划的过程中，经过了哪几个步骤呢？是不是自然就想到了目标，原则，期望的结果，收集计划要做的事项，下一步行动。\u003c/p>\u003cp>(Why，不这么做的坏处)\u003c/p>\u003cp>一般人要做一件需要多个步骤才能完成的复杂事情的时候，会按部就班地想到哪就做哪，把容易做的先完成，再期望想个好点子来完成剩余事情。\u003c/p>\u003cp>这样做，往往会让我们忙于处理各种各样的问题，容易造成混乱不清、压力频添的局面。当你陷入最后1小时紧急状态时，就会使自己手忙脚乱，出错的概率就会更大。\u003c/p>\u003cp>给大家举个我自己的例子，有一次我被公司委派为一个新项目的负责人，要在三个月交付一个重要的软件项目，由于没有明确的计划，我只是简单地分配了任务给团队成员，没有定期检查进度。结果，在项目截止日期临近时，我发现许多关键功能还存在问题，赶紧要求开发人员加班加点地修改Bug，最终导致项目延期。事后经过复盘，我发现缺少一个详细的项目计划，一次偶然的机会看到了这个片段，学习了自然计划法。\u003c/p>\u003cp>(How)\u003c/p>\u003cp>制订一个好的项目计划，只需要下面4个步骤：\u003c/p>\u003cp>1.定义目标和原则。明确你的目标是什么，以及你遵循的原则，这将是你计划的出发点和归宿。例如我的目标是在七月底举办一场隆重的同学聚会，原则是在武汉市，预算不超过1W元。\u003c/p>\u003cp>2.展望结果。想象任务完成后的理想状态，这有助于激发你的动力和创造力。例如来自五湖四海的同学们都聚在一起交流学习的经验和收获，在欢声笑语中度过了愉快的上午。\u003c/p>\u003cp>3.思考整理。首先，集思广益，和团队成员一起发散思考，收集所有可能的行动方案。也可以和其他人头脑风暴，尽可能多地列出行动点；其次，对想出来的行动点进行分类和排序，形成一个清晰的行动清单。比如先调查下哪些场地适合聚会，有哪些外地的同学，需要准备什么礼物，再对活动事项进行优先级排序等。\u003c/p>\u003cp>4.明确下一步的行动。从整理后的行动清单中，确定下一步具体要执行的行动。例如打电话通知所有同学，确定有哪些同学可以到场等。\u003c/p>\u003cp>回到刚才我那次项目管理失败的场景，如何运用自然计划法来制订项目计划呢？首先，我会明确项目成功交付的目标，并确立团队协作和沟通的原则。其次，我会想象项目按时交付后，客户满意和团队庆祝的场景；再次，我会收集团队成员的想法，并组织他们进行头脑风暴，列出所有可能的开发任务和风险点，将任务进行分类，明确每个任务的负责人，开始和结束时间；最后，我会确定每个任务负责人的下一步行动。通过这四个步骤，一个清晰的项目计划跃然纸上，极大地减轻了我们的焦虑。\u003c/p>\u003cp>（Where）这个方法适合于制订项目开发计划，或需要多个步骤才能完成的复杂事情的行动计划。不适合简单的或短时间就可以完成的事情。\u003c/p>\u003cp>（预防异议）可能有人会有这样的疑问，是不是所有的事情都要按照这几个步骤来做，是不是太复杂了？我的建议是过程要按这个操作，至于详细程度，根据事情的不同来进行调整和取舍。标准就是能够让我们的大脑保持轻松的状态，基本上就足够了，能够缓解我们的压力就可以了。\u003c/p>","interaction":"\u003cp>【A3促动参与】\u003c/p>\u003cp>学完了自然计划法的4个步骤，现在请大家在我设定的场景里进行一次现场演练，假设我们现在处于这样的场景：\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>马上要到国庆节了，小王的老婆想带孩子去海滨城市玩几天，问小王计划什么时候可以出去，然而最近工作有点忙，由于整天忙于项目就忽略了这件事。偶然有一次，看到同事老李的朋友圈晒旅游照片，觉得老李是一个很会计划的人，于是他私下请教老李，问老李如何制订家庭旅游计划。\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>现在请每两人一组，进行演练。一人扮演老李，一个扮演小王。为了能把今天学习的4个步骤做一个完整的练习，请扮演老李的同学们务必给小王完整地使用4个步骤的机会。演练时间为7-10分钟。稍后，我会请其中一组来到前面为大家现场演绎。\u003c/p>\u003cp>【角色扮演】\u003c/p>\u003cp>好，我看到大家都演练完了，我们现在请小刘和叶雨上来给大家演绎下。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>小王：老李，我最近想带孩子去海边城市玩，看你在朋友发了一些旅游的照片，感觉你是个很会计划的人，特来向你请教下，看你能不能帮我出一些计划，给一些建议。\u003c/p>\u003cp>老李：你的目标和原则是什么呢？\u003c/p>\u003cp>小王：我的目标是去三亚玩个5天，预算在2W左右。\u003c/p>\u003cp>老李：你期望的结果是什么样子的呢？\u003c/p>\u003cp>小王：结果就是家人在海边玩的很畅快，孩子也玩的很轻松，很愉快。\u003c/p>\u003cp>老李：那你可以和家人商量下想去哪些景点，规划下旅游行程，建议你从衣食住行四个方面进行考虑，想一想要哪些准备？\u003c/p>\u003cp>小王：交通方式，去三亚肯定是坐飞机比较方便，如果想游玩比较自由一点，会考虑在当地租个车；10月份天气相对来说比较凉爽，可能不需要带一些比较厚的，去海边的话，要准备沙滩鞋和游泳衣；吃的方面，可以在网上搜下比较大型的夜市，最好离酒店近一点；住的话，考虑主题酒店，最好带有亲子游玩的设施。\u003c/p>\u003cp>老李：建议你把想到的行动步骤整理下，最好按照先后顺利罗列一个清单。你下一步行动是什么呢？\u003c/p>\u003cp>小王：选日子，订机票。\u003c/p>\u003cp>【拆书家回应】\u003c/p>\u003cp>感谢两位的精彩演绎，生动形象。\u003c/p>\u003cp>（环节过渡）\u003c/p>\u003cp>刚刚我们完成了一次现场演练，现在请大家把关注点放到自己身上，规划一下未来我们要怎么去运用今天学到的自然计划法的四个步骤。\u003c/p>\u003cp>【A2分步催化应用之经验激活】\u003c/p>\u003cp>请大家思考一下，未来一个月或半年内，在工作和生活中，要做一件什么复杂的事情呢？可能是领导安排的一个项目，需要跨部门协作，和其他组员一起合作完成；可能是要给家里装修房子，和家人一起协商完成；\u003c/p>\u003cp>请想一想，给大家3分钟的时间在小组内讨论，只需要分享可能遇到的情景，不需要说具体怎么做。\u003c/p>\u003cp>看大家讨论这么热烈，请小刘来分享下自己的未来一个月或半年内想要做的一个项目或一件复杂的事情。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>小刘：我在考虑怎么给小孩制订一个未来的发展道路。现在大家都是千军万马走独木桥高考文化，我老婆是做番茄艺术培训，可能会走艺术这条道路，如果走艺术的话，生活相对比较自由点。\u003c/p>\u003cp>【拆书家回应】\u003c/p>\u003cp>谢谢小刘的分享。\u003c/p>\u003cp>【A2分步催化应用之催化应用】\u003c/p>\u003cp>刚才每个人都说出自己将来可能遇到的情景，现在请你想象一下，在这样的场景中，你会如何应用今天学的自然计划的四个步骤呢？请大家把自己要做的步骤都写下来，这样可以帮助大家提前预演一下。给到大家3分钟时间，结束之后请一位小伙伴给大家分享。\u003c/p>\u003cp>好，我看大家都很认真在写便签，差不多都已经写完了，现在我们请一位小伙伴来分享一下。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>小刘：目标就是小孩的未来发展方向以艺术为主，展望结果是学了艺术之后可以到处去演出，可以陶冶情操。我和老婆也商量了下，想了很多方法帮他往艺术方向发展，第一，减少不必要的文化作业；第二，每天花1.5个小时投入到艺术学习中；第三，提升英语水平，每天早上会花半个小时晨读，后面再进行相应的英语口语练习；第四，参加一些活动或比赛，比如下个月举办的艺术小人才比赛。下一步具体行动就是报名参加下个月的艺术小人才比赛，积累经验。\u003c/p>\u003cp>【拆书家回应】：\u003c/p>\u003cp>感谢小刘的分享，看来他已经完全掌握了这个方法，大家为他的表现鼓掌。\u003c/p>\u003cp>【简短有力结语】\u003c/p>\u003cp>今天我们学习了《搞定I：无压工作的艺术》这本书中的两个拆页，学习了管理承诺的三个步骤和自然计划法的四个步骤。管理承诺的三个步骤，让我们清空大脑，排除干扰，减轻焦虑。自然计划法的四个步骤可以帮助我们在做一个项目或复杂事情之前，理清思路，制订一个具体的行动计划。 \u003c/p>\u003cp>【强有力的结语】\u003c/p>\u003cp>相信大家通过今天的学习，体会到GTD方法强大之处了。想过上无压高效的生活，来读这本书就对了。今天的学习，到这里就结束了，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1730333542000,"updated_at":1732145802000,"ria":true},{"id":18025,"topic":"清空大脑","learn_goal":"","remark":"我们每个人的大脑都存着太多的待办事项，占据我们的大脑空间，除非我们将这些事情存入一个信任的外部系统，否则就很难让自己的大脑放松下来。","level":"TF3-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"拆大侠","city":"北京市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp> \u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp> 学习者在跟随我完成本场RIA现场学习后，可以让自己大脑里那些念念不忘的事情（界定），通过清空大脑四步法（澄清），将这些信息寄存（行为）到一个安全可靠的外部系统。\u003c/p>\u003cp> 自我介绍＋图书介绍（2分钟）\u003c/p>\u003cp> \u003cstrong>【自我介绍】\u003c/strong>\u003cbr> 大家好，首先做下自我介绍，姓名郑勇，三个标签：1、易效能时间管理教练；2、全域电商优惠导购及抖音本地生活入驻团队长；3、拆书帮一级拆书家。\u003c/p>\u003cp> \u003cstrong>【图书介绍】\u003c/strong>\u003cbr> （事件场景）之前我在一家汽车4S店负责采购工作，有个堂弟就拜托我在北京找一个配件春节的时候带回去，我答应没问题。但节前采购部门很忙，还有家里买年货啥的，就把这事忘了，等我回到老家堂弟过来找我，我一拍大腿，是彻底给忘了。\u003cbr> （提问）不知道在场的各位是不是也有同样的经历，拍胸脯答应别人的事，结果还是给忘记了，自己也感觉特别的不好意思。这类的事情可能都不止一次发生，但也没有想出能够避免的方法。\u003cbr> （影响）如果是家人朋友让我们办的事情给忘了，可能会影响关系和感情，如果是同事或者上级领导委派的事情给忘了，则很有可能会给人留下不靠谱的印象，影响到工作的顺畅和职业的发展。\u003c/p>\u003cp> （解决）而今天我为大家分享的这本书《搞定1-无压的工作艺术》，通过建立一个可靠的外部系统，帮我们管理这些事情，不仅避免了遗忘带来的后果，还减轻了大脑的压力。\u003c/p>\u003cp> 下面请大家先阅读一下拆页，看完的伙伴可以抬头示意我。\u003c/p>","ratings_count":1,"texts":[{"id":22273,"quote":"\u003cp> 阅读原文片段（2分钟）\u003c/p>\u003cp> \u003cstrong>拆页：片段来源《搞定1》P022-023\u003c/strong>\u003c/p>\u003cp> 在通常情况下，你对一些事情总是念念不忘，这是因为你希望它们的状况能有所改善，另外：\u003c/p>\u003cul>\u003cli>你还没有明确地认定它们的预期结果是什么。\u003c/li>\u003cli>你还没有确定你下一步的具体行动到底是什么。\u003c/li>\u003cli>你还没有把关于预期结果和即将采取行动的提示信息存入你所依赖的系统中去。\u003c/li>\u003c/ul>\u003cp> 这就是为什么你忘不掉这些事情的原因了。直到你澄清了所有问题，做出一切必要的决定，并把预期结果保存到那个系统中去（同时要确保你能在必要情况下随时访问和查询这个系统），你的大脑才会放松下来。你可以骗过别人，但是你却无法愚弄自己的大脑。它能够明察秋毫：你是否已经做出了必要的决定，是否已经把有关预期结果和行动的提示信息寄存于一个安全可靠的地方，以便这些信息能在恰当的时候提醒你采取行动。如果你没有做好这些工作，那么，你的大脑就一分钟也不会停止运转。通常情况下，当你对某件事还没有依照上述的处理方法处理时，你的某根神经仍然会持续不断地对你施加压力，这只会增加你的精神负担。\u003c/p>","explains":"\u003cp> 拆书家讲解引导（6分钟）\u003c/p>\u003cp>\u003cstrong> 【what】\u003c/strong>\u003cbr> 本段拆页告诉我们一个核心概念“外脑”，也就是我们的第二大脑。指导我们将这些代办事项放入一个可靠的外部系统也就是“外脑”，以此来减轻我们大脑的压力。\u003c/p>\u003cp>\u003cbr> \u003cstrong>【why】\u003c/strong>\u003cbr> 为什么要这样做呢？因为当今社会生活节奏快，我们每天都会面临非常多的事情要做，头脑里存着非常多的待办事项，一方面我们会遗忘，另外即使我们记着这些事情，大脑也很难做到恰当的时候主动提醒我们。如果这些事情没有明确的着落，就会持续给我们造成压力，大脑很难放松下来，也很难专注。\u003c/p>\u003cp>\u003cbr> \u003cstrong>【概念讲解-案例概念相互参照】\u003c/strong>\u003cbr> 那这个“外脑”系统到底指的是什么呢？首先我们确认它的特点，安全可靠，随时访问，恰当的时候提醒我们采取行动，也就是这个外脑系统需要符合以上特点。我举个几个例子我们一起分析下：\u003cbr> 1. 我们常用的笔记本算是外脑系统吗？就是那种纸质的下本子，其实是不算的，我们可能会丢掉它，除了不够安全可靠外，另外他也做不到随时访问，即使可以随身带在包里的那种，也不能在恰当的时候提醒我们。\u003cbr> 2. 第二个我们手机的备忘录算是第二外脑系统吗？也不算的，虽然可以做到安全可靠和随时访问，但备忘录需要主动查看，并不能主动提醒我们。\u003cbr> 3. 那清单软件算是外脑系统吗？这个是算的，市场上的绝大多数清单工具都具备安全可靠和随时访问以及提醒的功能，设备丢失我们通过账号登录找回就可以，随时访问也是可以的，因为手机都基本成了我们身体的一个器官了，提醒功能也都是具备的。\u003c/p>\u003cp>\u003cbr> \u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp> 那具体的步骤怎么操作呢？\u003cbr> 第一步：\u003cstrong>设定预期结果-\u003c/strong>也就是这件事情我要做到什么程度，达到什么成果或者是目标。\u003cbr> 第二步：\u003cstrong>明确下一步行动-\u003c/strong>从哪里开始下手，第一步要做的是什么，只有目标没有进一步的计划也是空中楼阁，把这件事分解成一个可执行的动作。\u003cbr> 第三步：\u003cstrong>录入外部系统-\u003c/strong>把这件事情或者这个行动录入到复合条件的外部系统，也就是“外脑”这里通常指电子清单工具，比如滴答清单‘、ToDo等，这类工具蛮多的。 \u003c/p>\u003cp> 第四步：\u003cstrong>设置提醒-\u003c/strong>设置提醒，这个提醒不仅仅是时间上的提醒，也有空间上的提醒，比如到什么地方提醒我做什么事，清单工具通常都有这个功能。\u003c/p>\u003cp> \u003cstrong>【个人案例】\u003c/strong>\u003c/p>\u003cp> 我个人是已经习惯把代办事项都收集到清单工具并进行排程，我家丫头告诉我哪天出去路过合生汇到名创优品帮她买一个紫色的签字笔，一个月亮的床头灯，另外再买脏脏包、泡芙和烤鸡爪，我个人还需要到二楼的书店去找一本书查一些内容。这些事情相对简单都是确定要做的，把东西都购买到家即可（设定预期结果），且下一步的行动很简单，路过合生汇去购买（明确下一步行动）。事情并不是很紧急马上就要去做，只是我刚好路过去完成这些事就行，所以我就把在合生汇需要购买的物品都录入清单系统（录入外部系统），然后设置路过合生汇时提醒（设置提醒），是不是很贴心。我不用用脑子总记着这件事了，而且买的东西多了我也记不住，并且可以在恰当的时候提醒我，只要我路过合生汇它就会弹出提醒，是不是很酷。\u003c/p>","interaction":"\u003cp> 催化应用（7分钟）\u003c/p>\u003cp>\u003cstrong> 【编写剧本】\u003c/strong>\u003c/p>\u003cp> 请各位根据我们今天学到的清空大脑四步骤，思考下未来的一周或一个月内可能遇到的一个场景来编写一个小剧本。要求有时间、地点、人物，包括事情的起因、经过、结果，以对话的形式呈现出来。然后写在咱们相应的表格中，5分钟左右的时间，我请现场的伙伴分享下他的剧本。\u003c/p>\u003cp>\u003cbr> \u003cstrong>【案例记录】\u003c/strong>\u003c/p>\u003cp> 学习者丹娜分享\u003cbr> 故事背景：暑假期间孩子有安排一些课外课，我还要上班，就不能随时跟进和提醒孩子参加课程。\u003c/p>\u003cp>时间：星期天晚上\u003c/p>\u003cp>地点：在家\u003c/p>\u003cp>人物：我和儿子\u003c/p>\u003cp>对话：\u003c/p>\u003cp> 儿子：妈，我经常错过上课的时间，总是忘了记不住怎么办呢？\u003c/p>\u003cp> 妈妈：是呀，总让老师提醒也不是事儿啊，咱们还是得保证能按时上课才行（设定预期结果），那儿子你去看下自己都有哪些课程，都在什么时间（明确下一步行动）。\u003c/p>\u003cp> 儿子：好的，周三晚上7:30我有个唐诗课，其它课我也写出来了。\u003c/p>\u003cp> 妈妈：很好，那就把这几个课录入到你的电话手表里（录入外部系统），然后设置两个一个是提前半天提醒，防止你安排别的事情，再设置一个提前10分钟提醒，让你准备上课（设置提醒）。\u003c/p>\u003cp> 儿子：好的，我马上搞定。\u003cbr> \u003cbr> \u003cstrong>【回应或反馈】\u003c/strong>\u003cbr> 感谢丹娜的分享，应用我们今天学习到的四个步骤帮儿子管理好课外班经常遗忘的事情，孩子的外脑系统不必像成人那样复杂，一个手机或者手表或者智能闹钟的提醒就可以轻松实现清空大脑和管理事情的目的。\u003c/p>\u003cp> \u003cstrong>【结束语】\u003c/strong>\u003cbr> 好的，大脑不是硬盘是CPU，希望大家把用到的清空大脑四步骤实践起来，解放我们的大脑，让事情有条不紊的进行。以上就是我分享的全部内容。谢谢大家！\u003cbr> \u003c/p>\u003cp> 实际用时总时长17分钟\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1725004428000,"updated_at":1726796940000,"ria":true},{"id":17968,"topic":"管理承诺三步法&自然计划法四个步骤","learn_goal":"","remark":"当你被大量事务缠身的时候，是不是感到事情太多做不完，无法专心做好手上重要的事情;领导委任你去做一个重要项目，由于缺乏经验，搞的自己身心俱疲，每天加班，仍然没有进展;如果你也遇到这样的问题，那快来跟我学习管理承诺三步法，清空大脑，减轻焦虑;学会运用自然计划法的四个步骤，制订具体的项目计划，轻松掌控项目进展。","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"paul1216","city":""},"club":{"name":"武汉珞珈分舵","city":"武汉"},"prologue":"\u003cp>【个人介绍和分组】\u003c/p>\u003cp>大家好，我叫陈舜尧，我有三个标签，第一个标签我是一名资深软件工程师，从事安卓手机软件研发有12年了，具有丰富的软件研发经验；第二个标签我是易效能时间管理践行者，从2021年开始学习GTD时间管理知识，在工作和生活中一直践行高能要事的法则。第三个标签我是一名终身学习者，每年至少会阅读15本书，目前在学习AI写作，AI提示词相关的技能。有对这方面感兴趣的同学欢迎和我链接。\u003c/p>\u003cp>【总学习目标】欢迎大家来到我的小课堂，今天我要拆解的书籍是《搞定I：无压工作的艺术》，希望大家通过今天的学习，可以学会运用两个方法。一个是你正在专心学习，突然脑中想到一件事或有人找你处理另外一件事的时候，你能熟练运用管理承诺的3个步骤，将事情记录下来，提醒自己之后再去处理。另一个是你能熟练运用自然计划法的4个步骤，在后面的现场演练中，为生活中的一件复杂的事情制订一份具体的行动计划。\u003c/p>\u003cp>【分组】为了帮助大家更好地掌握，吸收今天的学习内容，我设置了分组讨论和演练环节。现在我先给大家分一下组，按照就近、方便讨论的原则，左边的两位同学一组，中间的两位同学一组，孔老师和旁边的那位女士一组，可以吗？\u003c/p>\u003cp>\u003cstrong>F特征\u003c/strong>： 本书作者是戴维.艾伦，是一位享誉全球的时间管理大师，该书提供了一整套系统化的方法来帮助大家提高工作效率，减少工作压力，系统讲解了GTD（Getting Things Done）的时间管理方法，帮助全球千万读者掌握它搞定个人事务和工作，书中内容都是作者20多年在时间管理实战方面的宝贵经验提炼。\u003c/p>\u003cp>\u003cstrong>A优势\u003c/strong>： 这本书已在33个国家出版，风靡全球十余年，与其它同类书籍相比，书中介绍的GTD法则更加系统全面，已成为全球干万读者用来轻松高效完成工作与个人事务的优秀工具，方法实用，简单易行，提供的案例生动、真实，给人很好的启发。\u003c/p>\u003cp>\u003cstrong>B1利益\u003c/strong>： 读完这本书，你将能够学会如何清空大脑，将所有任务和想法都记录下来，掌握如何有效地组织和管理任务列表，确保每项任务都能得到适当的关注和完成。\u003c/p>\u003cp>\u003cstrong>B2\u003c/strong>：通过学习第一个拆页管理承诺三步法 ，可以帮助大家在日常工作中专注做自己想做的事情，排除干扰，减轻焦虑。学习第二个拆页自然计划法四个步骤，教你如何在错综复杂的环境中理清思路，制订行动计划，助你轻松应对项目或复杂的事情。\u003c/p>\u003cp>这两个拆页，第一个方法是当你被大量事务缠身的时候，将大脑中的想法记录下来，保存到一个笔记本或手机备忘录里，在某个时间提醒自己去行动，帮你减轻做事的焦虑；当你要做一件需要多个步骤才能完成的事情的时候，可以采用第二个方法，通过制订具体的行动计划，来提高做事的效率，减轻你的压力(两个方法是由面到点，是递进的关系)。\u003c/p>\u003cp>下面，我们正式进入学习环节。请大家阅读拆页1\u003c/p>","ratings_count":1,"texts":[{"id":22206,"quote":"\u003cp>【设定学习目标】\u003c/p>\u003cp>学完这个拆页，当大家在听我分享的时候，突然想到另外一件事情，能够采用管理承诺三步法，先将事情记录下来，再通过日历或闹钟提醒自己在其它时间去做。给大家1分钟的时间，看完后抬头示意我一下，谢谢。\u003c/p>\u003cp>\u003cstrong>拆页一《搞定I：无压工作的艺术》页码（P22-23）\u003c/strong>\u003c/p>\u003cp>为什么有些事情总是萦绕在你的心头\u003c/p>\u003cp>在通常情况下，你对一些事情总是念念不忘，这是因为你希望它们的状况能有所改善，另外：\u003c/p>\u003cp>·你还没有明确地认定它们的预期结果是什么。\u003c/p>\u003cp>·\u003c/p>\u003cp> .你还没有确定你下一步的具体行动到底是什么。\u003c/p>\u003cp>·你还没有把关于预期结果和即将采取行动的提示信息存入你所依赖的系统中去。\u003c/p>\u003cp>这就是为什么你忘不掉这些事情的原因了。直到你澄清了所有问题，做出一切必要的决定，并把预期结果保存到那个系统中去（同时要确保你能在必要情况下随时访问和查询这个系统），你的大脑才会放松下来。你可以骗过别人，但是你却无法愚弄自己的大脑。它能够明察秋毫：你是否已经做出了必要的决定，是否已经把有关预期结果和行动的提示信息寄存于一个安全可靠的地方，以便这些信息能在恰当的时候提醒你采取行动。如果你没有做好这些工作，那么，你的大脑就一分钟也不会停止运转。通常情况下，当你对某件事还没有依照上述的处理方法处理时，你的某根神经仍然会持续不断地对你施加压力，这只会增加你的精神负担。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导－不这么做的坏处&amp;预防异议\u003c/strong>\u003c/p>\u003cp>好，我看大家都看完拆页了，还是由我先来和大家分享。\u003c/p>\u003cp>（What）管理承诺是一种高效处理事情的方法，教大家学会记录大脑中的所有想法，排除干扰，专注做好当下重要的事情。\u003c/p>\u003cp>(Why，不这么做的坏处)\u003c/p>\u003cp>（一般做法）一个人的注意力通常就是30—45分钟，当你在专注做一件事的时候，突然脑子想到另外一件重要的事情或者被外部打断，你就很容易分心或走神，可能会停止做手上的事情，立马就去做其他事情去了。\u003c/p>\u003cp>（坏处）往往这些干扰的因素，不是特别重要紧急的事，却一直留在大脑里，让你做事无法专注，你就会很容易忽略手上更重要的事情要完成，一旦事情多了后，就容易产生焦虑。\u003c/p>\u003cp>（反例）给大家举个我自己的例子，已经放暑假了，老婆想带孩子出去旅游几天，跟我说要带孩子去看海，问我什么时候有时间一起去沿海城市玩几天，我跟她说最近工作有点忙，等到月底不忙了再安排。这段时间我就会一直想着这件事，偶尔也会心生焦虑。\u003c/p>\u003cp>\u003cstrong>【How细化行动步骤】\u003c/strong>\u003c/p>\u003cp>作者只告诉了我们事情萦绕在心头的原因，如何管理承诺，并没有给出具体步骤，我根据片段内容，梳理了以下3个步骤：\u003c/p>\u003cp>1.明确预期结果。你希望得到的理想结果是什么？怎样才算是完成了呢，将你想要的结果写在一张纸上，或者手机备忘录里。例如发朋友圈文案获得13个赞。\u003c/p>\u003cp>2.确定下一步行动。为了推进事情的进展，你需要采取下一步具体行动。例如写一篇50字的文案。\u003c/p>\u003cp>3.提醒自己去做。人的大脑是CPU，不是硬盘，将即将采取的行动写在笔记本上，或存入手机日历里，设置个闹钟提醒自己在某个时间去行动。例如定个晚上8点的闹钟，将写好的文案发到朋友圈。\u003c/p>\u003cp>（正例）回到刚才想和家人出去旅游的场景，我会这样运用管理承诺三步法，明确预期的结果是带家人去海边看日出，下一步行动是在周五的下午跟领导请2天假，通过工具在某个时间提醒自己去做，我会在手机日历上设置个周五下午5点的闹钟，提醒自己跟领导请假。通过这三步，我就不会一直想着这件事，让我专心做好眼前的事情。\u003c/p>\u003cp>（Where）在我们的工作和生活中，如果你正在专注做一件事，大脑突然想到其他事情要做，或者你的同事或家人有事找你，需要你帮忙处理下，可以使用这个方法。但需要注意，我们要根据当时的情况具体地分析，如果事情特别复杂，需要很多个步骤才能完成，或者事情特别简单，可以在2分钟以内解决的，就不能采用此方法。这一点，大家清楚了吗？\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验-拆为已用：提出一个显像问题】\u003c/strong>\u003c/p>\u003cp>想不想现场练习一下这个方法呢？请大家回想一下，最近你的生活和工作中，有没有遇到过你正在做一件重要的事情，突然有人找你有事，你不假思索地答应了对方。或者突然脑子里想到另外一件没有处理的事情，就去做其他事情去了。请大家在小组内分享一下事件发生的经过，只需要分享你遇到了一件什么事情，当时是怎么处理的。这里有个例子给到大家：在什么时间，在哪个地方，我正在做什么事情，突然想到某某事还未完成，或者有个人找我帮忙做其他事情。\u003c/p>\u003cp>给大家每人1分钟的时间，5分钟以后，我会请一位小伙伴和大家分享他的经历。\u003c/p>\u003cp>好，大家讨论分享得很热烈。现在，请一个小伙伴来分享一下她刚才想到的经历。大家鼓掌，请曾艺同学来分享一下。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>前段时间，我在办公室做会议纪要的时候，突然有个领导就找我，让我去送文件，然后又有一个领导走过来让我去帮忙办理什么支付之类的事情，在频繁被外部事情干扰下，本来应该做的那个会议纪要就完全没做，工作开展不顺利。\u003c/p>\u003cp>拆书家回应：感谢曾艺的分享\u003c/p>\u003cp>\u003cstrong>【A1+】反思加工\u003c/strong>\u003c/p>\u003cp>那如果用到今天我们学的管理承诺的三个步骤，再回到刚才大家提到的场景中，我们怎么可以更好地处理呢？大家可以试着把方法运用一遍，对比感受一下这个方法的好处。给大家2分钟时间，把结合管理承诺三个步骤以后的做法写下来。然后我会请一位小伙伴分享她是怎么做的。\u003c/p>\u003cp>好，我们现在再请曾艺来分享一下，针对刚才的经历，她反思后的做法。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>我在做会议纪要的时候，如果遇到了临时让我送文件，会判断这个事情对我是不是重要紧急的事，如果不是特别重要紧急的事情，可以先把它记录下来，保存到自己手机备忘录里，设置个闹钟提醒自己在做完手头上的会议纪要后，再进行实施。\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp>好，我们感谢曾艺的分享。他运用了管理承诺这三个步骤以后，明确了预期结果是先做好手中的会议纪要，确定了下一步具体行动送文件给另一个同事，最后在手机备忘录里写下了要实施的行动，提醒自己在其它时间去做！\u003c/p>\u003cp>（拆页过渡）刚才我们学习的是，用管理承诺三个步骤，将要做的事情记录下来，并设置了提醒。假设，你要做一件需要多个步骤才能完成的事情，只知道截止日期是在1个月后，你是不是感到有点压力山大？那这时候，我们怎样应对比较好呢？拆页2就给大家提供了方法。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":22207,"quote":"\u003cp>【设定拆页2的学习目标】\u003c/p>\u003cp>希望大家学完拆页2，当你做一件需要多个步骤才能完成的复杂事情之前，能熟练运用自然计划法的4个步骤，理清思路，制定一个具体的行动计划。在后面的现场演练中，通过运用自然计划法的4个步骤，为一件生活中的事情制订一个行动计划。\u003c/p>\u003cp>给大家1分钟的时间阅读第2个拆页。\u003c/p>\u003cp>\u003cstrong>拆页二\u003c/strong> \u003cstrong>《搞定I：无压工作的艺术》页码（P83-84）\u003c/strong>\u003c/p>\u003cp>好消息是，有那么一种思考方式，在面对各种工作、环境和主题时，都能以最小的消耗创造最高的价值。当我们为了达到预期结果而试图控制或执行某个项目时，我们通常都会采用这种自然计划模式。根据我的经验，人们计划得越深入，形式越随意自然，效果就越理想，同时，也越能释放更多的压力。\u003c/p>\u003cp>自然式计划模式\u003c/p>\u003cp>世界上那个才华横溢、最具创造力的计划者，就是与你朝夕相处的大脑。实际上，你自己就是一台生产计划的机器。当你穿衣、吃午饭、购物，或者是在与人侃侃而谈时，你的大脑都在一刻不停地盘算着。尽管其过程可能毫无章法可言，但事实上在大脑闪现出任何一个具体的方案之前，一些相当复杂的步骤就已经抢先登场了。人的大脑在面对任何一项任务的时候，都要经过5个步骤：\u003c/p>\u003cp>1.定义目标和原则。\u003c/p>\u003cp>2.展望结果。\u003c/p>\u003cp>3.头脑风暴/集思广益。\u003c/p>\u003cp>4.组织整理。\u003c/p>\u003cp>5.明确下一步的行动方案。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】拆书家讲解引导－不这么做的坏处&amp;预防异议\u003c/strong>\u003c/p>\u003cp>好，我看大家都看完拆页了，还是由我先来和大家分享。\u003c/p>\u003cp>（What）自然计划法，是一种制订计划的思考方式 ，可以帮助我们理清事情的要素，及要素之间的相互关联和重要程度，进而明确下一步具体行动。\u003c/p>\u003cp>(Why，不这么做的坏处)\u003c/p>\u003cp>（一般做法）一般人要做一件需要多个步骤才能完成的复杂事情的时候，会按部就班地想到哪就做哪，把容易做的先完成，再期望想个好点子来完成剩余事情。\u003c/p>\u003cp>（坏处）这样做，往往会让我们忙于处理各种各样的问题，容易造成混乱不清、压力频添的局面。当你陷入最后1小时紧急状态时，就会使自己手忙脚乱，出错的概率就会更大。\u003c/p>\u003cp>（反例）给大家举个我自己的例子，有一次我被公司委派为一个新项目的负责人，要在三个月交付一个重要的软件项目，由于没有明确的计划，我只是简单地分配了任务给团队成员，没有定期检查进度。结果，在项目截止日期临近时，我发现许多关键功能还存在问题，赶紧要求开发人员加班加点地修改Bug，最终导致项目延期。事后经过复盘，我发现缺少一个详细的项目计划，一次偶然的机会看到了这个片段，学习了自然计划法。\u003c/p>\u003cp>(How)\u003c/p>\u003cp>今天教你自然计划法，帮你制订项目计划，只需要下面4个步骤：\u003c/p>\u003cp>1.定义目标和原则。明确你的目标是什么，以及你遵循的原则，这将是你计划的出发点和归宿。例如我的目标是在七月底举办一场隆重的同学聚会，原则是在武汉市，预算不超过1W元。\u003c/p>\u003cp>2.展望结果。想象任务完成后的理想状态，这有助于激发你的动力和创造力。例如来自五湖四海的同学们都聚在一起交流学习的经验和收获，在欢声笑语中度过了愉快的上午。\u003c/p>\u003cp>3.思考整理。收集所有可能的行动方案，发散思考或者和其他人头脑风暴，尽可能多地列出行动点，对想出来的行动点进行分类和排序，形成一个清晰的行动清单。比如先调查下哪些场地适合聚会，有哪些外地的同学，需要准备什么礼物，再对活动事项进行优先级排序等。\u003c/p>\u003cp>4.明确下一步的行动。从整理后的行动清单中，确定下一步具体要执行的行动。例如打电话通知所有同学，确定有哪些同学可以到场等。\u003c/p>\u003cp>（反例变正例）回到刚才我那次项目管理失败的场景，如何运用自然计划法来制订项目计划呢？首先，我会明确项目成功交付的目标，并确立团队协作和沟通的原则。其次，我会想象项目按时交付后，客户满意和团队庆祝的场景；再次，我会组织团队成员进行头脑风暴，列出所有可能的开发任务和风险点，将任务进行分类，明确每个任务的负责人，开始和结束时间；最后，我会确定每个任务负责人的下一步行动。通过这四个步骤，一个清晰的项目计划跃然纸上，极大地缓解了我们项目交付的压力。\u003c/p>\u003cp>（Where）这个方法适合于制订项目开发计划，或需要多个步骤才能完成的复杂事情的行动计划。不适合简单的或短时间就可以完成的事情。\u003c/p>\u003cp>（预防异议）可能有人会有这样的疑问，是不是所有的事情都要按照这几个步骤来做，是不是太复杂了？我的建议是过程要按这个操作，至于详细程度，根据事情的不同来进行调整和取舍。标准就是能够让我们的大脑保持轻松的状态，基本上就足够了，能够缓解我们的压力就可以了。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3促动参与】\u003c/strong>\u003c/p>\u003cp>学完了自然计划法的4个步骤，现在请大家在我设定的场景里进行一次现场演练，假设我们现在处于这样的场景：\u003c/p>\u003cp>\u003cstrong>【场景设计】\u003c/strong>\u003c/p>\u003cp>放暑假了，小王的老婆想带孩子去海滨城市玩几天，问小王计划什么时候可以出去，然而最近工作有点忙，由于整天忙于项目就忽略了这件事。偶然有一次，看到同事老李的朋友圈晒旅游照片，觉得老李是一个很会计划的人，于是他私下请教老李，问老李如何制订家庭旅游计划。\u003c/p>\u003cp>\u003cstrong>【小组讨论】\u003c/strong>\u003c/p>\u003cp>现在请每两人一组，进行演练。一人扮演老李，一个扮演小王。为了能把今天学习的4个步骤做一个完整的练习，请扮演老李的同学们务必给小王完整地使用4个步骤的机会。演练时间为7-10分钟。稍后，我会请其中一组来到前面为大家现场演绎。\u003c/p>\u003cp>\u003cstrong>【角色扮演】\u003c/strong>\u003c/p>\u003cp>好，我看到大家都演练完了，我们请一个组到前面来给大家表演一下。我们现在请孔老师和新月这一组吧，大家鼓掌欢迎！\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>老李：根据我的以往经验，你这次是想去海滨城市去玩一下，是吗？\u003c/p>\u003cp>小王：对啊\u003c/p>\u003cp>老李：我已经玩了好多次了，听你说想制订一个旅行计划，跟你交流一下经验，有四个步骤，\u003c/p>\u003cp>第一步要定一下这个目标和原则，我想问一下你的目标是什么？\u003c/p>\u003cp>小王：目标是去三亚玩7天，原则是每个人不超过1W。\u003c/p>\u003cp>老李：第二步我们想象一下结果是什么？在三亚玩会经历一些什么美好的事情\u003c/p>\u003cp>小王：嗯，我想去海边游泳，想去拍美美的照片，去吃当地的特色小吃，在海边吹风冲浪。\u003c/p>\u003cp>老李：可以，如果计划好的话，这些目标都会达到。第三步我们来头脑风暴一下，要做哪些事情最终才能实现这个结果目标。\u003c/p>\u003cp>小王：要跟领导请假，要联系旅行社，要订机票，要买物资，要联系朋友，要存钱，要搜集旅游攻略。\u003c/p>\u003cp>老李：你看我用思维导图整理了下，最终我们都要做，可以对行动按照优先级排个序，第四步确定下一步行动是做什么呢？\u003c/p>\u003cp>小王：下一步行动就是联系旅行社\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp>感谢孔老师和新月女士的演绎，生动形象。新月女士扮演的小王，完美地运用了刚才学到的自然计划法的四个步骤，定义目标和原则、展望结果、思考整理、明确下一步行动。我们一起为他们的精彩演绎鼓掌吧。\u003c/p>\u003cp>\u003cstrong>（环节过渡）\u003c/strong>\u003c/p>\u003cp>刚刚我们完成了一次现场演练，现在请大家把关注点放到自己身上，规划一下未来我们要怎么去运用今天学到的自然计划法的四个步骤。\u003c/p>\u003cp>\u003cstrong>【A2分步催化应用之经验激活】\u003c/strong>\u003c/p>\u003cp>请大家思考一下，在未来工作和生活中，要做一件事情呢？可能是领导安排的一个项目，需要跨部门协作，和其他组员一起合作完成；可能是要给家里装修房子，和家人一起协商完成；\u003c/p>\u003cp>请想一想，给大家3分钟的时间在小组内讨论，只需要分享可能遇到的情景，不需要说具体怎么做。\u003c/p>\u003cp>看大家讨论这么热烈，请孔老师来分享自己的情景：\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>我们领导可能到十月中旬左右，让我去组织一个培训活动，训练比赛的一个活动，组织这个活动要准备很长时间，还要翻新出奇，不是那么好搞。\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp>谢谢孔老师的分享，他说的是在十月中旬这段时间，公司领导要他组织一个培训活动。\u003c/p>\u003cp>\u003cstrong>【A2分步催化应用之催化应用】\u003c/strong>\u003c/p>\u003cp>刚才每个人都说出自己将来可能遇到的情景，现在请你想象一下，在这样的场景中，你会如何应用今天学的自然计划的四个步骤来做呢？请大家把自己要做的步骤和要说的话都写下来，这样可以帮助大家提前预演一下。给到大家3分钟时间，结束之后请一位小伙伴给大家分享。\u003c/p>\u003cp>好，我看大家都很认真在写便签，差不多都已经写完了，现在我们请一位小伙伴来分享一下。大家鼓掌欢迎，请孔老师来分享一下。\u003c/p>\u003cp>【学习者案例】\u003c/p>\u003cp>公司要我组织一个活动，有点复杂，不是很好搞，我就按照四个步骤来完成。第一步定义目标是三天完成，原则是正常，不要出纰漏；第二步想要的结果是技能提升，发现潜在人才；第三步用思维导图整理行动点，写通知，编写教材，搞比赛的节目，组织人员公布结果，找上级要奖金；第四步明确下一步行动，就是写一个通知出来发下去，通知部门所有的同事。\u003c/p>\u003cp>【拆书家反馈】\u003c/p>\u003cp>感谢孔老师的分享，他已经完美地应用了定义目标和原则、展望结果、思考整理、明确下一步行动方案这四个步骤，制订一个具体的活动计划。看来他已经完全掌握了这个方法，大家为他的表现鼓掌。\u003c/p>\u003cp>\u003cstrong>【简短有力结语】\u003c/strong>\u003c/p>\u003cp>今天我们学习了《搞定I：无压工作的艺术》这本书中的两个拆页，学习了管理承诺的三个步骤和自然计划法的四个步骤。管理承诺的三个步骤，让我们清空大脑，排除干扰，减轻焦虑。自然计划法的四个步骤可以帮助我们在做一个项目或复杂事情之前，理清思路，制订一个具体的行动计划。\u003c/p>\u003cp>\u003cstrong>【强有力的结语】\u003c/strong>\u003c/p>\u003cp>相信大家通过今天的学习，体会到GTD方法强大之处了。想过上无压高效的生活，来读这本书就对了。今天的学习，到这里就结束了，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1723728946000,"updated_at":1725868367000,"ria":true},{"id":17452,"topic":"释放大脑压力、有效规划下一步，让你轻松活在当下，稳步推进梦想","learn_goal":"","remark":"你是否脑海盘旋很多事情？时常感到焦虑、不安、压力？\n你是否不知如何开展事情？想法空中楼阁，找不到抓手？\n那么今天我们学习一下“释放大脑压力、有效规划下一步”，让你释放大脑压力、有效规划下一步，让你轻松活在当下，稳步推进梦想","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"1405-吴先昇教练-庄宇亮","city":"杭州市"},"club":{"name":"杭州雷峰塔筹备分舵","city":"杭州"},"prologue":"\u003cp>【开场自我介绍】\u003c/p>\u003cp>大家好，我的名字是庄宇亮，庄子的庄，宇宙的宇，亮晶晶的亮，你可以想象成庄子在宇宙发光发亮，这样你就记住了。\u003c/p>\u003cp>我有三个标签，公务员，小说家，早起践行者。\u003c/p>\u003cp>今天我要过的是TF2-4，用时50-60分钟。\u003c/p>\u003cp>主题是:释放大脑压力，有效规划下一步。\u003c/p>\u003cp>【学习目标1】通过本次拆页1学习后，学习者能在现场运用“释放压力”三步骤 \u003cstrong>明确预期结果、制定行动计划、设置提醒系统\u003c/strong>，能在现场将大脑中的待办事项写成清单，从而减轻记忆负担。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>待会儿我们会有小组讨论环节，我以我左手为一组，右手为一组，分为三组，最边上的两个人为一组，根据现场情况灵活分组。\u003c/p>\u003cp>【图书介绍】1分钟\u003c/p>\u003cp>今天的拆页选自《搞定I：无压工作的艺术》\u003c/p>\u003cp>【F特征】\u003c/p>\u003cp>本书作者是戴维艾伦，是一位享誉全球的时间管理以及提高工作效率方面的顶尖专家，本书系统讲解了GTD(Getting Things Done)的时间管理方法，帮助全球千万读者掌握它搞定个人事务和工作，书中内容都是作者20多年在时间管理实战方面的宝贵经验提炼。\u003c/p>\u003cp>【A优势】\u003c/p>\u003cp>那这本书是很多同类时间管理方法的鼻祖，与其他同类时间类相比，书中的方法非常具有实操性，拿来就能用，比如列清单法，而且方法具有普适性，国内很多应用都是来源于GTD方法，比如番茄钟等软件。\u003c/p>\u003cp>【B1利益】\u003c/p>\u003cp>学习完拆页1如果你日常工作生活，总是效率低下，进展缓慢，建议你读读本书，学一下GTD时间管理方法，通过正确的运用，帮助我们减轻压力，提高效率，升职加薪。\u003c/p>\u003cp>【B2利益】\u003c/p>\u003cp>学习完拆页2，能帮助我们整理安排出大脑中纷繁复杂的事务，从而帮大脑减轻压力。\u003c/p>","ratings_count":2,"texts":[{"id":21630,"quote":"\u003cp>【阅读原文片段】 \u003c/p>\u003cp>片段来源：《搞定I：无压工作的艺术》P62-63页\u003c/p>\u003cp>为什么有些事情总是萦绕在你的心头在通常情况下，你对一些事情总是念念不忘，这是因为你希望它们的状况能有所改善，另外:\u003c/p>\u003cp>.你还没有明确地认定它们的预期结果是什么。\u003c/p>\u003cp>.你还没有确定你下一步的具体行动到底是什么。\u003c/p>\u003cp>.你还没有把关于预期结果和即将采取行动的提示信息存入你所依赖的系统中去。\u003c/p>\u003cp>持续不断且毫无成效地深陷于我们不得不处理的事务当中，是对时间和精力的最大浪费---克里·格利森.\u003c/p>\u003cp>这就是为什么你忘不掉这些事情的原因了。直到你澄清了所有问题，做出一切必要的决定，并把预期结果保存到那个系统中去(同时要确保你能在必要情况下随时访问和查询这个系统)，你的大脑才会放松下来。你可以骗过别人，但是你却无法愚弄自己的大脑。它能够明察秋毫: \u003cstrong>你是否已经做出了必要的决定，是否已经把有关预期结果和行动的提示信息寄存于一个安全可靠的地方,以便这些信息能在恰当的时候提醒你采取行动\u003c/strong>。\u003c/p>\u003cp>如果你没有做好这些工作，那么，你的大脑就一分钟也不会停止运转。通常情况下，当你对某件事还没有依照上述的处理方法处理时，你的某根神经仍然会持续不断地对你施加压力，这只会增加你的精神负担。\u003c/p>","explains":"\u003cp>【I拆书家讲解引导】（细化行动步骤）\u003c/p>\u003cp>【\u003cstrong>what\u003c/strong>】这个拆页告诉我们我们大脑中为什么总是魂牵梦绕一些事务，这会给我们造成了压力，我们只需要把他们搬出我们的大脑，这样就能减轻我们的焦虑。\u003c/p>\u003cp>【\u003cstrong>why\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>（一般的做法）\u003c/strong>\u003c/p>\u003cp>我们回想一下看看，我们在工作生活中，是不是经常有非常多的事情碰到一起，我们正在做这件事情的同时，脑子里还是在想另外一件事，这种情况有没有？\u003c/p>\u003cp>\u003cstrong>（不这样做的坏处）\u003c/strong>\u003c/p>\u003cp>可想而知，这样的一心二用，一心三用，不但提高不了工作效率，而且加大了我们的压力焦虑。\u003c/p>\u003cp>\u003cstrong>（这样做的好处）\u003c/strong>\u003c/p>\u003cp>如果我们把这些事情搬出我们的大脑，那么我们就能更好的活在当下，提高效率，减轻精神压力，轻装上阵，迎接挑战\u003c/p>\u003cp>【\u003cstrong>举个反例\u003c/strong>】\u003c/p>\u003cp>举我自己的一个例子，我工作之外空余时间如果有的多的话，我想在顾好家庭的前提下，系统的全方面的提升一下自己多方面的能力水平，例如：学习一下投资理财，学习一下拆书技艺，学习一下副业方面知识，学习一下如何创建自己一套知识课程，学习一下心理咨询师相关知识，学习打造个人品牌。\u003c/p>\u003cp>哈哈，其实你也看到了，我思维真的挺活跃的，可恰恰是这个活跃，让我挺焦躁不安的，这些“悬而未决”的事项一直在我的脑海中积压，让我持续困扰，美好愿望只是一个愿望而已了。\u003c/p>\u003cp>【根据原文信息提示和线索】\u003c/p>\u003cp>我尝试去这样来解决：\u003c/p>\u003cp>1你还没有明确地认定它们的预期结果是什么。\u003c/p>\u003cp>那我就明确预期结果。\u003c/p>\u003cp>2你还没有确定你下一步的具体行动到底是什么。\u003c/p>\u003cp>那我就明确下一步具体行动。\u003c/p>\u003cp>3你还没有把关于预期结果和即将采取行动的提示信息存入你所依赖的系统中去。\u003c/p>\u003cp>那我就预期结果和即将采取行动的提示信息存入我的待办事项专用本子里去。\u003c/p>\u003cp>【举个正例】\u003c/p>\u003cp>把所有脑子里纷繁的事项，从脑力里“请出去”，专门找一本待办事项本子，按照一个大致时间线，一类类的放进去，争取今年全部开花结果。\u003c/p>\u003cp>\u003cstrong>投资理财\u003c/strong>的话，我明确目标就是把所有钱都给我老婆，让她去管理，一般她都会去买基金，钱虽然不多，但很稳。下一步就是每月工资一到账，分80%都给我老婆。\u003c/p>\u003cp>\u003cstrong>学习拆书技巧\u003c/strong>的话，目标就是获得三级拆书家证书，下一步就是平均每周一拆。\u003c/p>\u003cp>\u003cstrong>学习心理知识\u003c/strong>，目标就是获得心理咨询师证书，下一步就是报一个培训班，争取今年拿出。\u003c/p>\u003cp>\u003cstrong>学习打造个人品牌\u003c/strong>的话，预期结果就是今年出一门网络微课，下一步就是进行一次主题式的阅读，把知识体系整理好。\u003c/p>\u003cp> 这样，我在做一件事情的同时，更能活在当下，享受其中，不会被其他的待办事项打扰，这些“悬而未决”的事情也不会让我感觉到焦虑，因为所有的事项，都是井然有序，稳步推进的，让我更加有信心，有目标去完成接下来的挑战！\u003c/p>\u003cp>【\u003cstrong>how\u003c/strong>】好了，根据以上自我案例剖析，我们可以得到以下3个步骤，我称为“释放大脑压力”三步骤。\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>明确预期结果。\u003c/strong>比如我想提高“拆书”水平，那么明确的预期结果就是取得三级拆书家的证书。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>制定行动计划。\u003c/strong>计划采取怎么样的行动来支持这个预期结果，需要花多长的时间，使用那些步骤来实现，列一份大致可行的行动下一步计划。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> \u003cstrong>设置提醒系统。\u003c/strong>我们可以把前面二步的预期结果和行动计划，写下来，比如写在一张纸上，列出待办清单，今日待办，或者设定一个小闹钟等等形式，把这些写出来或者澄清说明一下，这样相当于从大脑清空出来，留出内存，把这些“悬而未决”的事情，有一个妥善的安排。\u003c/p>\u003cp>【\u003cstrong>where\u003c/strong>】\u003c/p>\u003cp> 减压三步法，主要原理不在于把事情安排的多完美，而在于你把它写下来，有个大致可行的方案，从而让大脑减轻压力。\u003c/p>\u003cp>特别说明，减轻压力三步法适合不同尺度的时间范围，可以是在一天内的事情，也可以是一年范围，或者是几年之内需要完成的事情。\u003c/p>\u003cp>\u003cstrong>适用场景\u003c/strong>：对你来说重要但拖延的事情，紧急且在一段时间内需要处理完毕的，你关心的，你关注的，你需要在未来去完成的事情。比如项目赶工日期截止，关乎于未来前途的职业技能，一段有待修复的感情，当天需要完成的各种事项等等。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有些小伙伴会问，你这个“减压三步法”不就是把任务都写下来，这有什么难的？\u003c/p>\u003cp>\u003cstrong>拆书家反馈\u003c/strong>：嗯，的确，步骤看上去确实很简单，人尽皆知，\u003c/p>\u003cp>但为什么要这样，背后被忽视的深层认知，其实才是这个拆页的真正魅力所在。\u003c/p>\u003cp>这就涉及到一些脑科学原理，我们的大脑是用来思考的，不是用来储存杂七杂八的事情的。我们需要把储存和思考分开使用。\u003c/p>","interaction":"\u003cp>【A1激活经验-拆为己用：提出一个显像问题】\u003c/p>\u003cp>好了，刚才我讲解了这个片段，也分享了自己的一个经历，相信大家在过去的时间里，也有同样需要解决的事情却迟迟没有处理，大脑还时不时的回想起来，造成压力。\u003c/p>\u003cp>比如：\u003c/p>\u003cp>1.公司职工在单位上班，任务接着一件又一件下发，几乎快堆成山，手头坐着一件事，脑中想着却是另外一件，压力很大。\u003c/p>\u003cp>2.想学习一些新的技能，却因为工作生活各种琐事，一直压在那边没有去做，也没有对其有个回应。\u003c/p>\u003cp>3.想找一个配偶对象，却一直没有开始去做？朋友、亲戚却在旁边催催催。\u003c/p>\u003cp>4.想利用空余时间，给自己充电，早点拿出职业技能资格证书，加薪升职，却被生活中各种烦心事，给延误了。\u003c/p>\u003cp>\u003cstrong>给大家1分钟的时间讨论一下，请在小组讨论分享一下近阶段脑海中时不时弹出来，让你感觉到焦虑的事情。\u003c/strong>\u003c/p>\u003cp>【\u003cstrong>学习者案例\u003c/strong>】\u003c/p>\u003cp>王飞：最近的事情让我焦虑的事情确实挺多的，梳理一下会发现，想要学习拆书家，家里有个大孩子需要中考，小孩子也要管，而且9月份工作也会有变动，需要我去准备，还要练瑜伽，就像很多事情就等着我去做。\u003c/p>\u003cp>【A1+反思加工】\u003c/p>\u003cp>好的，我们刚才听了几位小伙伴的分享，看样子，大家基本上都有过脑海中“悬而未决”的事情，给大脑造成了压力，而且还不是少数，\u003cstrong>那么如果时光倒流的话，你将如何用今天学习的“减压三步法”来释放大脑压力呢？（刚才的自己的失败案例）\u003c/strong>\u003c/p>\u003cp>（分组）好，我给大家分一下组，给大家花1-2分钟请在小组内与小伙伴们分享讨论。2分钟后我们会请1-2位小伙伴来跟大家分享（具体分组情况根据现场人数来定）\u003c/p>\u003cp>【\u003cstrong>学习者案例\u003c/strong>】\u003c/p>\u003cp>王飞：我有点不太理解具体要做什么事。\u003c/p>\u003cp>拆书家引导：刚才所有你之前想要做的事情，首先我们要去明确一个结果。\u003c/p>\u003cp>王飞：这么多的事情都要去明确吗？\u003c/p>\u003cp>其他已经懂得方法的学习者：就是这么多的事情，比如说你要练瑜伽，教小孩，工作呀。\u003c/p>\u003cp>王飞：那我先把拆书家这个事情给做好，因为我感觉这是我最有兴趣，最想要去做的一件事情。\u003c/p>\u003cp>拆书家引导：那你拆书家要达到一个怎么样的段位或者结果？是三级，二级，还是一级拆书家？\u003c/p>\u003cp>王飞：是不是三级是最高，那我就来个初级吧。（\u003cstrong>明确预期结果\u003c/strong>）\u003c/p>\u003cp>拆书家引导：那就设置一级拆书家吧，那你的下一步行动计划是什么？\u003c/p>\u003cp>王飞：那就积极参加拆书家活动，在日常工作生活中把学习到方法都应用起来。\u003cstrong>（制定行动计划）\u003c/strong>\u003c/p>\u003cp>拆书家引导：那你怎么提醒你自己呢？\u003cstrong>（设置提醒系统）\u003c/strong>\u003c/p>\u003cp>王飞：那就用提前设置闹铃吧，不要错过拆书家过级活动。\u003c/p>\u003cp>拆书家：嗯，可以的，看样子在互动中，你已经把这个方法给掌握了，真的非常棒！\u003c/p>\u003cp>【解答学习者疑惑】\u003c/p>\u003cp>阳元生：我问一个问题，就是有时候制定了行动结果，也制定了行动计划，那最后没有行动怎么办？\u003c/p>\u003cp>拆书家：那这个问题提的非常的棒，那接下来就是进入拆页二的片段，咱们继续去深入学习。\u003c/p>\u003cp>阳元生：好的，非常期待。\u003c/p>\u003cp>拆书家：那我继续讲了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":21631,"quote":"\u003cp>【过渡】\u003c/p>\u003cp>现在我们已经学会了，借助“释放压力”三步骤，来释放我们大脑压力，减轻焦虑，可是当你真正着手去做的时候，发现根本无法行动，原因是什么呢？其实有时候我们根本没有一个具体可实际的下一步具体行动，找不到一个落脚点和抓手，如何找到具体可实际的下一步行动规划呢？下面，我们一起进入拆页2的学习。\u003c/p>\u003cp>【学习目标2】通过本次拆页2的学习后，学习者能在现场运用“规划下一步”三步骤\u003cstrong>制定目标、分解目标、落地执行\u003c/strong>，找到具体实际可行的下一步行动，方便课后把事情按照最小分解步骤推动起来，从而取得进展。\u003c/p>\u003cp>【逻辑关系】\u003c/p>\u003cp>本次两个拆页呈递进关系。\u003c/p>\u003cp>【阅读原文片段】 1分钟\u003c/p>\u003cp>通常情况下，由于我们没能对下一步行动作出最后的判断，即使那些最简单的事情也会被耽搁。我的学员经常会在清单上列出这样的条目：“调整汽车发动机”。难道“调整发动机”是下一步行动吗？当然不是这样，除非当你穿上工作服，手持工具走进车库，亲自实施调整发动机的行动，否则一切都是徒劳。\u003c/p>\u003cp>“那么，下一步行动是什么呢？”\u003c/p>\u003cp>“我得把汽车送到修理厂去。是的，我需要弄清楚修理厂能不能处理，我想我要给他们打个电话，约个时间。”\u003c/p>\u003cp>“你有电话号码吗？”\u003c/p>\u003cp>“呀，没有…….那个修理厂是弗雷德向我推荐的，但我不知道它的名称和电话号码。我知道了，我还缺少一些信息。\u003c/p>\u003cp>通常，这是最普遍的情况。扫了一眼这项工作后，我们会不由自主的想，“我还没有获取全部的信息。”我们知道有所缺失，但又无法确定到底是什么，因此我们就退却了。\u003c/p>\u003cp>“那么，下一步做什么呢？”\u003c/p>\u003cp>“我需要弄到它的名称和电话号码。我猜，我可以从弗雷德那里拿到。”\u003c/p>\u003cp> “你怎么做到呢？”\u003c/p>\u003cp> “我可以给弗雷德发电子邮件！”\u003c/p>\u003cp>\u003cstrong>因此，真正的下一步行动是“给弗雷德发电子邮件，问一下修理厂的情况”。\u003c/strong>\u003c/p>\u003cp>你是否注意到了，在我们判断出下一步行动方案前，需要经过几个步骤呢？这种情况非常典型。在大多数人的清单和大脑里，列出的都是类似的事情，而不是具体的下一步行动。\u003c/p>","explains":"\u003cp>【I拆书家讲解引导】\u003c/p>\u003cp>细心的小伙伴们，大家有没有观察到，其实我们这个拆页就是上一个拆页第二个步骤的细化学习。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>有些时候，造成我们拖延的原因，并不是因为我们不知道怎么做，往往只是因为我们的下一步行动计划不够具体可操作，造成事情根本得不到有效的推动。\u003c/p>\u003cp>【what】那这个拆页告诉我们，我们需要不断的问自己下一步行动计划是否能马上实施，就能最终找到关键可落地的下一步。\u003c/p>\u003cp>下面的话，我们来一个小互动，一个扮演小强，一个扮演教练。\u003c/p>\u003cp>【\u003cstrong>意译原书案例\u003c/strong>】（更贴近实际的案例）\u003c/p>\u003cp>【旁白】通常情况下，由于我们没能对下一步行动作出最后的判断，即使那些最简单的事情也会被耽搁。小强为了找到女朋友，经常会在清单上列出这样的条目：“健身房健身”。\u003c/p>\u003cp>【教练】难道“健身房健身”是下一步行动吗？当然不是这样，除非当你穿上健身服，手持健身包走进健身房，亲自开始健身的行动，否则一切都是徒劳。\u003c/p>\u003cp>【教练】“那么，下一步行动是什么呢？”\u003c/p>\u003cp>【小王】“我得亲自去一堂健身房。是的，我需要弄清楚需要制定怎么样的健身计划才能达到彭于晏那样的身材，我想我要找一个优秀健身教练。”\u003c/p>\u003cp>【教练】“你有自己认识的比较厉害的健身教练吗？”\u003c/p>\u003cp>【小王】“呀！没有....但我一个朋友小红好像去年从200斤减到150斤，曾经向我推荐过一位健身教练，而且健身房就在这附近，但我不知道健身房具体的地址和教练的联系方式。”\u003c/p>\u003cp>【旁白】通常，这是最普遍的情况。扫了一眼这项工作后，我们会不由自主的想，“我还没有获取全部的信息。”我们知道有所缺失，但又无法确定到底是什么，因此我们就退却了。\u003c/p>\u003cp>【教练】“那么，下一步做什么呢？”\u003c/p>\u003cp>【小王】“我需要找到健身房地址，并与教练取得联系，并制度科学合理的健身计划。我猜可以从小红口中获得实际地址，并听取他的减肥经验和大致健身费用，并取得教练的联系方式。”\u003c/p>\u003cp>【教练】“你怎么做到呢？”\u003c/p>\u003cp>【小王】“我可以马上给小红打一个电话”\u003c/p>\u003cp>【旁白】因此，真正的下一步行动是“给小红打一个电话，问一下健身的相关信息”。\u003c/p>\u003cp>【旁白】你是否注意到了，在我们判断出下一步行动方案前，需要经过j几个步骤呢？这种情况非常的典型。在大多数人的清单和大脑里，列出的都是类似的事情，而不是具体的下一步行动。\u003c/p>\u003cp>【how】\u003c/p>\u003cp>“规划下一步”三步法\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>制定目标。\u003c/strong>确定你要完成的目标或者遇到什么困难。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>分解目标\u003c/strong>。找出你认为需要做的下一步，并分析是否可以马上着手去做，如果不行，分析一下为什么，查找缺少信息，并找出原因，然后基于这个原因，规划出下一步。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> \u003cstrong>落地执行\u003c/strong>。直到这个行动不能再次被分解，足够清晰足够有条件去完成，那么这一步，才是真正有效的下一步，然后着手去做就行，推动事情发展。\u003c/p>\u003cp>【举个例子】\u003c/p>\u003cp>举个例子说明一下怎么做？我需要做的事情是成为一名心理咨询师（\u003cstrong>制定目标\u003c/strong>）。\u003c/p>\u003cp>我认为的下一步是报一个培训班\u003cstrong>（分解目标）\u003c/strong>，\u003c/p>\u003cp>下一步的行动计划是什么？\u003c/p>\u003cp>网上查询各个培训班的实际情况，需要价格合适，课程精良\u003c/p>\u003cp>但实际查询结果是培训班鱼龙混杂，价格有高有低，不能确认哪家才是最好的。\u003c/p>\u003cp>下一步的行动规划是什么？\u003c/p>\u003cp>问一个已经实际通过心理咨询师的朋友。\u003c/p>\u003cp>能直接做吗？\u003c/p>\u003cp>可以，马上打电话给他，问他当时报的是哪个培训班，大概价位是多少？\u003c/p>\u003cp>\u003cstrong>（落地执行）\u003c/strong>所以行动的下一步就是打电话给朋友，先确认大致价位以及他报的班级是什么，作为自己的一个选择依据，一个参考。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>\u003cstrong>适用场景\u003c/strong>：当你开展一项比较大的事项或者从来没有做过的事，不熟悉的事，内心充满迷茫，完全没有头绪，不知道该如何开展。\u003c/p>\u003cp>\u003cstrong>不适用场景\u003c/strong>：已经熟能生巧，甚至是养成了习惯，闭着眼睛都不用想下一步，比如说，起床后刷牙洗脸，或者是非常熟悉的事情，没有必要去想下一步。\u003c/p>","interaction":"\u003cp>【A3现场演练】\u003c/p>\u003cp>刚刚我们学习了“规划下一步”，现在大家一起来做一个现场演练，请大家认真听一下要演练的场景：\u003c/p>\u003cp>【场景】小王的孩子，今年读幼儿园中班，刚好暑假，可是一天到晚就直到拿奶奶的手机，看各种短视频，而且还不亦乐乎，小王直到问题的关键在于，自己小孩不知道空余时间应该作什么，但一直拖延解决这个问题，经朋友推荐，请教了一位世外高人夏总。\u003c/p>\u003cp>（分组）好，我给大家分一下组，给大家花5分钟请在小组内与小伙伴们分享讨论。\u003cstrong>5分钟后我会邀请2位小伙伴来跟大家演练，一个扮演夏老师，一个扮演小王，让夏老师利用“规划下一步”教会小王，如何做出真正有实质性的行动，慢慢推动这个事情，让事情得到进展。\u003c/strong>（具体分组情况根据现场人数来定）\u003c/p>\u003cp>【\u003cstrong>学习者现场演练\u003c/strong>】\u003c/p>\u003cp>王飞扮演小王，郭慧娟扮演夏老师\u003c/p>\u003cp>【小王】夏老师，现在是这样子，我们小朋友每天放学就在家里玩手机，我们能不能把这个情况给扭转一下？\u003c/p>\u003cp>【夏老师】这个当然我们是可以扭转的，首先我们可以跟孩子商讨一下，制定一个目标，就是他必须去运动，也可以选择阅读，当然也可以选择其他爱好的兴趣班什么的。这个由孩子来定，我们要跟孩子非常平等的去沟通，然后下来举个例子，如果孩子是想学小提琴的话，我们要制定一个目标，那么我们下一步就是要去找一个老师，然后跟老师谈学习的时间，然后是分解目标，我们什么时候去学，大概学多长时间，要跟孩子平等的去沟通，沟通好之后，我们就可以去执行，时间到了，我们就带他去学习小提琴，这样子。\u003c/p>\u003cp>【小王】嗯，大概了解了，我看我们家小孩子比较喜欢运动，但是我平时没有时间，要不给他找个培训班吧！\u003c/p>\u003cp>【夏老师】对，给他找个培训班吧，或者给她找个同样喜欢运动的小朋友，组队，大家可以相互的陪伴。\u003c/p>\u003cp>【小王】嗯，我想一下，“天天”小朋友喜欢运动，那我就叫天天吧，叫奶奶一起带他去。\u003c/p>\u003cp>【夏老师】对对对，还得有这一步。\u003c/p>\u003cp>【拆书家引导】那你现在可以跟“天天”家长打个电话了，马上问一下。\u003c/p>\u003cp>【拆书家分析】我感觉刚才两位的分享都非常的到位，角色扮演的都非常形象，“规划下一步”的123三步都有提到和运用起来。\u003c/p>\u003cp>【A2分步催化1-场景激活】\u003c/p>\u003cp>下面请大家考虑一下，在未来几个月内，或者今年内，在你的工作生活中，是否存在一些比较棘手的事项需要去处理。\u003c/p>\u003cp>在这里我提醒一下，这个环节，我们只需要分享场景就可以了，不需要分享怎么做。3分钟后我会邀请1-2名小伙伴来跟我们分享一下自己的经历。\u003c/p>\u003cp>这边，我简单的举几个例子\u003c/p>\u003cp>1.工作中所需要的职业技能，考证\u003c/p>\u003cp>2.兴趣爱好类，学尤克里里，练毛笔字\u003c/p>\u003cp>3.想要在今年2023年成为三级拆书家\u003c/p>\u003cp>4.想要寻找人生的另外一半\u003c/p>\u003cp>【\u003cstrong>收集学习者案例\u003c/strong>】\u003c/p>\u003cp>郭慧娟：我想要今年买一辆车子，因为我驾照已经考了快4年了。\u003c/p>\u003cp>木英：我想要在新的公司，组建一个新的部门组织部。\u003c/p>\u003cp>拆书家回应：不错，跟政府部门有类似的结构，也有一个叫组织部的。\u003c/p>\u003cp>王飞：我想要让自己家小朋友在班级里平均分考第一名。\u003c/p>\u003cp>拆书家回应：不错，有梦一定会实现，加油！\u003c/p>\u003cp>阳元生：我想一下，我要讲哪一个，成为一个三级拆书家，还有今年要成功做出一个直播课，在杭州产业之家，给一次公益的培训师。\u003c/p>\u003cp>阳元生朋友：我想今年成功转正，进入大厂。\u003c/p>\u003cp>细民子：参加一次自行车比赛吧！\u003c/p>\u003cp>【A2分步催化2-具体应用】\u003c/p>\u003cp>刚才小伙伴想出了未来想要实现的种种目标，那么现在请大家再继续思考一下，在刚才大家分享的案例当中，我们如何用今天所学的“规划下一步”来走出真正有效的下一步呢？\u003c/p>\u003cp>（分组）好，我给大家分一下组，给大家花1-2分钟请在小组内与小伙伴们分享讨论。5分钟后我们会请1-2位小伙伴来跟大家分享（具体分组情况根据现场人数来定）\u003c/p>\u003cp>简单回顾：“规划下一步”。\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>制定目标。2.分解目标\u003c/strong>。\u003cstrong>3.落地执行\u003c/strong>。\u003c/p>\u003cp>【\u003cstrong>收集学习者案例\u003c/strong>】\u003c/p>\u003cp>阳元生：我有一个目标，就是我在做青年社群，然后这个KPI是要招70个付费成员，就是1799的课程，现在遇到的就是招新成员（制定目标），我现在负责的有全国7-8个省（\u003cstrong>分解目标\u003c/strong>），那么这周的话，我就主抓3个省（\u003cstrong>分解目标\u003c/strong>）分别是天津、四川、江西，所以呢，下一步行动就是江西50，天津70，四川50个人，今天晚上分别就是给负责人打个电话（\u003cstrong>落地执行\u003c/strong>），去给他规划一下下一步的行动计划，把成员的表格更新一下，拉到一个新的付费群里，让新成员加上自己的微信。\u003c/p>\u003cp>拆书家回应：嗯，非常的棒，非常的具体清晰，大家给他鼓掌！\u003c/p>\u003cp>梦想非常的厉害，而且方法一步步的分解下来，都是非常的能落地执行。只要你晚上把这件事情推动起来，那么这三个省100多个付费学员，一定是能实现，那你就要去执行，不要看它简单，但如果你找到真正有效推动下一步的行动，那你肯定是让事情不断往前发展的，直到完成你的梦想。\u003c/p>\u003cp>木英：我今年的梦想就是搭建一个组织部，那么我现在开始分解目标，因为我对组织部一点都不了解，首先我想盘点一下我身边有哪些人是政府部门的同学或者是工作的，然后就是跟他们打一个电话，了解其中的工作机制是怎么样的，同时也是跟他们请教一下，这是我的分解目标，那么我的落地执行就是盘点哪些是政府部门的，然后开始打电话。\u003c/p>\u003cp>拆书家回应：相信你通过应用这个三步法，相信你的组织部一定会更加详细。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>感恩大家接近1个小时的陪伴，接下来，我们回顾一下，刚才我们学习了“释放压力”三步骤和“规划下一步”三步骤，让大脑减轻记忆负担，有效规划下一步。\u003c/p>\u003cp>“释放压力”三步骤是：\u003cstrong>明确预期结果、制定行动计划、设置提醒系统\u003c/strong>；“规划下一步”三步骤：\u003cstrong>制定目标、分解目标、落地执行\u003c/strong>。两者结合，这样能够帮助实现没有压力的工作状态，同时有效推进下一步进程。\u003c/p>\u003cp>最后用一句话结束今天的分享：\u003c/p>\u003cp>\u003cstrong>万里之行始于足下，让我们轻装上阵，奔赴梦想！\u003c/strong>\u003c/p>\u003cp>感谢聆听！谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1711617026000,"updated_at":1712847852000,"ria":true},{"id":17397,"topic":"学习自然计划模式   ","learn_goal":"","remark":"用最小的消耗获得最大的回报","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"宁静@微光","city":"廊坊市"},"club":{"name":"廊坊风陵分舵","city":"廊坊"},"prologue":"\u003cp>大家好，我是宁静，三个标签介绍自己\u003c/p>\u003cp>教育工作者：38年教育经历\u003c/p>\u003cp>瑜伽修炼者：15年瑜伽练习\u003c/p>\u003cp>阅读分享者：二级拆书家\u003c/p>\u003cp>今天我带领大家共同学习的主题是：学习“自然计划模式”，以最小消耗，创造最高的价值。主题来自《搞定》这本书\u003c/p>\u003cp>为了更高效地学习，咱们分下组，顺时针两人一组\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>大家通过今天的学习，能够运用“自然计划模式”的5个步骤，写出一个具体事项的完整计划，体验到如何以最小的消耗，创造最高的价值。\u003c/p>","ratings_count":1,"texts":[{"id":21581,"quote":"\u003cp>\u003cstrong>【R原文片段】\u003c/strong>\u003c/p>\u003cp>一个简单的事例：计划出去吃饭 (实体书：84-86页；电子书：96-98)\u003c/p>\u003cp> 你上一次出去吃饭时，最初的动机是什么？原因可能有很多：因为饥肠辘辘，或是朋友之间的社交活动，为了庆祝某一个特殊的日子，签订一笔生意的合同，又或是为了谈情说爱。只要是出于上述的某一个原因，你就可以马上开始进行计划了。你的意愿就是你的目标，它自然而然地启动了你内心深处的计划过程。同时，你的原则规定了你所做计划的界限。可能你自己并未意识到外出就餐原则的存在，但是你的思维却从来没有逾越这些原则：食物和服务的标准、支付能力、方便程度以及舒适度。无论如何，在制订计划时，你的目标就是你的动机，而原则又限定了你的计划。\u003c/p>\u003cp> 一旦做出决定要实现这一目标，那么首先进入你脑海的实质性问题是什么呢？恐怕不是“计划、第二部分、第1点、第3小点”吧。你的第一批想法很可能是这样的事情，如“在餐厅吃意大利风味的晚餐”，或者 “在比斯特罗咖啡馆街边的桌旁坐一坐”。你很可能还会想象出晚餐时的一些美好体验，或者设想一下晚餐的结局，也许你还想到了共同吃饭的人、就餐气氛什么的，这就是你的结果展望。当外出就餐的原因成为你的目标时，对晚餐进行的种种想象就是你的展望。\u003c/p>\u003cp> 一旦认同了这种展望，你的大脑便会自然而然地开始想一些问题：我们应该几点出发？这家餐馆今天晚上营业吗？人会不会很多？ 天气怎么样？是不是应该换身衣服？汽油还够吗？现在饿不饿？这就是头脑风暴。一旦承诺要达到某一目标，那么在达到之前，你就会身不由己地向自己接二连三地发问。这些问题是这个创造性过程的一个组成部分。当大脑意识到在你设定的目标和你目前的状况之间存在着一定的差距时，它会千方百计地弥补这一差距，以消除这种“认知失调”。这就是自然计划法中“如何……”这一思考阶段的起始点。但是，这种思考模式显示出了一定的随意性，因为你会想到有关外出就餐的方方面面的事情。当然，你不一定把所有浮现在脑海里的事情逐一地写入“简式计划”，但是，你的大脑确实经历了类似的过程。\u003c/p>\u003cp> 一旦头脑里装满了大量的想法和细节，你也就不由自主地开始了组织整理的工作。你可能会这样想，“首先，我们需要弄清楚那家餐厅是否营业”，或者“我们给安德森一家打个电话，看看他们是否愿意同我们一起出去吃晚饭”。一旦你对相关的结果产生了各式各样的想法，大脑就将自动根据事情的组成要素、重要程度和事件发展的先后顺序， 分门别类地进行归纳整理。组成要素是指“我们要考虑出行、人员和地点方面的事宜” ，重要程度是指“搞清楚大家是否愿意外出就餐是非常关键的”，先后顺序是指“首先，我们需要确认那家餐厅是否营业，然后给安德森一家打电话，接着更衣准备外出”。就其本质而言，这正是包含挑战、比较和评估的自然规划过程。事项的优越性、重要性和紧迫性的凸显是非常自然的过程。最后（假如你决定要进行这个项目 —— 以出去吃晚饭为例），为了确认首要的因素，你需要把注意力放在具体的下一步行动上。“给巴黎红咖啡馆打个电话，问问那里是否开门，然后预订一下座位。\u003c/p>","explains":"\u003cp>\u003cstrong>【A1技能点：量表自测法】\u003c/strong>\u003c/p>\u003cp>在学习之前，我们先来做个小测试，这里有5道自测题，请仔细阅读表中的每句话判断与自己是否符合，1分完全不符合，6分完全符合，最后算出总分。\u003c/p>\u003cp> 自然计划模式自测题 完全不符合----》完全符合\u003c/p>\u003cp>1. 我做事情前，会先问自己为什么做，最这件事的意图是什么。 1 2 3 4 5 6\u003c/p>\u003cp>2. 我做事情前，会先想象出做完这件事的画面，且可以清晰描述。 1 2 3 4 5 6\u003c/p>\u003cp>3. 我做事情前，会把所有那些有可能影响到预期结果，而又必须加以考虑的情况，全都摆在桌面上。 1 2 3 4 5 6\u003c/p>\u003cp>4. 我做事情前，可以把天马行空的想法一一罗列出来，进行归类整理。 1 2 3 4 5 6\u003c/p>\u003cp>5. 我做事情前，可以把“大事”拆解为小事，明确哪些可以立即行动，谁来负责行动。 1 2 3 4 5 6\u003c/p>\u003cp>\u003cstrong>【I解释量表自测题】\u003c/strong>\u003c/p>\u003cp>这个自测表主要是帮助大家了解自己是否具有 “自然计划模式”。看看大家的分数，学员回答：10分、17分、20分……\u003c/p>\u003cp>如果在20分以上，恭喜你，已经具备了这种模式，纵向管理方面很优秀了，10-20分之间的说明有这种意识，但没有形成稳定的模式，如果在10分以下的也不用担心，任何一种思维模式都可以通过训练获得的，今天我们通过学习，相信您一定有所收获。接下来，我们来看看书中的有关片段，。 \u003c/p>\u003cp>请大家先花2分钟左右时间阅读，\u003c/p>\u003cp>\u003cstrong>【简短互动】\u003c/strong>\u003c/p>\u003cp>提问，大家阅读了这个片段，能否感觉到这是一种计划模式？这种计划模式和常规的计划模式有什么不同？\u003cstrong>学员回答：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学员A:从不知道这是一种计划模式\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学员B：这种计划模式和常规的计划模式相比，相同的点是都有目标，不同的是目标之后先想到的是愿景，而不是常规的实施目标的步骤，这种模式更有利于行动\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学员C：这种模式给人“随意”感，轻松感\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>这个片段通过“计划出去吃饭”这个小故事，具体演绎了事件在自然计划模式下“纵向管理”的完美应用。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>为什么要学习这种模式呢？这种模式在面对各种工作、环境和主题时，都能以最小的消耗创造最高的价值，正如大家刚才所说，有轻松感，犹如“灵光一现”，又因为先想到愿景，心生向往，进而推动行动力。起到事半功倍的效果。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>在大部分时间里，我们是需要常规的计划模式的。但为了更严格地控制某一项目、找出解决方案或者确保行动方案切实可行，我们就需要将精力聚焦在某个项目上，那“自然计划模式”更有效，换句话说，有时“灵光一现”的想法就是自然计划模式的开端。它来得更直接，更有行动力。\u003c/p>\u003cp>\u003cstrong>【How】\u003c/strong>\u003c/p>\u003cp>自然计划模式下，纵向管理的5个阶段\u003c/p>\u003cp>1、 定义目标和原则：为什么、标准和价值观\u003c/p>\u003cp>2、 结果展望：愿景，蓝图\u003c/p>\u003cp>3、 头脑风暴：集思广益、不批判，只重数量，把分析组织工作置于次要地位。\u003c/p>\u003cp>4、 组织整理：明确事情的组成部分，整理分类、先后顺序、重要程度，细节周到\u003c/p>\u003cp>5、 明确下一步的行动方案：立即行动，谁来行动。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>有的朋友会问，怎么区分这种计划模式和常规计划模式的区别？\u003c/p>\u003cp>这是一种非正式的思考，不是常规做法，不用兴师动众，依靠团队协同完成计划。作者用 “信封背面的计划”来形容自然计划模式，就像你和朋友坐在咖啡屋里，说到你们的日程安排或销售报告，你可能随时将想到的事罗列在信封背面或者餐巾纸上。这种计划看似随意自然，但思考很深入，行动力也很强，从想到到做到“一竿子到底”，很高效。减少大脑内耗，还容易成增强成就感。\u003c/p>\u003cp>\u003cstrong>【自己举例应用】\u003c/strong>\u003c/p>\u003cp>过年了，我想要组织一个家庭新年盛会\u003c/p>\u003cp>1、目标和原则目标：我的目的是创造一个温馨、和谐、充满欢笑的新年氛围，让所有家庭成员都感到幸福和满足。原则是：确保安全，尊重传统文化，注重家庭成员参与互动。\u003c/p>\u003cp>2、展望愿景：想象着家庭成员围坐在一起，分享着美食、攀谈着家庭趣事、同长辈们讲那过去的故事，才艺展示、欢声笑语、温馨的氛围。强调家庭团聚和传统文化的传承。\u003c/p>\u003cp>3、头脑风暴。把能想到的所有事项罗列一下，比如准备哪些用品、哪些小活动、节目，放鞭炮、场地、录制视频等。考虑老人的需求，确保节目适合所有年龄段。\u003c/p>\u003cp>4、组织整理。根据重要性和紧急性对节目进行排序。分配任务：大姐负责准备食物、二姐负责布置场地、大哥负责购买鞭炮等。\u003c/p>\u003cp>5、明确下一步行动方案：制定详细的时间表，活动前准备、活动进行的时间线。提醒家人提前准备和安排时间，我可以立即行动的是把我的设想通知到家人。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3情景演练】\u003c/strong>\u003c/p>\u003cp>为了大家更好地掌握“自然计划模式”的方法，下边我们做一个情景模拟演练，以小组讨论，3分钟后进行分享。\u003c/p>\u003cp>【模拟情景】：元旦前夕，工会主席小想项组织一次联欢活动，如果你是小王，如何以“自然计划模式”来制定元旦联欢会方案？（要具体描述）\u003c/p>\u003cp>第一组分享：\u003c/p>\u003cp>1.目标原则：用一定的资金达到最佳的欢乐效果。\u003c/p>\u003cp>2.愿景：每一位都能参与，每个人都有收获，都玩的开心\u003c/p>\u003cp>3.头脑风暴：如何实现愿景，每个人的喜好不同，如何解决众口难调的问题，可以采用无记名投票，多种形式类型并存，如朗诵类、演唱类、竞赛类，根据投票数量确定活动内容。\u003c/p>\u003cp>4.组织整理：思考如谁设计分发投票表格、谁收集梳理投票结果等等。\u003c/p>\u003cp>5．下一步行动：主席把以上设想交给工会秘书长，由他负责行动落实。\u003c/p>\u003cp>\u003cstrong>【A2布置任务】\u003c/strong>\u003c/p>\u003cp>感谢伙伴的精彩分享，大家是否感觉到这个模式说起来简单，做起来也是有一定难度的呢？有道是万事开头难，通过刻意练习一旦掌握了这个方法，就会事半功倍。因此我要给大家布置一个需要回去完成的小任务：\u003c/p>\u003cp>在接下来的一周内，请各位伙伴选择一个工作或者生活事件，运用自然划模式的5个阶段写出事件完整的计划全貌，并分通过微信私信给我或者直接发到咱们的学习群内，谢谢！\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>最后，让我们一起回顾下今天学习的内容：\u003c/p>\u003cp>自然计划模式下，纵向管理的5个阶段\u003c/p>\u003cp>1、定义目标和原则 \u003c/p>\u003cp>2、结果展望\u003c/p>\u003cp>3、头脑风暴\u003c/p>\u003cp>4、组织整理\u003c/p>\u003cp>5、明确下一步的行动方案\u003c/p>\u003cp>分享金句：通过行为让自己感觉良好，要比通过让自己感觉良好来实现行动容易得多。\u003c/p>\u003cp>祝愿各位伙伴学以致用，掌握“自然计划模式”，以最小消耗，创造最高的价值，让我们的生活工作变得更加美好。谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1710513883000,"updated_at":1710951402000,"ria":true},{"id":17206,"topic":"管理承诺的三个原则","learn_goal":"","remark":"管理承诺的基本原则，我们对自己和他人都有很多的承诺，如何让这些承诺更好的兑现呢？给大家介绍一个简单的方法，只要三个步骤。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"深圳林歌","city":"深圳市"},"club":{"name":"深圳智行分舵","city":"深圳"},"prologue":"\u003cp>大家好，我是林歌，用三张标签做个简单自我介绍，第一张：美丽天使（做医美项目）；第二张：万里河山代言人（做旅游卡项目）第三张唤醒者：唤醒自己家人朋更优秀更期待更欣喜的一面。现在给大家分个组，这边的伙伴为A组，这边的伙伴为B组。待会有小组分享环节。今天我要拆的级别是2-2，今天拆的书是《搞定》，通过今天我带领的拆页学习，大家现场学会运用三个法则应对内心承诺。\u003c/p>\u003cp>特征：《搞定》这本书豆瓣评分8分，作者\u003c/p>\u003cp>戴维·艾伦 (David Allen)，全球管理咨询公司戴维·艾伦有限公司的创始人及总裁。根据三十多年的咨询经验和个人探索，他提出GTD自我管理方法，介绍此方法的《搞定I》(Getting Things Done)一书已在33个国家出版。他被《福布斯》杂志评为美国最优秀的管理教练之一。\u003c/p>\u003cp>A优势：该书四百多页，论述和诠释非常详尽，各种方法背后原理也讲的很清楚，可以很清晰让我们了解为什么这么做的原因，也能掌握书中介绍的无压力工作法精髓。\u003c/p>\u003cp>B利益：利益1通过本书学习，学会GTD工作法，让我们减少工作生活事情繁多的压力，让我们有条不紊安排好事情的秩序，通过工具清空大脑，获得精力提高执行效率。\u003c/p>\u003cp>利益2，通过本片段学习，学会通过用三个法则来应对内心承诺。\u003c/p>\u003cp>接下来大家花两分钟阅读一下我发到大家的这段原文片段，看完抬头看我让我知道你看完了。\u003c/p>","ratings_count":1,"texts":[{"id":21376,"quote":"\u003cp>数十年来,我为数千人做教育训练,发觉了一项基本道理:大部分的压力都源自于他们对说出的承诺管理不当。在学会更有效控制「开放式回路」(open loops)的事情后,连原本没有意识到自己「压力过重」的人,都能明显感受到变得更轻松、注意力更集中,工作产能也有提高。\u003c/p>\u003cp>你做出的承诺(commitmt)可能比想象中还多,而无论承诺大小,人都会下意识持续追踪进度。这就是我所谓的「开放式回路」,定义是:拉走你的注意力,但是却还没决定要放在哪里或如何去做的这些事情。「开放式回路」的等级,可以大到像「根除全球饥饿」的大事业,也可以是「雇用新助理」这种比较一般的事务,甚至是「换走廊灯泡」之类的芝麻小事。\u003c/p>\u003cp>为了有效处理这些大小事,首先,你必须先辨认与捕捉试图引你注意的所有事。其次,理清它们对你的确切意义,接着再决定该如何采取行动。这个流程看似简单，但实际上大多数人都不会贯彻落实地执行。他们不是缺乏足够的知识或动机(或两者皆缺乏)。最大的可能是因为，他们没意识到这个流程没有确实执行要付出多大的代价。\u003c/p>\u003cp>管理承诺的基本守则\u003c/p>\u003cp>妥善管理承诺,需要落实几项基本行动:\u003c/p>\u003cp>首先，如果有一件事占据心思，你就无法定下心。只要你认定为「需要被完成」的任何事・就必须捕捉这件事情到头脑之外的可靠系统中，或者是放入「收集工具」(collection tool)中，并且频繁检视并整理。\u003c/p>\u003cp>其次，必须确实地理清你的承诺是什么，并决定你要做哪些行动，甚至订出实现该承诺的计划。\u003c/p>\u003cp>第三，一旦决定必须采取的行动,你必须在你频繁检视的系统中,组织并保存好这些行动提示讯息\u003c/p>","explains":"\u003cp>好的大家阅读完了原文片段，那现在由我来解读一下。\u003c/p>\u003cp>What：这个片段介绍了用三个法则应对内心承诺的重要性和具体步骤。\u003c/p>\u003cp>Why：因为大部分人的压力来源于对自己的承诺管理过当，有太多事情拉走我们的注意力，所以有必要以外部工具采用片段介绍的法则让我们减少遗忘而未能实现承诺的状况。\u003c/p>\u003cp>HOW：片段介绍了三个法则的步骤\u003c/p>\u003cp>首先，收集承诺，既用工具收集内心承诺，也就是想要或觉得必须应该做的事情。\u003c/p>\u003cp>其次，行动意义，既明确该事情对我们的意义和价值，并制定好实现该承诺的计划。\u003c/p>\u003cp>第三，频繁检阅提示，既跟进计划落实情况。\u003c/p>\u003cp>举一个我的例子，去年去酒吧打台球，那时我很菜，谁都可以虐我，我定了一个目标，成为冠军，那时只是心里有了一个目标，并没有用工具收集，虽然心中也有想获得冠军对我的意义，但缺少了第三步的频繁检阅提示自己练球涨球技，所以这个目标我去年并没有实现。今年看到核心群分享了一个九宫格小程序，就用这工具重新收集了这个目标，并有意识稳步练球涨球技，经过频繁提示自己比赛涨球，上周五获得一个亚军，周一虽然第一轮被淘汰，直到昨晚在车公庙比赛，终于获得了冠军，实现今年第一个目标。\u003c/p>\u003cp>WHERE：该法则适用于需要耗费精力的事情，如果是已养成习惯的日常生活琐事可以不必收集，比如早上起来刷牙，出门记得带钥匙之类。\u003c/p>\u003cp>异议处理：可能有同学会觉得不需要用工具收集，靠大脑就可以了，一天可能有二三十件事情，一周就差不多两百件事情，一年差不多一万件事情，我们很难能准确记住每件事情的时间和进度的。我们的意识基本只能同时专注做一件事，如果大脑中充满各种未了事件拉走我们的注意力，我们大脑是很内耗的，还是利用好外部工具帮我们集中精力做事情，减少我们大脑的压力。这里给大家推荐我现在用的工具，滴答清单app，没有工具的可以下载一个。\u003c/p>","interaction":"\u003cp>提问设计：回想过去，你是否有那么一天，晚上睡觉的时候，回顾复盘当天，好像有一些事情今天忘记做了？我们每天要做的事情可能有10-30件，大脑同一时间只能专注一件事情，常常会忘记一些事情。大家想一想明天起床漱洗后，当天要做的3件重要事情。为了照顾你的隐私，小组内只分享一下你明天要做的一到两件事情就好。待会邀请一位同学上来分享一下，1-2件就可以。有请这位同学上来分享一下他明天要做的事情。\u003c/p>\u003cp>学习者分享：明天我要关闭掉公司的一个项目\u003c/p>\u003cp>好的有请，谢谢这位同学的分享。\u003c/p>\u003cp>提问设计：那现在大家小组内再分享一下如何应用刚学习到的收集，行动意义，提示检阅三步骤来应对你刚才列出的1件事情。做好提示信息。待会再邀请同学上来分享一下。有请这位同学继续来分享他的三步骤安排，\u003c/p>\u003cp>学习者拆为己用：对于我明天的工作关闭那个项目呃，\u003c/p>\u003cp>1，首先就是记录，就是把这个项目给关闭掉，并且在流程上给计划掉，\u003c/p>\u003cp>2，然后他的意义就是首先对于公司和团队利益来说的话，呃，我既然作为公司的一员，我必须要去做出来，我这个角色岗位需要做的事情。那么，对于个人来说的话，其实这个工作也不只是呃，这个给公司做的也是给分析他的团队成员合作的，也是对自己的这个。呃时间付出的付出的时间的一个见证，所以呃，我觉得这个首先是要对得起公司，对对得起自己\u003c/p>\u003cp>3，然后检验的话就是呃，首先是在这个笔记上面去检验，然后第2个就是在公司的流程嘛，上面也可以做到一个检验。\u003c/p>\u003cp>谢谢。谢谢这位同学分享所学致用。\u003c/p>\u003cp>那我的分享就到这里，大家记得应用，收集承诺，行动意义，检阅提示三法则，让我们工作生活更轻松。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1705370497000,"updated_at":1706188170000,"ria":true},{"id":16501,"topic":"原则：有效地处理内心的承诺","learn_goal":"","remark":"身在职场，压力大\n头脑中有太多事理不清头绪\n永远被各种任务和目标追赶着\n拆书家【张名纹】带你拆解《搞定1-无压工作的艺术》，保持清新头脑，轻松自如处理多项事务","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"文子飞飞","city":"南京市"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>\u003cstrong>1）分组\u003c/strong>\u003c/p>\u003cp>各位书友大家下午好！\u003c/p>\u003cp> 欢迎大家来到拆书现场。今天我训练的是《拆书家成长手册》V3的TF2-1, 希望大家有新的体验。接下来为方便我们的讨论，我们分成2个小组，为不移动座位，靠我这边为一组，另外一边为另一组。\u003c/p>\u003cp>\u003cstrong>2）自我介绍（比如三个标签）\u003c/strong>\u003c/p>\u003cp>我叫张名纹。我用三个标签来介绍我自己，第一新晋拆书家8月6日通过了TF1-2；第二企业的内训师，主要有结构性思维、演讲和行动学习促动师等版权课程；第三服装外贸人，就职于服装外贸公司，可以为大家提供性价比高的服装和校服。爱学习、乐分享，愿与大家一道拆书学习，成为更好的自己。\u003c/p>\u003cp> \u003cstrong>一、学习目标：\u003c/strong>\u003c/p>\u003cp> 在跟随我完成本次RIA现场学习后，学习者能够利用智慧去清空大脑，做到一次只做一件事情，轻松告别手忙脚乱。\u003c/p>\u003cp>\u003cstrong>二、图书介绍\u003c/strong>（1-2分钟）\u003c/p>\u003cp>今天我给大家带来的拆书是《搞定1：无压工作的艺术》\u003c/p>\u003cp>F 特征（核心是“书”，用于满足好奇心）：\u003c/p>\u003cp> 是世界知名时间大师戴维.艾伦经典著作。他拥有30多年丰富的管理经验，被誉为提高工作效率方面极具建树和影响力的思想家之一。 \u003c/p>\u003cp>A 优势（重点是“比较”，用于建立安全感）：\u003c/p>\u003cp> 是时间管理领域最具影响力的著作之一。书中介绍的GTD时间管理方法也成为全球千万读者用来轻松高效完成工作与个人事务的最佳工具。\u003c/p>\u003cp>B 利益（强调的是“学习者”的利益，用于引发兴趣）\u003c/p>\u003cp> 在职场的人或多或少都有这样的体验：压力太大；头脑中有太多的事情都理不清头绪；好像永远被事务追赶着。GTD系统将指导你在事务缠身的情况下，仍然能头脑清醒、轻松自如地控制和处理一切。\u003c/p>","ratings_count":1,"texts":[{"id":20619,"quote":"\u003cp>《搞定1：无压工作的艺术》\u003cstrong>P17-19页\u003c/strong>\u003c/p>\u003cp>原则：有效地处理内心的承诺\u003c/p>\u003cp>在数十年的培训工作中，我指导过数千人。在这个过程中，我发现了一个极为常见的现象，即由于人们对自己做出的承诺或者承担的义务管理不当，导致他们承受着重重压力的折磨，所以，学会对承诺事项加以控制可以有效缓解压力，即使是那些并没有明显体验到压力的人，如果他们学会了更加有效地对于生活中悬而未决的事项加以控制，那么在放松自我、集中精力、提高效率方面也会有明显的改善。\u003c/p>\u003cp>恐怕你已经与自己达成了许多协议（这一点或许你根本没有意识到）。而每一项协议，无论大小，都时时刻刻被你自身的无意识所紧密追随。这就是“未完成的事项”或者“悬而未决的问题”。他们可能是“根除世界上的饥饿问题”这类重大事务，也可能是“雇佣一个新助手”之类的一般性的事件，或是”更换走廊灯泡”一类的琐碎小事。\u003c/p>\u003cp>为了能够高效应对这些问题，首先你必须明确并收集所有那些”经常唤醒你模糊记忆”的事情，来搞清他们对你而言的真正意义，然后决定如何推动他们。这看起来极为简单，但在实际操作中，大多数人都难以始终如一的坚持下去，他们缺乏认识或动力。而最可能的原因是，他们并没有意识到忽略这种做法将会付出的代价。\u003c/p>\u003cp>如果希望出色地管理好所有的工作，那么，你需要做到下面几点：\u003c/p>\u003cp>第一，如果这件事总占据着你的头脑，你的思维就会受阻。任何一件你认为还没有完成的事情，都必须被置于一个客观、可靠的体系中，或者是我称为“文件夹”的工具之中——必须经常回访并予以清理。\u003c/p>\u003cp>第二，在明白你的工作到底是什么后，你还必须做出判断：需要采取什么行动来推动工作进程。\u003c/p>\u003cp>第三，一旦决定了需要采取的行动方案，你必须在某一个你会经常查阅的系统中保存好与这些行动相关的提示信息。\u003c/p>","explains":"\u003cp>【WHAT】你能不能想像有一个特别美好的场景和状态，虽然每天事务缠身，你却能够头脑清楚、轻松自如地控制和处理一切，其实这是可以做得到的。但实际上呢，很多人每天忙忙碌碌却效率不高，事情一多就手忙脚乱的。为什么呢？原来呀，是因为不能集中注意力。没有对未完成的工作进行管理，比如没有列入工作清单存放，没有时间截点，没有优先级，全部拥在大脑里面，导致做事时大脑心不在焉 ，那怎么能做好事情呢。\u003c/p>\u003cp>[WHY]于我就有一个鲜活的案例，8月4日上午9点，我在做部门的中期工作会议的计划，但是随后的一个小时的时间里边我脑子里边老是想着下午的新员工翻转培训，总觉得下午还有哪些没有准备好，有点烦躁有点急，一个小时工作计划也没有做出来。\u003c/p>\u003cp>[HOW]现在想来，当时确实就是没有进行事务的管理，那么现在是我的话，学习了这个有效地管理承诺之后，我就能很好地处理。\u003c/p>\u003cp>一是将这几项未完成的事情全部放到我的工作清单当中，并且每天晚上都要查看；\u003c/p>\u003cp>二是将这几项未完成的事情经过思考后，如果是简单的2分钟以内的，直接做，超过2分钟以内的列出一个行动方案以便于推进工作进程；\u003c/p>\u003cp>三是将这几项未完成的事情按照日期、时间进行日程提醒，以便时时提醒。\u003c/p>\u003cp>一旦将未完成的事情列入到工作清单当中，放到日程提醒当中，我们便可以放心地清空大脑，让大脑在一个时间段只做一件事情，轻松工作。\u003c/p>\u003cp>[WHERE]这个适合于想轻松高效完成工作与个人事务的任何人，工作、生活中同样适用。\u003c/p>","interaction":"\u003cp>\u003cstrong>五、【A1+】显像提问及反思加工经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A1（显像提问）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>各位书友，在最近一段时间，有没有出现过这样的情况，明明早上已经想好了当天要完成的一些工作，但是总被打乱，总不能静下心来做一件事情，心不在焉，弄得一天手忙脚乱。这可以是您自己、爱人或朋友的事情。大家来分享一下案例，说说是什么时候？什么事情呢？请你想一想，在小组内分享，大家先想个一分钟，再分享，但不用给出解决方案。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：（小组内分享过往经验）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.看书时没办法集中注意力，大脑会想各种各要的事。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.最近因为焦虑所以一度自身的状态很迷茫。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3.早上想看书，又想照顾孩子，无法专注。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A1+】反思加工经验\u003c/strong>（3-4分钟）\u003c/p>\u003cp>如果时间可以倒回的话，如果再遇到这样的事情，你可以思考下，怎样应用刚才学习的方法去做改进呢？然后请一位书友来分享一下。\u003c/p>\u003cp>\u003cstrong>1.看书时没办法集中注意力，大脑会想各种各要的事。解决方法是：大脑是中央处理器，把所想的事情全部记录下来，对事情做管理列行动方案，并作时间提醒，清空大脑，专注做一件事。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.最近因为焦虑一度对自身的状态很迷茫的时候，我会运用方法，把问题或者焦虑的问题罗列出来：一是把重要紧急的事情先做；二是把有困难完成的，分阶段进行，作好时间点及标签；三是每天重要而紧急的事做好时间点先完成。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3. 早上想看书，又想照顾孩子，无法专注。处理方法分三步：第一步把脑子里同时要处理的事情写在纸上或手机上；第二步从重要的事情开始，规划好时间；第三步作好时间或事项的提醒。比如这个案例中分时间段：5:00-5:40看书；5:40-6:15陪儿子，两不误，做到一次只做一件事情\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1693146593000,"updated_at":1694402087000,"ria":true},{"id":15359,"topic":"释放大脑压力、有效规划下一步，让你轻松活在当下，稳步推进梦想","learn_goal":"","remark":"你是否脑海盘旋很多事情？工作时常感到焦虑、不安、压力？\n你是否不知如何开展事情？想法空中楼阁，找不到抓手？\n那么今天我们学习一下“释放大脑压力、有效规划下一步”，让你释放大脑压力、有效规划下一步，让你轻松活在当下，稳步推进梦想\n ","level":"TF2-4","duration":65,"status":29,"type":0,"chaishujia":{"username":"1405-吴先昇教练-庄宇亮","city":"杭州市"},"club":{"name":"杭州雷峰塔筹备分舵","city":"杭州"},"prologue":"\u003cp>【开场】\u003c/p>\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我是庄宇亮，三个标签，马拉松爱好者，小说家，终身成长者。今天我要过的是TF2-4，用时60-75分钟，主题是:释放大脑压力，有效规划下一步。\u003c/p>\u003cp>【学习总目标】\u003c/p>\u003cp>在完成本次RIA线上学习后，学习者能在现场运用“释放压力”三步法\u003cstrong>明确预期结果、制定行动计划、设置提醒系统\u003c/strong>，释放大脑压力，减轻记忆的负担，再运用“规划下一步”三步法\u003cstrong>制定目标、分解目标、落地执行\u003c/strong>，找到具体实际可行的下一步行动，让事情慢慢推动起来，取得进展。\u003c/p>\u003cp>【学习目标1】通过本次拆页1学习后，学习者能在现场运用“释放压力”三步法\u003cstrong>明确预期结果、制定行动计划、设置提醒系统\u003c/strong>，把待办事项从大脑中释放出来，从而减轻记忆负担。\u003c/p>\u003cp>【学习目标2】通过本次拆页2的学习后，学习者能在现场运用“规划下一步”三步法\u003cstrong>制定目标、分解目标、落地执行\u003c/strong>，找到具体实际可行的下一步行动，把事情慢慢推动起来，取得进展。\u003c/p>\u003cp>【逻辑关系】\u003c/p>\u003cp>本次两个拆页呈递进关系。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>待会儿我们会有小组讨论环节，我会用腾讯会议为大家分组，请大家开启摄像头\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>今天的拆页选自《搞定I：无压工作的艺术》\u003c/p>\u003cp>【F特征】\u003c/p>\u003cp>本书作者是戴维艾伦，是一位享誉全球的时间管理以及提高工作效率方面的顶尖专家，本书系统讲解了GTD(Getting Things Done)的时间管理方法，帮助全球千万读者掌握它搞定个人事务和工作。\u003c/p>\u003cp>【A优势】\u003c/p>\u003cp>与同类时间管理书籍相比，可以算是经典中的经典,是由作者本人20多年丰富管理经验总结而成，不仅仅是讲具体的时间管理方法，还在于总结了一套“无压力工作”的经典理论，让为我们理论联系实际。\u003c/p>\u003cp>【B1利益】\u003c/p>\u003cp>如果你平常工作忙到四脚朝天，而且还没有成效，建议你读读本书，学一下GTD时间管理方法，通过正确的运用，帮助我们减轻压力，提高工作效率。\u003c/p>\u003cp>【B2利益】\u003c/p>\u003cp>学习完拆页1，能帮助我们整理安排出大脑中纷繁复杂的事务，从而帮大脑减轻压力。\u003c/p>","ratings_count":1,"texts":[{"id":19405,"quote":"\u003cp>【阅读原文片段】 1分钟\u003c/p>\u003cp>片段来源：《搞定I：无压工作的艺术》P62-63页\u003c/p>\u003cp>为什么有些事情总是萦绕在你的心头在通常情况下，你对一些事情总是念念不忘，这是因为你希望它们的状况能有所改善，另外:\u003c/p>\u003cp>.你还没有明确地认定它们的预期结果是什么。\u003c/p>\u003cp>.你还没有确定你下一步的具体行动到底是什么。\u003c/p>\u003cp>.你还没有把关于预期结果和即将采取行动的提示信息存入你所依赖的系统中去。\u003c/p>\u003cp>持续不断且毫无成效地深陷于我们不得不处理的事务当中，是对时间和精力的最大浪费---克里·格利森.\u003c/p>\u003cp>这就是为什么你忘不掉这些事情的原因了。直到你澄清了所有问题，做出一切必要的决定，并把预期结果保存到那个系统中去(同时要确保你能在必要情况下随时访问和查询这个系统)，你的大脑才会放松下来。你可以骗过别人，但是你却无法愚弄自己的大脑。它能够明察秋毫: \u003cstrong>你是否已经做出了必要的决定，是否已经把有关预期结果和行动的提示信息寄存于一个安全可靠的地方,以便这些信息能在恰当的时候提醒你采取行动\u003c/strong>。\u003c/p>\u003cp>如果你没有做好这些工作，那么，你的大脑就一分钟也不会停止运转。通常情况下，当你对某件事还没有依照上述的处理方法处理时，你的某根神经仍然会持续不断地对你施加压力，这只会增加你的精神负担。\u003c/p>","explains":"\u003cp>【I拆书家讲解引导】（细化行动步骤）\u003c/p>\u003cp>【\u003cstrong>what\u003c/strong>】这个拆页告诉我们我们大脑中为什么总是存在念念不忘的事情，给我们不时的制造压力，而且是时间越长，你越感觉到焦虑，其实原文片段中，已经给到了线索和提示，我们需要澄清，作出决定，并把预期结果保存进一个系统，这样大脑才会放松下来。\u003c/p>\u003cp>【\u003cstrong>why\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>（一般的做法）\u003c/strong>\u003c/p>\u003cp>同时存在三件以上都比较急的事情，因此在做的时候，脑子里老是在想另外一件事情怎么处理，于是焦躁不安的处理当前这件事情。\u003c/p>\u003cp>\u003cstrong>（不这样做的坏处）\u003c/strong>\u003c/p>\u003cp>这些悬而未决的事情，如果没有一个回应，会一直在大脑中一直提醒你，这样会造成压力，同时在处理其他事务的时候，也很难专注起来，降低你的工作效率。\u003c/p>\u003cp>\u003cstrong>（这样做的好处）\u003c/strong>\u003c/p>\u003cp>这样做的好处，在于让你放下其他工作，对其有一个回应，安心而不焦躁的完成当前工作，这样工作更加专注，更加高效。\u003c/p>\u003cp>【\u003cstrong>举个反例\u003c/strong>】\u003c/p>\u003cp>举我自己的一个例子，我工作之外空余时间如果有的多的话，我想在顾好家庭的前提下，系统的全方面的提升一下自己多方面的能力水平，例如：学习一下投资理财，学习一下拆书技艺，学习一下副业方面知识，学习一下如何创建自己一套知识课程，学习一下心理咨询师相关知识，学习打造个人品牌。\u003c/p>\u003cp>哈哈，其实你也看到了，我思维真的挺活跃的，可恰恰是这个活跃，让我挺焦躁不安的，这些“悬而未决”的事项一直在我的脑海中积压，让我持续困扰，美好愿望只是一个愿望而已了。\u003c/p>\u003cp>【根据原文信息提示和线索】\u003c/p>\u003cp>我尝试去这样来解决：\u003c/p>\u003cp>1你还没有明确地认定它们的预期结果是什么。\u003c/p>\u003cp>那我就明确预期结果。\u003c/p>\u003cp>2你还没有确定你下一步的具体行动到底是什么。\u003c/p>\u003cp>那我就明确下一步具体行动。\u003c/p>\u003cp>3你还没有把关于预期结果和即将采取行动的提示信息存入你所依赖的系统中去。\u003c/p>\u003cp>那我就预期结果和即将采取行动的提示信息存入我的待办事项专用本子里去。\u003c/p>\u003cp>【举个正例】\u003c/p>\u003cp>\u003cstrong>投资理财\u003c/strong>的话，我明确目标就是把所有钱都给我老婆，让她去管理，一般她都会去买基金，钱虽然不多，但很稳。\u003cstrong>学习拆书技巧\u003c/strong>的话，目标就是获得三级拆书家证书，\u003cstrong>学习心理知识\u003c/strong>，目标就是获得心理咨询师证书，\u003cstrong>学习打造个人品牌\u003c/strong>的话，预期结果就是6月份正式出版第一本自己的新书。\u003c/p>\u003cp>\u003cstrong>买基金\u003c/strong>，每月工资一到账，分80%都给我老婆，\u003cstrong>三级拆书家证书\u003c/strong>的话，平均每周一拆\u003cstrong>，心理咨询师\u003c/strong>的话，下一步就是报一个培训班，争取今年拿出；\u003cstrong>出版新书\u003c/strong>的话，就是做好三审三校，认真修改即可，问题不是很大。\u003c/p>\u003cp>把所有脑子里纷繁的事项，从脑力里“请出去”，专门找一本待办事项本子，按照一个大致时间线，一类类的放进去，争取今年全部开花结果。\u003c/p>\u003cp>这样，我在做一件事情的同时，更能活在当下，享受其中，不会被其他的待办事项打扰，这些“悬而未决”的事情也不会让我感觉到焦虑，因为所有的事项，都是井然有序，稳步推进的，让我更加有信心，有目标去完成接下来的挑战！\u003c/p>\u003cp>【\u003cstrong>how\u003c/strong>】好了，根据以上自我案例剖析，我们可以得到以下3个步骤，我称为“释放大脑压力三步法”。\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>明确预期结果。\u003c/strong>比如我想提高“拆书”水平，那么明确的预期结果就是取得三级拆书家的证书。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>制定行动计划。\u003c/strong>计划采取怎么样的行动来支持这个预期结果，需要花多长的时间，使用那些步骤来实现，列一份大致可行的行动下一步计划。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> \u003cstrong>设置提醒系统。\u003c/strong>我们可以把前面二步的预期结果和行动计划，写下来，比如写在一张纸上，列出待办清单，今日待办，或者设定一个小闹钟等等形式，把这些写出来或者澄清说明一下，这样相当于从大脑清空出来，留出内存，把这些“悬而未决”的事情，有一个妥善的安排。\u003c/p>\u003cp>【\u003cstrong>where\u003c/strong>】\u003c/p>\u003cp> 减压三步法，主要原理不在于把事情安排的多完美，在于你把它写下来，有个大致可行的方案，让大脑减轻压力。\u003c/p>\u003cp>特别说明，减轻压力三步法适合不同尺度的时间范围，可以是在一天内的事情，也可以是一年范围，或者是几年之内需要完成的事情。如果是一天之内的事情，有些事情的预期结果，只需要快速解决就行，并不完全跟你的理想和期望挂钩，毕竟工作当中繁杂需要快速解决的事情非常多。\u003c/p>\u003cp>\u003cstrong>适用场景\u003c/strong>：对你来说重要但拖延的事情，紧急且在一段时间内需要处理完毕的，你关心的，你关注的，你需要在未来去完成的事情。比如项目赶工日期截止，关乎于未来前途的职业技能，一段有待修复的感情，当天需要完成的各种事项等等。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有些小伙伴会问，你这个“减压三步法”不就是，目标、行动、记录吗？这有什么难的，你不说我也知道呀！\u003c/p>\u003cp>\u003cstrong>拆书家反馈\u003c/strong>：嗯，的确，步骤看上去确实很简单，人尽皆知，但为什么要这样，背后被忽视的深层认知，才是这个拆页的真正魅力所在。这个认知就是你如果不去对这些“悬而未决”的事项，有一个妥善的安排，它就会不断的给你制作焦虑，不断的提醒你，这个没完成，那个没完成，没完没了。不断给你制作压力，制作焦虑，让你失去该有的专注力和活在当下。看似简单步骤，却有效解决了这个平常人几乎都会犯的问题，这也是这本书，这个拆页所带来的巨大价值。\u003c/p>","interaction":"\u003cp>【A1激活经验-拆为己用：提出一个显像问题】\u003c/p>\u003cp>好了，刚才我讲解了这个片段，也分享了自己的一个经历，相信大家在过去的时间里，也有同样需要解决的事情却迟迟没有处理，大脑还时不时的回想起来，造成压力。\u003c/p>\u003cp>比如：\u003c/p>\u003cp>1.公司职工在单位上班，任务接着一件又一件下发，几乎快堆成山，手头坐着一件事，脑中想着却是另外一件，压力很大。\u003c/p>\u003cp>2.想学习一些新的技能，却因为工作生活各种琐事，一直压在那边没有去做，也没有对其有个回应。\u003c/p>\u003cp>3.想找一个配偶对象，却一直没有开始去做？朋友、亲戚却在旁边催催催。\u003c/p>\u003cp>4.想利用空余时间，给自己充电，早点拿出职业技能资格证书，加薪升职，却被生活中各种烦心事，给延误了。\u003c/p>\u003cp>\u003cstrong>给大家2分钟的时间讨论一下，请在小组讨论分享一下近阶段脑海中时不时弹出来，让你感觉到焦虑的事情。\u003c/strong>\u003c/p>\u003cp>【\u003cstrong>学习者案例\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>刘清栎\u003c/strong>：过去的一周时间里，过级看拆书帮手册，以及音频，不知道技能点的边界在哪里？挺焦虑的，恐惧的，而且还挺蒙的。\u003c/p>\u003cp>\u003cstrong>韩哥\u003c/strong>：过去的时候，还有一个是工作中的任务，需要写年度的分析报告，同时还要写3-2的稿子，挺焦虑的，而且当在写3-2的稿子的时候，脑子却在想3-3怎么搞？主要原因是3-3的微行动学习不知道是什么？不能专注于当下。\u003c/p>\u003cp>\u003cstrong>李永忠\u003c/strong>：最近一段时间事情挺多的，想写一篇网络安全的文章，但过去时间很久，也没用开动；第二个就是学习准备软件考试的事情；第三个就是有关密码技术的学习；第四个是想准备做一个有关时间管理课程开发的事情；第五个是准备拆书过级的准备工作，2-1已经过了一周还没有动静。这都是我所焦虑的事情。\u003c/p>\u003cp>【A1+反思加工】\u003c/p>\u003cp>好的，我们刚才听了几位小伙伴的分享，看样子，大家基本上都有过脑海中“悬而未决”的事情，给大脑造成了压力，而且还不是少数，\u003cstrong>那么如果时光倒流的话，你将如何用今天学习的“减压三步法”来释放大脑压力呢？（刚才的自己的失败案例）\u003c/strong>\u003c/p>\u003cp>（分组）好，我给大家分一下组，给大家花1-2分钟请在小组内与小伙伴们分享讨论。5分钟后我们会请1-2位小伙伴来跟大家分享（具体分组情况根据现场人数来定）\u003c/p>\u003cp>【\u003cstrong>学习者案例\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>刘清栎：\u003c/strong>\u003c/p>\u003cp>1. 明确预期结果。\u003c/p>\u003cp>就是过级通过，\u003c/p>\u003cp>2. 制定行动计划。\u003c/p>\u003cp>对每一个技能点进行全面你的掌握，第一步先看拆书家手册，第二步看阿拉丁的技能讲解，第三步如果还有不明白不明确的疑惑，就打电话给我师父\u003c/p>\u003cp>3. 设置提醒系统。\u003c/p>\u003cp>每天8点-10点之间，去研究技能点，设定一个闹钟进行拆书技能点的学习。\u003c/p>\u003cp>\u003cstrong>韩哥：\u003c/strong>\u003c/p>\u003cp>1. 自己的小论文。\u003cstrong>（明确预期结果）\u003c/strong>结果是必须得写完，\u003cstrong>（制定行动计划）\u003c/strong>计划三天左右时间写完，争取在本周交稿子，\u003cstrong>（设置提醒系统）\u003c/strong>提醒自己每天都要写一点。\u003c/p>\u003cp>2.研究3-3过级问题。结果是成功过级\u003cstrong>（明确预期结果）\u003c/strong>，\u003cstrong>（制定行动计划）\u003c/strong>每天用1-2个小时研究手册，看其他拆书家的实录，然后不懂的点就问师父。在纸上写下一个设定期限，大概半个月的时间，鼓励自己去完成。\u003cstrong>（设置提醒系统）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李永忠：\u003c/strong>\u003c/p>\u003cp>1.时间管理课程开发\u003cstrong>（明确预期结果）\u003c/strong>。做一个2小时的课程，先把课程的大纲做出来，然后逐步往里面添加内容，大概2周的时间，大概能大致梳理出来，再进行细化修改。\u003cstrong>（制定行动计划）\u003c/strong>最后每天早上8点定一个闹钟，来提醒自己。\u003cstrong>（设置提醒系统）\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":19406,"quote":"\u003cp>【过渡】\u003c/p>\u003cp>现在我们已经学会了，借助“释放压力”三步法，来释放我们大脑压力，减轻焦虑，可是当你真正着手去做的时候，发现根本无法行动，原因是什么呢？其实有时候我们根本没有一个具体可实际的下一步具体行动，找不到一个落脚点和抓手，如何找到具体可实际的下一步行动规划呢？下面，我们一起进入拆页2的学习。\u003c/p>\u003cp>【阅读原文片段】 1分钟\u003c/p>\u003cp>通常情况下，由于我们没能对下一步行动作出最后的判断，即使那些最简单的事情也会被耽搁。我的学员经常会在清单上列出这样的条目：“调整汽车发动机”。难道“调整发动机”是下一步行动吗？当然不是这样，除非当你穿上工作服，手持工具走进车库，亲自实施调整发动机的行动，否则一切都是徒劳。\u003c/p>\u003cp>“那么，下一步行动是什么呢？”\u003c/p>\u003cp>“我得把汽车送到修理厂去。是的，我需要弄清楚修理厂能不能处理，我想我要给他们打个电话，约个时间。”\u003c/p>\u003cp>“你有电话号码吗？”\u003c/p>\u003cp>“呀，没有…….那个修理厂是弗雷德向我推荐的，但我不知道它的名称和电话号码。我知道了，我还缺少一些信息。\u003c/p>\u003cp>通常，这是最普遍的情况。扫了一眼这项工作后，我们会不由自主的想，“我还没有获取全部的信息。”我们知道有所缺失，但又无法确定到底是什么，因此我们就退却了。\u003c/p>\u003cp>“那么，下一步做什么呢？”\u003c/p>\u003cp>“我需要弄到它的名称和电话号码。我猜，我可以从弗雷德那里拿到。”\u003c/p>\u003cp> “你怎么做到呢？”\u003c/p>\u003cp> “我可以给弗雷德发电子邮件！”\u003c/p>\u003cp>\u003cstrong>因此，真正的下一步行动是“给弗雷德发电子邮件，问一下修理厂的情况”。\u003c/strong>\u003c/p>\u003cp>你是否注意到了，在我们判断出下一步行动方案前，需要经过几个步骤呢？这种情况非常典型。在大多数人的清单和大脑里，列出的都是类似的事情，而不是具体的下一步行动。\u003c/p>","explains":"\u003cp>【I拆书家讲解引导】\u003c/p>\u003cp>【what】这个拆页告诉我们，我们往往做不出真正可以落地的下一步行动计划，需要通过不断的问自己真正的下一步是什么，才能找到。\u003c/p>\u003cp>【why】\u003c/p>\u003cp>有些时候，造成我们拖延的原因，不是因为我们不知道怎么做，而是无法确定下一步真正要做的是什么，造成事情根本得不到有效的推动。\u003c/p>\u003cp>【how】(细化行动步骤)\u003c/p>\u003cp>“规划下一步”三步法\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>制定目标。\u003c/strong>确定你要完成的目标或者遇到什么困难。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>分解目标\u003c/strong>。找出你认为需要做的下一步，并分析是否可以马上着手去做，如果不行，分析一下为什么，查找缺少信息，并找出原因，然后基于这个原因，规划出下一步。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> \u003cstrong>落地执行\u003c/strong>。直到这个行动不能再次被分解，足够清晰足够有条件去完成，那么这一步，才是真正有效的下一步，然后着手去做就行，推动事情发展。\u003c/p>\u003cp>【举个例子】\u003c/p>\u003cp>举个例子说明一下怎么做？我需要做的事情是成为一名心理咨询师（\u003cstrong>制定目标\u003c/strong>）。\u003c/p>\u003cp>我认为的下一步是报一个培训班\u003cstrong>（分解目标）\u003c/strong>，\u003c/p>\u003cp>下一步的行动计划是什么？\u003c/p>\u003cp>网上查询各个培训班的实际情况，需要价格合适，课程精良\u003c/p>\u003cp>但实际查询结果是培训班鱼龙混杂，价格有高有低，不能确认哪家才是最好的。\u003c/p>\u003cp>下一步的行动规划是什么？\u003c/p>\u003cp>问一个已经实际通过心理咨询师的朋友。\u003c/p>\u003cp>能直接做吗？\u003c/p>\u003cp>可以，马上打电话给他，问他当时报的是哪个培训班，大概价位是多少？\u003c/p>\u003cp>\u003cstrong>（落地执行）\u003c/strong>所以行动的下一步就是打电话给朋友，先确认大致价位以及他报的班级是什么，作为自己的一个选择依据，一个参考。\u003c/p>\u003cp>【where】\u003c/p>\u003cp>\u003cstrong>适用场景\u003c/strong>：当你开展一项比较大的事项或者从来没有做过的事，不熟悉的事，内心充满迷茫，完全没有头绪，不知道该如何开展。\u003c/p>\u003cp>\u003cstrong>不适用场景\u003c/strong>：已经熟能生巧，甚至是养成了习惯，闭着眼睛都不用想下一步，比如说，起床后刷牙洗脸，或者是非常熟悉的事情，没有必要去想下一步。\u003c/p>","interaction":"\u003cp>【A3现场演练】\u003c/p>\u003cp>刚刚我们学习了“规划下一步”，现在大家一起来做一个现场演练，请大家认真听一下要演练的场景：\u003c/p>\u003cp>【场景】小王的孩子，今年读幼儿园中班，刚好暑假，可是一天到晚就直到拿奶奶的手机，看各种短视频，而且还不亦乐乎，小王直到问题的关键在于，自己小孩不知道空余时间应该作什么，但一直拖延解决这个问题，经朋友推荐，请教了一位世外高人夏总。\u003c/p>\u003cp>（分组）好，我给大家分一下组，给大家花5分钟请在小组内与小伙伴们分享讨论。\u003cstrong>5分钟后我会邀请2位小伙伴来跟大家演练，一个扮演夏总，一个扮演小王，让夏总利用“规划下一步”教会小王，如何做出真正有实质性的行动，慢慢推动这个事情，让事情得到进展。\u003c/strong>（具体分组情况根据现场人数来定）\u003c/p>\u003cp>【\u003cstrong>学习者现场演练\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>刘清栎（小王）\u003c/strong>：夏老师您好，我家孩子整天拿奶奶的手机玩，我觉得这样不太好，太伤眼睛了，但是呢，我也不知道小孩空余时间应该做点什么？所以想给夏老师请教一下\u003c/p>\u003cp>\u003cstrong>韩哥（夏老师）\u003c/strong>：我觉得你这个想法很正常呀！因为小孩子没事情做，所以玩手机，所以关键点还在在于空余时间让小孩做点什么，比如说做游戏呀，看电影呀之类的，你能不能考虑考虑呢？\u003c/p>\u003cp>\u003cstrong>刘清栎（小王）\u003c/strong>：看电影吧，我觉得还是伤眼睛的，要不然一起做个游戏吧！做个游戏应该是可以的。\u003cstrong>（制定目标）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>韩哥（夏老师）\u003c/strong>：你看，我最近学了“规划下一步”三步法，你可以分为3个步骤来进行，第一步是制定目标，第二步是分解目标，第三步是执行落地。就是有时候我们往往做不出下一步，需要不断问自己真正的下一步是什么，这样才能有效推动我们事情进程。那首先我们来到第一步，制定目标，你觉得制定什么目标比较好？\u003c/p>\u003cp>\u003cstrong>刘清栎（小王）\u003c/strong>：我觉得做游戏比较好一点，看电影我担心影响孩子的势力\u003cstrong>（分解目标）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>韩哥（夏老师）\u003c/strong>：好的，第一步已经确定下来了，那我们现在来分析一下可行性，那你觉得这个事情马上就可以去做吗？还需要什么条件吗？或者说那你有没有什么朋友很会带孩子，是不是可以问一下，别的小孩子都在玩什么游戏？\u003c/p>\u003cp>\u003cstrong>刘清栎（小王）\u003c/strong>：我一个朋友就很会带孩子玩，我得问问她！\u003c/p>\u003cp>\u003cstrong>韩哥（夏老师）\u003c/strong>：嗯，是的，玩游戏分两种，一种是自己跟孩子玩，还有一种是跟其他小孩子一起玩！\u003c/p>\u003cp>\u003cstrong>刘清栎（小王）\u003c/strong>：嗯，那我了解了，我可以在她放学的时候，带她去小区游乐场玩，哪边有很多小朋友一起玩！\u003c/p>\u003cp>\u003cstrong>韩哥（夏老师）\u003c/strong>：好的，非常不错，那是不是相对找一个小朋友一起玩，会不会比较固定呢？那你是不是可以问一下知根知底的家长是否有时间玩！\u003c/p>\u003cp>\u003cstrong>刘清栎（小王）\u003c/strong>：对！我懂了，那我问问小区里，小孩子的同学玩的还是很不错的，我可以跟她妈妈约一个时间\u003cstrong>（执行落地）\u003c/strong>，\u003c/p>\u003cp>\u003cstrong>韩哥（夏老师）\u003c/strong>：嗯，是的！那我们就可以落地了，真正找到推动事情进展的下一步了！\u003c/p>\u003cp>【A2分步催化1-场景激活】\u003c/p>\u003cp>下面请大家考虑一下，在未来几个月内，或者今年内，在你的工作生活中，是否存在一些比较棘手的事项需要去处理。\u003c/p>\u003cp>在这里我提醒一下，这个环节，我们只需要分享场景就可以了，不需要分享怎么做。3分钟后我会邀请1-2名小伙伴来跟我们分享一下自己的经历。\u003c/p>\u003cp>这边，我简单的举几个例子\u003c/p>\u003cp>1.工作中所需要的职业技能，考证\u003c/p>\u003cp>2.兴趣爱好类，学尤克里里，练毛笔字\u003c/p>\u003cp>3.想要在今年2023年成为三级拆书家\u003c/p>\u003cp>4.想要寻找人生的另外一半\u003c/p>\u003cp>【\u003cstrong>收集学习者案例\u003c/strong>】\u003c/p>\u003cp>\u003cstrong>丽静\u003c/strong>：我在过完TF1-1后，不知道怎么选择后面的拆页，真的头很大。\u003c/p>\u003cp>\u003cstrong>刘清栎\u003c/strong>：其实我最近一直在比较焦虑的事情是3月18日的时候，一个期待了半年的事情，就有一个评委孵化营，据说是非常非常卷！但是我在那个期间，工作中有一个非常大的项目要做，所以我觉得这两个会有冲突！所以说就比较困扰！担心顾不上！\u003c/p>\u003cp>【A2分步催化2-具体应用】\u003c/p>\u003cp>刚才小伙伴想出了未来想要实现的种种目标，那么现在请大家再继续思考一下，在刚才大家分享的案例当中，我们如何用今天所学的“规划下一步”来走出真正有效的下一步呢？\u003c/p>\u003cp>（分组）好，我给大家分一下组，给大家花1-2分钟请在小组内与小伙伴们分享讨论。5分钟后我们会请1-2位小伙伴来跟大家分享（具体分组情况根据现场人数来定）\u003c/p>\u003cp>简单回顾：“规划下一步”。\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>制定目标。2.分解目标\u003c/strong>。\u003cstrong>3.落地执行\u003c/strong>。\u003c/p>\u003cp>【\u003cstrong>收集学习者案例\u003c/strong>】\u003c/p>\u003cp>刘清栎：\u003c/p>\u003cp>1.\u003cstrong>制定目标。\u003c/strong>我要确保接下来的两周时间精力能分配好这两件大事。这是我的目标。\u003c/p>\u003cp>\u003cstrong>2.分解目标\u003c/strong>。那么从工作项目上来看，我是不是可以从现在就做准备，我可以找领导沟通一下，确定项目的一个方向，这样可以分担大部分未来的压力和时间精力；那另外一个的话，在学习训练营的时候，肯定会布置作业，那就当日事情，当日毕！\u003c/p>\u003cp>\u003cstrong>3.落地执行。\u003c/strong>次日找领导沟通一下；把学习训练营的事情暂时先放一放，做好一个计划。这样时间精力的问题就完美解决了！\u003c/p>\u003cp>李永忠：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>制定目标。\u003c/strong>我想要做一个2个小时左右的时间管理课程的开发。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>分解目标\u003c/strong>。想要在公司跟同事们分享一下，但是没有一个具体内容可以分享，所以不能马上去做。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> \u003cstrong>落地执行。\u003c/strong>可以花点时间，先整理出一个课程的大纲。\u003c/p>\u003cp>\u003cstrong>丽静\u003c/strong>：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>制定目标\u003c/strong>。过1-2，找书或者是拆页，大概有1个月的时间。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>分解目标\u003c/strong>。我不知道怎么选拆页，我可以围观其他小伙伴过级，或者官网上看优秀人的1-2实录。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> \u003cstrong>落地执行\u003c/strong>。打开拆书帮官网，寻找优秀小伙伴1-2实录；预约一下其他朋友的过级时间，到时候观摩！\u003c/p>\u003cp>韩哥：\u003c/p>\u003cp>\u003cstrong>1.制定目标。\u003c/strong>我准备写一个课，就是体制内沟通的工具。\u003c/p>\u003cp>\u003cstrong>2.分解目标\u003c/strong>。但是现在沟通的工具的场景很多，包括销售、家庭、亲子关系，所以我就不能确定，是否体制内比较敏感的地方是不是需要一种沟通的工具呢？那么实际当中呢，这个问题也是真实存在的，上下属之间，因为沟通不到位，引发一些不良的情绪呀，不良的误会呀，导致工作推动有阻碍！所以我就不确定呀！那我可以问一下刚刚退休的一位老领导，通过他的一个分析，给我一个进一步的意见！\u003c/p>\u003cp>\u003cstrong>3.落地执行\u003c/strong>。打一个电话给退休的老领导。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>感恩大家接近1个小时的陪伴，接下来，我们回顾一下，刚才我们学习了“释放压力”三步法和“规划下一步”三步法，让大脑减轻记忆负担，有效规划下一步。\u003c/p>\u003cp>“释放压力”三步法是：\u003cstrong>明确预期结果、制定行动计划、设置提醒系统\u003c/strong>；“规划下一步”三步法：\u003cstrong>制定目标、分解目标、落地执行\u003c/strong>。两者结合，这样能够帮助实现没有压力的工作状态，同时有效推进下一步进程。\u003c/p>\u003cp>最后用一句话结束今天的分享：\u003c/p>\u003cp>\u003cstrong>万里之行始于足下，让我们轻装上阵，奔赴梦想！\u003c/strong>\u003c/p>\u003cp>感谢聆听！谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1679182154000,"updated_at":1680180889000,"ria":true},{"id":13591,"topic":"规划具体行动四标准法","learn_goal":"","remark":"这是世界知名时间管理大师，戴维·艾伦所撰写的。它是一套成熟的自我管理系统，可以帮助大家脱身于琐事的繁忙之中，帮助大家建立一个富有掌控感的工作节奏和让你获得自律且高效生活体验。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"Amandadada","city":"长沙市"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"\u003cp>大家好，我是今天的拆书家奉凰，大家可以叫我Amanda。我的三个标签是：主持人、培训师、三岁孩子的妈妈\u003c/p>\u003cp>今天我要拆解的书籍是《Getting Things Done》搞定。这是世界知名时间管理大师，戴维·艾伦所撰写的。它是一套成熟的自我管理系统，可以帮助大家脱身于琐事的繁忙之中，帮助大家建立一个富有掌控感的工作节奏和让你获得自律且高效生活体验。\u003c/p>\u003cp>这次拆解的原文片段来自于这本书第二章的73-74页，“确定某一时段具体行动的“四标准法”。”现在请各位小伙伴用2分钟的时间阅读手中的拆页，阅读完成的小伙伴可以举手示意一下。\u003c/p>","ratings_count":2,"texts":[{"id":17621,"quote":"\u003cp>确定某一时刻具体行动的“四标准法”\u003c/p>\u003cp>在星期三下午3点22分时，你如何选择下一步行动呢？这个时候，你可以按顺序采用下面四个标准：情境、有多少时间、有多少精力和重要性。\u003c/p>\u003cp>前三个标准描述了你每次采取行动的制约因素，第四个标准则是评估行动的价值大小。\u003c/p>\u003cp>1、情境\u003c/p>\u003cp>每时每刻，你都受限于自己的行动能力。只有很少一部分事情对地点没有特别要求（像拿一支笔和一张纸就可起草对一个项目的想法），但是，大多数事情都只能在特定的地点完成（在家或办公室），或者需要借助某些特定的工具（如一部电话、一台电脑）而这正是限制我们行动选择的首要因素。\u003c/p>\u003cp>2、有多少时间\u003c/p>\u003cp>所能支配的时间长短也是一个重要的限制因素。如果5分钟后你就必须去开会，你现在就不可能去执行那些耗时更久的行动。\u003c/p>\u003cp>3、有多少精力\u003c/p>\u003cp>你有多少精力呢？某些事情需要你头脑清醒、思路清断、富于创造力，而另一些则要求你具备充沛的体力。还有一些事情则对这两方面都没有特别要求。\u003c/p>\u003cp>4、当你考虑了情境、时间、精力这三个条件后，最后你就要判断哪个行动选项会给你最高的回报了。现在，你有1个小时的时间，你坐在办公室里守着电话和电脑，你的精力指数为7.3（最高为10）.你应该做些什么呢？给客户回一个电话？考虑下新的提案？处理一下语音信箱里的留言和电子邮件？或者联系一下你的配偶，看看她/他这一天过得怎么样？\u003c/p>","explains":"\u003cp>好的，我看到大家已经看完了拆页，接下来我就用我自己的语言和大家说说这个拆页中的内容：\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>\u003c/p>\u003cp>大家是不是时常觉得自己有很多事情要做，但是时间却永远都不够用？会不会时常觉得重要的事情有很多，不知道应该如何取舍？我就时常遇到上面所说的困境，总是渴望能从中获得解脱，却不知该怎么办才好？其实，如果我们能够做出具体的行动规划，就可以拥有时间掌控感，可以更好的分配我们的时间，更高效的完成自己的工作。\u003c/p>\u003cp>\u003cstrong>What：\u003c/strong>我们可以运用拆页中提到的“四标准法”，从3个价值评估，1个重要排序出发，帮助我们确定某个时间点或时间段的具体行动。\u003c/p>\u003cp>\u003cstrong>How：\u003c/strong>\u003c/p>\u003cp>具体我们可以如何去做呢？主要分为四步走：\u003c/p>\u003cp>第一、二、三步描述了你每次采取行动的制约因素，第四步是对行动的价值大小的评估。\u003c/p>\u003cp>第一步：情境分类：确定事情是否需要在特定地点、特定工具下才能完成？\u003c/p>\u003cp>第二步：时间分配：你有多少时间？完成这件事需要花费多少时间？\u003c/p>\u003cp>第三步：精力预估：简单预估一下这件事所需要的精力，再评估一下你现有的精力，确认你现有的精力值是否足以完成这些工作\u003c/p>\u003cp>第四步：重要性排序：按“最大回报”进行排序，确定做事的先后顺序。\u003c/p>\u003cp>听完说完，大家会不会感觉很疑惑，这四标准法好像听懂了又好像没听懂，如果在生活中遇到类似的事情，好像还是不知道应该如何应用？接下来，我就结合我自己的一个例子，来和大家分享一下，这四步到底应该如何应用。\u003c/p>\u003cp>昨天下午，我感觉自己非常的忙碌，因为当时的我手上同时有几件事情需要做，我感觉事情比较多，但是时间却不多了，接下来我们尝试根据刚刚提到的四标准法来尝试做一个具体的规划。首先我们来看看我当时需要做哪些事情。\u003c/p>\u003cp>①制作下次课的课件。②整理当月各领导的总结计划表并完成签批。③组织新员工周面谈。④阅读课程书籍，为开发课程做准备。\u003c/p>\u003cp>1、情境分类：看看我要做的事情是否有场景或者工具的限制。制作课件，我需要在一个有电脑的地方；整理总结计划表我需要在我的办公桌前；新员工周面谈我需要在会议室进行，阅读书籍我只要带着这本书，在哪里看都可以。\u003c/p>\u003cp>2、时间分配：我准备做这四项工作时，距离18点下班还有2个小时，我希望我可以在下班前尽可能多的完成以上工作。现在让我来预估一下我的时间，制作课件可能要花费1小时的时间，整理资料可能需要20分钟，新员工面谈需要30分钟，阅读书籍可能需要花费1.5小时才能完成对我目标篇章的阅读。\u003c/p>\u003cp>3、精力预估：制作课件可能要花费我40%的精力，整理资料可能需要花费20%的精力，新员工周面谈可能需要花费我30%的精力，阅读书籍做开发课程的积累可能需要花费我80%的精力。\u003c/p>\u003cp>那当时我的精力情况是什么样的呢？当时的我从下午1点半午休结束开始先是一个1.5个小时的方案讨论会，然后又做了1个小时的培训，到下午四点，我的精神上是疲惫的，当时我的精力值估计只有60%左右，这样一看，我就可以确定我的精力无法支撑阅读书籍了。\u003c/p>\u003cp>4、重要性排序：我的课件是周二上课需要用的，昨天已经周一，当天必须完成。整理总结计划资料补充签批只要能在本周内完成就可以了，今天周一，时间上还是充足的。新员工面谈是上周因为时间问题没有完成，遗留下的面谈，需要尽快完成。阅读书籍，这是我为之后开发课程做的储备工作，重在积累，没有特别强的时效性，所以其实不那么着急。\u003c/p>\u003cp>根据四标准法的判定，我发现我应该先完成我的课件，然后再完成新员工周面谈，这两项工作都完成以后如果精力足够的情况下，我可以去整理总结计划资料，那阅读书籍可能要放在之后再去做了，这样说大家可以明白四标准法应该如何应用了嘛？\u003c/p>\u003cp>Where：以上方法适用于有足够的时间可以事先规划工作的场景，不太适用于处理紧急、突发工作。比如领导临时通知你开会，那你当下肯定必须立马放下手头的事情，先去参加会议。\u003c/p>","interaction":"\u003cp>在这里我也想问问大家，平时你们在生活和工作中，有没有出现过下列情况：明明计划好要今晚要完成某个方案，却因为忘带电脑或重要资料，导致回家无法完成；信誓旦旦的说今天一定要把这个3个小时的课程上完，却因为工作疲惫、回到家不到9点就睡着了。因为同事着急找你帮忙，你一下就把领导交代的最重要的事忘在脑后了，结果同事的忙你帮完了，却耽误了自己的工作。\u003c/p>\u003cp>如果大家有遇到过类似的情况，请大家花3分钟的时间回忆一下事件的经过，和大家来分享一下。为了更方便大家分享，我们根据大家的位置来进行分组，2人一个小组，大家可以在小组内讨论。（在大家开始分享的时候提示大家）在分享的时候需要有具体的时间、地点、人物、事件以及感受，比如，我昨天在公司，因为要帮同事做一件事，而耽误了领导交给我的重要工作，被领导批评了，我感到很沮丧。\u003c/p>\u003cp>好，时间到，哪位小伙伴愿意分享一下自己的过往经历？\u003c/p>\u003cp>学习者案例记录：张靓\u003c/p>\u003cp>时间：昨天上午\u003c/p>\u003cp>地点：办公室\u003c/p>\u003cp>人物：张靓本人+办公室同事\u003c/p>\u003cp>事件：因为自己手头上有很多工作要做，但是总是被其他同事请求帮助的事情打断自己的工作节奏，打断自己的思路，让自己手头上的事情无法完成。\u003c/p>\u003cp>感受：觉得有一些事情很无力，可能有岗位的特殊性，所以难以自己分配时间，可能需要提前预估时间，多留出一些时间来做临时发生的事情\u003c/p>\u003cp>谢谢这位小伙伴的分享。现在请大家花1分钟的时间，按照刚刚说的四标准法来规划一下你明天早上起床后到上班前要做的事。要记得有明确的行动、期限以及可衡量的结果。\u003c/p>\u003cp>学习者案例记录：张靓\u003c/p>\u003cp>时间：早上起床到上班前要做的事\u003c/p>\u003cp>地点：家里\u003c/p>\u003cp>人物：张靓本人\u003c/p>\u003cp>具体行动：早上7点-7点40：洗漱+收听新闻 7点40-7点50：叫孩子起床洗漱，，目标是8点准时出门送孩子上学\u003c/p>\u003cp>好的，以上就是我今天想和大家分享的内容，希望能为大家带来帮助。谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1655369615000,"updated_at":1656987455000,"ria":true},{"id":13162,"topic":"确定某一时记得具体行动的“四标准法”","learn_goal":"","remark":"无","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"蓓蕾绽放","city":"苏州市"},"club":{"name":"苏州阅苏分舵","city":"苏州"},"prologue":"\u003cp>自我介绍：\u003c/p>\u003cp>哈喽，各位伙伴，欢迎来到拆书帮活动的现场。我是今天的分享人，我的名字叫张蓓蕾，意为“张开的花骨朵”，亦有“绽放之意”。我今天用三个标签：10年运营人、公益读书会发起人、运动达人。下面我来介绍一下拆书帮。\u003c/p>\u003cp>\u003cem>拆书帮\u003c/em>是基于拆书法的学习爱好者社群,表现为各地的\u003cem>拆书帮\u003c/em>分舵(也叫\u003cem>拆书帮\u003c/em>俱乐部)。\u003cem>拆书帮\u003c/em>分舵是公益性青年自组织,它的使命是帮助更多学习爱好者成长为拆书家。“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。拆书法主要以RIA便签\u003cstrong>为核心，包含个人学习的便签法和组织学习的拆书课两种形式。\u003c/strong>RIA分为：R（阅读片段）、I（用自己的话重述知识）、A1（描述自己的相关经验）和A2（以后我怎么应用）是一种非常适合成年人的学习方式，今天到场的都是学习爱好者，再次欢迎大家一同来感受学以致用的快乐。\u003c/p>\u003cp>今天我给大家带来的这个片段来自《搞定1 无压工作的艺术》一书，书中介绍的GTD（Getting Things Done）时间管理法是全球千万人在使用的高效完成工作与管理个人事务的优秀工具。\u003c/p>\u003cp>这本书会告诉我们\u003cstrong>如何更高效的利用时间，让事情井井有条，生活和工作都更加从容、放松。\u003c/strong>今天我们一起走进这本看似简单易行，背后却有深刻洞见的书。\u003c/p>\u003cp>\u003cstrong>首先，我们先用1分钟的时间来阅读手中的片段。阅读完的小伙伴可以举手示意我。\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":17142,"quote":"\u003cp>\u003cstrong>R原文片段：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>片段来源：《搞定1》 P.73\u003c/strong>\u003c/p>\u003cp>确定某一时刻具体行动的“四标准法” \u003c/p>\u003cp>在星期三下午3:22时，你如何选择下一步行动呢？你可以按顺序采用下面四个标准：（1） 情境（2）有多少时间（3）有多少精力（4）重要性 \u003c/p>\u003cp>\u003cstrong>情境-\u003c/strong>\u003cstrong>只有很少一部分事情对地点没有特别的要求\u003c/strong>(像拿一支钢笔和一张纸，就可以起草对一个项目的想法)，但是大多数事情都只能在特定的地点完成(在家或办公室)，或者需要借助某些特定的工具（如一部电话一台电脑），而这正是限制我们选择行动的首要因素。 \u003c/p>\u003cp>\u003cstrong>有多少时间\u003c/strong>—\u003cstrong>你所能支配的时间长短\u003c/strong>也是一个重要的限制因素，如果5分钟后你就必须去开会，你现在就不可能去执行那些耗时更久的行动。 \u003c/p>\u003cp>\u003cstrong>有多少精力\u003c/strong>—\u003cstrong>你有多少精力呢？\u003c/strong>有某些事情需要你头脑清醒，思路清晰，富于创造力，而另一些则要求你具备充沛体力，除此之外的一些事情是对这两方面都没有特别要求。 \u003c/p>\u003cp>\u003cstrong>重要性-\u003c/strong>当你考虑了情境，时间,精力这三个条件后，你就要选择哪个行动会给你最高的回报了，现在你有一个小时时间，你坐在办公室里守着电话和电脑，你的精力指数为7.3（最高位10）你应该做些什么呢？给客户回一个电话，考虑一下新的提案？处理一下语音信箱里的留言和电子邮件，或者联系一下你的配偶，看看他/她这一天过得怎么样？ 这时，你可以借助你的直觉，并依赖你此时此刻的判断力。\u003c/p>","explains":"\u003cp>【why】\u003c/p>\u003cp>对于现在人来讲，事情一般都比较满，过多的信息量造成我们一会儿做那件事儿，一会儿忙这件事儿，一整天下来总给人一种“碌碌无为”的感觉。想要专注的完成一件事儿需要我们通过有效的评估方式确定当下最能做的事情来提升做事效率。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>“选择行动四标准法”可以帮助我们从情境，时间，精力和重要性四个维度，判断在什么时间做什么事更有价值，从而选择最合适的行动。\u003c/p>\u003cp>那我们该怎么用呢？\u003c/p>\u003cp>【how】\u003c/p>\u003cp>当我们在某个时间点要安排具体的行动项目的时候，\u003c/p>\u003cp>\u003cstrong>第一步\u003c/strong>：分析情景\u003c/p>\u003cp>目前的行动项目所需要的情景是：室内或室外，是否需要电脑等其他设备，抑或一个人完成还是需要他人协同完成。\u003c/p>\u003cp>第二步：\u003cstrong>预估可支配时间\u003c/strong>\u003c/p>\u003cp>如果只有五分钟，那就只能微信回回消息打打电话。如果有半个小时以上，那就可以考虑写写工作计划什么的。\u003c/p>\u003cp>\u003cstrong>第三歩：判断精力值\u003c/strong>\u003c/p>\u003cp>处理不同的事情精力状态要求不同，就像做ppt，写文章就很烧脑，一定要思路清晰，精力值要求也较高。而跑步就只需要你有体力即可。\u003c/p>\u003cp>\u003cstrong>第四步：判断重要性\u003c/strong>\u003c/p>\u003cp>在前面三个因素都考虑后，最后我们要\u003cstrong>评估哪个行动在此刻更重要\u003c/strong>，相同的事情在不同的时刻重要性也可能不同，故选择此刻最重要的去做。\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>这个方法适合在特定的场景下手头有多个行动事项，想要安排但又不知道如何选择的情况确定当下可做的事项，比如办公室、家里等。不适合仅有一个很明确的行动项目或已确定不可更改的计划时使用，也不适合突发紧急情况的判断。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】下面我分享下我的个人经历：\u003c/strong>\u003c/p>\u003cp>这件事情就发生在过年期间，在妹妹的婚宴上拿着电脑加班的事情。\u003c/p>\u003cp>正月初六中午是妹妹婚礼待客宴会，当天妹妹的化妆和造型都是计划由我来操办，刚好当天又有很多家里的亲戚会来，又要招待大家，事情就比较多。但由于当天恰好工作上有一个事情要处理，不是最为紧急，但要在14点前完成。我开始并没有详细的计划时间安排，只是忙当时眼前的事情，最后弄得很紧张，带着电脑到酒店去完成的工作。如果现在重新梳理，我会按照如下方式安排当时行动：\u003c/p>\u003cp>1. 分析情景：给妹妹做造型需要在家完成，接待亲人要在酒店完成，工作需要笔记本电脑完成，所以早上在家我应该先处理在家要完成的任务；\u003c/p>\u003cp>2. 预估时间：做造型大概需要1h，我需要在12:30前完成；工作需要30min，需要14点前完成；\u003c/p>\u003cp>3. 评估精力：做造型更多是需要细致即可，而工作需要精力值比较高，我应该选择在精力值最高的早上完成；\u003c/p>\u003cp>4. 判断价值：妹妹待客是当天的大事，工作也比较重要，我可以合理安排时间处理完成，让两件重要的事情都能很好完成。\u003c/p>\u003cp>【A2】规划未来的应用\u003c/p>\u003cp>学习并深刻理解“四标准法”后，我在每天晚上做次日行动事项时会按照需要场景、时间、精力及重要性排序。明日预计要做的项目：\u003c/p>\u003cp>1. 写拆书稿（需要高精力，预计1.5h，需要电脑）；\u003c/p>\u003cp>2. 支援一线配送工作（预计三小时，精力要求：一般）；\u003c/p>\u003cp>3. 运动健身（跳操拉伸，预计1h，体力要求高）；\u003c/p>\u003cp>4. 起草老带新方案（1.5h，精力要求高）\u003c/p>\u003cp>按照这些标准划分，我会在早上起床后完成第1项任务；然后完成第4项任务；下午完成第2项任务；下午下班回来完成第3项任务。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1647573779000,"updated_at":1649333942000,"ria":true},{"id":12908,"topic":"如何选择下一步行动  让时间利用更高效？","learn_goal":"","remark":"时间管理只会按重要，紧急程度来分？即使做了计划，当一堆事情砸来的时候，还是手忙脚乱，不知道做什么好？你需要一个更高效的，判断如何在某个时刻安排下一步行动的方法。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"青青2015","city":"杭州市"},"club":{"name":"杭州光明顶分舵","city":"杭州"},"prologue":"\u003cp>大家好，欢迎来到拆书帮的现场。我是青青，从事0-6岁教育行业的知识工作者，期望能用自己的学习力影响更多人找到更好的自己。\u003c/p>\u003cp>今天我给大家带来的这个片段来自《搞定1 无压工作的艺术》，豆瓣评分8.3分，是本席卷世界的畅销书。这本书会帮助我们\u003cstrong>如何更高效的利用时间，让事情井井有条，生活和工作都更加从容、放松。\u003c/strong>\u003c/p>\u003cp>关于时间管理我们常用的是四象限法，根据事情的重要性和紧急程度来规划时间。今天，我会为大家介绍\u003cstrong>另一种帮助我们高效利用时间\u003c/strong>的方法。\u003c/p>\u003cp>首先，我们先用1分钟的时间来阅读手中的片段。阅读完的小伙伴可以举手示意我。\u003c/p>","ratings_count":1,"texts":[{"id":16879,"quote":"\u003cp>\u003cstrong>片段来源：《搞定1》 P.73\u003c/strong>\u003c/p>\u003cp>确定某一时刻具体行动的“四标准法” \u003c/p>\u003cp>在星期三下午3:22时，你如何选择下一步行动呢？你可以按顺序采用下面四个标准，\u003c/p>\u003cp>（1） 情境 （2）有多少时间 （3）有多少精力 （4）重要性 \u003c/p>\u003cp>\u003cstrong>情境-\u003c/strong>只有很少一部分事情对地点没有特别的要求(像拿一支钢笔和一张纸，就可以起草对一个项目的想法)，但是大多数事情都只能在特定的地点完成(在家或办公室)，或者需要借助某些特定的工具（如一部电话一台电脑），而这正是限制我们选择行动的首要因素。 \u003c/p>\u003cp>\u003cstrong>有多少时间\u003c/strong>—你所能支配的时间长短也是一个重要的限制因素，如果5分钟后你就必须去开会，你现在就不可能去执行那些耗时更久的行动。 \u003c/p>\u003cp>\u003cstrong>有多少精力\u003c/strong>—你有多少精力呢？有某些事情需要你头脑清醒，思路清晰，富于创造力，而另一些则要求你具备充沛体力，除此之外的一些事情是对这两方面都没有特别要求。 \u003c/p>\u003cp>\u003cstrong>重要性-\u003c/strong>当你考虑了情境，时间,精力这三个条件后，你就要选择哪个行动会给你最高的回报了，现在你有一个小时时间，你坐在办公室里守着电话和电脑，你的精力指数为7.3（最高位10）你应该做些什么呢？给客户回一个电话，考虑一下新的提案？处理一下语音信箱里的留言和电子邮件，或者联系一下你的配偶，看看他/她这一天过得怎么样？ 这时，你可以借助你的直觉，并依赖你此时此刻的判断力。\u003c/p>","explains":"\u003cp>好的，谢谢。刚才我看到大家都看完了，而且很认真，现在我为大家拆解一下这个片段。\u003c/p>\u003cp>\u003cstrong>【I环节：5分钟】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【why】\u003c/strong>\u003c/p>\u003cp>在某一时刻，我们常常会陷入不知道下一步做什么好的状态。有时一直犹豫纠结，时间不知不觉就浪费了。有时一会做做这个，一会做做那个，忙忙碌碌了一天，结果最重要的事都没完成，效率很低。\u003c/p>\u003cp>那么怎么做，我们才能更好的选择下一步行动，让时间利用更高效呢？\u003c/p>\u003cp>\u003cstrong>【what】\u003c/strong>\u003c/p>\u003cp>“选择行动四标准法”可以帮助我们从情境，时间，精力和重要性四个维度，判断在什么时间做什么事更有价值，从而选择最合适的行动。\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>\u003c/p>\u003cp>下面，我们来看看具体怎么做。\u003c/p>\u003cp>\u003cstrong>分析情境：想做的事是否受地点和工具的限制。\u003c/strong>\u003c/p>\u003cp>(1) 你现在是在哪里呢？家、办公室、车上，还是其它地点......\u003c/p>\u003cp>(2) 你想做的事需要什么工具呢？手机、电脑、网络.....\u003c/p>\u003cp>\u003cstrong>预估时间：接下来有多少时间能自由支配。\u003c/strong>\u003c/p>\u003cp>如果只有五分钟，那就只能微信回回消息打打电话。如果有半个小时以上，那就可以考虑写写工作计划什么的。\u003c/p>\u003cp>\u003cstrong>判断精力：当时的精力是否旺盛。\u003c/strong>\u003c/p>\u003cp>不同的事情，对精力状态要求是不一样的。像做设计，写方案就很烧脑，一定要思路清晰。那跑步的话，就要有足够的体力了。\u003c/p>\u003cp>\u003cstrong>看重要性：\u003c/strong>在前面三个因素都考虑后，最后我们要\u003cstrong>评估哪个行动带来的回报最高\u003c/strong>，选择最重要的去做。\u003c/p>\u003cp>假设上午10点，在办公室，正值精力充沛的时候，如果有1个小时的时间，你是会写方案，还是和客户沟通报价问题，还是把没有处理的邮件信息都回复了？\u003c/p>\u003cp>\u003cstrong>【where】\u003c/strong>\u003c/p>\u003cp>这个方法适合在某个时刻想要安排事情，但是不知道如何选择的情况。不适合时间安排固定不可更改，也不适合突发紧急情况的判断。\u003c/p>\u003cp>【例子】\u003c/p>\u003cp>\u003cstrong>下面我分享下我的个人经历：\u003c/strong>\u003c/p>\u003cp>上周一上午的时候，我就遇到事情太多没有选择好，弄得手忙脚乱，最重要的事没有做好的情况。那天早上从八点到九点半，我安排了带孩子打疫苗，送孩子上学，退快递，会议准备四件事。当时就是很被动的按照时间先后去完成，结果因为时间太赶了，会议准备没有做好。现在让我重新选择，我会这样做。\u003c/p>\u003cp>\u003cstrong>分析情境：\u003c/strong>当时我一直处于不同环境的变动中，会议准备是需要在安静的环境，用手机整理思路的。\u003c/p>\u003cp>\u003cstrong>预估时间：\u003c/strong>我需要30分钟的时间做会议准备，应当把这部分时间预留出来，把其他事情进行删减。\u003c/p>\u003cp>\u003cstrong>判断精力：\u003c/strong>早上的时候我的状态都不是很好，没有精力同时处理很多事。我应当减少一些事情的安排，让自己更有精力去思考。\u003c/p>\u003cp>\u003cstrong>看重要性：\u003c/strong>那天最重要的事情是关于会议准备，其他事情是可以做取舍的。比如送孩子上学是爷爷奶奶可以代替，寄快递是可以另外安排时间的。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1激活经验，给学习者分组】5分钟\u003c/strong>\u003c/p>\u003cp>【引指小组分享指令清晰】1分钟\u003c/p>\u003cp>大家读过拆页，也听了我的分享，请大家想想，\u003cstrong>在过去的一两周里\u003c/strong>是否遇到过类似的情况呢？\u003c/p>\u003cp>早上来到公司，打开工作清单，感觉事情太多做不完，不知道先做什么好，你当时是怎么做的？\u003c/p>\u003cp>下午三点，本来想写方案，但是感觉有些疲惫，是继续写方案还是选择其他的事情呢？\u003c/p>\u003cp>安排了下午花两个小时要去拜访客户，临时取消了，这个时间你会怎么安排？ \u003c/p>\u003cp>\u003cstrong>请大家按顺时针顺序，2个人组成一个小搭档，给大家2分钟的时间，\u003c/strong>互相分享下自己的经历，并简单的分析下在分析情境、预估时间、判断精力、看重要性，这四个标准是否有做到。\u003c/p>\u003cp>（小组内部交流分享）\u003c/p>\u003cp>\u003cstrong>好了，时间到。下面邀请一位伙伴来分享，请想要分享的小伙伴举手。（2分钟）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>sherry分享：\u003c/strong>\u003c/p>\u003cp>情境是晚上在家里，有很多时间，我需要拍个视频，但是晚上是能量比较低的时候。虽然原计划是拍视频，但是我那个时候能量比较低，所以我打算先把脚本写好，然后第二天早上再拍拍视频。虽然定了计划，但拍视频并不是非常重要的事情，所以我改成第二天早上高能量的时候。\u003c/p>\u003cp>\u003cstrong>谢谢这位小伙伴的分享\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A2催化应用】\u003c/strong> \u003cstrong>3分钟\u003c/strong>\u003c/p>\u003cp>接下来请大家想一想\u003cstrong>明天上班，先应用今天学到的“选择行动四标准法”来规划下上午三个小时的工作\u003c/strong>，请在标签纸上写下自己的安排！\u003c/p>\u003cp>比如，明天上午我是在办公室，我会安排在10-11点，精力状态最好的时候用电脑写活动方案PPT。\u003c/p>\u003cp>请大家参考这个样例，在便签纸上写下你的行动计划，\u003cstrong>1分钟时间\u003c/strong>，注意下，计划要符合SMART原则，请写出具体的做法，有明确的时限，可衡量的预期结果。\u003c/p>\u003cp>大家都写完了吗，下面请一位小伙伴来分享下。（1分钟）\u003c/p>\u003cp>\u003cstrong>瑞雪分享：\u003c/strong>\u003c/p>\u003cp>明天上午是工作日，情境是在办公室工作的环境，工具会用到电脑和参考书籍，预估时间是在10：00-11：30的时候是比较专注的，因为假期第一天上班，精力也不是太好。从重要性上来说，选择的工作会做企业文化项目的总结复盘。\u003c/p>\u003cp>最后我来总结一下今天学到的内容。这个片段告诉我们，\u003cstrong>如何通过“选择行动四标准法，确定下一步行动，让每个时间都能高效利用，更有价值。\u003c/strong>\u003c/p>\u003cp>好了，我今天的分享就到此结束了，希望今天的分享能够给大家带来帮助，下次再见！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1641390663000,"updated_at":1641971231000,"ria":true},{"id":12553,"topic":"工作优先级排序","learn_goal":"","remark":"每天我们面前总是摆满了长长的事务清单，很多时候我们没有充足的时间来处理，这时，你如何选择做哪些事情或者不做哪些事情呢？通常大部分人都是依靠直觉或者喜好来选择，但事情证明，这种感性的判断和选择方式，常常让我们处于尴尬或懊恼的境地。是否有更明智的决策方法呢？《搞定》的“四标准法”可以帮助我们确定某一时刻的具体行动，帮助我们做出更周全的选择。","level":"TF1-2","duration":14,"status":30,"type":0,"chaishujia":{"username":"徐徐","city":"石家庄市"},"club":{"name":"石家庄梧桐分舵","city":"石家庄"},"prologue":"\u003cp>大家好，我是徐徐，现在开始TF1-2的拆书过级。用三个标签介绍下自己，互联网产品经理、个人成长实践者和不断升级的拆书家。\u003c/p>\u003ch2>今天我们要拆的书是《搞定》，也称为无压力工作的艺术。\u003c/h2>\u003cp>这本书是世界知名时间管理大师、具有影响力的个人与组织效率专家戴维·艾伦的经典著作，已在33个国家出版，风靡全球十余年，是时间管理领域具有影响力的著作。\u003c/p>\u003cp>书中介绍的GTD（Getting Things Done）时间管理法是全球千万人在使用的高效完成工作与管理个人事务的优秀工具。今天我们一起走进这本看似简单易行，背后却有深刻洞见的书。\u003c/p>\u003cp>为了方便今天拆书活动的讨论环节，我们根据现场人员分成一组。\u003c/p>\u003cp>\u003cstrong>拆书技能点1：拆书活动前，已发送《拆书预备表》给观察家，且内容填写准确、完整。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书技能点2：选择图书是实用类或理论类图书\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书技能点4：对现场学习者进行分组。\u003c/strong>\u003c/p>","ratings_count":1,"texts":[{"id":16473,"quote":"\u003cp>\u003cstrong>拆书技能点3：拆页内容未超过2页图片内页。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书技能点5：【R】所选拆页包含具体行动或做法。\u003c/strong>\u003c/p>\u003cp>这次拆解的原文片段来自于《搞定》的“确定某一时刻具体行动的“四标准法”。刚才我已经把原文拆页发给大家了，现在请各位用3分钟的时间阅读一下原文片段，完成后麻烦小伙伴举手示意我。\u003c/p>\u003cp>选书：《搞定》\u003c/p>\u003cp>拆页：确定某一时刻具体行动的“四标准法”\u003c/p>\u003cp>在星期三下午3点22分时，你如何选择下一步行动呢？这个时候，你可以按顺序采用下面四个标准：情境、有多少时间、有多少精力和重要性。前三个标准描述了你每次采取行动的制约因素，第四个标准则是评估行动的价值大小。\u003c/p>\u003cp>情境\u003c/p>\u003cp>每时每刻，你都受限于自己的行动能力。只有很少一部分事情对地点没有特别要求（像拿一支钢笔和一张纸就可起草对一个项目的想法），但是，大多数事情都只能在特定的地点完成（在家或办公室），或者需要借助某些特定的工具（如一部电话、一台电脑），而这正是限制我们行动选择的首要因素。事情总是多得做不完，你可以每次只做一件事。无论是否已经采取行动，关键在于使自己保持良好的状态。\u003c/p>\u003cp>有多少时间\u003c/p>\u003cp>你所能支配的时间长短也是一个重要的限制因素。如果5分钟后你就必须去开会，你现在就不可能去执行那些耗时更久的行动。\u003c/p>\u003cp>有多少精力 你有多少精力呢？某些事情需要你头脑清醒、思路清晰、富于创造力，而另一些则要求你具备充沛的体力。还有一些事情则对这两方面都没有特别要求。\u003c/p>\u003cp>重要性\u003c/p>\u003cp>当你考虑了情境、时间、精力这三个条件后，最后你就要判断哪个行动选项会给你最高的回报了。现在，你有1个小时的时间，你坐在办公室里守着电话和电脑，你的精力指数为7.3（最高为10）。你应该做些什么呢？给客户回一个电话？考虑一下新的提案？处理一下语音信箱里的留言和电子邮件？或者联系一下你的配偶，看看她/他这一天过得怎么样？这时，你可以借助你的直觉，并依赖你此时此刻的判断力。\u003c/p>","explains":"\u003cp>\u003cstrong>拆书技能点6：【I】拆书家讲解引导中包含了：1）行动建议步骤；2）与行动各步骤对应的案例。\u003c/strong>\u003c/p>\u003cp>好，大家都读完了，下面我带领大家一起拆解一下这个片段。\u003c/p>\u003cp>每天我们面前总是摆满了长长的事务清单，很多时候我们没有充足的时间来处理，这时，你如何选择做哪些事情或者不做哪些事情呢？通常大部分人都是依靠直觉或者喜好来选择，但事情证明，这种感性的判断和选择方式，常常让我们处于尴尬或懊恼的境地。是否有更明智的决策方法呢？\u003cstrong>Why\u003c/strong>\u003c/p>\u003cp>这个片段中的 “四标准法”通过3个制约因素，1个重要性排序，帮助我们确定某个时间点或时间段的具体行动。\u003cstrong>What\u003c/strong>\u003c/p>\u003cp>具体怎么做呢？我们来梳理一下“四标准法”：\u003c/p>\u003cp>1、 情境判断：确定事情是否需要特定的地点或特定的工具才能完成。\u003c/p>\u003cp>判断你当下的情境与待办事项的匹配度。\u003c/p>\u003cp>2、 时间预算：你具体有多少时间可以支配，哪件事情花费时间更合适？\u003c/p>\u003cp>3、精力评估：你当前的精力情况如何，体力状态如何？哪些事情需要精力或体力充沛才能完成，哪些事情对此要求不高。寻找与你当前状态匹配的事情。\u003c/p>\u003cp>4、重要性排序：以最高回报为评估依据，做那件事对你收益最大的事情。\u003cstrong>How\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【重点】\u003c/strong>这个“四标准法”适用于有事务清单或执行事先安排好的工作，不适合于处理突发事件，这个方法帮助我们优先选择做什么事，适用于有选择的场合。\u003cstrong>Where\u003c/strong>\u003c/p>\u003cp>拿我上周五的例子来帮助大家理解一下。下午4点半，我在家中，有1小时的空余时间，手头有三件事可做，处理机动车违章记录，运动健身、阅读。到底该做哪件事呢？ 按照以前的选择习惯，我更倾向于按自己的喜好，会优先选择运动和阅读。而运用“四标准法”判断结果会怎样？\u003c/p>\u003cp>1、情境判断 \u003c/p>\u003cp>运动健身可以在家里，也可以去附近的公园；阅读在家中就可以进行；处理机动车违章记录需要出门到附近的警察亭。 \u003c/p>\u003cp> 2、 时间判断\u003c/p>\u003cp>运动健身，一般都是30-60分钟，阅读的时间，可以根据需要可长可短，60分钟是个不错的选择。处理机动车违章记录大概需要30分钟左右。\u003c/p>\u003cp> 3、 精力评估\u003c/p>\u003cp>下午4点半是喝下午茶的时候，需要补充精力，精力值大概为4。体力值大概为6。运动健身主要对体力有要求，当前的体力没有问题。阅读，需要精力值大概在6以上，有点吃力。处理机动车违章对体力和精力都没有要求。\u003c/p>\u003cp> 4、 重要性排序\u003c/p>\u003cp>运动健身和阅读是精神和身体的更新，属于日常重要习惯。处理机动车违章记录，临期了，需要尽快处理，非常重要。\u003c/p>\u003cp>通过以上四个维度的评估，我优先选择了处理机动车违章，然后剩余30分钟到附近公园跑步。 这个决策显然比依靠直觉更加周全。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书技能点7：【A1】指令清晰。学习者在小组内分享了自己的经验并有一位代表分享了本组的一个经验，对现场学习者进行了分组。\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>通过解读这个拆页和举例分析，我们了解到确定某一时刻具体行动的“四标准法”应该在什么场景下使用，具体怎么做。下面请大家回想一下自己过去一周或者一个月，有没有某一时刻面临选择做什么或不做什么的情境或经历呢？或者纠结某个时间点该做什么的情景呢？认真思考一下，在小组内分享，要求有明确的时间、地点、人物、和事件。时间5分钟。\u003c/p>\u003cp>好，时间到，哪位小伙伴愿意分享一下自己的经历？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>时间：某天晚上7点50分。\u003c/p>\u003cp>地点：在餐厅用餐完毕，下一个安排是去电影院看电影，电影的开始时间是8点50.\u003c/p>\u003cp>人物：张先生和他女朋友\u003c/p>\u003cp>事件：吃完饭和看电影的空档时间是1小时，不知道如何安排？是会单位加班？还是回家？或者在车里安静的坐一会呢？\u003c/p>\u003cp> \u003cstrong>拆书技能点8：【A2】指令清晰。提醒每个学习者都写下了一个包含具体做法，其中包含具体的行动方案，有明确时限和可衡量或可观测预期结果的便签。\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>谢谢这位小伙伴的分享。那现在请大家花1分钟的时间来应用练习一下，按GTD“四标准法”确定你明天早上或晚上某一具体时刻要做的事“写在便签上。要求有具体的行动方案、明确的期限以及可衡量的结果。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>目标：运用GTD“四标准法”确定你明天早上某一具体时刻要做到事。\u003c/p>\u003cp>行动：时间和地点是早上上班路上8点10分到8点半，大概15到20分钟，有三件事可以干，听歌，看手机app，或者听得到电子书。\u003c/p>\u003cp>考虑到自己的精力比较充沛，决定听得到电子书。 \u003c/p>\u003cp>期限：明天早上使用GTD“四标准法”一次安排要做的事情。\u003c/p>\u003cp>\u003cstrong>拆书技能点9：总时长不少于10分钟，没有超过15分钟。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书技能点10：每个环节的时长分配符合本级训练概述的要求。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书技能点11：按“逐字稿包含开场、R、I、A1、A2、A3……的预备表+现场完整案例”格式整理实录。（此项可在活动结束后校验）\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1635212479000,"updated_at":1635212955000,"ria":true},{"id":11990,"topic":"如何更好的管理你的承诺？逃离忙碌且盲目的陷阱！","learn_goal":"","remark":"如果你在任何情况下、任何时间内都能够随心所欲地控制自己的一切事务，情况会是怎么样呢？如果你的内心世界非常清澈，感受不到任何压力，情况会怎样？","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"清风不二","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"\u003ch1>可观察衡量的目标\u003c/h1>\u003cp>大家好，我是今天的拆书家清风，希望通过本次拆书，大家能运用管理承诺的3个要求，对自己未来一周的承诺做一次判断。\u003c/p>\u003ch1>FAB图书介绍-163字-2分钟\u003c/h1>\u003cp>【F】：《搞定》是一本时间管理的经典著作，作者戴维·艾伦是被誉为世界最有影响力的工作效率提升大师，同时他也是世界银行、盖茨基金会，的组织效能首席顾问。\u003c/p>\u003cp>【A】：这本书经历过了时间的考验，自2001年出版后，13次再版，是目前时间管理领域最有影响力的著作之一，豆瓣评分8.3分，很多书都能看到他的影子，比如我之前拆的《小强升职记》就算是它的故事版本。\u003c/p>\u003cp>【B1】： 这本书将告诉你如何使用GTD的核心方法，帮助你走工作的泥沼，有效运用时间，实现无压力的工作艺术嘛。\u003c/p>\u003cp>【B2】：今天这个拆页能够帮助你更好的理解和管理你的承诺。\u003c/p>","ratings_count":1,"texts":[{"id":15948,"quote":"\u003cp>\u003cstrong>拆页原文-220字-2分钟\u003c/strong>\u003c/p>\u003cp>管理承诺时的基本要求\u003c/p>\u003cp>如果希望出色地管理好所有的工作，那么，你需要做到下面几点：\u003c/p>\u003cp>第一，如果这件事总占据着你的头脑，你的思维就会受阻。任何一件你认为还没有完成的事情，都必须被置于一个客观、可靠的体系中，或者是我称为“文件夹”的工具之中——必须经常回访并予以清理。\u003c/p>\u003cp>第二，在明白你的工作到底是什么后，你还必须做出判断：需要采取什么行动来推动工作进程。\u003c/p>\u003cp>第三，一旦决定了需要采取的行动方案，你必须在某一个你会经常查阅的系统中保存好与这些行动相关的提示信息。\u003c/p>","explains":"\u003cp>拆书家引导讲解-620字-6分钟\u003c/p>\u003cp>\u003cstrong>what:\u003c/strong>\u003c/p>\u003cp>今天这个拆页解决的问题是“如何管理自己的承诺”，它需要满足3个基本要求，分别是收集承诺，理解承诺，回顾承诺。我们先来聊一下什么是承诺？\u003c/p>\u003cp>承诺就是你和自己或他人达成的协议，可以是未完成的事情，可以是晚上做一个可乐鸡翅，下周去拜访客户，或者悬而未决的问题。比如中午吃什么？我什么时候能在上海买房？什么时候我才能成为3级拆书家？\u003c/p>\u003cp>\u003cstrong>Why：\u003c/strong>\u003c/p>\u003cp>那么我们为什么要管理自己的承诺呢？主要有两点原因，第一个是给他人的承诺，如果一个人总是无法完成对你的承诺，你还愿意把下一次的项目交给他么？第二个是对自己的承诺，如果一个人总是无法完成对自己的承诺，他会不断的贬低自己，失去自信心，然后更加拖延不想做事情，于是再次失败，陷入恶性循环。\u003c/p>\u003cp>\u003cstrong>HOW：\u003c/strong>\u003c/p>\u003cp>那么该如何管理承诺呢？拆提到了这样3点：\u003c/p>\u003cp>1.用单独工具收集承诺\u003c/p>\u003cp>2.制定行动方案来推动承诺\u003c/p>\u003cp>3.在常用场景下，设置行动方案的提醒\u003c/p>\u003cp>首先是用单独工具收集承诺，我们为什么要收集承诺呢？\u003c/p>\u003cp>因为你的大脑并不总是那么有用，有句话叫做“好记性不如烂笔头”，你需要有一个地方保存你的这些念头。\u003c/p>\u003cp>如果你没有把这些承诺收集，并记录下来，那么他们就总会缠绕在你心头，让你念念不忘。\u003c/p>\u003cp>这里面特别强调的是，收集的工具尽量是你触手可及的，并且高频出现在你身边的，比如手机的便签，微信的传输助手，都是你快速收集你的承诺的好帮手，它会帮助你更完全的收集你的承诺。\u003c/p>\u003cp>其次是制定行动方案来推动承诺\u003c/p>\u003cp>就是知道我们为什么要做这件事，以及接下来推动承诺落地的行动计划是什么。\u003c/p>\u003cp>当一个大的棘手大项目向我们袭来的时候，我们会有下意识的畏难抵触情绪，这种情绪会阻碍行动，所以我们要将任务进行拆解，直到拆分到第一个5分钟内可以做的行动，比如“收集一下工作背景”，“问一下同事之前谁做过相关的工作”。\u003c/p>\u003cp>最后是在常用场景下，设置行动方案的提醒\u003c/p>\u003cp>我们看拆页中有2个关键词，一个是“经常查阅”，一个是“提示”，前者是增加触发回顾这个环节的概率，后者的“提示”是说帮助你回访承诺的内容和进度。\u003c/p>\u003cp>When:\u003c/p>\u003cp>这个拆页的有两个使用边界，第一个是你相信承诺是可以被管理的，第二个是你希望更出色的完成全部承诺，而不是完全随心所欲，想到哪，做到哪。\u003c/p>\u003cp>【举个栗子】-工作场景\u003c/p>\u003cp>上个季度末我们小组茶话会，聊自己下个季度的想法，然后我想出一个旅游行业报告，我把它记录在了笔记本上，但是半个季度过去了，也一直没开始，直到上周我要换新笔记本，才发现了这个case，结合今天的拆页，我做得好的点是收集了这个承诺，并且无意识的回访承诺，让我看到了这个工作，但我并没有理解这个承诺，没有探索为什么要做这个行业报告，现在我理解了，这个行业报告对于我来说，至少有2个价值，一个是行业的深度研究，另外一个是报告对外输出算是我的季度工作亮点，也算是团队工作亮点，于是我就开始着手收集资料，并设定了一个闹铃，提醒我每周3回顾进度，跟进下一步行动计划。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>可能有的小伙伴会问，这么做就一定能够兑现自己的承诺么？答案是否定的，我们通过这3个步骤，可以做到让你的承诺更容易被看见，更容易被行动被落地，实际工作中你可能会因为遇到突发状况，调整你的承诺内容和完成期限。\u003c/p>","interaction":"\u003ch1>A2分步催化-7分钟\u003c/h1>\u003cp>【分步催化1：指向未来的显像提问】-5分钟\u003c/p>\u003cp>分步催化1：\u003c/p>\u003cp>明天是周一，想象一下你早上到公司，泡好一杯茶，坐在工位上，想起了今天的拆书，打算尝试一下工作承诺的管理，于是你写下了本周要处理的全部工作。\u003c/p>\u003cp> 分享案例：\u003c/p>\u003cp>LZ同学：\u003c/p>\u003cp>1.跟专利老师定稿，把稿件投出去\u003c/p>\u003cp>2.书架整理，决定看书顺序\u003c/p>\u003cp>【分步催化2：学习者加工未来的场景】-2分钟\u003c/p>\u003cp>感谢A同学分享，已经完成了承诺管理的第一步收集承诺。\u003c/p>\u003cp>你觉得做“专利定稿”对你的帮助是什么，下一步你打算怎样开始这件事情？以及把它放在怎样的场景下更容易触发呢？\u003c/p>\u003cp>LZ同学：\u003c/p>\u003cp>收集整理书架，找到看书顺序列表：用手机收集好这个待办需求，理解整理书架，是为了把“数据图像分析”类书籍顺序前置，同时安排好每天晚上睡觉前看半小时书，在床边设置好这个提醒。\u003c/p>\u003cp>【伙伴分享】\u003c/p>\u003cp>【强有力的结尾】\u003c/p>\u003cp>以上就是我今天的拆书分享，相信大家都对下周工作做了承诺管理的检验，期待大家的实践分享。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1627314708000,"updated_at":1637024463000,"ria":true},{"id":11433,"topic":"如何清理工作篮","learn_goal":"","remark":"搞定","level":"TF2-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"谭亭亭","city":"湖州市"},"club":{"name":"苏州阅苏分舵","city":"苏州"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>各位小伙伴早上好，欢迎大家来到2-2的拆书现场，我是谭亭亭，谭咏麟的谭，亭亭玉立的亭。用三个标签介绍一下自己：首先我是一名一级拆书家，成为三级拆书家是我接下来的目标；其次我是一名高校教师，通过我的不断学习带领学生打怪升级是我的终极梦想；最后我还是一个宝妈，有一名8岁女儿，最享受的时光就是与女儿一起畅聊未来。\u003c/p>\u003cp>为了更好的讨论，我们首先就近原则将小伙伴分为两组。\u003c/p>\u003cp>【图书介绍】\u003c/p>\u003cp>【F】今天拆解的片段选自世界时间管理大师戴维·艾伦的《搞定I：无压力工作艺术》，这是目前最具影响力的时间管理类著作。其提出的理念Get things done(GTD)被奉为时间管理的经典。目前市面上很多时间管理类的书籍中，都有GTD的影子。\u003c/p>\u003cp>【A】具体来说，《搞定》介绍的方法独特性有二：其一，方法更具宽容性。书中介绍的方法呈现出较强的模块化特征，即便你无法全盘掌握其中的GTD体系，某些模块的应用，比如2分钟法则，依然能提高工作效率；其二，方法更具适用性。目前世界上已经开发出上百款专门针对GTD的工具，如Wunderlist（奇妙清单）、Omnifocus，以及滴答清单。这些软件都为重度GTDer提供了发挥的空间。\u003c/p>\u003cp>【B】（B1）《搞定》中提出的GTD工作方法包含了5个步骤：即收集、整理、组织、回顾、行动，通过这5个步骤的逐步使用，可以让你真正把事情搞定，而不是一直留着一些没有处理完的清单持续焦虑；（B2）今天的拆页着重关注其中的第二个阶段：清空工作篮。往往是这个环节的忽视，让我们的生活一度陷入忙乱，在做重要的事情之前，清空大脑，分类处理信息，并对不同信息区别处理是高效完成工作的重要环节。\u003c/p>\u003cp>请大家花1分钟时间浏览一下拆页内容，对于拆页中的流程表，重点关注黑色加粗部分的内容，也就是中间一列的内容。请阅读完成后举手示意我。\u003c/p>","ratings_count":1,"texts":[{"id":15355,"quote":"\u003cp>l R（阅读原文拆页。选自《搞定I：无压力工作艺术》P173-174）\u003c/p>\u003cp>\u003cstrong>理清阶段：清空工作篮\u003c/strong>\u003c/p>\u003cp>假如你已经完成了收集过程，现在你要做的就是彻底清空你的工作篮。所谓清空工作篮，并不意味着完成你所收集到的全部工作。\u003cu>它指的是识别你收集到的每样东西，确定它是什么，它意味着什么，它需要你采取什么样的行动\u003c/u>。如果你希望从总体上了解工作处理流程，你可以参考下述工作处理流程图。中间一列内容(位于直角方框中)，就是你在处理和确定下一步行动过程中需要采取的具体步骤。本章介绍的重点，就是\u003cstrong>中间这一列\u003c/strong>的内容，它们将工作篮中的任务转化为具体的下一步行动。你将看到，任何一个悬而未决的问题在经过这几个步骤的处理之后，都能迎刃而解。它会帮助你明确下一步行动。比如，你拿起工作篮中的某样东西时，意到“我该给安德里娅打个电话，告诉她这件事情。算了，还是等到星期一她在办公室的时候再打吧”，那么你要做的就是将“给安德里娅打个电话”这个行动推迟，并把它记录在你的日程表里。\u003c/p>","explains":"\u003cp>I：拆书家讲解引导\u003c/p>\u003cp>你可能也有这样的困扰，每天都在接收和应付四面八方扑来的各种信息和工作，包括老板布置的各类任务，下属提出的协助要求、需要打扫的房间……当这些信息和工作进入到你的待处理清单（工作篮）中时，你会如何处理？通常的反应是：直接去做啊！还等什么？！然而，这么做的结果不是高效的完成任务变得更轻松，而是会让你的待办清单越来越冗长，堆积了越来越多未能完成的任务，陷入永无止境的焦虑。\u003c/p>\u003cp>（负面例子）试想一下：早晨，作为产品经理的你刚坐到办公桌前就接到老板的电话：上午把A产品品牌宣传的PPT做好，下午开会要用，于是赶紧交代下属整理资料完成初稿，要求中午前提交以便午休修改。交代到一半，又接到市场部的电话，要求就B产品的市场计划做出邮件回复，以便进一步修改；邮件刚开头，实习生来说：老大，昨天您交代的数据表我有些地方不明白，能否指教一二？于是，你拿起电脑和资料开始给实习生讲解数据表。好不容易讲完了，却突然意识到已经11:00点了，赶紧去问下属资料整理情况，下属却说：还没整理完。只好自己抱了一堆资料回办公室做PPT，12：45终于做好了PPT，却发现忘记了定午餐……\u003c/p>\u003cp>一天下来，你一直处于高度紧张状态，应付不断出现的新状况，到了快下班时，才突然想起市场部的邮件还没有回复，答应女儿的蛋糕也没有定……\u003c/p>\u003cp>（what）回想一下你是否也有过同样的感受？为什么会这样呢？原因是面对扑面而来的各种任务信息你选择了直接行动。片段介绍了接收任务信息到行动之间的步骤：清空工作篮。有了这个步骤，可以让你更容易掌控生活。\u003cu>通过今天的RIA现场学习，大家可以试着找到1-2个适合自己的工作篮，并运用清空工作蓝的方法对自己的工作日常进行重新规划，每天至少节约1-2个小时工作时间\u003c/u>。（学习目标）\u003c/p>\u003cp>（how）怎么做到呢？我将其总结为四个步骤（ACTS）：\u003c/p>\u003cp>\u003cstrong>第一步：\u003c/strong>（\u003cstrong>A\u003c/strong>dd）将任务信息加入工作蓝。工作篮是帮你将信息暂时移至头脑之外，不占据当下精力的一种方法。工作篮可以是手机上的记事本、备忘录或者各种云端笔记。\u003c/p>\u003cp>\u003cstrong>第二步：\u003c/strong>（\u003cstrong>C\u003c/strong>lassify）对工作篮中的信息进行分类。被放入工作篮的信息可以被分为两类：一类是需要及时处理的，一类是不需要处理的，包括一些没用的垃圾信息或者暂时不需要的信息。对于不需要处理的信息，可以直接扔掉（垃圾信息）或放入参考资料（以后或许有用）；需要及时处理的信息则进入下一步。\u003c/p>\u003cp>\u003cstrong>第三步：（T\u003c/strong>wo-minute-rule\u003cstrong>）\u003c/strong>按照2分钟原则确定任务完成顺序。2分钟以内可以完成的，立即完成；2分钟以内无法完成的进入下一个步骤。\u003c/p>\u003cp>\u003cstrong>第四步：\u003c/strong>（\u003cstrong>S\u003c/strong>chedule）制定日程表。对于2分钟以内无法完成的任务，可以选择委托他人完成或延迟完成，无论选择哪种，都需要制定好日程表，以便提醒自己随时跟进。\u003c/p>\u003cp>（正面例子）运用ACTS方法再来看一下产品经理的一天。\u003c/p>\u003cp>第一步：将任务信息加入工作篮。当天的工作有：帮女儿定蛋糕、定午餐、完成上级指派的任务、与市场部对接B产品的市场计划；与实习生交流数据表制作。\u003c/p>\u003cp>第二步：将信息进行分类。以上清单中没有不需要处理的信息，可以直接进入第三步。\u003c/p>\u003cp>第三步：按时间选择立即行动的任务：2分钟以内可以完成的包括订蛋糕、预定午餐，可以选择优先处理。\u003c/p>\u003cp>第四步：制定日程表。其他任务则可以按照工作安排放在日程表中随时跟进。具体来说，可以制定如下的日程表：\u003c/p>\u003cp>可以看到，经过以上安排，这位经理一上午的工作井井有条，由于每一个时间段专注完成一件事情，效率会大大提升，不会像案例中那样手忙脚乱。\u003c/p>\u003cp>（where）片段中的ACTS方法不仅可以用于职场工作的安排，对于家庭中遇到的琐事也可以使用。\u003c/p>\u003cp>【预防异议＋讲解】有的伙伴可能会说，现实中的琐事比案例可多多了，很难那么理想化的安排各项工作。的确，现实永远比理想更残酷，但越是如此，我们才越需要不断修炼技巧帮助我们从焦虑中解脱出来，只要你不断训练，让自己具备遇事不急，分类处理的自然反映，相信你必然会成为掌控时间的高手；也有的伙伴会问，清空工作蓝，对于短时间内无法完成的工作，要怎么做接下来的安排呢？别急，这是GTD第3个环节的工作，我们今天只需要掌握时常清空工作蓝的方法就可以了。\u003c/p>","interaction":"\u003cp>l A2（分步催化1）\u003c/p>\u003cp>【分步催化1：指向未来的显像提问】\u003c/p>\u003cp>现在就请大家设想发生在你身上的忙碌的一天。想象一下，周末的清晨，你满怀欣喜的开启一天的生活，你早早的坐在阳光明媚的阳台上，摊开买了许久的书，身边的咖啡还散发着迷人的香气，就在这时，一声“妈妈！”/“一声急促的电话铃声”(可能是工作电话)拉开了今天的序幕……\u003c/p>\u003cp>请伙伴们想象一下，这一天在你身上会发生什么不可思议的事情？请用1分钟的时间思考并在小组内分享，提醒一下，这一天可能发生的事情或许有很多，请小伙伴聚焦4-6件可能让你焦头烂额的事情。1分钟之后，请伙伴们描述一下可能出现的“狼狈”场景。\u003c/p>\u003cp>【伙伴分享】\u003c/p>\u003cp>学习者宝妈分享\u003c/p>\u003cp> 我周末的事情非常多，简直是一场战斗，包括孩子的安排：如早上8点的象棋课、下午1点的羽毛球课，晚上的架子鼓课，这些都需要接送，陪伴，耗费很长时间，另外还有自己的工作，比如党员的答辩安排，互联网竞赛的时间安排，拆书过级等工作，可能会跟孩子的事情冲突，所以导致自己的事情都被压缩或拖延，非常焦虑。\u003c/p>\u003cp>拆书家：感谢宝妈的分享，可以看得出来，宝妈的周末非常忙碌，一方面要为孩子的各种安排劳心费力，另一方面还要顾及自身的发展。刚刚宝妈聚焦了几件必须要完成的工作，这些工作在安排上可能会发生时间冲突，导致顾此失彼。这个场景适合我们今天的练习。\u003c/p>\u003cp>l A2（分步催化2）\u003c/p>\u003cp>【催化学习者加工未来的场景】\u003c/p>\u003cp>现在请大家试着将这一天可能遇到的各种任务通通收进工作篮，并逐步运用ACTS方法化解一个个危机，重新安排自己一天的时间表，让你的这一天井井有条，充满生机。首先大家用3分钟时间在小组内进行分享。接着我们邀请小伙伴来向其他组分享。\u003c/p>\u003cp>【分享行动计划】\u003c/p>\u003cp>学习者婷婷分享\u003c/p>\u003cp>我分享一下我上班时间的安排，上班时间我通常会首先有一个to do list，但是微信时常会跳出一些工作，比如拆书帮小伙伴的咨询，还有公司临时安排的其他事情，根据今天学到的ACTS方法，我首先会将这些信息收集到to do list中（Add），然后我会进行分类（Classify），确实需要做的我会看，（Two minute rule）2分钟以内能完成的我就会率先完成，比如对于一个技能点的咨询；2分钟以内无法完成的就会延迟放入日程表（Schedule）\u003c/p>\u003cp>总结：感谢婷婷的分享，非常棒，婷婷的学习能力非常强，她运用了今天的ACTS方法，将工作中临时遇到的工作通过收集、分类、加入日程表的方式快速清空大脑，让自己在特定的时间内专注完成某一项工作，相信工作效率也会非常高！\u003c/p>\u003cp>请大家回去以后也试着运用今天的方法对每天的工作安排进行重新规划，期待大家都成为时间的掌控者！\u003c/p>\u003cp>今天的拆书到此结束，感谢大家的聆听！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1619271701000,"updated_at":1620439796000,"ria":true},{"id":11325,"topic":"时间管理","learn_goal":"","remark":"阅读","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"谭亭亭","city":"湖州市"},"club":{"name":"苏州阅苏分舵","city":"苏州"},"prologue":"\u003cp>【自我介绍，1分钟】\u003c/p>\u003cp>各位伙伴大家好，感谢大家来到TF1-1的练级场。我是谭亭亭，谭咏麟的谭，亭亭玉立的亭，接着我用3个标签简单做一个自我介绍：首先，我是一位宝妈，家有8岁女儿一枚，在与女儿“斗智斗勇”中不断成长，是我生存的必备技能；第二，我是一名教师，与学生分享新知、用知识催化能力是我追求的目标；第三，我是一名持续学习者和实践者，以上两个标签，都要求我不断追求高效持续学习。\u003c/p>\u003cp>【拆书帮介绍，2分钟】\u003c/p>\u003cp>那么，何为拆书？又何为拆书帮呢？简言之，拆书，就是一种将书中知识转化为能力的学习方法。具体来说，“拆书”分为三个步骤，我将其总结为“拆解、关联、内化”：\u003cstrong>第一，拆解全书\u003c/strong>，选取能够为“我”（或学习者）所用的知识片段；\u003cstrong>第二，解释片段内容\u003c/strong>，目的是完成书中知识与“我”（或学习者）原有知识体系的关联\u003cstrong>；第三，内化知识，催化能力提升，\u003c/strong>即通过对自我（或学习者）经验的反思和对未来的行动规划将知识内化为能力。拆书法即可以用于自我的知识内化学习，也可以成为引导他人，进行能力培训的组织学习法。\u003c/p>\u003cp>“拆书帮”是由拆书爱好者聚集形成的学习型组织，具体表现为各地拆书帮分舵；“拆书帮”是一个能量场，为拆书爱好者持续赋能，与拆书爱好者陪伴成长。\u003c/p>\u003cp>今天我要拆解的拆页选自时间管理大师戴维·艾伦的《搞定I：无压力工作艺术》，请大家用1分钟的时间阅读手中的拆页，阅读完成后请举手或眼神示意。\u003c/p>","ratings_count":1,"texts":[{"id":15251,"quote":"\u003cp>下面，请大家花2分钟时间阅读下面的拆页，阅读完请眼神示意我：\u003c/p>\u003cp>【R】片段节选自《搞定I：无压力工作艺术》（作者：[美]戴维·艾伦）P73-74\u003c/p>\u003cp>\u003cstrong>确定某一时刻具体行动的“四标准法”\u003c/strong>\u003c/p>\u003cp>在星期三下午3点22分时，你如何选择下一步行动呢?这个时候，你可以按顺序采用下面四个标准:情境、有多少时间、有多少精力和重要性。\u003c/p>\u003cp>前三个标准描述了你每次采取行动的制约因素，第四个标准则是评估行动的价值大小。\u003c/p>\u003cp>\u003cstrong>情境\u003c/strong> 每时每刻，你都受限于自己的行动能力。只有很少部分事情对地点没有特别要求（像拿一支钢笔和一张纸就可起草对一个项目的想法），但是，大多数事情都只能在特定的地点完成（在家或办公室），或者需要借助某些特定的工具（如一部电话台电脑），而这正是限制我们行动选择的首要因素。\u003c/p>\u003cp>\u003cstrong>有多少时间 \u003c/strong> 你所能支配的时间长短也是一个重要的限制因素。如果5分钟后你就必须去开会，你现在就不可能去执行那些耗时更久的行动。\u003c/p>\u003cp>\u003cstrong>有多少精力\u003c/strong> 你有多少精力呢?某些事情需要你头脑清醒、思路清晰、高于创造，而另一些则要求你具备充沛的体力。还有一些事情则对这两方面都没有特别要求。\u003c/p>\u003cp>\u003cstrong>重要性\u003c/strong> 当你考虑了情境、时间、精力这三个条件后，最后你就要判断哪个行动选项会给你最高的回报了。现在，你有1个小时的时间，你坐在办公室里守着电话和电脑，你的精力指数为7.3（最高为10）。你应该做些什么呢?给客户回一个电话？考虑下新的提案？处理一下语音信箱里的留言和电子邮件？或者联系一下你的配偶，看看她/他这一天过得怎么样？这时，你可以借助你的直觉，并依赖你此时此刻的判断力。\u003c/p>","explains":"\u003cp>相信大家已经阅读完了拆页，接下来我将运用RIA便签法拆解片段：\u003c/p>\u003cp>【分享I便签】（3分钟）\u003c/p>\u003cp>即解释片段内容，通过这·个部分，大家可以试着理解片段内容并关联自己的经验。这里，我将用到3W1H方法：【why】面对每天多如牛毛的工作，你是否感慨时间不够用？你是否也会有这样的时刻：好不容易把急事要事处理完了，突然不知道下一步该干啥了？往往在选择中浪费时间，最后导致每天都没办法清空任务篮？这时，我们可能需要一个有效的工具来高效判断某一个具体时刻应该如何安排下一步行动？【what】拆页中介绍了一种“四标准法”可以从\u003cstrong>情境、时间、精力、重要性\u003c/strong>四个方面评估筛选某个时间点接下来的行动安排。其中，情境、时间和精力是行动的制约因素，重要性则用于评估行动的价值。运用“四标准法”，可以有效、准确的确定某一时刻的最佳行动安排，提高工作效率。【how】具体来说，“四标准法”包括如下步骤：\u003cstrong>（1）评估情境\u003c/strong>。评估每项工作完成所需具备的情境因素，包括工作环境、工作条件等，对比你所处的环境是否具备这些条件，看工作地点是否合适，是否有工作完成的必要条件（电脑、投影），如果不具备，工作就难以开展。如你现在在车间，就没办法完成需要电脑才能完成的生产计划制定工作。\u003cstrong>（2）评估时间\u003c/strong>。评估你在此刻能够自由支配的时间以及每项工作完成需要的时间，选择匹配最佳的行动。如果你此时只有半个小时时间，半小时后你不得不去开会，那么就不能安排需要一个小时才能完成的PPT制作；\u003cstrong>（3）评估精力\u003c/strong>。任何工作都需要耗费一定的精力，包括脑力和体力。如果你刚刚才从压力巨大的谈判会议中出来，就不要安排同样需要打开脑洞的bp写作，选择清理电脑桌面可能更适合你。\u003cstrong>（4）评估行动的重要性。\u003c/strong>在符合以上3个制约条件的情况下，选择能带来回报最大的行动作为下一步的安排。通过以上四个步骤，便可筛选出当下时刻最适合的行动；【where】“四标准法”可以用于安排非紧急事务的安排，也可以用于日常碎片化时间的工作安排，高效完成任务清单。\u003c/p>","interaction":"\u003cp>【分享A1便签】（3分钟）即激活自己的经验。这里我讲一件发生在自己身上的事情，我们一起体会一下“四标准法”在工作中的应用。在刚刚过去的这个周三，中午吃好饭回到办公室，距离下午1：30的开会时间还有一个小时，我打开嘀嗒清单看了我当天的计划清单，还有以下4件事需要完成：\u003c/p>\u003cp>（1） 到医院拿体检报告\u003c/p>\u003cp>（2） 批改学生作业\u003c/p>\u003cp>（3） 财务报销\u003c/p>\u003cp>（4） 准备女儿十分钟队会的PPT\u003c/p>\u003cp>（5） 去学校超市买生活必需品\u003c/p>\u003cp>我初步评估了我的情况：我当时在办公室，有电脑，有一个小时可支配时间，上了一上午课，有些疲惫。又评估了待办事项：到医院拿体检报告大概需要半小时，加上找医生看报告的时间，1个小时恐怕不太够，因而放弃；财务报销中午财务不上班，因而也放弃；给女儿做PPT需要耗费大量的脑细胞，当时的精力不允许，因而也放弃；批改学生作业及到超市采购都可以完成，但相对来说，批改学生作业更重要，去超市采购可以放在下班后完成，因而，选择了利用一个小时的时间批改学生作业，考虑到只有一个小时的时间，批改的效率竟然出奇的高。相信如果在以后能够持续使用四标准法来规划工作，一定会取得更好的效果。\u003c/p>\u003cp>【分享A2便签】（4分钟）\u003c/p>\u003cp>规划未来的应用。接下来，我将运用“四标准法”重新评估我的日程表，充分利用“碎片时间”，提高工作效率。这里我以周四的日程表为例， \u003c/p>\u003cp>周四我的固定日程安排如下：\u003c/p>\u003cp> \u003cbr> 时间\u003cbr> 调整前\u003cbr> 上午\u003cbr> 6:30-7:10\u003cbr> 跳绳\u003cbr> 7:50-8:20\u003cbr> 送女儿上学\u003cbr> 8:30-11:00\u003cbr> 备课+科研\u003cbr> 下午\u003cbr> 12:30-1:00\u003cbr> 上班途中\u003cbr> 1:30-3:10\u003cbr> 上课\u003cbr> 3:30-5:00\u003cbr> 室外活动\u003cbr> 晚上\u003cbr> 7:00-8:30\u003cbr> 亲子时间\u003cbr> 10:00\u003cbr> 科研\u003cbr> 11:00\u003cbr> 睡觉\u003cbr> \u003c/p>\u003cp>除了固定的日程安排，还有一些其他的工作，比如学生的竞赛指导、投稿信息的收集等，但总会因为没时间而无法完成，或者为了完成这些工作导致其他工作没法完成。但细看日程表，其实可以利用的碎片化时间非常多。\u003c/p>\u003cp>这里我将以其中一个时间点为例，展示我将如何运用“四标准法”调整日程表，让工作变得更高效。\u003c/p>\u003cp>我们就以下午3:30这个时间点为例，这个时间段，本来的安排是与女儿的室外活动时间，看似无法插入其他工作，但按照“四标准法”来看一下：（1）从情境来看，在室外，无法从事一些需要电脑的工作；（2）从时间来看，有1个半小时的时间，虽然可选择的活动比较多，但是自由度比较大；（3）从精力来看，刚上完课的我不希望在这个时间做脑力工作；在以上3个约束条件限制下，当天的日程中，可以将跳绳放到这个阶段来同步进行；同时，女儿每天都有听中英文音频的任务，以前会安排在写完作业后，但总是因为时间不够而放弃一个。我也可以把中文音频放在室外活动的时候听，因为中文音频不需要特别安静的环境（情境），也不需要女儿非常集中注意力（精力），放在室外听，完全没有问题。综合考虑两件事情的重要性，在这个阶段安排既可以让我们的室外活动变得更丰富，也可以很轻松的完成两件任务。\u003c/p>\u003cp>对于其他时间点，我也按照“四标准法”一一进行了评估，发现原来没有时间完成的任务在调整后都可以利用“碎片化”时间完成了。以下是我调整前后的时间表对比，伙伴们可以对照一下。\u003c/p>\u003cp> \u003cbr> 时间\u003cbr> 调整前\u003cbr> 调整后\u003cbr> 上午\u003cbr> 6:30-7:10\u003cbr> 跳绳\u003cbr> 科研\u003cbr> 7:50-8:20\u003cbr> 送女儿上学\u003cbr> 送女儿上学+听英语音频\u003cbr> 8:30-11:00\u003cbr> 备课+科研\u003cbr> 备课+科研\u003cbr> 下午\u003cbr> 12:30-1:00\u003cbr> ——\u003cbr> 听网课音频\u003cbr> 1:30-3:10\u003cbr> 上课\u003cbr> 上课\u003cbr> 3:30-5:00\u003cbr> 室外活动\u003cbr> 室外活动，跳绳，女儿听中文音频\u003cbr> \u003cbr> 7:00-8:00\u003cbr> 亲子游戏\u003cbr> 亲子游戏\u003cbr> 晚上\u003cbr> 8:00-9:00\u003cbr> ——\u003cbr> 阅读时间\u003cbr> 10:00\u003cbr> 科研\u003cbr> 睡觉\u003cbr> 11:00\u003cbr> 睡觉\u003cbr> \u003cbr> \u003c/p>\u003cp>经过这样的调整，我基本可以保证每天早睡，而且任务基本可以完成，是不是很棒呢？\u003c/p>\u003cp>以上便是我对片段的解读及应用，感谢大家的聆听。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1618146879000,"updated_at":1618378407000,"ria":true},{"id":9638,"topic":"龙卷风TF2-4过级","learn_goal":"正确应用四标准法，确定某个时刻做什么，能更加高效地利用时间。","remark":"搞定！","level":"TF2-4","duration":30,"status":30,"type":0,"chaishujia":{"username":"龙卷风","city":"昆明"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>各位小伙伴，大家好！我是龙卷风，很高兴能和大家一起进行拆书训练！\u003c/p>\u003cp>为了便于拆书活动的开展，今天的小伙伴我们编成一个小组，待会讨论、交流、分享的时候就以小组为单位进行。\u003c/p>\u003cp>\u003cstrong>学习目标\u003c/strong>\u003c/p>\u003cp>今天拆页的主题是：时间四标准法，拆解片段来自《搞定I:无压工作的艺术》 P286。 \u003cbr>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，各位能够正确应用四标准法，确定某个时刻做什么，能更加高效地利用时间，事半功倍。 \u003cbr>\u003c/p>\u003cp>\u003cstrong>图书介绍\u003c/strong>\u003c/p>\u003cp>下面给大家介绍下这本书：\u003c/p>\u003cp>【F】：这本《搞定1:无压工作的艺术》作者是戴维·艾伦，美国著名的行政管理培训专家，其根据自己的研究和从业30多年的经验，提出了GTD管理时间、管理行为的具体方法，帮助人们优化时间管理流程，提升个人效率，既适用于企业，也适用于我们每个人。 \u003cbr>\u003c/p>\u003cp>【A】：和其他同类型时间管理书籍相比，《搞定》是目前时间管理领域最有影响力的著作之一，是著名的GTD（Getting Things Done）法则的起源，GTD已成为全球千万读者用来轻松高效完成工作与个人事务的优秀工具，影响广泛而且深远；和其他同类书籍相比，书中介绍GTD更加系统全面完整，条理清楚，方法实用、简单易行，提供的案例生动、真实，给人很好启发。\u003c/p>\u003cp>【B1】：大家可能都有过这样的经历和感受：每天都有做不完的事情，看似乎都很紧急，都很重要，时间管理和工作规划经常被打乱，自己似乎被各种任务和目标追赶着走，压力山大，常常感到焦虑不安？\r\n这本书将告诉你如何使用GTD的收集、整理、组织、回顾、执行五个核心原则，运用技巧、方法和工具，帮助你走工作出规划和执行中的泥沼，有效运用时间，完成工作，实现目标，走出时间管理困境，通向高效、轻松的彼岸，掌控生活！ \u003cbr>\u003c/p>\u003cp>【B2】：小伙伴是不是有时候感觉到突然间一下子要做的事情太多，自己无从下手，理不清头绪，凭感觉就确定某个时刻来做某项事情，常常是时间不够、或者是条件不具备，搞得没办法开展？\r\n今天拆页将帮助你高效确定某个时刻的具体工作安排，并让你把经常性、重复性工作模式固化下来，形成习惯，让你头脑清醒、科学、高效地搞定每日工作。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003cbr>\u003c/p>","ratings_count":1,"texts":[{"id":13471,"quote":"\u003cp>接下来，请大家花1-2分钟阅读下原文拆页。\u003c/p>\u003cp>\u003cstrong>[主题]：\u003c/strong>确定某一时刻具体行动的“四标准法”\u003c/p>\u003cp>\u003cstrong>[片段来源]：\u003c/strong>拆解片段来自《搞定I:无压工作的艺术》 P286\u003c/p>\u003cp>\u003cstrong>【R：阅读原文】\u003c/strong>\u003c/p>\u003cp>确定某一时刻具体行动的“四标准法”\u003c/p>\u003cp>在星期三下午3点22分时，你如何选择下一步行动呢？这个时候，你可以按顺序采用下面四个标准：情境、有多少时间、有多少精力和重要性。\u003c/p>\u003cp>前三个标准描述了你每次采取行动的制约因素，第四个标准则是评估行动的价值大小。\u003c/p>\u003cp>\u003cstrong>情境\u003c/strong>&nbsp;每时每刻，你都受限于自己的行动能力。只有很少一部分事情对地点没有特别要求（像拿一支钢笔和一张纸就可起草对一个项目的想法），但是，大多数事情都只能在特定的地点完成（在家或办公室），或者需要借助某些特定的工具（如一部电话、一台电脑），而这正是限制我们行动选择的首要因素。\u003c/p>\u003cp>事情总是多得做不完，你可以每次只做一件事。无论是否已经采取行动，关键在于使自己保持良好的状态。\u003c/p>\u003cp>\u003cstrong>有多少时间 \u003c/strong>你所能支配的时间长短也是一个重要的限制因素。如果5分钟后你就必须去开会，你现在就不可能去执行那些耗时更久的行动。\u003c/p>\u003cp>\u003cstrong>有多少精力 \u003c/strong>你有多少精力呢？某些事情需要你头脑清醒、思路清晰、富于创造力，而另一些则要求你具备充沛的体力。还有一些事情则对这两方面都没有特别要求。\u003c/p>\u003cp>\u003cstrong>重要性 \u003c/strong>当你考虑了情境、时间、精力这三个条件后，最后你就要判断哪个行动选项会给你最高的回报了。现在，你有1个小时的时间，你坐在办公室里守着电话和电脑，你的精力指数为7.3（最高为10）。你应该做些什么呢？给客户回一个电话？考虑一下新的提案？处理一下语音信箱里的留言和电子邮件？或者联系一下你的配偶，看看她/他这一天过得怎么样？\u003c/p>","explains":"\u003cp>好，小伙伴们都已经阅读完了，下面我们来具体解析下。\u003c/p>\u003cp>\u003cstrong>【预防可能的异议】\u003c/strong>\u003c/p>\u003cp>1.&nbsp;你可能会觉得这么做太麻烦了，说之前凭感觉多省事，也不过来啦。事实上凭感觉的情况下我们浪费的时间、带来的麻烦会更多；我们应用“四标准法”虽然会增加几个步骤，但会使后面的执行更加科学、顺畅、高效，起到事半功倍的效果。\u003c/p>\u003cp>2.有没有小伙伴看后觉得这也太理论化了，实际生活中没有这么理想和条理分明。我有时候也有这种感觉，我们难以精确评估自己的精力、工作时间。这反而表明我们更需要联系自己的真实经验，不断积累应用，从自己的案例中来具体应用，做到学以致用。\u003c/p>\u003cp>\u003cstrong>WHAT\u003c/strong>\u003c/p>\u003cp>“四标准法”是指从情景、时间、精力、重要性四个标准，顺序进行分析评估筛选，帮助你确定某个时间点做什么，最终合理高效地确定具体行动。其本质就是在面对纷繁复杂的选项面前确定选择标准并按照标准筛选，确定最优选项的一种方法。\u003c/p>\u003cp>情景、时间、精力、重要性四个筛选标准中情景、时间、精力是制约因素，主要用来判断行动是否具备条件，重要性则是评估行动的价值。\u003c/p>\u003cp>\u003cstrong>WHY\u003c/strong>\u003c/p>\u003cp>在某个时刻做什么？面对多个任务，多个选择时，我们往往很难做出决定，会在选择中浪费时间和资源；没有标准的选择和采取的行动也可能并不是最优选择，往往会是条件不具备，精力跟不上，效果不好，效率低下。\u003c/p>\u003cp>\u003cstrong>HOW\u003c/strong>\u003c/p>\u003cp>“四标准法”可细化为下列步骤进行:\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.地点\u003c/strong>\u003cstrong>评估。\u003c/strong>首先要评估对场所、地点是否有特殊要求，其次评场所、地点是否估具备条件；场所、地点是制约行动选择的第一因素，是情景评估的关键因素；虽然有些行动对地点没有特殊要求,但我们还是要先进行评估。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.工具评估。\u003c/strong>评估工具如电脑、投影仪、软件等工具是否具备；地点和工具是物理条件的评估，其组成的情景模式是限制我们行动选择的首要因素；不具备，行动就难以开展，安排就无法落地。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>时间评估。\u003c/strong>地点、工具具备了，就要分析自身可使用时间的长短，并选择与之匹配的行动。自己可支配的时间少于完成行动完成时间，行动就完成不了，多于完成时间，就会产生时间浪费。时间长短是选择行动的重要因素。\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>.精力评估。\u003c/strong>行动需要精力，我们需要从当前的脑力、体力两方面来筛选行动，使自身精力匹配行动。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>5\u003c/strong>\u003cstrong>.重要性评估。\u003c/strong>最后对各个行动进行价值分析，看哪项行动回报最高，价值最大，并最终确定价值最大的下一步具体行动。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>以上五步，不断筛选，最终挑选出条件符合、价值最高的行动，使我们确定在某个时刻具体做什么。\u003c/p>\u003cp>\u003cstrong>W\u003c/strong>\u003cstrong>HERE\u003c/strong>\u003c/p>\u003cp>“四标准法”适用于非紧急情况下的行动选择和确定，紧急情况下采取的行动通常以“优先级”为最高选择标准进行筛选确定。\u003c/p>\u003cp>\u003cstrong>【举个例子】负面一般做法\u003c/strong>\u003c/p>\u003cp>一般情况下，人们在安排某个具体时刻应该做什么的时候，往往只会考虑到时间的长短，没有全面考虑地点、工具、精力、重要性等因素，或者是凭感觉、看心情。\u003c/p>\u003cp>\u003cstrong>【不按折页做的后果】\u003c/strong>\u003c/p>\u003cp>在这种考虑因素不全的情况做出的安排，往往会出现情景不合适、物理条件不具备、精力不济、没办法完成的情况，或者是完成了效果不理想；凭感觉、看心情，那安排计划事项完成的质量、效果更是不可控，经常是时间过了，事情没做。\u003c/p>\u003cp>\u003cstrong>【举个例子】负面例子\u003c/strong>\u003c/p>\u003cp>在2018年6月世界杯赛程期间，在有比赛的每个周六、周日晚上，我都在为22:00以后该干什么而发愁，完成拆书帮训练营作业？还是健身跑步？还是看世界杯？或者干脆什么都不做，睡觉？\u003c/p>\u003cp>在纠结中，任着性子来，看世界杯吧！一看就到次日凌晨4点钟，第二天要不晚起，要不起来精神状态很不好，拆书帮作业质量也不高，健身活动也没有开展，自己为了完成拆书作业而焦虑，自己感觉很焦虑。\u003c/p>\u003cp>\u003cstrong>回顾反思：\u003c/strong>\u003c/p>\u003cp>在面对多个行动选项时没有按照一定的标准进行筛选，率性而为，选择了对我来说最不重要、最舒服的行动——“看世界杯”，这也是回报和重要性最小行动选项，错过了健身、拆书帮作业。\u003c/p>\u003cp>\u003cstrong>【翻转案例】拆页行动翻转例子\u003c/strong>\u003c/p>\u003cp>到7月世界杯后期，我按照“四标准法”来分析确定每周六、日22:00后的具体行动：\u003c/p>\u003cp>从地点和工具、精力、时间等要素来看，看世界杯、做作业、健身、睡觉的行动地点、工具（电脑、手机）都具备，自己能支配的时间、精力也能支持；\u003c/p>\u003cp>在重要性分析上，按照其产生回报的最大化来排序，也就是这些行动对自身成长、自身状态的好处来看，应该是完成拆书帮作业、健身、睡觉、看世界杯；\u003c/p>\u003cp>最终我确定了22:00后完成拆书帮作业，23:30分健身，然后睡觉休息，次日看世界杯集锦；这样我较好地完成了拆书训练营作业、健身和休息，感觉到自己充分利用了时间、掌控了生活。\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A1\u003c/strong>\u003cstrong>】激活经验\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：【显像提问】\u003c/strong>\u003c/p>\u003cp>1.&nbsp;好，下面请小伙伴们用30秒回想一下，在最近这段时间的某一天，你面对大大小小的多个事项时，如年底各种总结、报表、明年计划和重点、个人提升、出差、拜访客户、内部联谊等多个事项，感到压力山大、时间不够用、事情做不完，你是怎样了安排确定在某个时间点来做这些事情的？有过一拍拍脑袋、跟着感觉走的情况，想到哪件就做哪件？\u003c/p>\u003cp>2.&nbsp;给大家1分钟的时间，请各位将以上所说的或类似经历场景的关键词简单写在便利贴上。\u003c/p>\u003cp>（拆书小伙伴现场准备）\u003c/p>\u003cp>3.好，时间到，下面我们请一位伙伴给大家分享一下，这里我们只需要分享当时的具体场景就可以了，什么时间，什么地点、什么情况等。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：现场记录\u003c/strong>\u003c/p>\u003cp>\u003cstrong>范范：\u003c/strong>我给大家分享上周的一个事情；前几天我报名参加了讲师协会培训，1月4日上午10点钟，我正在家里看书的时候，协会把我拉进微信群里面，通知我下午培训。当时我就蒙圈了，下午有拆书活动啊！拆书和培训有冲突啊？我下午13:30分应该做什么？去培训还是参加拆书活动？我当时就觉得，讲师协会这个活动通知有问题，协会原先说会把我拉进微信群里，及时通知培训安排的，我就没有跟进关注，现在突然拉我进群就通知，这也太草率了！随后一想拆书活动是当前比较重要的一件事，培训活动通知草率，他们承诺的事情没有做到，没有及时通知我，何况我下次还能参加，我还是按照计划参加下午的拆书活动吧。\u003c/p>\u003cp>\u003cstrong>拆书家讲解：\u003c/strong>非常感谢范老师的分享；刚才范老师给我们分享了她在面对培训、拆书活动等多个事情的情况下，自己是时如何确定做什么的，她先是凭自己感觉对事情进行考虑，随后对两件事情的重要性进行了排序，并作出了决定；这个场景非常契合我们这个拆页的内容！让我们用热烈的掌声感谢范老师的分享！\u003c/p>\u003cp>\u003cstrong>【反思加工A1+】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家\u003c/strong>\u003cstrong>：\u003c/strong>现在请大家想想看，面对刚才写下的场景，根据我们拆页中的建议你可以怎样应用“四标准法”来确定某一时刻具体行动？\u003c/p>\u003cp>给到大家2分钟时间，大家写在便签纸上，之后也邀请1位小伙伴进行分享。\u003c/p>\u003cp>（拆书小伙伴现场准备）\u003c/p>\u003cp>\u003cstrong>分享者案例记录：\u003c/strong>\u003cstrong>现场记录\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家讲解：\u003c/strong>好的，时间到！下面我们还是邀请范老师来给大家分享：如果面对刚才所说的情况，该如何应用“四标准法”来做得更好，有请范老师！掌声鼓励！\u003c/p>\u003cp>\u003cstrong>范范：\u003c/strong>好的，在刚才分享的场景里面，我虽然进行了选择，但我觉得应用拆页所学的“四标准法”来确定下午具体安排，我会做到更好，能把两个事情都排起来、完成好。具体做法是：\u003c/p>\u003cp>第一步：地点评估。培训、拆书都需要特定的地方，都需要相对安静；距离拆书小伙伴也比较近，其实两者是可以兼容的，把拆书活动的地点调整到培训的地方，就都能满足场所条件。\u003c/p>\u003cp>第二步：工具评估。培训、拆书对工具要求就较低，我随身携带笔记本、资料，就能满足。\u003c/p>\u003cp>第三步：时间评估。拆书活动估计要2小时，培训也需要2小时；这一天天上午和下午我都有时间，都能满足时间要求，如果将拆书活动安排在上午，下午培训，这个冲突就不存在。\u003c/p>\u003cp>第四步：精力评估。培训和拆书都需要脑力和体力的支持，我上午下午在精力方面都没有问题，自己的体力、脑力、精神状态都OK！\u003c/p>\u003cp>第五步：重要性评估。拆书活动目前是我们筹备分舵一个非常重要的事情，培训我下一次还可以参加；因此拆书活动比较重要放在上午，下午进行培训，重要性方面都能兼顾到。\u003c/p>\u003cp>经过评估后，我会这样来安排当天的事情，上午10:00进行拆书活动，地点安排在协会培训的地方或者是附件合适的点；下午13:30参加培训。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家点评：\u003c/strong>范老师的分享生动展现了“四标准法”步骤和作用，大家掌声鼓励！！范老师面对上午的情况，从原来的凭感觉、没有全面评估作出选择，到现在从情景、时间、精力、重要性四个方面筛选，合理安排，将拆书和培训计划安排得妥妥的，做到了“鱼与熊掌兼得”，实现提高时间利用率、提升效率的目的！再次感谢范老师的精彩分享！\u003c/p>\u003cp>\u003cstrong>【拆书家总结】：\u003c/strong>刚才给大家分享的“四标准法”，是用来确定某一时刻具体行动的，第一步地点评估，第二步工具评估；第三步时间评估，第四步精力评估，第五步重要性评估，评估后合理高效地确定某个时间点的具体行动。\u003c/p>\u003cp>接下来的折页是“行为模式化”，就是在习惯培养中将经常性、重复性的事情或工作模式化。下面我们一起来学习，大家都准备好了吗?小伙伴们加油！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":13472,"quote":"\u003cp>通过上一个拆页，大家能够应用“四标准法”确定某一时刻具体行动，高效利用时间，避免纠结和浪费时间了；哪确定某个时刻做什么后，我们能不能更进一步，将经常性、重复性的事情固化下来，形成习惯，进一步提升效率啦？\u003c/p>\u003cp>当然能！答案就在第二个拆页：行为模式化；跟随我完成本次学习后，小伙伴们就能将经常性、频繁发生的事情“行为模式化”即变成固定的行为模式，形成在固定的时间、地点、条件下做相同事情的规律，固定行为模式，帮助养成习惯，实现高效利用时间、提升效率的目的。\u003c/p>\u003cp>\u003cstrong>【片段之间是\u003c/strong>\u003cstrong>递进\u003c/strong>\u003cstrong>关系】\u003c/strong>\u003c/p>\u003cp>这个拆页和第一个拆页之间是递进的关系，“四标准法”确定某一时刻具体行动，行为模式化则将“四标准法”确定的某一时刻重复性发生的的具体行动模式化，形成规律，养成习惯。下面就给大家分享行为模式化的方法。\u003c/p>\u003cp>请大家花1-2分钟阅读下原文拆页。\u003c/p>\u003cp>[主题]：习惯化为固定的模式\u003c/p>\u003cp>[片段来源]：《坚持，一种可以养成的习惯》P.83\u003c/p>\u003cp>\u003cstrong>【R：阅读原文】\u003c/strong>\u003c/p>\u003cp>行为模式化\u003c/p>\u003cp>所谓“行为模式化”，是指把你想培养的习惯化为固定的模式（时间、做法、地点），并认真执行。\u003c/p>\u003cp>如前所述，我们在不知不觉中培养了好多习惯。这些习惯被嵌入到每个人的生活之中，所以我们每天都会重复做出习惯性的动作。\u003c/p>\u003cp>因此请把你想培养的习惯化为正确而规律的行为模式吧。比起每天在不同地点或不同时间点采取行动，重复已化为模式的行动会更容易。这就是成功培养习惯的捷径。\u003c/p>\u003cp>例如，许多上班族早晨一到公司就马上检查电子邮件。如果不看就觉得浑身不对劲。同样地，每天都在上午六点起床的人，就算是假日也会在六点钟就自动醒来。\u003c/p>\u003cp>如果新的习惯已经养成的话，你就会在无意识中做出相应的动作。\u003c/p>\u003cp>通过行为模式化，如果你不在某个时间做某件事就觉得浑身不对劲的话，那你就成功地培养了这个习惯。\u003c/p>\u003cp>若要模式化可以采取以下三种方法：\u003c/p>\u003cp>方法一 时间：决定星期几，几点开始\u003c/p>\u003cp>例如：每周一、三、五晚上八点开始阅读。\u003c/p>\u003cp>方法二 内容：决定数量与方法\u003c/p>\u003cp>例如：每天花30min听CNN的英语新闻。\u003c/p>\u003cp>方法三 地点：决定地点例如：在上班途中、办公室、家中或附近的咖啡店学习。\u003c/p>","explains":"\u003cp>好，小伙伴们都已经阅读完了，下面我们来具体解析下。\u003c/p>\u003cp>\u003cstrong>【预防异议】\u003c/strong>\u003c/p>\u003cp>1.&nbsp;可能小伙伴会质疑，这个根本做不到，培养习惯要在时间、地点、内容方面进行固定这是很难的，这些因素怎么可能会不变？其实，只要我们努力了，就会逐步形成固定的行为模式化，既是在某种情况下某个要素不具备，如地点变化了，但由于形成了模式、养成了习惯，我们会不自觉地提醒自己该开展习惯性行动了，这也有利于我们行为的开展、习惯的培养。\u003c/p>\u003cp>2.&nbsp;同时，因为客观现状做不到，那说明在特殊的情况不满足我们拆页的边界条件，你得想其他的思路或办法处理这种特殊情况。\u003c/p>\u003cp>\u003cstrong>【What】\u003c/strong>\u003c/p>\u003cp>行为模式化，就是把想要培养的行为习惯在时间、地点、内容方面固定下来，形成固定的行为模式，形成规律，并且严格执行。\u003c/p>\u003cp>\u003cstrong>【Why】\u003c/strong>\u003c/p>\u003cp>习惯养成需要重复和坚持，如果重复性、频繁发生的事情每次都在不同时间、不同地点开进行，往往会让人感觉很难做下去，不利于习惯的培养；反之，如果在相同时间、相同地点、做相同的事情，形成行为模式，就能形成规律，也就更容易进行，有利于习惯养成；行为模式化后，如果没有完成，自己还会感觉不自在，潜意识会提醒自己该做固定的事啦。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>如何养成固定的行为模式、形成习惯啦？我们可以细化为以下具体步骤：\u003c/p>\u003cp>第一步，固定时间。将要培养的习惯也就是频繁地、规律性发生的行为开展时间固定下来，如每个星期几、几点，或者是每天几点要做什么事情。比如：每周五晚上七点陪小孩上英语课。 \u003c/p>\u003cp>第二步，固定内容。固定要做什么、做多少、怎么做，如每周五晚上七点用45分钟和小孩一起上英语、做课堂笔记、关键资料拍照等。\u003c/p>\u003cp>第三步，固定工具。固定使用什么工具，如使用电脑、手机、某个软件等。\u003c/p>\u003cp>第四步，固定地点。如，陪小孩上英语课是在英语培训学校W5教室。\u003c/p>\u003cp>时间一长，就形成了固定的行为模式，不知不觉中养成习惯，在相同时间点、地方就会自然而然触发固定的行为。&nbsp;\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【案例意译】\u003c/strong>\u003c/p>\u003cp>女儿3岁多时，每天早上8点钟起床后，我们就领着她到卫生间，给她打好水、准备好牙膏牙刷，教她如何刷牙，为了吸引她，我们专门准备了电动牙刷；晚上9点钟睡觉前，也会带领着她到卫生间进行刷牙；刚开始，小家伙对电动牙刷很感兴趣，觉得好玩，对刷牙没有什么感觉，没有掌握刷牙的技巧，也不会主动提出来去刷牙，一个星期后，她逐渐有了主动刷牙的意识，一起床就知道去卫生间洗漱，要刷牙，刷牙也能很好地完成；晚上时间一到有时候还提醒我们她要刷牙了；一个月后，她已经养成了刷牙习惯！\u003c/p>\u003cp>其实，这就是早晚刷牙固定行为模式的形成过程，将刷牙时间固定、地点固定，内容固定，工具固定，最终形成固定模式，养成习惯，在固定的时间、地点、使用相同的工具、做相同的事情。\u003c/p>\u003cp>\u003cstrong>【举个例子】负面一般做法\u003c/strong>\u003c/p>\u003cp>通常，人们在培养习惯的时候往往没有计划性，靠自觉、靠意志，想起来做，忘记了或者忙不过来就中断，甚至放弃了；绝大多数情况下更是没有将时间、地点、内容、方式、标准等方面明确、固定下来，随意性很大。\u003c/p>\u003cp>\u003cstrong>【不这么做的后果】\u003c/strong>\u003c/p>\u003cp>没有将时间、地点、工具、内容、方式、标准固定下来，没有形成固定的套路，没有产生规律，坚持会有难度，自然而然产生“三天打鱼两天晒网”的情况，不断重复“开始--中断--重启--中断”的恶性循环，导致行为无法固化，习惯养成失败。\u003c/p>\u003cp>\u003cstrong>【举个例子】负面例子\u003c/strong>\u003c/p>\u003cp>也是在2018年6月世界杯赛程期间，我参加拆书训练营、看世界杯、健身、会议、培训等事情非常多，加之频繁出差，每天有需处理的新公文将近70-80份，一天处理不完就会积压下来，最多的时候将近300多份公文待处理；我不论在哪个地方、哪个时间想起了就赶紧处理公文，有时用电脑OA、有时用手机APP,但很悲催，常常是没处理几份就被其他事情打断，又要重新开始，进入系统、读公文、思考、处理，效率低下，公文老是处理不完，自己精神状态也不佳。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>回顾反思：\u003c/strong>这其实就是自己没有将公文处理这个行为模式化，没有在固定时间、固定地点、固定方式、固定工具进行，没有形成习惯，导致效率低下。\u003c/p>\u003cp>\u003cstrong>【翻转案例】拆页行动翻转例子\u003c/strong>\u003c/p>\u003cp>也就是在学习完这个拆页后，我结合“四标准法”应用行为模式化方法，每天在固定的18:00点，在自己办公室这个固定地点，用固定的工具，做固定的事情，就是用OA系统处理40分钟的公文；由于这个时间段同事下班了，我也不会去开会了，干扰少、办公系统又快，自己就能集中精力、高效处理公文；经过一个星期的尝试，一到这个点，我就会潜意识提醒我该处理公文了，逐渐形成了固定的行为模式；经过一个月的努力，我最终形成了每天18:00处理公文的习惯，做到当日公文当日处理。\u003c/p>\u003cp>\u003cstrong>【Where】\u003c/strong>\u003c/p>\u003cp>该方法不适用于地点场地、时间要求较高，工作内容、标准经常性变化的行为习惯的培养；对于这种情况则需要配合“四标准法”等方法来处理。\u003c/p>","interaction":"\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A3\u003c/strong>\u003cstrong>】促动参与\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：【\u003c/strong>\u003cstrong>现场演练\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>1.&nbsp;我们刚刚学习了行为模式化的方法来培养习惯，提升效率。现在我们一起做一个演练。请大家认真听一下要演练的场景：\u003c/p>\u003cp>小王没有运动的习惯，时间一长身体吃不消。为改变这情况，他计划每周跑步3次，并逐步养成跑步习惯，实现从“宅一族”到“运动族”的转变；可是由于工作任务重、时间紧张、跑步场地不固定等情况，小王没能很好地坚持下来，不但没有养成运动习惯，还产生焦虑情绪。冠军是小王的死党，非常爱运动，有良好的跑步习惯而且熟悉“行为模式化”。于是，小王约冠军出来请教如何形成跑步习惯，冠军决定“行为模式化”三步法帮助小王来将跑步模式化，最终形成习惯。\u003c/p>\u003cp>现在，请每两人一组，进行演练。一人扮演小王，向冠军请教如何培养跑步习惯，根据冠军的建议制定“行为模式化”四步法形成习惯的方案；一人扮演冠军，分享介绍自己应用“行为模式化”四步法培养跑步习惯的方法和步骤，启发小王制定跑步模式化方案。\u003c/p>\u003cp>2.&nbsp;各位清楚演练的内容了吗？好，下面给大家4分钟的时间在小组内讨论，由小组推选一组进行分享，4分钟后我们请一组上来分享；\u003c/p>\u003cp>3.最后给大家1分钟的时间，请大家注意控制好时间；\u003c/p>\u003cp>4.好，时间到，下面我们请小伙伴给大家分享；分享前，请大家介绍自己扮演的角色。\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：现场记录\u003c/strong>\u003c/p>\u003cp>七月：大家好，我是七月，我扮演的角色是小王；\u003c/p>\u003cp>范范：大家好，我是范范，我扮演的角色是冠军，小王的死党；\u003c/p>\u003cp>七月：冠军啊，我最近的身边感觉不是很好，想跑跑步并行习惯，但事情一多、工作一忙就坚持不下来，悲催啊！我看你每天都跑步，也坚持得挺好的，你给我想想办法呗，看看我怎么做能形成跑步的习惯。\u003c/p>\u003cp>范范：找我就对了！其实这有个过程的，我先分享一下我的做法吧，看看你能不能从中受到一些启发，这可是要看悟性的哦！\u003c/p>\u003cp>七月：没问题，我这悟性！你说说看。\u003c/p>\u003cp>范范：我就是把跑步这个活动的一些因素固定下来，把跑步模式化，最终养成习惯。\u003c/p>\u003cp>第一就是固定跑步时间，我每天晚上21:30分开始跑步，这个时候孩子的事情已经OK，其他事情我也搞定，有空啦。\u003c/p>\u003cp>第二就是固定跑步内容。首先我固定跑步的距离，也就是5公里，绕小区道路跑6圈；然后就是固定跑步的形式，慢跑为主，约跑团的小伙伴一起在这个时间线上跑，相互鼓励，支持。\u003c/p>\u003cp>第三步就是固定跑步工具。我下载了keep这个APP,让其指导我跑步，我还在上面打卡分享，激励自己。\u003c/p>\u003cp>第四就是固定跑步地点，我去健身房也不合适，我就在我们小区的运动跑道上跑，这点离家挺近，很方便的。\u003c/p>\u003cp>固定下来后，跑步的时候就按照模式来，两周后形成固定行为模式，时间一长自然就形成了习惯了。你清楚该怎样培养跑步习惯了吧？\u003c/p>\u003cp>七月：我清楚啦，果然找对人了！\u003c/p>\u003cp>范范：可别得意，你自己试着给自己制定个跑步习惯养成方案吧，我看看你到底悟出了什么。\u003c/p>\u003cp>七月：好的！\u003c/p>\u003cp>范范：一周跑几次？\u003c/p>\u003cp>七月：一周跑3次吧。\u003c/p>\u003cp>范范：时间怎么安排啦？\u003c/p>\u003cp>七月：我把时间安排在早上6点至7点，这个时间我有空；\u003c/p>\u003cp>范范：你怎么跑？\u003c/p>\u003cp>七月：慢跑为主，然后每周提升；目前就一个人跑吧；小区里面也没有经常跑步的小伙伴。\u003c/p>\u003cp>范范：要不试试线上约小伙伴一起跑的方式，相互鼓励下。\u003c/p>\u003cp>七月：这个要试试，大家一起跑会更好些！\u003c/p>\u003cp>范范：用什么工具来帮助自己跑步啦？\u003c/p>\u003cp>七月：我也下个KEEP，让其指导跑步、分享打卡；跑鞋、服装这些装备就不用说了，早准备好了。\u003c/p>\u003cp>范范：你在健身房跑还是小区里面跑？\u003c/p>\u003cp>七月：在小区跑吧。\u003c/p>\u003cp>范范：小区有跑道吗？还是沿着路绕圈？\u003c/p>\u003cp>七月：沿着小区绕圈吧，跑个5圈，每圈有800米左右！\u003c/p>\u003cp>范范：你看，方案不出来啦。你是在早上6点至7点，约小伙伴一起线上跑，跑5圈，将近4公里，地点就在小区道路上。时间、方式、工具、细节、地点都固定了，下一步就看你执行啦！你可以加入我们的线上跑团一起跑！\u003c/p>\u003cp>七月：好的、谢谢！\u003c/p>\u003cp>\u003cstrong>拆书家追问：\u003c/strong>谢谢小伙伴们精彩表演！！掌声鼓励！！我问问七月，你觉得还有哪些因素可以固定下来，更加有利于行为模式化，更加有利于跑步习惯的养成？\u003c/p>\u003cp>七月：我想了一下，在时间方面可以更加固定并细化一些，将每周跑步时间固定下来；星期三、星期五早上我有事情，我就把三次跑步固定在每周一、周二、周四早上6点至7点，避免被事情赶着走。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>】\u003c/strong>时间一细化，更加固定，这更有利于跑步模式化，形成规律，有利于习惯养成。刚才大家应用“行为模式化”四步法进行演练，在分享经验、制定计划中充分体现了固定跑步时间、跑步方式、跑步工具、跑步地点的具体做法，体现了拆页的关键点。\u003c/p>\u003cp>\u003cstrong>【拆书家反馈\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>】\u003c/strong>刚才的角色扮演，两个小伙伴在拆页知识点应用上都准确恰当，表演自然流畅，充分证明小伙伴们已经掌握了“行为模式化”四步法培养习惯的核心内容，我建议大家为他们的的出色表现鼓掌！\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>A2\u003c/strong>\u003cstrong>】催化应用\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【分步催化1】\u003c/strong>\u003c/p>\u003cp>刚才我们大家一起在组内完成了跑步模式化、习惯培养的步骤练习，接下来我们大家设想一下：\u003c/p>\u003cp>1.&nbsp;未来1-2周你将把一项行为模式化，并逐渐培养成习惯，比如：每天早上起床，你换上运动服迎着晨光去跑步，每天晚上你在灯下读书写作，又或者是每天临睡前向自己最亲近的人如爱人、小孩赞美他们的表现，说一声谢谢，然后认真回顾总结自己的一天，复盘自己的表现，你开始了一个美好习惯的养成。\u003c/p>\u003cp>2.&nbsp;给大家2分钟的时间，请大家想一想有没有和这些类似的场景，可以利用行为模式的方法；大家将今后可以用到的场景关键字简单地写在便利贴上，要写明什么时间，什么地点、什么行为，形成一个场景。\u003c/p>\u003cp>（小伙伴写场景）\u003c/p>\u003cp>4.下面我们邀请小伙伴来分享。有请七月给大家分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：现场记录\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>七月：我计划在未来的1-2个月，每天早上一到办公室后就坐下来认认真真地写晨间日记，复盘总结前一日的工作、不足和改进方法，计划当天要做的的事情，合理分配时间、安排工作，最后逐步养成习惯。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>七月的这个写计划的场景与我们的拆页契合度非常高，能很好地应用拆页的知识，有利于将写计划行为模式化、培养成为习惯，有利于个人的高效管理和成长，非常好的应用场景！\u003c/p>\u003cp>\u003cstrong>【分步催化\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>1.各位设想一下，面对刚才各位写下的可能遇到的场景，用我们刚刚学习的行为模式化方法，应该怎么做呢？给大家4分钟的时间，请大家写到便签上。\u003c/p>\u003cp>（小伙伴们写）\u003c/p>\u003cp>2.好的，时间要到了，小伙伴们也写好了。下面请七月来给我们分享一下他如何做的？她将如何应用行为模式将写计划行为模式、培养成习惯？ \u003c/p>\u003cp>\u003cstrong>学习者案例记录：现场记录\u003c/strong>\u003c/p>\u003cp>\u003cstrong>七月：\u003c/strong>刚才我分享的是未来1到2个月的时间里，培养写晨间日记的习惯，复盘前日、计划当天；根据拆页“行为模式化”培养习惯的四步法，我将这样来做：\u003c/p>\u003cp>第一是固定时间，固定为每天08:30-09:00来做；这个时间我刚好到办公室开始一天的工作，总结复盘、计划提升刚好。\u003c/p>\u003cp>第二是固定内容，我把时长固定，就是30分钟，太短完成不了，太长效率不高；固定日记模板，先复盘后计划；复盘时，对照前一日计划和完成情况，列出没有完成的计划项目，分析是什么原因导致计划没有完成，计划执行中出现了问题，可以采用什么方式来改进、改进方法是什么；当天计划时，列出当天要做的事情，根据“四标准法”分配到相应的时间点，然后将复盘中想到的改进办法和措施应用到当天相关的事情中；\u003c/p>\u003cp>第三就是工具固定，我给自己准备了一个笔记本，用固定的笔记本来写，不用电脑，避免干扰；用纸质笔记本我更有感觉；\u003c/p>\u003cp>第四地点固定，固定在办公室，这个时候因为同事都还没有上班，非常安静，没有人打扰，有利于复盘、计划。\u003c/p>\u003cp>这就是我培养复盘前日、计划当天习惯的分享。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【拆书家\u003c/strong>\u003cstrong>总结\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>七月这个计划，应用“行为模式化”培养习惯的四步法很有深度，在固定时间、内容、工具、地点的基础上，更厉害的是通过日记模板将内容和方式进一步固定，而且模板中应用了前一个拆页的“四标准法”，将两个拆页内容很好地结合起来、应用起来！谢谢你的精彩分享！掌声送给你！\u003c/p>\u003cp>\u003cstrong>结语\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>逐字稿：今天我们的两个拆页的内容全部讲完了，让我们来回顾一下，为高效利用时间、搞定事情，培养习惯，我们需要应用“四标准法”和行为模式化方法。第一个拆页我们学习了通过利用地点、工具、时间、精力、重要性等标准确定某个时刻做什么；第二个拆页我们学习了通过固定时间、固定内容、固定工具、固定地点，将行为模式化，习惯化；两个拆页综合应用就能确定某个时间做什么，并将一些重复、频繁的行为模式化，固化成规律，形成习惯，从而提高时间利用率、提升工作效率。\u003c/p>\u003cp>再次感谢小伙伴们的参与和分享，希望今天的拆书能给大家有所启发，让大家在以后的道路上，合理分配工作，高效利用时间，固化好行为、养成好习惯，快速成长，掌控生活！\u003c/p>\u003cp>以上是今天的全部内容，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1578835326000,"updated_at":1578836155000,"ria":true},{"id":8912,"topic":"消除负面情绪 ","learn_goal":"通过学习拆页，掌握消除负面情绪的方法","remark":"在工作中，生活上，有没有体验过、经历过一些负面的情绪？假如现在让你时空穿梭，让你回到那个时刻，你有什么样的感受呢？如果重来，你会重新做一个什么样的决定呢？让我们跟着时间管理大师戴维艾伦，听听他是如何消除负面情绪的。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"竹本1314","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是竹本，是今天的拆书家，今天给大家带来的书名是《搞定I》，这是一本关于时间管理的书。\r\n这本《搞定》的作者是戴维·艾伦，被称为“世界最具影响力的个人与组织效率思想家之一”，尤其在开发个人和企业潜力方面，他被普遍认为是世界级权威。他也因此被誉为提升工作效率方面的顶级思想家，被《福布斯》杂志评为美国最优秀的管理教练之一。\r\n这本《搞定》是戴维·艾伦根据三十多年的咨询经验和个人探索，他提出GTD（Get Things Done）自我管理方法，一书已在33个国家出版。与其他时间管理类书籍相比，GTD的方法能让你的生活更加轻松、愉悦和高效\r\n大家有了解过四象限法则吧，可是有没有这样的一种情况，你在做一件重要紧急的事，可是脑子里想着另外一件不重要不紧急的事，心绪不宁？这本书里提供的GTD的方法，可以让你在不焦虑的情况下完成工作上、生活中的事项。\r\n通过本次的学习，大家可以学习到这自己的能力范围之内，学会并掌握书中告诉我们的方法，如何降低甚至消除自己的消极情绪，先处理情绪，再处理事情。","ratings_count":0,"texts":[{"id":12638,"quote":"\u003cp>\u003cp>消极情绪的来源不良情绪来自何处？是要做的事情太多了吗？不对，要做的事情总是太多。如果你仅仅因为要做的事情比你能做的要多而感觉不好的话，那你就永远无法感觉好起来。因此，要做的事情太多并不是引发消极情绪的根源，这种情绪应该来自别处。\u003c/p>\u003cp>焦虑和内疚并不是因为承担了太多工作而造成的，而是由于你撕毁了同自己的约定而导致的。当某人单方面撕毁了与你签订的协议时，你会怎么想呢？他和你约好星期四下午4点钟见面，而当约定的时间到了，他却连个招呼都不打就爽约了，这时你会有什么样的感觉呢？我想必定是沮丧和失望吧。当人们在生活中食言毁约时，他们为之付出的代价就是人际关系中信任感的丧失，这是一种绝对负面的影响。\u003c/p>\u003cp>你收集到工作篮中的东西都是什么呢？这些东西其实都代表着你同自己签订或者至少明确接受的协议——你在某种程度上告诉自己应该以某种方式进行处理的事项。消极情绪都是你违反这些协议所导致的直接后果——它们是自我信任感丧失的结果。\u003c/p>\u003cp>如果你告诉自己要起草一份战略计划，却未能按时完成，这一定让你感到十分沮丧。如果你计划要整理一下当前的工作，但是最终却未能实现，那随之而来的自然就是内疚和挫折感。如果你决定要多抽出些时间来陪你的孩子，但是却没有做到，那你感受到的肯定是焦虑和挫败感。应该如何减少消极情绪？\u003c/p>\u003cp>如果你的消极情绪来自于毁约，那么可以使用以下3种方法来对付这种局面，消除负面影响：\u003c/p>\u003cp>\u003cstrong>不签订协议。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>完成协议。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>重新商定协议。\u003c/strong>\u003c/p>\u003cp>所有这些方法都会让你感觉好起来。\u003c/p>\u003c/p>","explains":"\u003cp>片段给出了产生消极情绪的原因以及如何来消除负面情绪带给你的影响\u003cp>大家在职场中有没有这样的经历，下属或者同事统一的一个小错误，你的心情好一些，会笑着让对方修正；当你心情不好的时候，你对着下属或者同事发火，然后多米诺骨牌效应开始。一个小小的错误，在你的眼里都会被放大。\u003c/p>\u003cp>为什么会这样呢？因为情绪，那么如果我们先处理了情绪，再来处理事情，心态和效率都会提高。\u003c/p>\u003cp>书中给出了三个方法：\u003c/p>\u003cp>不签订协议——放弃一些事情不去做。就像文中说的那样，当需要做的事情多到自己完不成的程度，自己很容易产生消极情绪，更容易受消极情绪的影响。\u003c/p>\u003cp>完成协议——只要完成一件事，你就会有成就感，那种感觉，我相信大家有过。\u003c/p>\u003cp>重新商定协议——和需要协作的对方，协商到自己可以掌控到的范围，让自己从容一些。\u003c/p>\u003cp>\u003cp>我的例子：\u003c/p>\u003cp>我的上一份工作是财务工作，大家对财务工作的繁琐性多少有所耳闻。没错，财务工作月底工作很忙的。\u003c/p>\u003cp>我16年的时候在天津担任总账会计的时候，一道月底，我就会进入“更年期”状态。\u003c/p>\u003cp>16年3月底，是月底，又是第一季度末，要做的工作比平时月底更多，这个时候呢，很多同事遇到工作上的困难会向我求助， 我喜欢帮助别人，于是我“照单全收”，统统记下。别人很开心，当我深夜一个人在加班的时候，我就很焦虑，开始拖延，时不时刷个微博、微信，工作更做不完了。第二天还起不来。\u003c/p>\u003cp>我的反思：\u003c/p>\u003cp>其实我的问题在与很随意的和别人“签下一个协议”，然后还做不完，这样长时间的未完成事项，同时对自己能力的怀疑，开始焦虑。\u003c/p>\u003cp>按照片段中的方法，根据自己的情况，不要和同事或者求助的人“签订一个协议”，会增加自己的负荷；第二种方法是先完成目前有的“协议”，让自己获得成就感，有了成就感就会产生积极的情绪。第三种方法是和同事或者求助者协商完成的时间。\u003c/p>\u003c/p>\u003cp>按照片段的方法，不会有积极的情绪，至少不会有消极的情绪。\u003c/p>\u003cp>这个方法在什么时候不好用呢？不要用在不重要不紧急的事情上。不要因为不重要不紧急的事情没有做产生一些消极的情绪，这样做没有意义。\u003c/p>\u003c/p>","interaction":"\u003cp>\u003cp>大家有没有经历过这样的场景：\u003c/p>\u003cp>你在工位上写着今天准备做的事：第一件，完成一件本职工作，第二件，写一份总结，第三件，处理一下和同事协同的工作。第四件，准时下班陪孩子。\u003c/p>\u003cp>等你下班的时候，发现只完成了一件，这个时候，你还不得不加班完成另外的事情，自己计划要做的事没有按照自己的进度进行，此时此刻你的感受是什么样子？已经加班了1个小时，你的孩子给你打电话，问你什么时候回家？你会怎么回复？会不会迁怒孩子呢？\u003c/p>\u003cp>好了，现在按照开始的分组，大家在小组内分享一下自己过去的经历。\u003c/p>\u003cp>学习者A分享：\u003c/p>\u003cp>最近状态比较低落，工作上一直加班，被事情催着走的状态，情绪就比较低落，就导致一些事情忘记，等同事来催的时候，才开始做。回过来发现，自己怎么成为这样子了，对自己的认可度会降低，现在表现不好，开始自我否定，心里会有一些不爽。\u003c/p>\u003cp>现在大家在小组里讨论一下，如何运用今天学习的片段重新来改善刚才的经历呢？\u003c/p>\u003cp>学习者A分享\u003c/p>\u003cp>通过今天的拆页学习，运用拆页中的方法，可以这么做：\u003c/p>\u003cp>把之前没有完成的先完成了，把欠的债先完成了。然后根据自己的精力情况，选择性接受和拒绝一些事情，另外可以和同事协商一个可以完成的时间\u003c/p>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1569143478000,"updated_at":1569143478000,"ria":true},{"id":8911,"topic":"自我管理类——消除负面情绪","learn_goal":"通过拆页的学习，降低甚至消除负面情绪对我们的影响","remark":"在工作中，生活上，有没有体验过、经历过一些负面的情绪？假如现在让你时空穿梭，让你回到那个时刻，你有什么样的感受呢？如果重来，你会重新做一个什么样的决定呢？让我们跟着时间管理大师戴维艾伦，听听他是如何消除负面情绪的","level":"TF1-2","duration":20,"status":0,"type":0,"chaishujia":{"username":"竹本1314","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"大家好，我是竹本，很感谢今天大家的到来，自我介绍一下，我的3个标签：\r\n第一个标签：做竖屏思维导图，工具是XMIND\r\n第二个标签：我是微软认证的办公软件大师\r\n第三个标签：双拼输入法陪练\r\n以上就是我的自我介绍，大家有没有记住我呢？如果要记住一个词，那就是宝藏男孩\r\n今天我要拆解的图书是《搞定》，英文名字是《get things done》，缩写是《GTD》作者是时间管理大师戴维•艾伦\r\n豆瓣上评分8.3，每一个职场中人或多或少都有这样的体验：压力重重；太多事情都理不清头绪；似乎永远被各种任务和目标追赶着……时间管理大师戴维•艾伦将指导你走出规划和执行工作中的泥沼，通向高效、轻松的彼岸。要想让事情井井有条，关键便是——从容、放松。","ratings_count":0,"texts":[],"created_at":1569142654000,"updated_at":1569142654000},{"id":8787,"topic":"控制项目：纵向管理项目的5个阶段","learn_goal":"通过5个步骤解决待办事项","remark":"职场中有没有遇到下面这样的情况：\r\n领导分配了一项任务，无从下手；\r\n自己立了很多flag，结果都停留在了一些APP上。\r\n你需要的是一个可以简单重复的步骤，同时还可以传授给其他人。","level":"TF1-2","duration":15,"status":29,"type":0,"chaishujia":{"username":"竹本1314","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是竹本，很感谢今天大家的到来，自我介绍一下，我的3个标签：\r\n第一个标签：做竖屏思维导图，工具是XMIND\r\n第二个标签：我是微软认证的办公软件大师\r\n第三个标签：双拼输入法陪练\r\n以上就是我的自我介绍，大家有没有记住我呢？如果要记住一个词，那就是宝藏男孩\r\n今天我要拆解的图书是《搞定》，英文名字是《get things done》，缩写是《GTD》作者是时间管理大师戴维•艾伦\r\n豆瓣上评分8.3，每一个职场中人或多或少都有这样的体验：压力重重；太多事情都理不清头绪；似乎永远被各种任务和目标追赶着……时间管理大师戴维•艾伦将指导你走出规划和执行工作中的泥沼，通向高效、轻松的彼岸。要想让事情井井有条，关键便是——从容、放松。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":12494,"quote":"\u003cp>第3章 控制项目：纵向管理项目的5个阶段\u003c/p>\u003cp>自然计划模式 \u003c/p>\u003cp>世界上那个才华横溢、最具创造力的计划者，就是与你朝夕相处的大脑。实际上，你自己就是一台生产计划的机器。当你穿衣、吃午饭、购物，或者是在与人侃侃而谈时，你的大脑都在一刻不停地盘算着。尽管其过程可能毫无章法可言，但事实上在大脑闪现出任何一个具体的方案之前，一些相当复杂的步骤就已经抢先登场了。\u003c/p>\u003cp>人的大脑在面对任何一项任务的时候，都要经过5个步骤：\u003c/p>\u003cp>&nbsp;\u003cstrong>1. \u003c/strong>\u003cstrong>定义目标和原则。 2. 展望结果。 3. 头脑风暴/集思广益。 4. 组织整理。 5. 明确下一步的行动方案。\u003c/strong>\u003c/p>\u003cp>&nbsp;一个简单的事例：计划出去吃饭\u003c/p>\u003cp>你上一次出去吃饭时，最初的动机是什么？原因可能有很多：因为饥肠辘辘，或是朋友之间的社交活动，为了庆祝某一个特殊的日子，签订一笔生意的合同，又或是为了谈情说爱。只要是出于上述的某一个原因，你就可以马上开始进行计划了。\u003c/p>\u003cp>\u003cstrong>你的意愿就是你的目标，\u003c/strong>它自然而然地启动了你内心深处的计划过程。同时，你的原则规定了你所做计划的界限。可能你自己并未意识到外出就餐原则的存在，但是你的思维却从来没有逾越这些原则：\u003cstrong>食物和服务的标准、支付能力、方便程度以及舒适度。\u003c/strong>\u003c/p>\u003cp>无论如何，在制订计划时，\u003cstrong>你的目标就是你的动机，而原则又限定了你的计划\u003c/strong>。 一旦做出决定要实现这一目标，那么首先进入你脑海的实质性问题是什么呢？恐怕不是“计划、第二部分、第1点、第3小点”吧。你的第一批想法很可能是这样的事情，如“在餐厅吃意大利风味的晚餐”，或者“在比斯特罗咖啡馆街边的桌旁坐一坐”。你很可能还会想象出晚餐时的一些美好体验，或者设想一下晚餐的结局，也许你还想到了共同吃饭的人、就餐气氛什么的，这就是你的\u003cstrong>结果展望\u003c/strong>。\u003c/p>\u003cp>当外出就餐的原因成为你的目标时，\u003cstrong>对晚餐进行的种种想象就是你的展望\u003c/strong>。 一旦认同了这种展望，你的大脑便会自然而然地开始想一些问题：我们应该几点出发？这家餐馆今天晚上营业吗？人会不会很多？天气怎么样？是不是应该换身衣服？汽油还够吗？现在饿不饿？这就是\u003cstrong>头脑风暴。\u003c/strong>\u003c/p>\u003cp>一旦承诺要达到某一目标，那么在达到之前，你就会身不由己地向自己接二连三地发问。这些问题是这个创造性过程的一个组成部分。当大脑意识到在你设定的目标和你目前的状况之间存在着一定的差距时，它会千方百计地弥补这一差距，以消除这种“认知失调”。\u003c/p>\u003cp>这就是自然计划法中“如何……”这一思考阶段的起始点。\u003c/p>\u003cp>但是，这种思考模式显示出了一定的随意性，因为你会想到有关外出就餐的方方面面的事情。当然，你不一定把所有浮现在脑海里的事情逐一地写入“简式计划”，但是，你的大脑确实经历了类似的过程。一旦头脑里装满了大量的想法和细节，你也就不由自主地开始了\u003cstrong>组织整理的工作\u003c/strong>。\u003c/p>\u003cp>最后，为了确认首要的因素，你需要把注意力放在具体的下一步行动上。\u003c/p>","explains":"\u003cp>好，看到很多伙伴已经阅读了，没有阅读完的伙伴我们可以一起来学习\u003c/p>\u003cp>what:片段给出了一个处理事项的5个步骤，分别是\u003c/p>\u003cp>\u003cstrong>1. \u003c/strong>\u003cstrong>给行动设定一个目标和原则，为什么做这件事以及这件事的边界。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2. \u003c/strong>\u003cstrong>对行动过程进行想象\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3. \u003c/strong>\u003cstrong>关于第二个问题的，自己“头脑风暴”一下。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4. \u003c/strong>\u003cstrong>组织整理一下头脑风暴的问题\u003c/strong>\u003c/p>\u003cp>\u003cstrong>5. \u003c/strong>\u003cstrong>行动\u003c/strong>\u003c/p>\u003cp>结合片段，给大家分享一下我是如何应用以上5个步骤的\u003c/p>\u003cp>上周三也就是8月28日我拆1-1的内容，那么“拆1-1”就是一个我要准备的事项。\u003c/p>\u003cp>\u003cstrong>首先明确一下我的目标和原则\u003c/strong>：目标是通过1-1的各项训练内容。原则是按照拆书家手册里的1-1级别的技能\u003c/p>\u003cp>\u003cstrong>其次我展望拆书的结果：\u003c/strong>我对当晚拆书的情况进行各种想象，比如我想到我站在大家的面前，手里拿着我写好的要点，解读给大家听。\u003c/p>\u003cp>\u003cstrong>第三，头脑风暴\u003c/strong>。有了第二步的展望，我开始想一些问题：我应该几点到加减法咖啡厅？我要不要拿出一个计时器来？要不要提前吃点东西？\u003c/p>\u003cp>\u003cstrong>第四，以上在我脑海里的内容，便开始进行了组织整理。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>最后，按照以上的内容，我开始行动。\u003c/strong>我要5点左右到这里，再看一遍逐字稿，演练一遍。我包里装了代餐饼干，可以当晚餐。以上准备妥当以后，等着开始。\u003c/p>\u003cp>以上就是我的例子。\u003c/p>","interaction":"\u003cp>好了，大家在过往的经历中有没有这样的场景：双11、双12，明明只想买一件外套，结果外套没买，买了一堆护肤品。去了超市，明明想着就买一桶方便面，结果方便面是买了，还买了各种饼干饮料。\u003c/p>\u003cp>现在大家2-3个人一个小组，在小组内分享一下自己过去的经历，成功的也可以，失败的也可以，用时6分钟。\u003c/p>\u003cp>学习者A案例分享：\u003c/p>\u003cp>学习者A平时喜欢一些花草，在朋友圈里和微信群发一些和花草有关的东西，然而并没有专门运营这件事，一直觉得这件事挺好，但一直没有行动起来。同时呢，一个朋友一直在做这件事（固定分享关于花草的内容），于是学习者A在上上周五的时候决定做一个分享，要开始做这件事（直接到行动了），在群里发晚上9点做一个分享，但是过程没有什么准备。晚上到家已经七八点了，一边整理东西，一边思考要分享的点，因为准备很匆忙，开始的时候也晚了。分享的东西就太多了。\u003c/p>\u003cp>学习者A分享自己运用片段步骤的计划做的：\u003c/p>\u003cp>教师节快到了，要给老师准备节日礼物了，按照片段的步骤来做给老师准备礼物\u003c/p>\u003cp>大家已经完成了自己过去经验的回顾，那么现在拿出便签，在便签上写下未来如果遇到相似的情况，如何使用今天学到的内容来解决。用时1分钟。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1567782862000,"updated_at":1567815759000,"ria":true},{"id":8786,"topic":"自我管理类——掌控工作和生活","learn_goal":"掌控生活和工作","remark":"在今天这个信息量和工作量倍增的世界，一些老的工作方法已经失去了效用。每一个职场中人或多或少都有这样的体验：压力重重；太多事情都理不清头绪；似乎永远被各种任务和目标追赶着……时间管理大师戴维•艾伦将指导你走出规划和执行工作中的泥沼，通向高效、轻松的彼岸。要想让事情井井有条，关键便是——从容、放松。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"竹本1314","city":"北京市"},"club":{"name":"北京翰林分舵","city":"北京市"},"prologue":"\u003cp>大家好，我是竹本，很感谢今天大家的到来，自我介绍一下，我的3个标签：\r\n第一个标签：很多人称呼我是“宝藏男孩”，因为我会的技能比较多\r\n第二个标签：我是微软认证的办公软件大师，专项是EXCEL\r\n第三个标签：工具达人，各种提高效率的工具，我可以帮你通过工具层面提高效率\r\n以上就是我的自我介绍，大家有没有记住我呢？如果要记住一个词，那就是宝藏男孩\r\n &nbsp; &nbsp;&nbsp;\u003c/p>\u003cp>今天来的有新朋友，这里跟大家介绍一下“什么是拆书”和拆书帮。\u003c/p>\u003cp>大家有没有玩过消消乐？或者类似的游戏。\u003c/p>\u003cp>这种游戏有一个特别有意思的地方，就在你玩到后面的时候，不得不用道具提高通关率和减少通关的时间。游戏开发商送你道具，让你用道具体验快速通关的爽感。\u003c/p>\u003cp>我理解的拆书法，就是游戏里的“道具”，你没有用这个道具，你也可以通关，用了这个道具，能让你更快的完成通关。\u003c/p>\u003cp>换到读书上，可以这样理解，按照过去的方法，也可以读完一本书，只是时间和效率的问题。\u003c/p>\u003cp>拆书，通过3张便签，分别是R（阅读原文） I（用自己的话转述原文） A（反思过去和规划未来应用） 三张便签，以提升能力和解决问题为目标的阅读方法。\u003c/p>\u003cp>拆书法是建立在成人学习5大公理上，这5大公理分别是：\u003cstrong>自我导向、关联经验、强调实践、聚焦于解决实际问题、内在驱动。\u003c/strong>\u003c/p>\u003cp>拆书帮是什么？\u003c/p>\u003cp>拆书帮是聚集了一群迫切想要用知识去指导实践的职场人，是基于拆书法的爱好学习者社群，表现为各地的分舵，比如大家现在来到的北京翰林分舵。拆书帮分舵是非营利性“青年自组织”，使命是“释放学习促进者的能量”，帮助更多学习爱好者成为拆书家。\u003c/p>\u003cp>拆书法又分为“个人拆书法”和“组织拆书法”。个人拆书法是自己阅读的过程中使用的拆书法，组织拆书法就像今天这样的，由拆书家带领大家一起学习。\u003c/p>\u003cp>今天为大家带来的是《搞定》，英文名字是《get things done》，缩写是《GTD》现在给大家发拆页，大概用3-4分钟的时间，大家阅读一下拆页，阅读完的伙伴可以抬头示意我一下\u003c/p>","ratings_count":2,"texts":[{"id":12493,"quote":"\u003cp>第2章 掌控生活：横向管理工作流程的5个步骤\u003c/p>\u003cp>轻松掌控知识工作的核心方法，是熟练掌握工作流程管理的5个阶段，这5个阶段也是我们经验的总结和体现。无论在什么情况下，我们在处理生活和工作中遇过的问题及持续发生的新事务和变化时都将经历这5个独立阶段。无论是私事还是公事，要想使事务处于你的控制之中，都需要经历这些阶段。而这些不同阶段各有其最佳方法和管理工具。它们必须作为一个整体发挥作用，你才能在复杂的工作环境中呈现出最佳状态，提高工作效率。这些管理方法不只限于“组织整理”或者“确定优先事项”，这些方法固然很好，但它们只是应用这5个阶段所获得的结果，而不是阶段本身。我即将描述的这些阶段应该作为一个整体发挥作用，它们所产生结果的便利性和挑战性将出乎你的意料。 \u003c/p>\u003cp>&nbsp;我们：\u003cstrong>（1）收集引起我们注意的事务和信息；\u003c/strong>（\u003cstrong>2）理清每个项目的意义和相关措施；（3）组织整理结果，提出选项；（4）进行思考回顾；（5）选择行动。\u003c/strong>\u003c/p>\u003cp>这些阶段共同构成了我们生活中的横向管理系统，而且我们还可以随时向其中添加需要考虑的新事项。 只有在人类生活的主要领域，即人们训练自身反应、学习控制自身环境的过程中寻求自由的原则，才能得出有用的自由定义。 ——沃尔特·李普曼 这些并非主观或纯粹理论性的建议，当我们想控制并稳定某些事情，令其发挥建设性作用时，大家都会这么做。\u003c/p>\u003cp>如果你打算为朋友做顿饭，但到家时发现厨房一团糟，你会怎样处理？\u003c/p>\u003cp>\u003cstrong>首先要确认摆放不到位的所有东西（收集）；决定保留什么，扔掉什么（理清）；把东西归位——放回冰箱、扔进垃圾箱，或放进水池（整理）；然后核对你的食谱，以及已有的食材和厨具（回顾），然后把黄油放进锅里融化，开始做饭（行动）。 \u003c/strong>\u003c/p>\u003cp>这几个步骤的原理很简单。可能你没有察觉到，不过这确实就是我们习以为常的处理事情的方法。但是根据我的经验，大多数人在这5个阶段中，都还有很大的效率提升空间。我们对工作流程的管理包括了5个环节，并且管理的效果通常取决于这5个环节中最薄弱的一环。因此，除非所有环节都紧密结合，并按统一标准加以管理，否则，其最终效果将难以保证。\u003c/p>","explains":"\u003cp>好，看到很多伙伴已经阅读了，没有阅读完的伙伴我们可以一起来学习\u003c/p>\u003cp>what:片段给出了一个定义，轻松掌控知识工作的核心方法。\u003c/p>\u003cp>why：大家回忆一下，有没有经历过工作没有头绪的状态，因为工作多，感觉很焦虑，很拖延。\u003c/p>\u003cp>举个栗子，明明要给同事发个邮件，拿出手机开始刷外卖；明知道这会应该做一些紧急的事情，却开始做不重要不紧急的事情.......\u003c/p>\u003cp>这是病，得治。有药吗？药，就在片段里\u003c/p>\u003cp>how：这个片段中给出了5个步骤：\u003c/p>\u003cp>\u003cstrong>（1）收集引起我们注意的事务和信息；\u003c/strong>\u003c/p>\u003cp>（\u003cstrong>2）理清每个项目的意义和相关措施；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（3）组织整理结果，清理出有用的和无用的内容；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（4）进行思考回顾；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（5）选择行动。\u003c/strong>\u003c/p>\u003cp>结合片段，给大家分享一下我是如何应用以上5个步骤的，先分享一下我过去的经历\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>我15年10月的时候，刚调到天津，担任总账会计的工作，工作很繁琐，如果大家周围有从事财务工作的朋友，一定听他们经常抱怨，加班多，工作多，整理凭证、报税，查账等等。是的，这就是财务工作的写照。\u003c/p>\u003cp>刚接手这份工作的时候，工作很没有头绪，办公桌上也是很乱，各种单据铺的满我的工位，月底工作很焦虑。\u003c/p>\u003cp>我独立接手工作是11月，11月的最后2天是结账时间，这个时候，应该是到了检查当月各种工作是否完成。这个时候呢，又是各种琐碎工作集中的时候，比如业务员还要继续报销费用，库房材料还要盘点，当月的现金也要盘点........\u003c/p>\u003cp>总之呢，第一个月过的很“糟糕”，因为这件事，报表不仅交的迟了，财务经理和我都被罚款了。\u003c/p>\u003cp>用片段中的步骤反思一下，首先是没有做到整理工作内容，工作来一件做一件，也不管和自己的有没有关系，就接过来，让自己开上去很“忙碌”，其实是“无效的努力”。都没有做到“收集”和分类，那么后面的步骤当然无法进行了。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>大家有没有定期在家里进行清理物品的习惯呢？家里东西一定很多，让你整理无法下手，不论是你的，还是你另一半的，或者是孩子的。\u003c/p>\u003cp>下周末，我计划用这个方法，在我住的地方，进行了一次“断舍离”，用的方法就是书中的步骤，\u003c/p>\u003cp>（1）把所有东西拿出来，\u003c/p>\u003cp>（2）决定扔掉什么，不用什么，闲置的东西可以送给朋友\u003c/p>\u003cp>（3）把剩下的自己要用的东西重新归类；\u003c/p>\u003cp>（4）检查一下自己的东西，和摆放的原则。比如换季了，夏天的衣服可以叠起来，长袖可以拿出来洗干净，挂起来。\u003c/p>\u003cp>（5）按照第四步，做起来。just do it.\u003c/p>\u003cp>以上就是我今天的内容，希望对大家有所帮助，我是宝藏男孩竹本。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1567781947000,"updated_at":1567782010000,"ria":true},{"id":8118,"topic":"破解焦虑烦恼，用有效计划实现无压工作","learn_goal":"清空大脑，摆脱压力；纵向管理项目，确保项目达到预期结果","remark":"在今天这个信息量和工作量倍增的世界，每一个职场中人或多或少都有这样的体验：压力重重；太多事情都理不清头绪；似乎永远被各种任务和目标追赶着……如何走出各种焦虑和压力，轻松安排计划，确保达成预期目标？","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"littledl2019","city":"大连"},"club":{"name":"大连知行分舵","city":"大连"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;【自我介绍】\r\n大家好，非常感谢大家来参加我的拆书练级活动。用三个标签介绍一下我自己，第一个标签是工程设计，第二个标签是学习爱好者，第三个标签是成长，我参加拆书帮也是挑战自我选择成长的过程。\r\n现在先分组下组，这边3位小伙伴一组，中间3位小伙伴一组，这边4位小伙伴一组，一会儿大家需要在小组内进行讨论。\r\n【图书介绍】\r\nF：我今天分享的片段选自《搞定1》，这本书是时间管理类的经典著作，在全球被翻译成30多种语言出版，作者戴维•艾伦，是一名资深的行政管理专家和培训家，被誉为在提升工作效率方面最具建树和影响力的思想家之一。本书从收集、处理、组织整理、回顾、执行五个方面介绍了GTD系统，以及如何在工作和生活中运用，帮助我们提高工作的效率。\r\nA：和其他的书相比，这本书权威严谨且生动实用，它不仅传授了时间管理和精力管理方面的具体知识，更是总结了一套“无压力工作”的经典理论。\r\nB：在今天这个信息量和工作量倍增的世界，每一个职场中人或多或少都有这样的体验：压力重重；太多事情理不清头绪、不知从哪里入手；似乎总是被各种任务和目标追赶着……本书提供了一种解决的方法GTD，getting things done即搞定，承诺自己一切准备就绪，对自己的行为负责，对想要达成的结果负责，从而提升生活和工作的质量。\r\n下面请大家阅读一下第一个片段，时间是一分钟。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":11714,"quote":null,"explains":"\u003cp>【学习目标】\u003c/p>\u003cp>通过这个片段的学习，学习者能够意识到产生焦虑的原因，很多时候是由于一些重要的事情需要处理，却一直没有得到妥善的解决，通过运用“明确预期结果——制定下一步行动——设置提醒系统”三步法，把待办事项从大脑中清理出来，让大脑摆脱压力、实现高速运转。\u003c/p>\u003cp>【I：讲解】\u003c/p>\u003cp>（负面一般做法）\u003c/p>\u003cp>大家有没有过这样的经历，总有一些未完成的事务或者想法徘徊在你的脑中，像买了很久的书一直没有读，老板交待你做项目的改进方案却迟迟没有进展，你似乎觉得一直很忙没有时间去处理这些事？\u003c/p>\u003cp>（不这么做的坏处）\u003c/p>\u003cp>这些待办的事项一直徘徊在你的脑中不断的给你带来压力，时间越长，焦虑感越重；而大脑的主要职责应该是是CPU，是运算的不是存储的系统，这种事务的积累会使人特别的疲惫，也会给我们带来很多的焦虑感。\u003c/p>\u003cp>（拆页行动建议）\u003c/p>\u003cp>如何解决这种困扰呢？根据片段中这个方法，我们需要明确预期结果、制定下一步行动、设置提醒系统通过这三个步骤来放空大脑，恢复高效的运转状态。\u003c/p>\u003cp>我们具体的来看一下：\u003c/p>\u003cp>第一步，明确预期结果。比如说我想“提高英语水平”，一个明确的预期结果可能是取得商务英语证书，或者去外企打拼。\u003c/p>\u003cp>第二步，制定下一步行动。计划采取哪些行动来达成目标，预计花多长时间？比如，我准备减肥，如果我的目标是2个月减10斤，这里包括的行动是每天做哪些运动、运动量是多少，如何调整饮食等等一些具体的行动。\u003c/p>\u003cp>第三步，设置提醒系统。比如，列出总待办清单，今日待办清单等等。\u003c/p>\u003cp>（负面例子）\u003c/p>\u003cp>举一个自己的例子。前年，我准备参加一个考试，当时在现场出差，白天想的是晚上回去一定要看书，晚上回到住处就会想先休息一会儿再看，然后就没有然后了，那段时间每天都感到特别焦虑，结果书没看几页，倒长胖了。\u003c/p>\u003cp>根据这个片段来看，这个片段中提到的这几点焦虑产生的原因都很符合我当时的状况。\u003c/p>\u003cp>（正面例子）\u003c/p>\u003cp>根据这个拆页的建议，我应该是：\u003c/p>\u003cp>1. 明确预期结果：设定的目标是，那次考试4门课，当年至少通过3门；\u003c/p>\u003cp>2. 制定下一步行动：预计每本书看多少时间，比如每本书看2-3遍，大约20天，并做脑图笔记帮助记忆。\u003c/p>\u003cp>3. 设置提醒系统：做出详细的学习计划，每天监督自己去执行。\u003c/p>\u003cp>以上就是用这套系统来清空大脑。\u003c/p>","interaction":"\u003cp>【A1：显像提问】\u003c/p>\u003cp>接下来，请大家回想一下，在过去的一个月当中，有哪些需要解决的事情却迟迟没有处理？比如“老板让你做的工作方案，你不知如何下手”、“想学习一些技能，却一直压在那里也没有去做，比如想学做漂亮的PPT却想了很久却一直没有去做”。大家在小组内讨论一下，每人考虑一个让你感到焦虑的事情分享一下，时间是2分钟。\u003c/p>\u003cp>时间差不多了，哪位小伙伴来分享一下？\u003c/p>\u003cp>学习者一：\u003c/p>\u003cp>我准备拆书稿的时候就特别焦虑。比如说每天都在想，我今天要改好，结果因为事情耽误了，到晚上就放弃了。第二天又重新这个过程总是在循环。最后实在不行了就交了，其实也没怎么减轻焦虑。\u003c/p>\u003cp>学习者二：\u003c/p>\u003cp>我现在最大的焦虑就是，我的时间安排在拆书、全国共拆和训练营上。其实我自己的培训师简历以及课程大纲，前两天在参加培训的时候发现了是在裸奔的状态，特别需要修改，而且对方还说你赶快修改好了来做。但是这个修改可能需要一个月的时间，我一想到这个就感到特别的焦虑。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>如果回到当初，运用今天学到的这个方法，明确预期结果——制定下一步行动——设置提醒系统，我们如何来改善刚才的那种状况呢，或者我们如何对这个事件重新进行一个规划？大家在小组内再讨论一下，时间是3分钟。每人写一个便签。\u003c/p>\u003cp>下面请一位小伙伴来分享一下。\u003c/p>\u003cp>学习者二：\u003c/p>\u003cp>1. 明确预期结果，对于前一段时间的焦虑，我的课程大纲，准备在上个月底前完成5页的培训师简历，7页的课程大纲。\u003c/p>\u003cp>2. 制定下一步行动，每天写一页，按照一个主题。在时间范围内，\u003c/p>\u003cp>第三个就是设置提醒系统。每天早上8点钟设置提醒（开始行动），每天晚上八点钟再设置一个检查一下。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":11715,"quote":null,"explains":"\u003cp>【学习目标】\u003cbr>\u003c/p>\u003cp>通过这个片段的学习，学习者在面对一个项目时，不再盲目采取行动，而是按照自然式计划模式的纵向管理流程，通过“定义项目的目标和原则——展望结果——人言可畏思广益——组织整理——明确下一步行动方案”五个步骤，确保项目达到良好的预期结果。\u003c/p>\u003cp>【过渡】\u003c/p>\u003cp>学完了这个片段，回想到以前的经历，我们之所以感到焦虑，是因为我们的大脑里积压了太多的没有完成的事务，通过运用“明确预期结果——制定下一步行动——设置提醒系统”三步法，就可以把清空我们的大脑。然而清空大脑只是一个开始，我们还需要对它进一步处理。\u003c/p>\u003cp>在我们的工作和生活当中，有一类事务，是项目。在我们着手处理一个项目时，具体需要怎样做来保证它顺利执行呢？接下来，我们来看一下第二个片段，自然式计划模式，时间是2分钟。\u003c/p>\u003cp>大家都已经读完了吧？\u003c/p>\u003cp>【why】\u003c/p>\u003cp>在我们的工作和生活中，有一类任务，像是出去作一场旅行、或者组织一场活动、开发一个产品、制作一个方案……这些都需要多个步骤来完成，这类事务叫做项目。\u003c/p>\u003cp>【what】\u003c/p>\u003cp>我们需要对项目进行适当的管理和规划，以推进它向着期望的方向发展。这个片段介绍的就是对项目的管理方法。\u003c/p>\u003cp>我们一起来看一下，具体的步骤：\u003c/p>\u003cp>【How】\u003c/p>\u003cp>第一，定义目标和原则。\u003c/p>\u003cp>目标是我们为什么要做这个项目，做这件事的原因。目标不同，采取的行动也就不同。比如说，出去旅行，是为了去放松悠闲、还是到景点打卡拍照？采取的行动也会不一样。\u003c/p>\u003cp>定义目标主要是为了制定成功的标准、这样会更容易界定成功。\u003c/p>\u003cp>这里我们来举个例子，比如说小明准备去美国旅行。\u003c/p>\u003cp>目标可以设定为：七月份去美国自驾旅行一周，领略异国风光。\u003c/p>\u003cp>原则，是我们要遵循的标准和价值观。\u003c/p>\u003cp>在这个例子里，我们可以定义它的原则是旅行食宿的花销要做到经济实用。\u003c/p>\u003cp>第二步是展望结果。\u003c/p>\u003cp>把预期的结果转化为一个场景，场景的画面越清晰具体，也越容易让我们接近成功，也会让我们的精力聚焦在这上。\u003c/p>\u003cp>比如，在这里，小明可以想像在美国漫步在街上，欣赏着异域风光的场景，发朋友圈后得到大批朋友的艳羡。\u003c/p>\u003cp>第三步，头脑风暴。\u003c/p>\u003cp>头脑风暴大家比较熟悉的吧？这里不多说，头脑风暴有几个原则：不批判，不质疑，不评估。追求数量，不求质量。收集来的信息越多越好。\u003c/p>\u003cp>比如，这个例子中，小明这时拿出纸笔罗列出与去着美国旅行相关的所有相关信息。\u003c/p>\u003cp>比如包括：办护照、办签证、制定旅行路线、买机票、订酒店、换美元、准备携带的物品。还有其他的，这里不再罗列。\u003c/p>\u003cp>第四步，组织整理。【细化步骤】\u003c/p>\u003cp>头脑风暴收集信息，大多是比较杂乱的，接下来我们需要对这些信息进行归类整理。\u003c/p>\u003cp>这里包括以下4个步骤：\u003c/p>\u003cp>（1）归类，找到信息之间的内在联系，进行归类。\u003c/p>\u003cp>在这个例子里，我们可以归下类，\u003c/p>\u003cp>手续类包括：办护照、办签证、买机票、订酒店\u003c/p>\u003cp>物品类包括：换美元、准备携带的物品\u003c/p>\u003cp>（2）梳理先后顺序。很多事情都是有前后顺序的，比如先开花后结果。\u003c/p>\u003cp>办护照——办签证——买机票、订酒店\u003c/p>\u003cp>制定旅行路线——买机票、订酒店\u003c/p>\u003cp>其他的没有太过明显的顺序。\u003c/p>\u003cp>（3）确定重要程度。\u003c/p>\u003cp>这几点都是必要的，这里不列重要程度了。\u003c/p>\u003cp>（4）描述，要求是足够详细，挑出几个重要的进行描述。\u003c/p>\u003cp>为了节省时间，我们挑几个进行描述：\u003c/p>\u003cp>路线：安排一周行程\u003c/p>\u003cp>酒店：经济型，卫生、安全\u003c/p>\u003cp>物品清单：必备的物品。\u003c/p>\u003cp>第五步，明确下一步行动。 \u003c/p>\u003cp>制定详细的方案，比如什么时候办护照、什么时候办签证、什么时候制定旅游路线，制定一个详细的规划，确定完成时间。\u003c/p>\u003cp>之后就是照单执行。\u003c/p>\u003cp>以上就是运用“自然式计划”的过程。\u003c/p>\u003cp>（预防异议）\u003c/p>\u003cp>讲到这里，有些伙伴可能会说：是不是所有的事情都按这个流程来走，是不是太复杂了？ \u003c/p>\u003cp>我们的建议是，过程要按这个操作，至于详细程度，根据事情的不同来进行调整、取舍。标准就是能够让我们的大脑保持轻松的状态，基本上就足够了，能够缓解我们的压力就可以了。\u003c/p>","interaction":"\u003cp>【A3】\u003c/p>\u003cp>下面我们来做一个练习：\u003c/p>\u003cp>大家在小组内讨论之后，运用自然式计划模式对项目进行梳理，时间是15分钟。\u003c/p>\u003cp>下面请一组老板和经理来给大家讲解一下。\u003c/p>\u003cp>非常感谢这组小伙伴的分享，刚才的分享整个就是按照这个流程来走的，过程非常清晰也非常仔细，非常感谢。\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>（A2分步催化1）\u003c/p>\u003cp>下面来请大家考虑一下，在未来一个月的工作和生活当中，你会处理哪些项目？是要准备一场拆书课还是一次练级？或者工作中需要做一个方案？或者制定一个学习计划，等等。请大家在小组内讨论一下，你准备着手处理的那个项目，时间是2分钟。\u003c/p>\u003cp>学习者三：\u003c/p>\u003cp>我们要办暑期的两期儿童情商训练营，这是我们的目标。\u003c/p>\u003cp>（引导）说一个场景就行，介绍一下背景就行。\u003c/p>\u003cp>这个项目的背景就是目前是零起步开始招生，在七月中下旬和八月上旬开展两期的儿童情商训练营，目前准备开始招生。\u003c/p>\u003cp>（A2分步催化2）\u003c/p>\u003cp>请大家再考虑一下，如何使用自然式计划模式的五个步骤来对刚才的项目制定计划？大家先在小组内讨论，然后每人写一个规划应用，时间是5分钟。\u003c/p>\u003cp>这里有一个要求，要符合SMART原则：明确、可实现、可衡量、与其他目标有相关性、有明确的截止日期。\u003cbr>\u003c/p>\u003cp>下面请一位小伙伴来分享一下。\u003c/p>\u003cp>学习者三：\u003c/p>\u003cp>（1.目标和原则）\u003c/p>\u003cp>我的目标是在一个月之内，30天之内招满30个学员。\u003c/p>\u003cp>原则是帮助这些孩子们在两期的训练营，每期是一个星期的时间内，帮助他们对自己情商的管理，有初步的认识和理解以及应用。再加上沟通、融入团队、尊重与鼓励、专注力的这些训练。是很棒的一套课程，这些是我想带给这些孩子们的，也是我认为4-12岁孩子应该具有的技能，希望我们能提供给他们。\u003c/p>\u003cp>（2.展望结果）\u003c/p>\u003cp>展望结果就是希望招满30个孩子，让这些孩子带动身边更多的小伙伴们。因为我们后期还有更多的课程，包括有专门的专注力的课程，还有ICIR的课程。希望他们能够持续关注我们的教育，从而带动，更多的小伙伴到我们这里来学习。\u003c/p>\u003cp>（引导）他们也会非常愿意到你们这里来学习，他们会觉得非常的开心。\u003c/p>\u003cp>孩子在这边成长，能够看到他们一点点进步，这是我们希望展望的最终结果。\u003c/p>\u003cp>(3. 头脑风暴)\u003c/p>\u003cp>那我们有家长群，通过陆续开发，希望有更多的线上线下呃家长们来关注我们。\u003c/p>\u003cp>（引导）他们会给你们良好的建议。\u003c/p>\u003cp>对，给我们良好的建议，以及认可我们的理念帮我们宣传推广。\u003c/p>\u003cp>（通过收集家长们的建议，以及自己在这方面的经验，收集到的相关信息，有：线上线下推广、客户信息、客户分类ABC类、客户需求、孩子年龄、课程开发、家长对孩子情商的关注、线上调查表、家长讲堂……）\u003c/p>\u003cp>（4. 组织整理）\u003c/p>\u003cp>（4.1归类）客户分类：前期我们收集到家长的信息，包括线上线下的。我们会分为ABC类客户，根据每个客户不同的需求，需要的课程也不一样。\u003c/p>\u003cp>（推广类：线上线下推广、线上调查表、家长讲堂\u003c/p>\u003cp>课程类：情商、课程开发\u003c/p>\u003cp>客户类：客户信息、客户分类ABC、客户需求、孩子年龄）\u003c/p>\u003cp>（4.2 排序）\u003c/p>\u003cp>（1）先收集客户名单对我来说是最重要的。\u003c/p>\u003cp>刚刚搬到这边来，然后这边的家长都不了解我们。\u003c/p>\u003cp>（2）再一个要分出ABC类客户，这个对我们来说也很重要。\u003c/p>\u003cp>（3）然后再根据孩子不同的特点再细分，孩子需要一个什么样的课程？比如说以情商为主的孩子，要在这里筛选出家长对孩子情商关注度更高的优先挑选。\u003c/p>\u003cp>（顺序：收集客户名单——客户分类——根据客户开发课程）\u003c/p>\u003cp>（4.3重要程度）收集信息最重要，客户信息，让更多的家长知道我们。\u003c/p>\u003cp>（4.4描述）比如说你刚才说的收集什么信息，都收集什么样的信息？\u003c/p>\u003cp>收集信息，我们分两种，一个是线上的，我们有一个调查表在群里面。那么线下的，我们就是面对面的沟通，包括孩子的年龄、他的一些简单的特点，包括家长对孩子的一些诉求。\u003c/p>\u003cp>（5. 明确下一步行动）\u003c/p>\u003cp>下一步的行动方案是：\u003c/p>\u003cp>我们要在微信群里面发布信息，在6月15号之前持续的发布信息；\u003c/p>\u003cp>6月15号要做一个家长讲堂和孩子公开课的演示；\u003cbr>\u003c/p>\u003cp>以及其他方式持续推广暑期的两期儿童情商训练营。\u003c/p>\u003cp>这个项目是有点太大了。在这么短的时间内总结出来这么多，非常棒，非常感谢！\u003c/p>\u003cp>【结语】\u003cbr>\u003c/p>\u003cp>最后，我们来总结一下，大脑是CPU不是硬盘，它是用来运算，而不是储存，如果我们的大脑积压了太多的事务，就会造成效率大大的降低，让我们感到非常焦虑。所以我们需要把那些待办事项清出大脑。清空大脑的过程就需要用第一个片段，明确预期结果、制定下一步行动、设置提醒系统这三个步骤来执行。\u003c/p>\u003cp>对于清出来的项目，就需要按照第二个片段，自然式计划模式来进行管理和规划。这样才能保证它得到顺利执行，达成良好的预期结果。\u003c/p>\u003cp>希望大家都可以运用今天学习到的方法，切实帮助自己实现没有压力的工作状态，同时把各项事务处理的井井有条，非常感谢大家！\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1560075824000,"updated_at":1562367556000},{"id":7877,"topic":"用清单搞定身边事以及如何高效利用碎片时间","learn_goal":"2-4过级","remark":"用清单高效做事，以及如何高效利用碎片时间。","level":"TF2-3","duration":60,"status":30,"type":0,"chaishujia":{"username":"薛锦聪","city":"邯郸"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>各位小伙伴们，大家晚上好！我是薛锦聪，矿院大四学生。我的三个标签是：GTD、写作、野生交易员。待会我们的活动需要分组，那我左边的（几个）为一组，右边的（几个）为一组。\u003c/p>\u003cp>【总目标】通过本次学习，学习者能够将大脑中的想法和任务有序清空，罗列，确定某一时刻的具体行动。\u003c/p>\u003cp>【分目标】拆页一的学习：学习者在面对一堆想法和任务时，能够及时清空大脑，罗列计划；拆页二的学习：学习者在一个空闲时间段或一个时间点，能够运用GTD“四标准法”确定某一时刻的具体行动，充分利用时间。\u003c/p>\u003cp>\u003cstrong>新技能：介绍图书FAB\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>今晚我要拆解的片段来自《搞定1》一书。\u003c/p>\u003cp>【F特征】《搞定1》是世界知名时间管理大师戴维-艾伦的经典著作，这本书介绍了全球千万人正在轻松使用的GTD（Getting Things Done）个人事务管理系统。\u003c/p>\u003cp>【A优势】于同类书籍相比，本书内容是David-Allen 30多年在个人和组织效率方面的研究汇总而成，既适用于工作，也是适用于生活。而且，市面上的大部分时间管理书籍脱胎于此，可以说是首屈一指的时间管理书籍。\u003c/p>\u003cp>【B1利益】在这个充满变化需要不断学习新知才能紧随的时代，GTD将提供一个完善的系统，足够强硬的逻辑，来支持你进行行动决策。\u003c/p>\u003cp>【B2利益】通过今晚的学习，片段一不仅能够帮助大家在思路杂乱的状态下，有效清空大脑中的各种想法和任务，减轻大脑负担，专注于当下事务。片段二还能够就某个特定场景，运用GTD“四标准法”，确定某一时刻的具体行动，充分利用碎片化时间。实现整段时间和碎片时间的合理使用。\u003c/p>","ratings_count":1,"texts":[{"id":11419,"quote":"\u003cp>刚才已把原文片段发下去了，下面请大家用2分钟时间阅读原文拆页片段。\u003c/p>\u003cp>\u003cstrong>原则：有效地处理内心的承诺\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;在数十年的培训工作中，我指导过数干人。在这个过程中，我发现了一个极为常见的现象，即由于人们对自己做出的承诺或者承担的义务管理不当，导致他们承受着重重压力的折磨。所以，学会对承诺事项加以控制，可以有效缓解压力。即使是那些并没有明显体验到压力的人，如果他们学会了更加有效地对生活中悬而未决的问题加以控制，那么在放松自我、集中精力、提高效率方面也会有明显的改善。\u003c/p>\u003cp>&nbsp;&nbsp;恐怕你已经与自己达成了许多协议（这一点也许你根本没有意识到）。而每一项协议，无论大小，都时时刻刻被你自身的无意识所紧密追随。这些就是“未完成的事情”或者“悬而未决的问题”。它们可能是“根除世界上的饥饿问题”这类重大事务，也可能是“雇用一个新助手”之类的一般性事件，或是“更换走廊灯泡”一类的琐碎小事。\u003c/p>\u003cp>&nbsp;&nbsp;为了能够高效应对这一问题，首先，你必须明确并收集所有那些“经常唤醒你模糊记忆”的事情，搞清它们对你而言的真正意义，然后决定如何推动它们。这看起来极为简单，但在实际操作中，大多数人都难以始终如一地坚持下去。他们缺乏认识或动力，而最可能的原因是，他们没有意识到忽略这种做法将会付出的代价。\u003c/p>","explains":"\u003cp>\u003cstrong>新技能：【I】拆书家讲解引导之细化行动步骤\u003c/strong>\u003c/p>\u003cp>在工作或生活当中，大家有遇到过这种情况不？你会经常用大脑记忆某种任务或想法，通过不断地记忆来想起这件事的存在，好提醒你及时完成任务。可这一阵子你实在太忙了，没法腾出时间来解决它们。拖延下去，进而产生了抗拒心理。\u003c/p>\u003cp>那我们该怎么处理这些信息和任务呢？我将David Allen的表述，结合GTD整个体系，梳理出了以下四个步骤。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>）细化行动步骤\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>收集所有事项。\u003c/strong>务必收集所有脑海中吸引你注意力的事项和想法，可以尝试用笔记下。可能是“明早9:30开会”、“周末陪老婆逛街”、“下周一替领导取某某报告”等。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>理清事项意义。\u003c/strong>这件事情对你有什么意义，做了后会产生什么改变，不做又会造成多大影响？\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>罗列具体行动。\u003c/strong>确定下一步行动，具体到看一眼就能执行的程度；比如说本周五晚上7:00在邯郸新世纪参加拆书活动。\u003c/p>\u003cp>\u003cstrong>4.\u003c/strong>\u003cstrong>提醒设置。\u003c/strong>可以用闹钟、台历等来提醒自己某一时间段或某一时间点该做什么事了。\u003c/p>\u003cp>本方法需要在一个相对放松的环境下，有充裕的时间来完成，不适合紧急情况下。\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>）不那么做的坏处\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp;如果我们不那么做又会怎样呢？大家一般都是想到啥就做啥，缺少条理，经常丢三落四的，还有可能因为脑子里有很多事，注意力容易分散。杂念越多，越容易焦急，一急起来，又容易忘事，陷入恶性循环，还很影响自己的心情 。我有一回参加项目答辩，同时设计讲稿、制作PPT，到现场忘带U盘了，急忙跑出去联系我同学送过来，结果发言的时候前言不搭后语。如果我能够清空下自己的大脑，梳理清楚各件事的意义，并给它们列个行动清单，并设置相关提醒，也不至于忘带U盘了，还能够安心地观察现场的变化，集中注意力调整我的讲稿和表述方式，有可能顺利晋级决赛。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>）异议预防性讲解\u003c/strong>\u003c/p>\u003cp>有的伙伴自己也曾做过清单，也明白它的重要性，还是做不到。这是可以理解的，我也是这样从一开始的“三天打鱼两天晒网”的状态过来，最好的解决方法就是你每天都在使用，可以不完全列出来，只要你在用它，哪怕是罗列一件事，也是成功的开始。当你愉快地完成了所列任务，会促使你更加愿意使用下去，并慢慢喜欢上“清空大脑”这项行动。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>）举个例子\u003c/strong>\u003c/p>\u003cp>举个自己的例子。这周三，我既要做中期答辩PPT，还要写设计说明书，更想把换了几天的脏衣服拿去洗。忙得乱成一团，那我是这样做的。\u003c/p>\u003cp>首先，为了让自己不再困惑，先把这3件事写在本子上。\u003c/p>\u003cp>其次，开始理清各项的意义。中期答辩PPT要得比较急，今晚就得交给老师；下周一15号要交毕设初稿，包括设计说明书，时间已经很近了；脏衣服；脏衣服再放着估计要臭，明后天要洗澡也没什么衣服换。\u003c/p>\u003cp>之后，我确定下来的行动计划是这样的。上午制作10页答辩PPT，下午和晚上撰写1000字设计说明书，晚上23:00在寝室洗衣服。\u003c/p>\u003cp>&nbsp;&nbsp;最后，将这3件事记录在滴答清单中，并设置了时间提醒。\u003c/p>","interaction":"\u003cp>\u003cstrong>显像提问\u003c/strong>\u003c/p>\u003cp>好，现在请大家仔细想下，过去一周有哪些事情是一直占用着你的注意力，让你感到焦虑，也没有处理好的呢？有可能是“撰写拆书稿”、“阅读某本书”、“周末和老公/老婆去哪玩呢”等。当时你又是如何面对这些事的？请大家回想下，并在组内分享。\u003c/p>\u003cp>\u003cstrong>灿阳——案例分享：\u003c/strong>\u003c/p>\u003cp>从原来时间比较多，到现在有固定的时间，最近事情一直也比较多，太忙了没参加拆书过级。师父一直也在催我，韩哥也问过我“你进度这不行啊。”我是真的把这当回事了记在心里了。平时工作的话，也会很焦虑，老惦记着这件事。从周一的时候就开始做这件事，确定了片段，后面来来回回折腾才把稿件确定出来。\u003c/p>\u003cp>\u003cstrong>引导者：\u003c/strong>好的，感谢灿阳给我们带来的一个分享（掌声），听得出来为拆书过级做了很多努力。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003cstrong>A1+\u003c/strong>\u003c/p>\u003cp>要是能回到当时，针对其中的一件事，运用拆页一学习到的方法：收集所有事项，理清事项意义，罗列具体行动，提醒设置。你会怎么处理呢？\u003c/p>\u003cp>下面给大家3分钟时间，写在纸上，并在小组内讨论分享。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>韩晓东——案例分享：\u003c/strong>\u003c/p>\u003cp>上周二事情比较多，上午要带父母去体检，下午要去参加小孩的家长会，下午还要主持工程会议。没有提前和老婆商量，发生了一些不愉快的事。按照今天所学的，我会这么来做：\u003c/p>\u003cp>1.&nbsp;首先，收集所有事项，把这些事情记录下来；\u003c/p>\u003cp>2.&nbsp;其次，这些事情都很重要。因为个人时间有限 ，所以，我当天会带父母去体检，提前告诉老婆去参加孩子的家长会。\u003c/p>\u003cp>3.&nbsp;之后，我的计划是：提前和老婆协商，叫她参加孩子的家长会；我上午陪父母去医院体检，下午主持工程会议。\u003c/p>\u003cp>4.&nbsp;最后，我会把这些计划记录在我的手机备忘录里头，并设置相应的提醒时间。其实，我电脑里有一堆的工作清单呢。\u003c/p>\u003cp>\u003cstrong>引导者：\u003c/strong>好，感谢韩哥带来的分享，听得出韩哥也有使用清单的习惯。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":11420,"quote":"\u003cp>\u003cstrong>片段一和片段二的逻辑关系：\u003c/strong>\u003c/p>\u003cp>刚才我们学习了如何清空大脑，减压，理清事项的意义和下一步行动。接下来我们学习GTD的“四标准法”用以确定某一时刻的具体行动。如果说有效处理内心承诺是面，立足于一个较长的确定的时间段。那么，确定某一时刻具体行动的“四标准法”是个点，是基于一个碎片化的时间点，一个场景。这是两者的区别，也是两者的逻辑关系。清空大脑所做的事情是一整段时间，而碎片时间，更多是做你任务清单上，或者你能想到的事。\u003c/p>\u003cp>具体又是怎么一会事呢?下面给大家2分钟的时间来阅读原文片段。\u003c/p>\u003cp>\u003cstrong>确定某一时刻具体行动的“四标准法”\u003c/strong>\u003c/p>\u003cp>在星期三下午3点22分时，你如何选择下一步行动呢？这个时候，你可以按顺序采用下面四个标准：情境、有多少时间、有多少精力和重要性。\u003c/p>\u003cp>&nbsp;&nbsp; 前三个标准描述了你每次采取行动的制约因素，第四个标准则是评估行动的价值大小。\u003c/p>\u003cp>&nbsp;&nbsp; \u003cstrong>情境\u003c/strong>&nbsp;每时每刻，你都受限于自己的行动能力。只有很少一部分事情对地点没有特别要求（像拿一支钢笔和一张纸就可起草对一个项目的想法），但是，大多数事情都只能在特定的地点完成（在家或办公室），或者需要借助某些特定的工具（如一部电话、一台电脑），而这正是限制我们行动选择的首要因素。\u003c/p>\u003cp>&nbsp;&nbsp; \u003cstrong>有多少时间\u003c/strong>&nbsp;你所能支配的时间长短也是一个重要的限制因素。如果5分钟后你就必须去开会，你现在就不可能去执行那些耗时更久的行动。\u003c/p>\u003cp>&nbsp;&nbsp; \u003cstrong>有多少精力\u003c/strong>&nbsp;你有多少精力呢？某些事情需要你头脑清醒、思路清断、富于创造力，而另一些则要求你具备充沛的体力。还有一些事情\u003c/p>\u003cp>则对这两方面都没有特别要求。\u003c/p>\u003cp>&nbsp;&nbsp; \u003cstrong>重要性&nbsp;\u003c/strong>当你考虑了情境、时间、精力这三个条件后，最后你就要判断哪个行动选项会给你最高的回报了。现在，你有1个小时的时间，你坐在办公室里守着电话和电脑，你的精力指数为7.3（最高为10）。你应该做些什么呢？给客户回一个电话？考虑一下新的提案？处理一下语音信箱里的留言和电子邮件？或者联系一下你的配偶，看看她他这一天过得怎么样？\u003c/p>","explains":"\u003cp>拆页2介绍了GTD“四标准法”的具体用法，将从3个价值评估，1个场景分类，帮助我们更好地确定某个时间点的具体行动。\u003c/p>\u003cp>\u003cstrong>1）\u003c/strong>\u003cstrong>细化行动步骤\u003c/strong>\u003c/p>\u003cp>第一步，情境分类：确定事情是否需要在特点地点、特定工具下才能完成？\u003c/p>\u003cp>第二步，时间分配：你有多少时间？这件事又需要多少时间完成？\u003c/p>\u003cp>第三步，精力预估：简单预估下这件事所需要的精力，你拥有的精力，是否能有效处理任务？\u003c/p>\u003cp>第四步，重要性排序：按“最大回报”进行排序，确定要做的事。\u003c/p>\u003cp>而这个方法适用于执行事先安排好的任务，不太适用于处理紧急任务。\u003c/p>\u003cp>第五步，任务汇总：最终按时间顺序整理出各项任务。\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>）不那么做的坏处\u003c/strong>\u003cstrong>+\u003c/strong>\u003cstrong>预防异议\u003c/strong>\u003c/p>\u003cp>&nbsp;那我要是不那么做又会怎样呢？碎片化时间，大部分人会出于本能地下意识掏起手机刷朋友圈、看剧、浏览新闻、玩会游戏，发呆等。不仅消耗精力，还可能为此付出更多的时间用来维持娱乐状态，陷入低效状态。而上进的那一部分人，又会抱怨自己今天一事无成。最怕你很想努力，却一直处于低效的状态不能自拔。去年国庆去上海拜访一位前辈，也是我第一次外出拜访网友，当时我提前20分钟到了约定的咖啡厅，闲着无聊一会刷手机，一会瞅瞅室内环境。结果见面的第一眼，没说出话来，很尴尬地请他坐下，给他点了份咖啡缓解尴尬。如果我当时能够充分利用那20分钟时间，组织语言想下自我介绍，以及请教的内容，以及这次见面后的祝福语等，那一定会给朋友留下一个更加深刻的记忆，大家都会更期待下次见面。\u003c/p>\u003cp>&nbsp;这时有伙伴可能不高兴了，我好不容易有那么一会时间休息，还要考虑怎么加以利用时间做事，岂不是很烦。当然了，你有权给自己好好放松下。但你要是想提高自己，充分利用碎片化时间将更好地帮助你成长。\u003c/p>\u003cp>&nbsp; &nbsp;其中，针对一段比较长的时间，可做两件事以上的，按四标准法最终确定好的事情做个汇总，如果在较短的时间内决定做一件事情，直接去做就好。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>）举个例子\u003c/strong>\u003c/p>\u003cp>举个例子。刚才坐车过来的路上，我有50分钟的空闲时间。想了下，可以做这三件事：回复“滼音基金”客户提出的股票问题，写一篇300-400字的毕设周志，在滴答清单上列出下周的任务清单。\u003c/p>\u003cp>\u003cstrong>一、\u003c/strong>\u003cstrong>情景分类：\u003c/strong>情境所限，这些事正好也只能用手机来做。毕设周志需要在电脑上提交，只好用手机备忘录里头打个稿，提交的时候复制过去就行。\u003c/p>\u003cp>\u003cstrong>二、\u003c/strong>\u003cstrong>时间分配：\u003c/strong>回复客户问题大约要5-7分钟，毕设周志大约要花20分钟，列任务清单大约花15分钟。\u003c/p>\u003cp>\u003cstrong>三、\u003c/strong>\u003cstrong>精力预估：\u003c/strong>中午睡过觉，精力都允许，没啥问题。\u003c/p>\u003cp>\u003cstrong>四、\u003c/strong>\u003cstrong>重要性排序：\u003c/strong>回复客户消息最重要；周志排在第二，截止时间在周日；罗列下周的任务清单的截止时间在周日，所以排在第三。\u003c/p>\u003cp>\u003cstrong>五、 \u003c/strong>\u003cstrong>任务汇总：\u003c/strong> \u003c/p>\u003cp>最后确定下来的执行顺序是这样的：\u003c/p>\u003cp>（1）&nbsp;&nbsp; 首先，在微信上，用5-7分钟时间回复客户问题；\u003c/p>\u003cp>（2）&nbsp;&nbsp; 之后，在备忘录里，用20分钟撰写300-400字的毕设周志；\u003c/p>\u003cp>（3）&nbsp;&nbsp; 最后，在滴答清单里，用15分钟的时间罗列下周计划。\u003c/p>","interaction":"\u003cp>拆页\u003cstrong>2 - A3&nbsp;\u003c/strong>促动参与\u003c/p>\u003cp>（A3角色扮演）\u003c/p>\u003cp>下面大家两人1小组，加工出一个剧本。一人是万爸爸，GTD学习者；一人是女儿玲玲，高三学生。暑假准备外出参观高校，在地铁站等车，正好有1个半小时的空闲时间，附近有商场和书店。而万老师刚学习完GTD的“确定某一时刻的“四标准法””，又会如何引导孩子充分利用这段空闲时间呢？\u003c/p>\u003cp>&nbsp;&nbsp;其中，玲玲爸爸的扮演者必须运用到今天所学的四标准法，细化的五步骤：情景分类、时间分配、精力预估、重要性排序、任务汇总，来引导玲玲进行思考，产生行动。讨论和编写剧本的时间为5分钟，5分钟后我们会请1-2个小组进行角色扮演展示。好，下面大家开始。\u003c/p>\u003cp>&nbsp;学习者分享：\u003c/p>\u003cp>（灿阳扮演爸爸，小青扮演女儿玲玲）\u003c/p>\u003cp>爸爸：玲玲你看我们现在还有一个半小时才开始发车，你有没有想要在附近逛一逛啊，或者这段时间找点事做。\u003c/p>\u003cp>玲玲：那我们做些什么合适呢？\u003c/p>\u003cp>爸爸：行，你看咱这现在有商场和书店，然后呢，我们有一个半小时的空闲时间，你看有没有需要买些什么东西？比如买水啊，上趟洗手间啊，或者其他想做的事情呢？你看，你也快高三了，我们要去高效参观旅行，需不需要先去书店看些跟高校相关的书，对高校提前做个了解，行程更有目标。\u003c/p>\u003cp>玲玲：行。我们具体要买的水啊，路上要买的东西啊，我们可以在去书店回来的路上花20分钟买了。到了书店差不多有1小时的时间，我们可以看半个小时的书。然后多留出10分钟的时间，上个洗手间的什么。\u003c/p>\u003cp>爸爸：整个精力状态怎么样？\u003c/p>\u003cp>玲玲：还挺不错，可以在书店休息调整下。\u003c/p>\u003cp>爸爸：行，那就这么办吧？\u003c/p>\u003cp>\u003cstrong>引导者反馈：那最后，你们是决定怎么做的？（任务汇总）\u003c/strong>\u003c/p>\u003cp>爸爸：我们最后确定下来是这样的。先去书店花半小时左右的时间，了解下附近高校，回来的路上大约花20分钟去商场买水、洗漱用品、零食，最后预留20分钟左右的时间回来，以及上个洗手间什么的。\u003c/p>\u003cp>\u003cstrong>引导者反馈：\u003c/strong>感谢灿阳和小青带给我们的分享，从讨论的内容看得出来两位非常的细心，运用刚才所学的GTD四标准法，做到合理利用碎片化时间。\u003c/p>\u003cp>\u003cstrong>（A2分步催化1）\u003c/strong>\u003c/p>\u003cp>现在请大家仔细想下，未来一周内，你是否会有一段碎片化时间，有可能是，食堂排队吃饭的10分钟，接送小孩的等待20多分钟，上班等公交的20多分钟等。并在小组内交流分享。\u003c/p>\u003cp>\u003cstrong>小青\u003c/strong>\u003cstrong>——\u003c/strong>\u003cstrong>学习者分享：\u003c/strong>\u003c/p>\u003cp>每次过来拆书的路上，会有一段碎片化的时间。（\u003cstrong>引导者：\u003c/strong>小青姐，时间是\u003cstrong>下一周哦\u003c/strong>。你说的是下周五过来拆书的路上会有一段碎片化时间吗？）\u003c/p>\u003cp>对的对的，下周五过来参加拆书的路上我会有大约20分钟的空挡时间。\u003c/p>\u003cp>\u003cstrong>引导者：\u003c/strong>感谢小青的分享！\u003c/p>\u003cp>\u003cstrong>（A2分步催化2）\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp;好，下面大家运用今晚拆页2所学的GTD“四标准法”，确定下周五18:00过来拆书的路上，这20-30分钟，你真正能做的事，要求具体到看一眼就能执行。给大家3分钟的思考时间，并在小组内交流分享。\u003c/p>\u003cp>\u003cstrong>常乐\u003c/strong>\u003cstrong>——\u003c/strong>\u003cstrong>学习者分享：\u003c/strong>\u003c/p>\u003cp>&nbsp; 我这个碎片化的时间一般在送孩子上辅导班。\u003c/p>\u003cp>&nbsp; 下周五下午，17:00-18:40孩子要上围棋班。一般都会提前10分钟送孩子到学校，有2个小时的碎片时间，直接回家这个时间在路上花的也不值当，只能在外头溜达。所以我自己能想到有这4件事情可以做：\u003c/p>\u003cp>1．罗列在纸上：去附近石简书店看会书，去丛台公园健走，回复微信消息，听音频课；\u003c/p>\u003cp>2．场景分类：音频课在家里头学习比较合适。\u003c/p>\u003cp>3．重要性排序：只是充分利用，并没有什么特别重要的。\u003c/p>\u003cp>4．精力和时间预估：\u003c/p>\u003cp>如果说下周五我出去玩了比较累，就不去丛台公园健走了，1小时去石简书店看书，10-20分钟刷手机，回复消息，以免错过开家长会什么的消息；如果精力允许的话，我会去丛台公园健走30分钟，回来还会剩一些时间，用来回复消息。大体就是这样。\u003c/p>\u003cp>1.总得来说：\u003c/p>\u003cp>下周五精力允许，去丛台公园健走，后回复微信消息；身体状态不佳，则去石简书店看书放松会，之后用10-20分钟的时间来浏览、回复微信消息。\u003c/p>\u003cp>\u003cstrong>引导者：\u003c/strong>说的很棒，感谢常乐姐带来的分享。（掌声）不得不称赞她快速的学习能力和严谨的逻辑，都是值得我们学习的。\u003c/p>\u003cp>\u003cstrong>结语：\u003c/strong>\u003c/p>\u003cp>那么，最后，我们来回顾总结下：\u003cstrong> \u003c/strong>\u003c/p>\u003cp>一开始，我们将大脑中所有吸引你注意的事项和想法进行了一个大扫除，释放压力，重新梳理它们的意义，罗列任务计划。后面我们又学习了GTD的“四标准法”，根据场景、时间、精力及重要性及汇总，来确定某一时刻的下一步行动。希望我今晚的学习分享，能够帮助到大家。\u003c/p>\u003cp>&nbsp;&nbsp; 好，我今晚的分享到此结束，感谢大家的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1557723142000,"updated_at":1558443137000,"ria":true},{"id":7866,"topic":"用超前的规划代替超前的焦虑","learn_goal":"学习者学完之后，可以用用超前的规划代替超前的焦虑","remark":"","level":"TF3-3","duration":30,"status":29,"type":0,"chaishujia":{"username":"徐雪艳","city":"厦门"},"club":{"name":"厦门鹭岛抚琴分舵","city":"厦门"},"prologue":"\u003cp>大家好，我是徐雪艳，我是一名电商网站产品经理，但是在这里，我是一名拆书家，二级拆书家。我是在2017年3月5日加入拆书帮的，我今天还带来了我的拜师协议，上面有东哥的签名。到现在为止，我已经在拆书帮781天，感谢东哥一路走来的陪伴和指导，也感谢所有小伙伴的陪伴和见证，在拆书帮我成长了很多。\u003cbr>\u003c/p>\u003cp>回到今天拆书主题，今天我要拆的书是《搞定1》，我将跟大家一起学习这本书里的两个片断，大约需要一个小时的时间。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":11392,"quote":"\u003cp>\u003cstrong>【学习主题】\u003c/strong>\u003c/p>\u003cp>用超前的规划代替超前的焦虑\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>片断1学习目标：在跟随我完成本次的RIA现场学习后，学习者能够用收集－整理－记录的三步法（澄清），制定（行为）待办清单（界定），处理大脑应对太多待办事情而导致焦虑的问题。\u003c/p>\u003cp>片断2学习目标：在跟随我完成本次的RIA现场学习后，学习者能够用定时定点回顾的方式（澄清）提升（行为）清单的有效性（界定），缓解工作和生活的压力。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>【事件】我想，在座的应该会同意我们处于一个信息量和工作量剧增的时代。我们这一代人的工作方式跟我们的父辈们有着巨大的不同。60后的父辈们只要到达工作场所，完成那些显而易见的工作即可，工作都是一目了然。而对于我们80后90后来说，每天面对的工作场景是塞满邮件的电子邮箱，模棱两可的领导指示，随时可能接到的突发任务，让你无处藏身的微信和电话，不是有这样的段子吗，说新浪的程序员在婚礼现场都被领导抓去处理问题。\u003c/p>\u003cp>【提问】面对这巨大和无法预测的压力，你是如何应对的呢？是从容规划，一切按你自己的安排有节奏地推进？还是天天忙得像热锅上的蚂蚁内心还是充满着焦虑？\u003c/p>\u003cp>【影响】如果是觉得无序和忙乱，那我们就可能失去重心和焦点，无法清晰地为自己规划工作和生活，将不可避免陷入低效和心乱如麻的泥沼，结果是要么你工作不见成效，你自己不满意，领导也不满意，要么就是工作压力越来越大，工作和生活很难平衡。\u003c/p>\u003cp>【解决】庆幸的是，已经有管理大师给我们提供了应对压力的工具。《搞定》系列书籍就提供了这样的工具。《搞定》是美国著名作家戴维艾伦的经典著作。只要谈到时间管理，个人自我管理，很多人都会推荐《搞定》系列。《搞定1》已经在全世界33个国家出版，因为这部著作，戴维艾伦被誉为世界顶级效率思想家。《搞定》系列总共有三本书，《搞定1》，也就是我今天要拆的片段来源，是最经典的一本，很多人说读了第一本就可以了解搞定的精髓，确实，这本书里提供了实用的操作指南，教你如何释放你的大脑空间做到心静如水，如何把待办事项整理成行动清单，如何回顾，如何行动，做到无压工作。\u003c/p>\u003cp>今天我从书里节选了两个片断，我们一起来学习如何做到心静如水，如何把需要做的事情转换成切实可行的行动清单从而帮助我们尽可能完成该完成的事情，做一个能够管理焦虑的人。\u003c/p>\u003cp>【A1】正式开始今天的分享之前，我先请大家做一个简单的测试，大家可以借此机会了解一下自己的个人事务处理效率。\u003c/p>\u003cp>请大家仔细阅读表格中描述的每一句话，并与自己平时的做法进行对照，然后给自己打分，1分代表完全不符合，6分代表非常符合，凭直觉回答就可以了，没有对错，只是为了让你了解一下你自己的情况。\u003c/p>\u003cp>\u003cstrong>【自测量表】\u003c/strong>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>问题&nbsp;\\&nbsp;得分\u003c/p>\u003c/td>\u003ctd>\u003cp>1&nbsp;完全不符合\u003c/p>\u003c/td>\u003ctd>\u003cp>2&nbsp;基本不符合\u003c/p>\u003c/td>\u003ctd>\u003cp>3&nbsp;偶尔不符合\u003c/p>\u003c/td>\u003ctd>\u003cp>4&nbsp;有时候符合\u003c/p>\u003c/td>\u003ctd>\u003cp>5&nbsp;基本符合\u003c/p>\u003c/td>\u003ctd>\u003cp>6非常符合\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1.&nbsp;每隔一段时间我就会好好梳理一下我在工作以及家庭中的角色和职责\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.&nbsp;每一天开始我都非常清楚我这一天该完成什么事情\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.&nbsp;每当我注意到有一件事情需要我去处理时我喜欢把它记在某个地方而不是记在脑子里\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4.&nbsp;只要是我觉得需要做的事情我一定能够按时完成\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5.&nbsp;处理问题时我总是会先设想一下这个问题解决好了理想状态是什么，然后再去设想有哪些行动可以达到这个理想状态\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>6.&nbsp;我非常受不了开会聊半天结束时没有明确的行动项和负责人\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>7.&nbsp;每隔一段时间我就会回顾一下我之前的计划和实现的结果\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>【I】大家可以计算下，你们所获得的总分。\u003c/p>\u003cp>如果你总分在35以上，说明你很擅长自我管理，是一个效率达人\u003c/p>\u003cp>如果是21—35，也挺不错的，有潜力成为效率达人\u003c/p>\u003cp>如果是21分以下，你可能是一个比较随性的人，但难免在事情多的时候陷入慌乱，需要学习和实践一些提升自我管理的技巧，今天我带来的学习片段对你会有帮助。\u003c/p>\u003cp>接下来请先阅读第一个片段，读完的小伙伴请举手或者眼神示意我一下。\u003c/p>\u003cp>\u003cstrong>【学习目标1】\u003c/strong>\u003c/p>\u003cp>片断1学习目标：在跟随我完成本次的RIA现场学习后，学习者能够用收集－整理－记录的三步法（澄清），制定（行为）待办清单（界定），处理大脑应对太多待办事情而导致焦虑的问题。\u003c/p>\u003cp>\u003cstrong>【片断一】\u003c/strong>\u003c/p>\u003cp>《搞定I》P22-23\u003c/p>\u003cp>\u003cstrong>为什么有些事情总是萦绕在你的心头\u003c/strong>\u003c/p>\u003cp>在通常情况下，你对一些事情总是念念不忘，这是因为你希望它们的状况能有所改善，另外：\u003c/p>\u003cul>\u003cli>\u003cp>你还没有明确地认定它们的预期结果是什么。\u003c/p>\u003c/li>\u003cli>\u003cp>你还没有确定你下一步的具体行动到底是什么。\u003c/p>\u003c/li>\u003cli>\u003cp>你还没有把关于预期结果和即将采取行动的提示信息存入你所依赖的系统中去。\u003c/p>\u003c/li>\u003c/ul>\u003cp>这就是为什么你忘不掉这些事情的原因了。直到你澄清了所有问题，做出一切必要的决定，并把预期结果保存到那个系统中去，(同时要确保你能在必要情况下随时访问和查询这个系统)，你的大脑才会放松下来。你可以骗过别人，但是你却无法愚弄自己的大脑。它能够明察秋毫：你是否已经做出了必要的决定，是否已经把有关预期结果和行动的提示信息寄存于一个安全可靠的地方，以便这些信息能在恰当的时候提醒你采取行动。如果你没有做好这些工作，那么，你的大脑就一分钟也不会停止运转。通常情况下，当你对某件事还没有依照上述的处理方法处理时，你的某根神经仍然会持续不断地对你施加压力，这只会增加你的精神负担。\u003c/p>","explains":"\u003cp>【What】在这个片段作者解释了为什么有些时候，甚至是很多时候，我们的脑子会不得安宁，心里总觉得还有非常非常多事情需要去做，心乱如麻。作者说，会出现这种状况是因为我们给大脑大多负担了。\u003c/p>\u003cp>【Why】虽然超强大脑是存在的，但是，对于普通人来说，盘踞在你脑子里问题的数量和处理问题的效率是成反比的，也就是说，你脑子里要记越多事情，你处理问题的效率就越低。所以，作者主张，提升效率的一个重要技巧就是把一切事务赶出大脑。\u003c/p>\u003cp>【概念讲解 &amp; 互动】没错，清空大脑内存，做到心静如水，这是《搞定》这本书的两个重要思想之一。那什么是“清空大脑内存”呢？\u003c/p>\u003cp>拆书家 【概念反讲1】：举个例子，我今天觉得非常累，什么事都不想去想，在家睡大觉，这是清空大脑内存吗？\u003c/p>\u003cp>饭团老师：这只是暂时的\u003c/p>\u003cp>佳山：它在梦里\u003c/p>\u003cp>拆书家：哈哈，对，在梦里，一觉醒来还是要面对现实，只是暂时逃避。相反，真正要清空大脑是需要拿出勇气，大胆面对一切困扰你的事情，全部搜集出来，不管事情大小，也不论轻重缓急，这一步在书里，叫做“收集”。\u003c/p>\u003cp>拆书家 【概念反讲2】：再举个例子，年底好多事情好忙啊，总觉得事情还有很多，我现在拿出勇气坐下来好好地想，长长的一个清单，做业绩报告，准备2019年计划，给部门员工做业绩考核，和总部老板开会，给孩子买过年新衣服，带父母体检，准备日本旅游，等等等等，把要做的事情都抓出来了，就能心如止水了吗？\u003c/p>\u003cp>佳山：会吧\u003c/p>\u003cp>拆书家：事情有没有进展了呢？\u003c/p>\u003cp>饭团老师：只是把事情列出来而已，没有推进\u003c/p>\u003cp>拆书家：是的，迈出了勇敢的一步，收集出了很多待办事项，但这只是一个愿望清单。很多人这么做了，会发现事情并没有进展，内心还是很不淡定。只有感觉掌控一切的时候才会心如止水。而掌控一切是要知道自己要做的事情是什么，要做成什么样，怎么做到，在心里盘算清楚，才能运筹帷幄。回到我的清单例子，我需要针对每一项待办明确目标和行动计划，才能放心。比如，给孩子买过年的新衣服，我需要明确目标是买新衣服，还要想一想行动计划，比如，我需要：1. 看一下日历找出我什么时候有时间去逛商场 2.确定去哪里买 3.列一下具体需要买什么，外套，毛衣，鞋子等，这样我才能心里有底。所以单纯的列愿望清单并不一定能清空大脑，甚至有时反而会徒增焦虑，而列出可以计划、有进展的、可以自己掌控的清单，才有助于心如止水。这一步在书里叫做理清和整理，简单叫整理。\u003c/p>\u003cp>拆书家【概念反讲3】：收集了待办事项，有了行动计划，全在脑子里过了一遍也都记在脑子里了，这下总该清爽了吧？是不是“心如止水”了呢？\u003c/p>\u003cp>佳山：可能会有一些新事情加进来\u003c/p>\u003cp>拆书家：嗯，可能会有意外\u003c/p>\u003cp>悠悠：可能会忘记掉，得设置一些时间点提醒自己要去做\u003c/p>\u003cp>拆书家： 嗯，是的，有那么多事情，我们是都要记在脑了里吗？如果我的脑子还是需要记住这所有事情和计划，那还是负担很重，还是会担心漏做了什么事情。所以，需要找一个外部系统记录，也就是找一个靠谱的外脑帮忙，这样，你就真的可以不再去想这事了，只需要在想知道自己现在该做什么的时候去查看这个记录系统。至于这个系统是什么，因人而异了，用着顺手就好，可以是笔记本手写，可以是各种APP， 随便搜一下GTD APP就能找到很多，APP篇不在我们今天讨论范围，有兴趣的小伙伴我们可以线下交流。这里我要强调一下，把清单记录在外部系统，有助于将大脑暂时清空，减轻负担，让我们安心专注于处理当下的事务，一次只做一件事情。这个外部系统相当于大脑的延伸，让我们可以在专注当前事情与掌控全局之间从容切换，无需时刻记挂着所有事情。这一步在书里叫做记录。\u003c/p>\u003cp>【HOW】总结一下，如何清空大脑内存，达到“心静如水”：\u003c/p>\u003cp>1，收集， 需要直面焦虑，冷静地把自己脑子里想到的所有事情都记录下来，不管事情大小，也不管轻重缓急\u003c/p>\u003cp>2，整理， 整理出每件事情要达到的效果，做好行动计划，整理的结果是一个具体的行动清单\u003c/p>\u003cp>3，记录，把行动清单记录在外部系统，解放大脑，这个系统应该方便你自己随时查询，也能在适当的时候提醒你该做什么事\u003c/p>\u003cp>有了收集－整理－记录这三步准备工作，就可以按行动清单一项一项行动了。\u003c/p>\u003cp>【适用边界】这个方法只适用于工作吗？其实不是，工作生活都可以。它甚至不止适用于成年人，小孩也一样。凡是需要专注在当前事情上的时候，任何人任何时候都可以通过清空大脑的方法来提升效率。在我身上发生了一件事我觉得很有意思。我儿子6岁，我从他五岁开始就想让他去学钢琴，但是他去试了几次觉得太难了，不肯去，我也没逼他。今年6岁，我又引导他去试。这次他觉得好一些，决定继续试几次课。可是上了几次之后他又说太难了，不学了。我觉得很奇怪，才学几个音，怎么会太难。我用尽办法骗他继续。有一天他很激动地跟我说，今天老师考我，随便考我都记住了。他很激动，我也很开心，赶紧给他鼓励说，你看，坚持学习就能进步。可是他说，你知道为什么吗，因为我今天把脑子里的英语全都忘记了，只想钢琴的事情，所以我就记得清楚了。我故做惊讶，我说，那你把英语都忘了怎么办，下次学英语的时候你又觉得难了。他说，不会，下次上英语课我再把钢琴都忘了。多么神奇啊，这个清空大脑的做法对小孩适用，这是他教我，我并没有给他讲过《搞定》这本书。所以我更加坚信，专注是需要心无旁骛。小孩子的世界很简单，而我们成人要处理的事情多得多，不可能说忘就敢忘，我们忘的方式需要靠谱一点，需要通过收集－整理－记录的方式，放在一个你暂时不需要去担心的地方，就能忘。\u003c/p>\u003cp>【异议预防】收集－整理－记录这个方法听起来有些机械有些麻烦，但其实越忙的人越需要一个科学的个人事务管理办法，它可以让我们一次只专注于做一件事情。不忙，不在乎时间管理的人就可以随性。不过，这三步只是帮助你清空大脑，如果是为了达到无忧工作和生活，这本书里还有介绍后续的行动和回顾环节。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3&nbsp;促动参与】\u003c/strong>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>刚才我们学习了收集－整理－记录的方法，帮助我们列出了行动清单，让大脑和内心重归平静。请小伙伴回想一下，你们曾经遇到焦虑的时候，是否有尝试过类似的方法，列过清单呢？现在我们来分组讨论一下，两两一组，一起花3分钟时间讨论一下自己列过的一个清单，把你的这个清单写下来，在小组内分享下你列的这个清单效果怎么样，有没有碰到什么问题。如果你没有列过清单，就讨论一下你是不是听说过列清单搞定的方法，你没有选择用列清单的方法是不是遇到了什么困难。一会儿我请小伙伴给大家分享一下讨论的情况。\u003c/p>\u003cp>看来大家对于清单都有一些感受，谁愿意分享一下用清单提升效率中遇到过什么问题？\u003c/p>\u003cp>【1 学习者提出问题&amp;拆书家提问式反馈明确问题】\u003c/p>\u003cp>问： 志文，你碰到过什么样的问题吗？\u003c/p>\u003cp>答：我其实工作中经常要用到清单，因为工作中需要和别的同事配合很多，必须一项一项列出来。我碰到的问题有两个，一是推进过程中没有去看清单，到最后去看的时候才发现清单里的项目并没有完成。另一个是清单列的不够详细，考虑不够周全，做的时候才发现这也没有列出来那也没有列出来。\u003c/p>\u003cp>问：志文提到两个问题，一个是清单执行不完，另一个是清单列的不够细，没有考虑对别人的依赖。大家有同样的问题吗？\u003c/p>\u003cp>答：有\u003c/p>\u003cp>问：哪一个问题更常出现？\u003c/p>\u003cp>答：执行不完，达不到效果\u003cbr>\u003c/p>\u003cp>【明确问题】好，由于时间关系，我们今天没办法讨论所有问题，那接下来我们集中来讨论一下“清单执行不完，达不到效果”这个问题。\u003cbr>\u003c/p>\u003cp>【2 分组讨论问题本质】\u003c/p>\u003cp>既然大家都觉得这是一个比较普遍的问题，我们进一步讨论一下这个问题的本质原因是什么。解释一下，什么叫问题的本质，它是问题存在的最关键原因，找到了问题的本质，离找到解决办法就不远了。请继续在刚才的小组内讨论“清单执行不完，达不到效果”这个问题的本质是什么。大家可以想想我刚才讲的“心静如水”的概念和步骤，使用一些追问工具来找到本质，比如，五问法，鱼骨法等。我给大家发便签，可以边讨论边在便签上写下来。时间是5分钟，看大家能讨论到什么程度。\u003c/p>\u003cp>【3 明确问题本质】\u003c/p>\u003cp>现场小组讨论的过程\u003c/p>\u003cp>可能的原因1：清单整理得不够细该做的没在清单上\u003c/p>\u003cp>可能的原因2：突发事件打断清单的执行（执行力不够）\u003c/p>\u003cp>可能的原因3：清单列得太多没有重点没有按优先级去排列被清单吓到无法按清单去执行\u003c/p>\u003cp>（提问）最后结论呢？请小组说一下你们的结论\u003c/p>\u003cp>小组分享：我们最后大家觉得，是“清单列得太多失去重心导致清单失去效用”是问题的本质。\u003c/p>\u003cp>【4 分组讨论解决方案】\u003c/p>\u003cp>好，大家认同吗？有没有要补充的呢？（学员表示暂时没有补充）\u003c/p>\u003cp>好，现在我们已经讨论出了问题的本质，那么怎么解决这个问题让清单重返效用呢？请大家继续在小组内讨论该问题的解决方案（讨论目标），讨论结果可以写在便签上，5分钟后请伙伴们进行分享。\u003c/p>\u003cp>【5 学员分享解决方案】\u003c/p>\u003cp>为了每个小组都有展示的机会，我请每个小组轮流分享，每个小组都来说说你们讨论的结果。下面请大家说，我在白板上写。\u003c/p>\u003cp>1. 排优先级别\u003c/p>\u003cp>2. 清单中，列出今天必须做的事\u003c/p>\u003cp>3. 每次只做一件事，做完才做下一件事\u003c/p>\u003cp>4. 大清单小清单 – 用一个清单库收集所有待办，没有优先级排序，另外再准备一个今日待做，今天待沟通，今天待检核，今日最重要的三件事\u003c/p>\u003cp>5. 找一个好工具- 固定用一个触手可及的工具记录清单\u003cbr>\u003c/p>\u003cp>【拆书家总结】\u003c/p>\u003cp>太棒了，这是我们集体的智慧，讨论出了“清单列太多导致失去重心，清单失去效用”这个问题的解决方案，我总结一下：\u003c/p>\u003cp>1.大清单 - 用大清单收集所有待办事项，避免忘记该做的事情\u003c/p>\u003cp>2.小清单 - 从大清单中挑出今日待办，可以为今日待办分类，比如：今日待做，今日待沟通，今日待查，今日最重要的三件事\u003c/p>\u003cp>3.专注 - 每次只做一件事，做完一件事再去做下一件事，突发事件尽量先放进待办清单\u003c/p>\u003cp>4.工具 - 找一个好工具管理清单\u003cbr>\u003c/p>\u003cp>【适用边界】既然我们都有出现过不再相信清单的情况，下次碰到这个问题时，就可以用这些方法恢复对清单的信心，使工作生活重归高效。\u003c/p>\u003cp>【A2】布置任务&nbsp;\u003c/p>\u003cp>这么棒的群体智慧，我希望大家回去后可以应用一下，请在接下去的一周内，在你碰到心乱如麻感觉心里有很多事情需要做感觉焦虑时，如果你没有用过清单就请尝试用收集-整理-记录的方法建立一个清单，如果你已经建立了清单，就用我们讨论的提升清单效力的方法改善清单。欢迎小伙伴把你们应用的情况通过微信发给我。【特定任务的A2】\u003cbr>\u003c/p>\u003cp>【学员案例-任务完成情况收集】\u003c/p>\u003cp>志文的反馈：\u003c/p>\u003cp>我平时会使用清单帮助自己完成工作，但是经常觉得清单上的事情没能按计划完成。这一周来我尝试用大清单－小清单－一次只做一件事情的方法帮助自己提升效率。\u003c/p>\u003cp>1. 周一开例会，我在例会中用本子记录其他团队或者其他同事希望我提供给他们的支持，或者共同配合要推进的事情。（收集- 大清单）\u003c/p>\u003cp>2. 开完例会后，我把细节留在本子上，把归类按优先级整理后的大目标放进一周工作计划，只有二到三项，最多不会超过五项；并且给每个计划制定输出目标，这样才能衡量任务的完成度。（整理 - 小清单）\u003c/p>\u003cp>3. 我把一周的工作计划用邮件发给各相关同事负责人，这样他们可以了解我们安排，和他们相关的事情是否在我的工作计划中体现。（记录和透明）\u003c/p>\u003cp>4. 每天上班前头一件事，是列出我当日的工作清单，其中贯穿期间的是周计划中的工作。另外每天会有一些突发工作，我也会记录在列表中，同样每天项目通常是三项，最多也不超过五项。这时会根据优先级和时间约定，给任务划分先后。然后一件一件开始完成，完成后会在清单上划除。每天结束会核对清单看是否有遗漏，或者没有完成需要转移到第二天的任务。（小清单-专注）\u003c/p>\u003cp>5. 当某个任务比较复杂时，如改造某个模块，我会给自己安排一个改造步骤，如第一步跟换变量，第二步改造线程，第三步扩展等等。（整理）\u003c/p>\u003cp>【拆收家点评】志文很好地应用了提升清单效力的方法，帮助自己完成清单上的事情，从他的工作习惯中可以看出他收集-整理-记录清单的使用场景和方法。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}},{"id":11393,"quote":"\u003cp>【引入第二个片断】\u003c/p>\u003cp>刚才我们学习了收集-整理-记录的方法，帮助我们列出行动清单，让大脑和内心重归平静。我们也谈了这个方法中会碰到的问题，清单用着用着就不能信了，因为列太多，失去了重心，也可能要做的事情却没有在清单上。我们一起找到了解决办法，更好地让清单帮助我们提升效率。其实，为了让清单更有效，刚才志文也提到，要经常回顾清单。既然让大脑100%投入当前的工作才能充分发挥大脑的作用，那我们就需要保持待办事项清单是完整有效的，这样大脑就不用回归去记忆那些你没有记录下来的事项，也才能对着清单一项一项去执行，否则我们就会不相信清单，把清单放在一边。而要做到这个，就需要经常回顾清单。接下来我就跟大家讲讲“回顾”这个环节。\u003c/p>\u003cp>请阅读第二个片断，这个片断我们要学习如何“回顾”。\u003c/p>\u003cp>【片断二】\u003c/p>\u003cp>片断2学习目标：在跟随我完成本次的RIA现场学习后，学习者能够用定时定点回顾的方式（澄清）提升（行为）清单的有效性（界定），缓解工作和生活的压力。\u003c/p>\u003cp>\u003cstrong>【阅读原文】\u003c/strong>\u003c/p>\u003cp>《搞定I》267-268\u003c/p>\u003cp>\u003cstrong>回顾阶段：保障系统的有效运行\u003c/strong>\u003c/p>\u003cp>实行这套工作流程管理方法的目的，并不是让你的大脑偷懒，而是想尽办法充分利用大脑的资源，并让它工作得更加优雅、更有效率、更具创造性。只有在大脑100%投入到当前的工作中时，才能达到这一目的。为了做到这点，你必须确信你正在做的事情是确实需要完成的，而其他没有进行的工作确实可以暂时“不去进行”。这能改善现有条件，使你始终保持最佳行动状态。定期回顾你的系统，反思其内容，保持其时效功能，这是实现系统清晰度和稳定性的前提。\u003c/p>\u003cp>例如你有一个电话清单，但是如果有一些你必须要打的电话却没有被列在这个清单上，你的大脑就不会再相信这个电话清单，从而导致你的大脑在完成这个低脑力要求的活动时也无法感到轻松。结果，你的大脑又不得不重新担负起记忆、加工处理和提醒的责任，从而又像以前一样低效运转。\u003c/p>\u003cp>所有这一切意味着，你的系统不可能处于静止不动的状态。这个系统必须实时更新，紧跟事态的发展，这样才能帮助你在行动的时候做出恰当的选择，这也正是回顾过程的主要目的。同时，回顾过程还可以从不同角度对你的生活与工作进行持续不断的评估。\u003cbr>\u003c/p>","explains":"\u003cp>【What】这个片断讲的是“回顾”行动清单。收集-整理-记录-行动-回顾，这是“搞定”这个系统工作方法的一个闭环，有了回顾，才能使你的待办清单内容可靠，才能持续解放大脑去记忆待办事项的负担，因此提升大脑专注投入当前工作的效率。\u003c/p>\u003cp>【互动 － 拆书家】回顾，更口语化的说法，就是检查自己的清单，让它成为你可以依赖的工具。那小伙伴觉得检查自己的清单要做什么呢？\u003c/p>\u003cp>【小伙伴】看这件事情有没有做完，把原来列的清单找出来对一下\u003c/p>\u003cp>【拆书家】嗯，检查，看一下清单里的内容是否完成了。还有吗？\u003c/p>\u003cp>【小伙伴】更新\u003c/p>\u003cp>【拆书家】嗯，新的事情需要往里加。那多久需要检查一次呢\u003c/p>\u003cp>【小伙伴】完成一件事情就去对一次\u003c/p>\u003cp>【拆书家】嗯，可以的，其实，多久回顾一次因人而异，因事而异\u003c/p>\u003cp>【HOW】总结一下，回顾待办事项清单，你可以这么做：\u003c/p>\u003cp>1，\u003cstrong>定时定点\u003c/strong>- 你需要找一个合适的时间和地点来做回顾这件事情，比如你不会想在开车的时候回顾，因为回顾需要绝对的专注，并且可以操作你的清单。你可能会选择在一个密闭工作空间，避免有人打断。而时间呢，在新的一个星期开始或者结束的时候，或者每天工作开始或者结束的时候，都是适合回顾的时间。\u003c/p>\u003cp>2，\u003cstrong>做好回顾准备\u003c/strong> - 回顾需要完整，所以，确保你把所有的待办事项都摆出来，有些时候你可能随手把一个待办事项写在便利贴上还来不及放进待办清单，这个时候记得整理一下所有的便利贴。\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp; \u003cstrong>检视并更新你的清单 － 增删改\u003c/strong>\u003c/p>\u003cul>\u003cli>\u003cp>\u003cstrong>删 \u003c/strong>- 已完成的事项- 当发现有些事项已经完成，或者不再需要，去掉它，去掉已完成事项会增加成就感，而去掉不需要的事项可以保持清单的干净度，增强完成的信心\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>改 \u003c/strong>- 有变化的事项 - 如果有些待办事项有新的任务需要完成，修改它\u003c/p>\u003c/li>\u003cli>\u003cp>\u003cstrong>增 \u003c/strong>- 新增加的事项 - 用第一个片断的方法，整理新的待办事项并且记录，把新的待办事项加进行动清单\u003c/p>\u003c/li>\u003c/ul>\u003cp>小tip, 可以给自己固定回顾时间和地点，甚至时长，有助于形成回顾的习惯。\u003c/p>\u003cp>【举例说明】我是怎么做回顾清单这件事呢？我有每周和每天回顾工作清单的习惯，我的回顾时间是在新的一周开始的时候和每天工作开始的时候，并不是到办公室每一件事就是回顾，我会先浏览完邮箱里的邮件，看邮件的时候不马上回复，而只是flag一下需要有下一步行动。浏览完邮件后，我再开始回顾。我会在我自己的位子上，把手机关静音，屏幕朝下盖住，避免干扰。我主要是用日历记录固定时间需要做的事情，还用本子和excel分类列出需要我去做的事情。所以我会打开我的日历，本子和excel，扫一眼这周或者今天我在什么时间该去开什么会，然后，把我今天还需要做的事情写进excel，把已经完成的事情在excel里标注已完成，已经不需要做的事情删去，昨天到今天记在本子上的笔记也整理成待办事项放进excel里的清单列表，这样一天开始我才觉得踏实。这个回顾的时间不长，10-30分钟。\u003c/p>\u003cp>【适用边界】什么情况下你应该考虑回顾清单呢？只要你想通过清单提升工作效率，减轻焦虑感，希望通过GTD这一套方法来提升自己的时间管理方式，就应该保证自己的清单是更新的，就需要定期回顾，否则随着工作和生活要处理各类新事务、大脑容易陷入到忽视之前定的清单计划，导致清单失效。其实很多时候你觉得搞定这一套方法没有达到理想效果，问题就在于你的清单不够完整不够更新，而保证时间做回顾是一个解决办法。\u003cbr>\u003c/p>","interaction":"\u003cp>【A2 催化学习者应用】\u003cbr>\u003c/p>\u003cp>以上就是我对这个拆页的讲解。拆书法的精髓是拆为己用，了解了一个知识，要把它应用在自己的工作生活中。为了让大家在今后能更好的运用今天所学到的方法，重视回顾，我们先在今天的现场模拟应用一下。\u003c/p>\u003cp>请大家再回过头去看一下刚才学习第一个片断后你自己记录下来的清单，设想一下，为了让你在接下去一个月内或者更久的将来，你的这种清单更有效帮助你，你可以通过什么样的回顾计划来确保它的时效和完整？\u003c/p>\u003cp>这个环节，我请大家自己编一段小故事，几百字即可，这个故事需要有背景，任务、情节变化和角色对话、动作等。这个故事的背景可以是大家使用清单的场景，对话中体现今天学习的回顾方法，也就是，定期定点，做好回顾准备然后检视及更新清单，讲一讲你如何用回顾的方法提升清单的作用，帮助你更高效地工作和生活。我准备了一个小剧本模板，发在群里，大家可以参考一下，时间五分钟。五分钟后我们请一组伙伴来讲讲他们的剧本。\u003cbr>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>小剧本\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>项目\u003c/p>\u003c/td>\u003ctd>\u003cp>内容\u003c/p>\u003c/td>\u003ctd>\u003cp>备注\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>背景\u003c/p>\u003c/td>\u003ctd>\u003cp>佳山有列清单的习惯，但是主要用在工作中。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>事件内容\u003c/p>\u003c/td>\u003ctd>最近佳山出现了工作和生活压力都上升的情况，所以他就找学习过搞定方法的朋友吐槽一下，希望可以得到一些建议。\u003c/td>\u003ctd>\u003cp>介绍背景、时间、地点、人物关系、人物的内心想法、点睛评语等\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物角色\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A：佳山 （需要让清单更好地平衡工作生活）\u003c/p>\u003cp>角色B：悠悠 （为佳山提建议）\u003c/p>\u003c/td>\u003ctd>\u003cp>可为多人角色\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>对白\u003c/p>\u003c/td>\u003ctd>\u003cp>角色A：悠悠，最近好烦啊，工作压力大，家里又不理解，老婆总是报怨我陪她太少也不管孩子，我爸我妈又说我天天回家晚，跟他们沟通少，工作压力大，生活压力也大，白头发都出来了，再这样下去头发都快没了。\u003c/p>\u003cp>角色B：其实，你有列清单啊，把你作为各种角色该做的事情都列一列，工作的角色下需要做哪些事情，作为家里的一员该做哪些事情。你还可以定期回顾一下自己的清单看是不是重要的事情都去做了。\u003c/p>\u003cp>角色A：哦？怎么做回顾呢？\u003c/p>\u003cp>角色B：比如，你可以固定在晚上抽一些时间出来，回顾你当天做的事情，比如陪家人老婆孩子做了什么，陪了多少时间，如果你发现陪的时间太少，那你在第二天该做的事情清单里重点把这部分补上，作为优先要做的事情。这样的话就可以减少家人对你的抱怨，抱怨少了你就可以更好地专注在你的工作上，对工作的事项也按刚才说的回顾方法重新安排一下。\u003c/p>\u003cp>角色A：嗯，我觉得你这个办法挺好的，清单除了用在工作中，其实在生活和陪伴家人以及个人学习方面也可以用列清单的方式来操作，用回顾的方式去看哪一块做得比较不好，后面再加强这一块的投入，这样方方面面都可以照顾到\u003c/p>\u003cp>角色B：对的，可以试试\u003c/p>\u003c/td>\u003ctd>\u003cp>人物之间对话的具体内容\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>谢谢小伙伴的分享，故事很精彩哦，悠悠建议佳山清单不仅包含工作内容，还可以包含陪伴家人的部分，建议佳山每天晚上定时回顾一下自己的清单和当天做的事情，看看哪一部分花的时间偏少了就更新第二天的清单，优先加强，小伙伴很好地应用了今天学到的知识点，也希望佳山可以用清单减轻工作和生活的压力。\u003cbr>\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>《搞定》系列书籍非常经典，值得细细地反复去读。今天我只是分享书中的两个片断，也是我认为非常有意义的两个片断。首先，我们学习“收集-整理-记录“的方法，帮助我们把事情赶出大脑，转移到书面的行动清单上，做到心静如水，从而可以让大脑专注于当前的事情。然后，我们知道，清单需要定期回顾才能让它保持时效，让清单保持可靠，也就能让大脑保持专注。让我们用”搞定“的方法搞定我们的工作，生活和学习，下次，在你感觉焦虑的时候，想到”搞定“，把超前的焦虑变成超前的思考和规划，相信你可以做一个从容淡定的让自己满意的人！\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1557500926000,"updated_at":1557537262000,"ria":true},{"id":7528,"topic":"用清单记录和四标准法高效做事","learn_goal":"2-4过级","remark":"高效做事，妥善安排时间。","level":"TF2-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"薛锦聪","city":"邯郸"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>【开场】各位小伙伴们，大家晚上好！我是薛锦聪，矿院大四学生。我的三个标签是：GTD、写作、野生交易员。待会我们的活动需要分组，那我左边的（几个）为一组，右边的（几个）为一组。\r\n【总目标】通过本次学习，学习者能够将大脑中的想法和任务有序清空，罗列，确定某一时刻的具体行动。\r\n【分目标】拆页一的学习：学习者在面对一堆想法和任务时，能够及时清空大脑，罗列计划；拆页二的学习：学习者在一个空闲时间段或一个时间点，能够运用GTD“四标准法”确定某一时刻的具体行动，充分利用碎片时间。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>\u003cp>\u003cstrong>新技能：介绍图书FAB\u003c/strong>\u003c/p>\u003cp>今晚我要拆解的片段来自《搞定1》一书。\u003c/p>\u003cp>【F特征】《搞定1》是世界知名时间管理大师戴维-艾伦的经典著作，这本书介绍了全球千万人正在轻松使用的GTD（Getting Things Done）个人事务管理系统。\u003c/p>\u003cp>【A优势】于同类书籍相比，本书内容是David-Allen 30多年在个人和组织效率方面的研究汇总而成，既适用于工作，也是适用于生活。而且，市面上的大部分时间管理书籍脱胎于此，是首屈一指的时间管理书籍。\u003c/p>\u003cp>【B1利益】在这个充满变化需要不断学习新知才能紧随的时代，GTD将提供一个完善的系统，足够强硬的逻辑，来支持你进行行动决策。\u003c/p>\u003cp>【B2利益】通过今晚的学习，大家不仅能够有效清空大脑中的各种想法和任务，减轻大脑负担，专注于当下事务。还能够运用GTD“四标准法”，确定某一时刻的具体行动，充分利用碎片化时间。\u003c/p>","ratings_count":1,"texts":[{"id":11003,"quote":"\u003cp>刚才已把原文片段发下去了，下面请大家用2分钟时间阅读原文拆页片段。\u003c/p>\u003cp>\u003cstrong>原则：有效地处理内心的承诺\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;在数十年的培训工作中，我指导过数干人。在这个过程中，我发现了一个极为常见的现象，即由于人们对自己做出的承诺或者承担的义务管理不当，导致他们承受着重重压力的折磨。所以，学会对承诺事项加以控制，可以有效缓解压力。即使是那些并没有明显体验到压力的人，如果他们学会了更加有效地对生活中悬而未决的问题加以控制，那么在放松自我、集中精力、提高效率方面也会有明显的改善。\u003c/p>\u003cp>&nbsp;&nbsp;恐怕你已经与自己达成了许多协议（这一点也许你根本没有意识到）。而每一项协议，无论大小，都时时刻刻被你自身的无意识所紧密追随。这些就是“未完成的事情”或者“悬而未决的问题”。它们可能是“根除世界上的饥饿问题”这类重大事务，也可能是“雇用一个新助手”之类的一般性事件，或是“更换走廊灯泡”一类的琐碎小事。\u003c/p>\u003cp>&nbsp;&nbsp;为了能够高效应对这一问题，首先，你必须明确并收集所有那些“经常唤醒你模糊记忆”的事情，搞清它们对你而言的真正意义，然后决定如何推动它们。这看起来极为简单，但在实际操作中，大多数人都难以始终如一地坚持下去。他们缺乏认识或动力，而最可能的原因是，他们没有意识到忽略这种做法将会付出的代价。\u003c/p>","explains":"\u003cp>\u003cstrong>新技能：【I】拆书家讲解引导之细化行动步骤\u003c/strong>\u003c/p>\u003cp>在工作或生活当中，大家遇到过这种情况不？你会经常用大脑记忆某种任务或想法，通过不断地记忆来想起这件事的存在，好提醒你及时完成任务。可这一阵子你实在太忙了，没法腾出时间来解决它们。拖延下去，反而产生了抗拒心理。\u003c/p>\u003cp>那我们该怎么处理这些信息和任务呢？我将David Allen的表述，结合GTD整个体系，梳理出了以下四个步骤。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>）细化行动步骤\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>收集所有事项。\u003c/strong>务必收集所有脑海中吸引你注意力的事项和想法，可以尝试用笔记下。可能是“明早9:30开会”、“周末陪老婆逛街”、“下周一替领导取某某报告”等。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>理清事项意义。\u003c/strong>这件事情对你有什么意义，做了后会产生什么改变，不做又会造成多大影响？\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>罗列具体行动。\u003c/strong>确定下一步行动，具体到看一眼就能执行的程度；比如说本周五晚上7:00在邯郸新世纪参加拆书活动。\u003c/p>\u003cp>\u003cstrong>4.\u003c/strong>\u003cstrong>提醒设置。\u003c/strong>可以用闹钟、台历等来提醒自己某一时间段或某一时间点该做什么事了。\u003c/p>\u003cp>本方法需要在一个相对放松的环境，充裕的时间来完成，不适合紧急情况，时间极其有限（几分钟）内能做完。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>）不那么做的坏处\u003c/strong>\u003c/p>\u003cp>不这么做又会怎样呢？悬而未决的任务和想法将占据你的大脑，时不时地消耗你的注意力，迫使你不得不从手头的工作中分出精力来对付它们。不仅降低了你的工作效率，还让你在做重要决定时，无法专注思考，产生差错，影响你生活正常进行。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>）异议预防性讲解\u003c/strong>\u003c/p>\u003cp>有伙伴可能会困惑，那每天都要写出来岂不是很麻烦。频率可以是一周一次，不必每天都做。而有的伙伴自己也曾做过清单，明白它的重要性，还是做不到。这是可以理解的，我也是这样从一开始的&quot;三天打鱼两天晒网”的状态过来，最好的解决方法就是你每天都在使用，可以不完全列出来，只要你一开使用它，哪怕是罗列一件，当你很愉快地完成了，你就会继续使用下去，并喜欢上这个行动的。\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>）举个例子\u003c/strong>\u003c/p>\u003cp>举个自己的例子。这周一，我既想找英文文献给我们老师审核，又想尽快改好2-4的拆书稿，我师父好早点给出修改建议，还想参加下午13:30开始的股票直播课。这三件事我是这么处理的。\u003c/p>\u003cp>首先，我把这三件事写在一张A4白纸上。\u003c/p>\u003cp>其次，考虑到英文文献老师催得急，这事放在第一位，不然下一步翻译工作得拖好久；2-4文稿周四前必须完成，而直播课不能回看，那就下午13:30-14:30听课，其他时间修改拆书稿。\u003c/p>\u003cp>之后，根据实际情况确定下来的下一步行动分别是：上午寻找英文文献，并交由课题组老师审核；下午13:30-14:30观看风云老师的股票直播课；在3月28日前修改好2-4拆书稿，并交由小六师父审核。\u003c/p>\u003cp>&nbsp;&nbsp;最后，将这3件事记录在滴答清单中，并设置了相应的时间提醒。\u003c/p>","interaction":"\u003cp>\u003cstrong>显像提问\u003c/strong>\u003c/p>\u003cp>好，现在请大家仔细想下，过去一周有哪些事情是一直占用着你的注意力，让你感到焦虑？有可能是“撰写拆书稿”、“阅读某本书”、“周末和老公/老婆去哪玩呢”等。当时你又是如何面对这种情况的呢？请大家写在纸上，并在组内分享。\u003c/p>\u003cp>小杜：\u003c/p>\u003cp>&nbsp; &nbsp;这周手上主要有2件事：家教（兼职，买个新手机）、计算机二级考试。每天晚上19:30-22:00做家教，做完家教回来，利用22:30到24:00的时间，来学习计算机二级考试。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003cstrong>A1+\u003c/strong>\u003c/p>\u003cp>要是能回到当时，针对其中的一件事，运用拆页一学习到的方法，你会怎么处理呢？\u003c/p>\u003cp>下面给大家3分钟时间，写在纸上，并在小组内讨论分享。\u003c/p>\u003cp>丽珍姐：\u003c/p>\u003cp>&nbsp; 上周正好事情比较多，有外出学习、拆书逐字稿修改、陪老爸输液、上班、陪伴老妈。\u003cstrong>（\u003c/strong>\u003cstrong>收\u003c/strong>\u003cstrong>集所有事项）\u003c/strong>先把脑海里这些事情都记下来。\u003cstrong>（\u003c/strong>\u003cstrong>理清事项意义）\u003c/strong>陪老爸输液肯定不能推迟，排在第一位；陪伴老妈在第二位；晚上要过级，写拆书稿放在第三位，学习和上班可能需要请假或上班。\u003cstrong>（\u003c/strong>\u003cb>罗列具体行动）\u003c/b>针对于拆书稿这一件事，晚上陪伴老妈的空闲时间，重新审查一遍。\u003cstrong>(\u003c/strong>\u003cb>提醒设置)\u003c/b>定个时间段，在晚上21:00-21:30重新阅读。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":11004,"quote":"\u003cp>刚才我们学习了如何有效清空大脑，减压，清理事项的意义，确定任务安排。接下来我们学习GTD的“四标准法”用以确定某一时刻的具体行动，下面给大家2分钟的时间来阅读片段。\u003c/p>\u003cp>\u003cstrong>确定某一时刻具体行动的“四标准法”\u003c/strong>\u003c/p>\u003cp>在星期三下午3点22分时，你如何选择下一步行动呢？这个时候，你可以按顺序采用下面四个标准：情境、有多少时间、有多少精力和重要性。\u003c/p>\u003cp>&nbsp;&nbsp; 前三个标准描述了你每次采取行动的制约因素，第四个标准则是评估行动的价值大小。\u003c/p>\u003cp>&nbsp;&nbsp; \u003cstrong>情境\u003c/strong>&nbsp;每时每刻，你都受限于自己的行动能力。只有很少一部分事情对地点没有特别要求（像拿一支钢笔和一张纸就可起草对一个项目的想法），但是，大多数事情都只能在特定的地点完成（在家或办公室），或者需要借助某些特定的工具（如一部电话、一台电脑），而这正是限制我们行动选择的首要因素。\u003c/p>\u003cp>&nbsp;&nbsp; \u003cstrong>有多少时间\u003c/strong>&nbsp;你所能支配的时间长短也是一个重要的限制因素。如果5分钟后你就必须去开会，你现在就不可能去执行那些耗时更久的行动。\u003c/p>\u003cp>&nbsp;&nbsp; \u003cstrong>有多少精力\u003c/strong>&nbsp;你有多少精力呢？某些事情需要你头脑清醒、思路清断、富于创造力，而另一些则要求你具备充沛的体力。还有一些事情\u003c/p>\u003cp>则对这两方面都没有特别要求。\u003c/p>\u003cp>&nbsp;&nbsp; \u003cstrong>重要性&nbsp;\u003c/strong>当你考虑了情境、时间、精力这三个条件后，最后你就要判断哪个行动选项会给你最高的回报了。现在，你有1个小时的时间，你坐在办公室里守着电话和电脑，你的精力指数为7.3（最高为10）。你应该做些什么呢？给客户回一个电话？考虑一下新的提案？处理一下语音信箱里的留言和电子邮件？或者联系一下你的配偶，看看她他这一天过得怎么样？\u003c/p>","explains":"\u003cp>拆页2介绍了GTD“四标准法”的具体用法，将从3个价值评估，1个场景分类，帮助我们更好地确定某个时间点的具体行动。\u003c/p>\u003cp>我们一般在一段空挡的等待期：等车、坐地铁、排队等。大部分人会刷会朋友圈、看会新闻、刷抖音、看会电影、玩一局游戏......很快地度过了等待期。如果我们能更加有针对性地使用这段时间，不但能让自己感觉充实，又有意义。\u003c/p>\u003cp>那我们具体该怎么做呢？\u003c/p>\u003cp>\u003cstrong>1）\u003c/strong>\u003cstrong>细化行动步骤\u003c/strong>\u003c/p>\u003cp>第一步，情境分类：确定事情是否需要在特点地点、特定工具下才能完成？\u003c/p>\u003cp>第二步，时间分配：你有多少时间？这件事又需要多少时间完成？\u003c/p>\u003cp>第三步，精力预估：简单预估下这件事所需要的精力，你拥有的精力，是否能有效处理任务？\u003c/p>\u003cp>第四步，重要性排序：按“最大回报”进行排序，确定要做的事。\u003c/p>\u003cp>第五步，任务汇总：最终按时间顺序整理出各项任务。\u003c/p>\u003cp>本方法适用于一段可自主支配的短暂空闲时间，或一时间点，不适用于非常紧急的状态下使用。\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>）不那么做的坏处\u003c/strong>\u003cstrong>+\u003c/strong>\u003cstrong>预防异议\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;\u003c/strong>那我要是不那么做又会怎样呢？没有及时规划，你有可能白白浪费那几十分钟的空闲时间。这时有伙伴可能不高兴了，我好不容易有那么一会时间休息，还要考虑怎么加以利用时间做事，岂不是很烦。当然了，你有权给自己好好放松下。但你要是想提高自己，充分利用碎片化时间将更好地帮助你成长。\u003c/p>\u003cp>&nbsp; 其中，针对一段比较长的时间，比如半天以上，可做两件事以上的，按四标准法最终确定好的事情做个汇总，如果在较短的时间内决定做一件事情，直接去做就好。\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>）举个例子\u003c/strong>\u003c/p>\u003cp>举个例子。在刚才打车过来的30分钟内，等车有5分钟，我可以做这么几件事：去食堂买杯粥垫胃、回复朋友微信消息、拆书场景预演。具体我是这么考虑的：\u003c/p>\u003cp>\u003cstrong>一、\u003c/strong>\u003cstrong>情景分类：\u003c/strong>买粥需要去食堂，等滴滴的在食堂边上，方便；回复朋友消息需要用到手机这个工具；拆书预演不分场景，嘴里念词，脑中想像。\u003c/p>\u003cp>\u003cstrong>二、\u003c/strong>\u003cstrong>时间分配：\u003c/strong>等车大约5分钟，买粥只能在这个点买，错过了没法买；回复朋友消息3分钟，拆书场景预演15分钟。\u003c/p>\u003cp>\u003cstrong>三、\u003c/strong>\u003cstrong>精力预估：\u003c/strong>只有拆书预演对精力有一定要求，状态正好允许。\u003c/p>\u003cp>\u003cstrong>四、\u003c/strong>\u003cstrong>重要性排序：\u003c/strong>肚子比较饿，填饱要紧，所以买粥第一，拆书预演第二，回复朋友消息第三。\u003c/p>\u003cp>\u003cstrong>五、 \u003c/strong>\u003cstrong>任务汇总：\u003c/strong>\u003c/p>\u003cp>综合考虑，最终的结果是：\u003c/p>\u003cp>1.食堂买粥，边喝边等；\u003c/p>\u003cp>2.在车上，用1分钟时间回复朋友消息\u003c/p>\u003cp>3.在车上，给大脑和嘴巴，15分钟时间进行拆书预演\u003c/p>","interaction":"\u003cp>拆页\u003cstrong>2 - A3&nbsp;\u003c/strong>促动参与\u003c/p>\u003cp>\u003cstrong>（A3角色扮演）\u003c/strong>\u003c/p>\u003cp>下面大家两人1小组，加工出一个剧本。一人是万爸爸，GTD学习者；一人是女儿玲玲，高三学生。暑假准备外出参观高校，在地铁站等车，正好有1个半小时的空闲时间，附近有商场和书店。而万老师刚学习完GTD的“确定某一时刻的“四标准法””，又会如何引导孩子充分利用这段空闲时间呢？\u003c/p>\u003cp>其中，玲玲爸爸的扮演者必须运用到今天所学的四标准法，细化的五步骤：情景分类、时间分配、精力预估、重要性排序、任务汇总，来引导玲玲进行思考，产生行动。讨论和编写剧本的时间为5分钟，5分钟后我们会请1-2个小组进行角色扮演展示。好，下面大家开始。\u003c/p>\u003cp>&nbsp;学习者分享：\u003c/p>\u003cp>常乐饰爸爸，丽珍饰女儿玲玲。\u003c/p>\u003cp>爸爸：闺女，咱们离开车还有一个半小时呢。咱们这段时间干点啥呢？我昨天刚跟你分享了GTD的“四标准法”，还记得不？\u003c/p>\u003cp>女儿：记得。\u003c/p>\u003cp>爸爸：那你安排一下，我们这段时间干点啥合适？\u003c/p>\u003cp>女儿：一直站着等车也挺累的，旁边正好有个茶餐厅，要点甜点，喝个茶。\u003cstrong>（情景分类）\u003c/strong>\u003c/p>\u003cp>爸爸：行，那再来点点心。那我们在那单单当中赏景吗？\u003cstrong>（时间分配）\u003c/strong>\u003c/p>\u003cp>女儿：在这过程中本来还想拆拆书，吃东西不太方便，可以给妈妈打个电话，谈谈心。拆书这事，可以往后放一放。\u003cstrong>（重要性排序）\u003c/strong>\u003c/p>\u003cp>爸爸：好！那这一个半小时，我们就去茶餐厅，休息一会，吃些点心。然后，给妈妈打个电话这事很重要，出来旅游给她报个平安，别让她老惦记着。而你说的拆书，听到这我很开心，我们可以看各自想看的书。时间充裕的话，还可以谈谈心。\u003cstrong>（任务汇总）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>（A2分步催化1）\u003c/strong>\u003c/p>\u003cp>现在请大家仔细想下， 你在一段碎片化时间内，会怎么去处理呢？比如说，下周五18:00过来拆书的路上，20-30分钟内，你手头上有哪些想做呢？并在小组内交流分享。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者分享：\u003c/strong>\u003c/p>\u003cp>小杜：去家教的路上，要坐半个小时小时的公交车。这个过程比较无聊，我会去看一些教学视频，后面会听会歌放松一下。\u003c/p>\u003cp>常乐：下周一，每次接孩子会等10-20分钟时间，有时候拖堂会等更久，很无聊。我可以做好几样事：刷朋友圈，看新闻，回复消息，和一块早到的家长聊聊，去旁边的超市买东西。\u003c/p>\u003cp>\u003cstrong>（A2分步催化2）\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 好，下面大家就自己刚才提到的场景，你会如何充分利用这段时间呢？需要运用到今晚拆页2所学的GTD“四标准法”：情景分类、时间分配、精力预估、重要性排序（、任务汇总）。给大家3分钟的思考时间，并在小组内交流分享。\u003c/p>\u003cp>\u003cstrong>学习者分享：\u003c/strong>\u003c/p>\u003cp>常乐：我刚才提到了，每次去学校\u003cstrong>（情境分类）\u003c/strong>接孩子总会空出来10-20分钟的时间。时间不长，我可以刷圈、和其他家长沟通孩子的学习情况、给孩子买蛋糕，\u003cstrong>从时间上来说\u003c/strong>，这是允许的。\u003cstrong>论重要性，\u003c/strong>孩子下周一会有一个课外班，怕他挨饿，会先去附近的蛋糕店给他买点心。所以说，我到那边，会先去给孩子买蛋糕，之后利用剩下的时间和其他家长交流，还有机会的话，再刷会朋友圈。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>\u003cbr>\u003c/p>\u003cp>那么，最后，我们来回顾总结下：\u003cstrong> \u003c/strong>\u003c/p>\u003cp>今晚我们学习如何清空大脑，收集所有吸引你注意力的事项，并根据其意义做出任务清单。又学习了GTD的“四标准法”，根据场景、时间、精力、重要性（及汇总），来确定某一时刻的下一步行动。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 最后，祝愿我们邯郸回车巷筹备分舵，顺利转正！\u003c/p>\u003cp>&nbsp;好，我今晚的分享到此结束，感谢大家的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1554649251000,"updated_at":1554650820000,"ria":true},{"id":6815,"topic":"影响大脑成功收集有效信息的3个条件","learn_goal":"正确管理生活中的未竟之事，从而完成任务、推动想法，布置行动","remark":"我们在生活中会给某项事务贴上“需要做”的标签，为了正确的管理这些未竟之事，我们需要从三个方面去有效的推动任务的完成，具体如下：1、赶出大脑：花一点时间把头脑中的内容清晰的记录下来；2、减少收集工具：用高效的收集工具来辅助思考；3、定期清空：做完一件事就把它从你的工具记录中删除，最多留下这件事总结的经验教训。只有准确的掌握这三个要领，才能更好的推动想法和布置行动。","level":"TF1-1","duration":10,"status":30,"type":0,"chaishujia":{"username":"机小灵z","city":"无锡"},"club":{"name":"无锡太湖分舵","city":"无锡"},"prologue":"\u003cp>1.自我介绍:大家好，我叫机小灵，真实名字是嵇灵，竹林七贤之一嵇康的嵇，之所以叫机小灵，是觉得每一个人虽然渺小，但是他能借助舞台去感染别人，实现从0到1的跨越。我有三个标签，第一个标签就是出差多，但是出差的时候有独处的时光，并且能在不同的城市寻找不一样的故事；第二个标签就是折腾，相信生活有无限种可能；第三个标签就是人如其名（1’左右）\u003c/p>\u003cp>2.介绍拆书和拆书帮（1-2’）\u003c/p>\u003cp>&nbsp;&nbsp;（1）拆书是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心而不是以知识为中心，要把知识关联学习者的经验、规划具体的运用。拆书法分为应用于个人学习的拆书帮便签读书法和应用于组织学习的拆书帮现场学习法RIA，R环节是阅读原书拆页，I环节是拆书家对原文知识拆页的讲解和对现场学习者的引导。A1是激活学习者的经验，A2催化学习者的应用，A3促动学习者现场演练。\u003c/p>\u003cp>&nbsp;&nbsp;（2）拆书帮：是基于拆书法的学习爱好者的社群，表现为各地的拆书帮分舵，拆书帮分舵是公益性青年自组织，其使命是有更多学习爱好者成为拆书家。\u003c/p>","ratings_count":1,"texts":[{"id":10171,"quote":"\u003cp>《搞定I：无压工作的艺术》：影响成功收集的因素\u003c/p>\u003cp>如果你的大脑也当作一个“存储器”来看待的话，那么很可能对你而言具有潜在意义的各种“未竟之事”现在就已经被你收集起来了。我们在这一阶段所要做的，正是确保一切必要的事情统统得以收集，并且存储在你大脑之外的某个地方。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;遗憾的是，仅仅有合适的收集工具，并不能保证顺利完成所有收集工作。大多数人都拥有某种形式的收集设备，但是，这些设备或多或少存在失控的情况，或者根本得不到充分利用。我们一起看看成功收集的3个必要条件：\u003c/p>\u003cp>1、每一件悬而未决的事情都必须存储在你的收集系统中，而不是在你的大脑里。\u003c/p>\u003cp>2、你应该尽可能的控制收集工具的数量，越少越好，够用即可。\u003c/p>\u003cp>3、你必须定期清空这些设备。\u003c/p>","explains":"\u003cp>首先，这个片段告诉我们影响大脑成功收集有效信息的3个条件。\u003c/p>\u003cp>那我们为什么要去收集这些数据呢，主要是因为我们在生活中会给某项事务贴上“需要做”的标签，为了正确的管理这些未竟之事，我们需要确保收集这些信息的有效性，从而来完成任务、推动想法、布置行动。\u003c/p>\u003cp>那么，如何确保成功收集有效信息，就有以下3个条件：\u003c/p>\u003cp>1、赶出大脑：花一点时间把头脑中的内容清晰的记录下来\u003c/p>\u003cp>2、减少收集工具：用高效收集工具来辅助思考\u003c/p>\u003cp>3、定期清空。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>月底再加上年底，工作量史无前例，昨天早晨还在脑海里过了一遍一天要做的事，结果其中查客户库存忙的时间拖延了，耽误了进程，再到下午销售部来电话时，才想起中午应该要提报一个表格的，当时还记在一个便签上了，便签随手一扔放在了包的角落里，手机备忘录里记着的是别的事，这么一来，很难合理规划事务，还会丢三落四，导致工作滞后。 &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>A1+：\u003c/strong>使用的收集信息工具多了反而不易消化事物，这一点那一点，自己都不知道从何下手，没有起到真正使用lists的目的，反而在大脑里不停出现这些烦躁的事，它们在打架的同时占用我们的注意力，很难集中精力去做好一件事，两件事，所以这个时候应该使用文段中的3个有效收集数据的条件：1、赶出大脑：不要让这些繁杂的事占据我的大脑，大脑应该用来储存一些反思总结感悟到的有意义的灵感；2、减少收集工具，便签、笔记本、文件夹等适用于办公室，像我这样出差比较多的，应该使用手机，那么“奇妙清单”就显得便捷又高效，它能记录每个时间节点应该要去推进的工作，想到要搜索什么事项了随时可以拿出来记和看；3、定期清理：做完一件事把它删除在临时存储器中，最多留下这件事总结的经验教训。\u003c/p>\u003cp>\u003cstrong>&nbsp;A2：\u003c/strong>\u003c/p>\u003cp>目标：计划12:18日-20日前花两天时间列未尽事宜的清单（尽量保证周围无任何事务打扰），并在20-22日内确保工具篮里职务反面和个人生活方面的未尽事宜全部完成（前提是这些未尽事宜的时间节点是这段时间的、短期能解决的），长远的清单仍然保留\u003c/p>\u003cp>行动：\u003c/p>\u003cp>1、赶出大脑：找一张白纸，排除一切杂事，把他们一个个写下来；\u003c/p>\u003cp>2、减少收集工具：就使用奇妙清单来标记接下来每一件事的内容和时间节点；\u003c/p>\u003cp>3、定期清空：12月22日前完成奇妙清单里罗列的所有待办事项，奖励自己一本品牌营销的书（先前卖了很多书，也有每月资金规划），未完成就惩罚自己12月28日不去看张学友的演唱会（票已买）\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1545146425000,"updated_at":1545153210000,"ria":true},{"id":5519,"topic":"如何正确决定下一步行动","learn_goal":"遇到“多任务待处理”的情况下，学会决定先处理哪一项","remark":"戴维。艾伦《搞定I无压工作的艺术版》已经成为时间管理领域颇具影响力的著作之一，书中介绍的GTD时间管理方法也成为全球千万读者用来轻松高效地完成工作和个人事物的工具。这本书致力于帮你解除精神上的负担，并把事情做好。只有轻松，才能高效","level":"TF2-1","duration":20,"status":30,"type":0,"chaishujia":{"username":"餐盘上的桃乐丝","city":"上海市"},"club":{"name":"上海申活分舵","city":"上海市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;大家好！我是Doris。\r\n &nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;在我们学习拆页之前，我先介绍下拆页选自的这本书《搞定》，作者戴维•艾伦在这书中系统地介绍了GTD(Getting Things Done)时间管理方法，而这本书已经成为时间管理领域颇具影响力的著作之一，全球千万读者都运用书中介绍的时间管理方法来轻松搞定工作与个人事务。如果你常常感到被N多待做工作压得喘不过来气，这本书可以帮你解除精神上的负担，轻松高效地把事情做好。&nbsp; &nbsp;\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;那么我们先来看下今天的学习目标：在跟随我完成本次RIA现场学习后，大家就能够在遇到“多任务待处理”的情况下，更容易决定先去处理哪一项。接下来我们就聚焦在拆页上，就请大家花1分钟时间，阅读手中的原文片段。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":8690,"quote":null,"explains":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;我们经常会遇到这个问题：此时此刻，我还有N件事情没有搞定，接下来，我究竟该先做哪一件比较好呢？随便选一件自己最感兴趣的？还是选最重要的？还是选最紧急的呢？以上都是单一的判断维度，容易顾此失彼。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp;而这个时候我们应当对自己“当下所处的客观环境”以及“各项事务的回报高低”做一个综合判断。这就好比寻觅结婚对象，你不可能只看长相，性格或者收入，因为单一维度很难使得我们选到合适的对象，从而浪费感情和精力。同理，面临多项待做任务，我们随意的决定，\u003cstrong>很可能会使我们损失的是：浪费了接下来的这段工作时间，低效率或者一些工作根本来不及做，从而让我们更加焦虑。\u003c/strong>\u003c/p>\u003cp>&nbsp; 那么面临“多任务待处理”，我们该怎么决定下一步的行动呢？拆页给出了“4标准法”：【标准1】\u003cstrong>所处的情境\u003c/strong>？确定有哪些事务你在当下所处的环境有条件完成。【标准2】\u003cstrong>有多少时间？\u003c/strong>假如你拥有30分钟，就不要处理1小时才能完成的工作。【标准3】\u003cstrong>有多少精力？\u003c/strong>此刻你的精力状态如何？满分10分的话可以打几分？待处理工作中哪些需要的精力与之相匹配？【标准4】\u003cstrong>考虑最高回报工作项。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;我们以拆页末提出的情境\u003cstrong>举例练习\u003c/strong>一下：\u003c/p>\u003cp>&nbsp; 待处理事务：A给客户回电话 B考虑新提案 C 处理语音信箱里的留言和邮件 D联系配偶，看他/她这一天过的怎么样\u003c/p>\u003cp>1所处情境：有电脑，有电话；ABC均具备处理条件，D就不太合适了\u003c/p>\u003cp>2时间：1小时；整段时间，ABC单独来看，基本都可在1小时内完成\u003c/p>\u003cp>3精力值：7.3分；精力值较高，适合聚焦在复杂或者耗费精力的事项上。A和B更匹配此时状态\u003c/p>\u003cp>4回报率：执行A的时间有不确定性，这通电话可长可短，且有可能因客户突发要求增加临时任务，回报率低；执行B需要整段时间全神贯注，拿下新客户，提案很重要，如果接下来的1小时能够完成，可以最大程度让我如释重负，回报率最高。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp;“4标准法”在所有情况下都\u003c/strong>\u003cstrong>适合么？显然这个方法适合于“待处理事务”都在你的可控范围内，否则，它就不适用了。\u003c/strong>比如你的领导明确要求你1小时内完成提交部门月度预算报表，你就不可能说我现在精力值不够处理这样的事务。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>接下来，请大家思考，\u003cstrong>近期你有没有遇到这样的情况\u003c/strong>：明明从忙碌的一天中，好不容易挤出了几个小时，打算完成几项你非常希望在当天就能结束掉的工作。但是你没有刻意安排处理顺序，跟着感觉走，做完一件，再处理下一件。但当时间结束的时候，你对自己的行动效果并不满意，或者有几件事根本还没来得及做，令你感到莫名的懊恼？请大家写下来，并按照我们发放拆页时的分组，进行组内讨论。\u003c/p>\u003cp>【学习者分享A1】\u003c/p>\u003cp>昨天我非常希望自己完成三件事情：准备讲书稿（为了参加公司近期比赛）， 去上健身课，&nbsp;&nbsp;练习2-4拆书（今天要来拆）。我没刻意安排顺序，就先准备了讲书稿，但是一直找不到合适的素材，就一直耗在这件事上，最终也没完成。所以昨天仅完成了“上健身课”这一件事情，拆书练习也没做。&nbsp;\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>那接下来，请大家接着思考刚才你写下的这个经历。\u003cstrong>如果回到当时，你根据今天所学的“4标准法”，你会如何调整处理这些事务的先后顺序呢？\u003c/strong>请大家在便签纸上写下来并在组内交流。\u003c/p>\u003cp>【学习者分享A1+】\u003c/p>\u003cp>如果回到昨天，我会综合考虑来重新安排三件事情的顺序：早上我的精力值高，但相对于准备公司的讲书稿，练习拆书时间更可控，因此我会先来练习“2-4拆书”，就能保证这件事情完成（达成可控回报）；接下来我就可以没有负担地专心准备讲书稿了，如果上午不能完成，中午去上个健身课放松一下，回来接着进行。\u003c/p>","flags":{"r":false,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1531540911000,"updated_at":1531543817000},{"id":4851,"topic":"自然计划模式","learn_goal":"自然计划模式","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"熊熊2040","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是熊熊。\r\n为了方便待会大家讨论，首先我们来分一下组，4人为一组，请大家找到自己的组员。\r\n日常生活中，有没有觉得时间不够用的时候，感受工作效率低而带来的焦灼感，想改变生活或者工作不良习惯呢？这本书统统都可以帮你解决以上问题，提高工作效率，轻松规划生活工作，形成一个全面的管理系统，获得更多的自由时间做自己想做的事情。\r\n这本书《搞定1》是世界知名时间管理大师戴维•艾伦的经典之作，2001年首次出版距今已经16年时间，而这本书已经全球33个国家出版畅销，他被《福布斯》杂志评为美国最优秀的管理教练之一。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":2,"texts":[{"id":7907,"quote":"\u003cp>\u003cstrong>【R】阅读原书拆页\u003c/strong>\u003c/p>\u003cp>\u003cstrong>今天给大家分享主题，是书中节选的“自然计划模式”，\u003c/strong>下面请大家阅读发在拆书帮大群里的片段（或者查看手中的文档），时间一分钟，请大家读完抬头示意我。谢谢！\u003c/p>\u003cp>\u003cstrong>自然计划模式\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 世界上邦个才华横溢、最具创造力的计划者，就是与你朝タ相处的大脳。实际上，你自己就是一台生产计划的机器。当你穿衣、吃午饭、购物，或者是在与人侃侃而谈时，你的大脑都在一刻不停地盘算着。\u003c/p>\u003cp>&nbsp; &nbsp; 尽管其过程可能毫无章法可言，但事实上在大脑闪现出任何一个具体的方案之前，一些相当复杂的步骤就已经抢先登场了。人的大脑在面对任何一项任务的时候，都要经过5个步骤:\u003c/p>\u003cp>1.定义目标和原则。\u003c/p>\u003cp>2.展望结果。\u003c/p>\u003cp>3.头脑风暴/集思广益。\u003c/p>\u003cp>4.组织整理。\u003c/p>\u003cp>5.明确下一步的行动方案。\u003c/p>","explains":"\u003cp>\u003cstrong>【I】讲解原文知识\u003c/strong>\u003c/p>\u003cp>我看到大多数的小伙伴都已经阅读完了，没有看完也没有关系，接下来的分享中我会对原文进行深入的解读；\u003c/p>\u003cp>看完这个片段有没有这样的感受，当决定做一件事情常常是依靠直觉思考，想到就马上开始行动；这个思考过程是杂乱的出现在我们脑袋里面，书中的五个步骤，“把完成一件计划”每个阶段的要做的内容都明确下来了，只要按照步骤去做，就能推进计划的完成。\u003c/p>\u003cp>\u003cstrong>给大家介绍一下这五步：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一步，定义目标；就是做这个事情的动机，需要有明确的想实现的目标；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步，展望结果；意思是通过我们的想象对计划结果的进行美好过程的联想；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步，头脑风暴；在大脑里面产生许多点子、想出办法的过程；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第四步，组织整理；对头脑风暴的结果进行梳理、根据重要程度、时间先后排序的过程就是组织整理；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第五步，明确下一步行动；根据组织整理的结果去行动执行。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>这样说来还是比较抽象，举个例子：\u003c/strong>\u003c/p>\u003cp>熊熊请新交往的男朋友吃饭规划，看看怎么来具体运用这五步：\u003c/p>\u003cp>第一步，定义目标；问问自己最终实现的目的是什么？出去吃饭是为了联络加深感情，请他感受到温暖；\u003c/p>\u003cp>第二步，展望结果； \u003c/p>\u003cp>想象一些具体、比较美好的画面；我就想到了自己坐在餐厅里，他温情的看着我的模样；桌上的烛光映衬到墙面，烛光不断舞动的场景，这就是我对吃饭场景的总总想象的展望。有了美好画面，很多指导行动想法就开始冒出来，\u003c/p>\u003cp>第三步，头脑风暴；\u003c/p>\u003cp>几点出门，天气如何，穿什么衣服，要不要提前预约，路上会不会堵车，，，等等灵感就冒出来，灵感冒出来这个创造性过程就是头脑风暴，有了这么多想法，我需要一个便签记录下来这些灵感，就到了\u003c/p>\u003cp>第四步，组织整理；\u003c/p>\u003cp>组织整理这些灵感需要遵循三个方面，有利于帮助我们更加了解这个事情及指导下一步行动。第一方面，构成要素，由几个事项组成，如规划时间、事情准备、预计费用等，考虑吃饭这个事情重要组成部分。第二方面，重要程度，吃饭这个事情对我而已就重要是，需要落实餐厅是否要提前预约，男朋友周末那个时间休息，能不能来，划分优先级处理顺序，也就是第三方面，先后顺序，根优先级及构成要素一一落实。把这三个方面都考虑清楚之后，自然就知道下一步要做什么，也就是\u003c/p>\u003cp>第五步，明确下一步行动；\u003c/p>\u003cp>我首先要给餐厅去个电话落实一下是否预约提前预约，在给男朋友打电话落实吃饭时间，地点等等，最后我要考虑穿什么，到这里，我的整个计划约会的基本都落实了。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】分享过往经验：\u003c/strong>\u003c/p>\u003cp>刚刚分享了一个例子，大家可以回想一下，你最近一次制定新工作计划、安排重要会议、或者跟家人朋友吃饭是怎么安排的，结果怎么样？大家按照刚才的分组，在小组里面相互讨论，时间为5分钟。\u003c/p>\u003cp>邀请1位学习者进行A1分享。\u003c/p>\u003cp>小煤球案例分享：上周一领导安排一个一项工作，说周六组织一场露营有特色活动。在接到这个工作之后，我就着手开始制定计划，联系了几家场地，然后分别去现场看了看，落实了费用，最后选择了二家综合性价比最高的露营地点推荐给领导。\u003c/p>\u003cp>本以为领导会说在这段时间内把事情安排的这么仔细，详尽，等着他表扬我。他却说，怎么不找几家山上的多比较一下，这二个地方都没有什么露营的特点。后面又返工找了二家山上的露营基地，这个事情才定下来。\u003c/p>\u003cp>结合今天的做计划的方法来看，自己在“定义目标”、“展望结果”这二步没有太多考虑，就直接开始着手头脑风暴、整理，进行下一步行动了。\u003c/p>\u003cp>如果时间可以倒回，我应该在第一步就与领导一起把此次活动清晰的目标达成统一意见，如：什么是有特色的活动，对于人员、场地、内容有什么特殊的要求没有。再去具体执行的话，这样效率会更加高效一些。\u003c/p>\u003cp>\u003cstrong>【A2】写下行动步骤：\u003c/strong>\u003c/p>\u003cp>我们今天了解到理性思维 “自然计划模式”的运用步骤，用今天学习到的方法来“计划一件下周具体要做的重要的事情”，写在自己的A4字上面，时间为1分钟，在写具体步骤的时候，需要注意整个事情是可实施、可衡量、有清晰的行动步骤这几点。\u003c/p>\u003cp>邀请1位学习者进行A2分享。\u003c/p>\u003cp>张张案例分享：下周要带家人，爸爸妈妈还有弟弟一家人在重庆市区内旅游，因为他们来重庆的次数不是很多，二天的时间想让大家玩的开心一点。根据今天学习到的“自然计划模式”的方法了，可以这样来做：\u003c/p>\u003cp>第一步，定义目标；\u003c/p>\u003cp>带家人在重庆市区内玩耍，实质的目的是为了增进家人之前的感情及互动，让大家留下美好的回忆；\u003c/p>\u003cp>第二步，展望结果；\u003c/p>\u003cp>在头脑中想象，大家在重庆的风景区留影，一家人都在开心的比划着剪刀手；妈妈在树林中要滑到了，爸爸赶忙牵着妈妈的手，搂着她的腰，我和弟弟在一旁偷偷的笑。一家人其乐融融的场景。\u003c/p>\u003cp>第三步，头脑风暴；\u003c/p>\u003cp>随着头脑中画面的呈现，我想到了可以去歌乐山、可以去磁器口、可以去南山、或者观音桥小吃街、日本料理，拍摄全家福等等内容，我把这些点子都记录下来。\u003cbr>\u003c/p>\u003cp>第四步，组织整理；\u003c/p>\u003cp>根据周六与周日的时间行程安排，可以锁定周六先去磁器口，感受一下重庆的历史文化，下午去歌乐山玩相对比较刺激的山地活动，晚上还可以去感受一下当地特色美食辣子鸡，吃完之后，在慢悠悠回家；周日根据大家的具体情况而定，可以去观音桥吃吃小吃，找一家相馆拍摄一套全家福，弄完之后在南山看看。这样下来，二天的行程丰富而有趣，会让大家充满回忆。\u003c/p>\u003cp>第五步，明确下一步行动；\u003c/p>\u003cp>所以先要落实一下周末二天的天气预报，是否适合户外活动；还需要先找个相馆进行预约，贮备一下户外用的防蚊夏季用品等等。\u003c/p>\u003cp>\u003cstrong>我的分享完了，希望大家在便签上写下对我这次分享的看法和建议。谢谢大家。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1521634794000,"updated_at":1558926550000,"ria":true},{"id":4843,"topic":"确定某一时刻的具体行动","learn_goal":"合理确定工作的方法。","remark":"当你的面前总是摆放着长长的事件清单，而你又总是找不到充足的时间来处理的时候，你是如何决定做哪些工作和不做哪些工作的呢？ 3月20日，涂乐邀您一起探索合理确定工作的方法。","level":"TF2-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"涂乐","city":"长春市"},"club":{"name":"北京城市之光分舵","city":"北京市"},"prologue":"\u003cp>大家好，先做一个自我介绍。我是涂乐，我的本名叫邢延富，一般情况下都会认为我这个姓氏是刑天的刑，但我的这个是邢台的邢，开加耳刀。我最重要的一个标签是城市之光分舵舵主的徒弟。\u003cstrong>（学习目标）\u003c/strong>在跟随我完成本次RIA现场学习后，学习者能够运用确定某一时刻行动的方法，\u003cstrong>【可被测量的行为】\u003c/strong>在任何时刻都能够把最应该做的哪件事情从众多的事情中找出来，从而充分、高效利用时间。\u003cstrong>（图书介绍）\u003c/strong>\u003cstrong>【B】\u003c/strong>我今天选择的是关于时间管理方面的书。但是时间管理的书有很多，我为什么会选择手里这本书呢，在回答这个疑问前。我先问大家一个问题，现在我们每天要做事情是比以前多了还是少了呢？我想大部分人都是多了，对吧。那么在事情变得越来越多，而我们时间没有变化的情况下，我们会怎么样？我们会变成越来越忙，压力呢越来越大，对吧。所以正是因为这个原因我选择了今天的这本书，这本书可以帮助我们避免发生刚刚说的那种状况，能够让我们把所有的事务进行合理的安排，达到轻松自如的状态。\u003cstrong>【F】\u003c/strong>这本书的名字叫\u003cstrong>【实用类书籍】\u003c/strong>《搞定I》，它还有一个副标题叫无压工作的艺术。他的作者是戴维艾伦，这个人因为这本著作被誉为是提升工作效率的顶级思想家，注意两个字顶级。由此可以看出，这本书在时间管理领域是有很高的地位的，是一本很有权威的书籍。\u003cstrong>【A】\u003c/strong>说到时间管理领域方面的书籍，很多的著作给我们灌输的思想都是要事第一，把时间都留给那些重要的事情，不重要的事情可以忽略掉，对吧。但是这本书的理念是事情不管重要还是不重要，如果不处理它，它就会一直在我们的大脑中存在，影响我们做事的效率。所以作者主张要把脑海中所有要做事情都写下来，然后对它们进行一一处理。这样做之后，就可以让我们达到一种轻松自如的控制和处理一切的状态。所以在时间管理方面有需求的小伙伴，可以看看这本书，说不定能够给你一些启发。下面我请小伙伴帮我给大家发一下拆页，读完后请给我一个示意。谢谢。\u003c/p>","ratings_count":2,"texts":[{"id":7900,"quote":"\u003cp>\u003cstrong>【内容未超过2页图书内页】\u003c/strong>在星期三下午3点22分时，你如何选择下一步行动呢？这个时候，你可以按顺序采用下面四个标准：情境、有多少时间、有多少经历和重要性。\u003c/p>\u003cp>前三个标准描述了你每次采取行动的制约因素，第四个标准则是评估行动的价值大小。\u003cstrong>【具体How】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>情境\u003c/strong>&nbsp; 每时每刻，你都受限于自己的行动能力。只有很少一部分事情对地点没有特别要求（像拿一只钢笔和一张纸就可起草对一个项目的想法），但是，大多数事情都只能在特定的地点完成（在家或在办公室），或者需要借助某些特定的工具（如一部电话、一台电脑），而这正是限制我们行动选择的首要因素。\u003c/p>\u003cp>\u003cstrong>有多少时间\u003c/strong>&nbsp; 你所能支配的时间长短也是一个重要的限制因素。如果5分钟后你就必须去开会，你现在就不可能去执行那些耗时更久的行动。\u003c/p>\u003cp>\u003cstrong>有多少精力&nbsp;\u003c/strong> 你有多少精力呢？有些事情需要你头脑清晰、思路清晰、富于创造力，而另一些则要求你具备充沛的体力。还有一些事情则对这两方面都没有特别要求。\u003c/p>\u003cp>\u003cstrong>重要性\u003c/strong>&nbsp; 当你考虑了情境、时间、精力这三个条件后，最后你就要判断哪个行动选项会给你最高的回报了。现在你有一个小时的时间，你坐在办公室守着电话和电脑，你的精力指数为7.3（最高为10）。你应该做些什么呢？给客户回一个电话？考虑一下新的提案？处理一下语音信箱里的留言和电子邮件？或者联系一下你的配偶，看看她/他这一天过得怎么样？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 这时你可以借助你的直觉，并依赖你此时此刻的判断力。\u003cbr>\u003c/p>","explains":"\u003cp>&nbsp; &nbsp; &nbsp; 好，看到多数的小伙伴都已经读完，没读完的也没有关系，我们一起来看一下。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 在当下，我们的工作越来越多，而时间呢越来越不够用。当我们每天面对着那些处理不完的事情时，我们如何去取舍呢。通常情况下，是根据我们自己的感觉来做决定的，比如我们觉得重的要就先做，如果不重要就先放一放再说。但是这样做真的合理吗？不一定吧。那怎么才能做出一个合理的选择呢？\u003c/p>\u003cp>\u003cstrong>【how】\u003c/strong>这个拆页提供了一个方法，通过行动的四个标准来决定你此刻要做的事情，四个标准分别是：所处的情景、可支配的时间、有多少精力、事情的重要性。具体的做法是，首先用前三个标准找出能做的事情都有哪些，然后根据事情重要性选出最重要的那一个。\u003c/p>\u003cp>\u003cstrong>【举例子】\u003c/strong>下面我用一个例子来说明一下如何来应用它，请大家看拆页的背面。左边是事件背景。背景是周一早上我们到公司，正准备按照工作清单做事的时候，助理告诉我们因为某个项目出了问题，15分钟后要开一个临时项目会议，并给了我们两页A4纸的会议资料。那么这个时刻我们做工作清单中的哪件事情是最合理的。右边是我们的工作清单，一共有7件事。\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;\u003c/strong> \u003cstrong>工作清单：\u003c/strong>\u003c/p>\u003cp>1、和同事小A讨论项目\u003c/p>\u003cp>2、处理电子邮件\u003c/p>\u003cp>3、做一个客户回访电话\u003c/p>\u003cp>4、浏览项目会议资料\u003c/p>\u003cp>5、写市场调查报告\u003c/p>\u003cp>6、年终总结报告\u003c/p>\u003cp>7、下午2点钟到客户公司谈项目\u003cbr>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp;&nbsp;\u003c/strong> 根据四个标准分别来看一下，第一个所处的情景，这个时候我们在办公室，有电脑、电话、相关资料等等的资源，除了第7件无法做之外，其他的工作都没问题；接下来可支配的时间，时间是15分钟，那么清单上需要长时间的1、5、6是做不完的，所以排除掉；接着是有多少精力，一天刚刚开始，精力很充沛，这些工作都可以做。通过这三个标准筛选后，我们筛选出是的工作有2、3、4；即处理电子邮件、做一个客户回访电话、浏览项目会议资料。最后一步，对比事情的重要性。马上就要开会了，事先了解一些情况是这三件事中最重要的，所以最合适的事情是浏览会议资料。\u003c/p>\u003cp>\u003cstrong>【避免异议】\u003c/strong>通过这样做可以帮助我们选出最合适的事情来做，但你可能会觉得，选一件事情还要这么多步骤，又是筛选、又是对比的，这也太麻烦了。事实上，不这么做可能会更糟。试想一下，在刚刚的例子中，如果我们选择了写市场调查报告这件事，那么开会的时候，我们脑子里可能还在思考报告中的某个问题，影响了会议效率；或者是集中精力参加完会议后，发现刚刚的想法忘记了，要重新思索、梳理思路，反而花费了更多的时间。所以方法虽然有些麻烦，但是是值得的，而且当我们熟练以后，就会很自然的做出选择了。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>在使用这个方法的时候要注意，它适用的情形是当我们面对很多的事情的时候，在当下这个时刻，我们应该选择哪一件事情来做。还有一个条件在这个时刻我们是有选择权的。如果情形不符合或者没有选择权，那么这个方法就不能用了。\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>A2催化应用：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>催化1\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;&nbsp; \u003c/strong>接下来请大家设想一下，在未来的一段时间里是否会遇到这样的情景，\u003cstrong>【具体情境】\u003c/strong>比如早上你刚刚到公司，打开电脑准备处理一下手上的所有工作，但被告知半小时后陪领导出去谈一个项目。或者是某天同时接到多个客户的电话，催你办理他们的项目。又或者是公司派你出差，当你感到机场时发现飞机晚点了，这个时候你想到正好有几件事情要处理一下。\u003c/p>\u003cp>\u003cstrong>【A2指令1】\u003c/strong>上面的哪一个情景或类似的情景是你将会遇到的。具体的情景是怎么样的。给大家几分钟的时候在组内分享讨论一下。\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>我给大家分下组，我们仍然按照晓军分的组，这边四个人一组；这边四个人一组，一共两组。\u003c/p>\u003cp>\u003cstrong>催化2\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;&nbsp; \u003c/strong>好，时间到。刚刚大家都想到了自己将会遇到什么场景了。\u003cstrong>【A2指令2】\u003c/strong>那再设想看看，在这个场景下，当你决定要去做哪个工作的时候，你突然想起了今天的拆书内容。确定行动的四个标准：所处的情景、可支配的时间、有多少精力和事情重要性。那么按照这四个标准你是怎么做出选择的。给大家5分钟的时间在组内互相分享一下，组内分享结束后，我会邀请小伙伴来做分享。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;&nbsp; 好的，时间到，邀请一位小伙伴来分享你将会遇到的情景是什么，用今天的方法你是怎样选择出合理的事情的。\u003c/p>\u003cp>\u003cstrong>【学习者A2案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>李娟：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>将会遇到的情景：\u003c/strong>四月份因为公司培训会经常到外地出差，会遇到飞机晚点的情况。\u003c/p>\u003cp>\u003cstrong>要做的事情：\u003c/strong>刷手机；阅读一本书；处理一些工作（落地后的工作）\u003c/p>\u003cp>方法：根据这个方法，\u003cstrong>情景\u003c/strong>是在机场，这些都可以做；可支配\u003cstrong>时间\u003c/strong>是不确定的，大概1-2个小时，这些都可以做；\u003cstrong>有多少精力\u003c/strong>，精力比较充沛，事情都可以做；事情的\u003cstrong>重要性\u003c/strong>，这个事情中\u003cstrong>处理一下落地后的工作\u003c/strong>是最重要的，所以会选择这个来做。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>总结\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp;&nbsp; 谢谢李娟的分享，下面做个小总结。今天的主题是确定某一时刻的具体行动的“四标准”，情境、有多少时间、有多少精力、重要性。这个方法可以帮助我们在任何时候都能选出合适的行动、从而高效率生活和工作。\u003c/p>\u003cp>最后，希望这个方法能给大家带来帮助或者是启发。谢谢大家！\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1521608689000,"updated_at":1526274301000,"ria":true},{"id":4564,"topic":"学会关注结果","learn_goal":"学会关注结果、明确定义结果","remark":"你是否渴望过这样一种状态：自己虽然整日事务缠身，却仍然头脑清醒；你能够轻松自如地控制和处理一切；拥有极高的效率，卓越的效果吗？学会关注结果，过高效的人生。","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"邱小猫","city":"上海市"},"club":{"name":"上海喜乐分舵","city":"上海市"},"prologue":"大家好，我是邱小猫。我是重新入会的新晋拆书家。\r\n用三个标签来介绍自己：\r\n1）IT女：在银行做技术支持，是银行应用的急诊医生+护工\r\n2）侠女：痴迷武侠好多年，对那个快意恩仇的世界依旧神往\r\n3）不像上海妹子的上海妹子\r\n拆书是赵周老师提出的一种读书方法。强调以学习者为重心，而不是以书本里的知识为重心。\r\n提出一种RIA的读书方法，把书本里的知识拆解成学习者的能力。\r\nR环节是指阅读原文片段\r\nI环节是指用自己的语言重述知识\r\nA环节是拆为己用\r\n-A1指向过去，也就是根据知识点联系自己过去的经验\r\n-A2指向未来，未来可以如何行动把学习到的知识运用起来\r\n-A3现场演练\r\n拆书帮是各个小伙伴用RIA的方法一起学习、交流、分享的学习组织。在全国多个地区都有拆书帮分舵。上海有喜乐，申活，申展，羊角村等。会员与非会员都可以参与拆书活动。一般由拆书帮会员来带拆书籍，带领大家一同学习。\r\n今天给大家待拆《搞定》，请大家先看下拆页，请阅读完毕之后给我示意。","ratings_count":1,"texts":[{"id":7591,"quote":"\u003cp>处理日常事务时一个重要的技巧就是：学会在脑海中对结果做出正面的预期，并以此影响实践。\u003c/p>\u003cp>判明事务的目标，确定下一步行动，这才能最大限度地提高工作效率。\u003c/p>\u003cp>结果和行动是紧密联系、相互影响的。只有当你对预期结果一清二楚时，才有可能找出恰当的行动，只有你知道该如何行动，结果和现状才能联系起来。你可以，而且必须同时从这两方面入手来解决问题。\u003c/p>\u003cp>“我们希望这次会议达成什么样的决议？”“这个表格的目的何在？”“这项工作的理想人选应该具有什么样的能力？”“我们希望通过使用这种软件取得何种成果？”在大多数情况下，我们听不到这样深刻的问题。在重大会议上，我们确实会听到很多不错的意见，但学会在日常工作中不断问自己“为什么要做这件事？”“做成这件事会怎样？”才是最关键的——这会对你产生极为深远的影响。\u003c/p>\u003cp>追问你想要做的事的目的，是健康而成熟的表现，在具体方法明确之前，想象成功的场景，是一种需要强化的重要能力。愿意构思想法，无论好坏，并不加批判地表达和收集他们，是全面发挥创新能力的关键。为了获得特定的结果，仔细分析多重想法和各类信息，将他们组织、排序、区分其重要性，是一项必须进行的心智训练。而决定并执行下一步行动——在现实世界推进某事的发展——是高效行动的核心本质。\u003c/p>","explains":"\u003cp>想要有高效行动，需要有两步，1）定义结果 2）确立行动。\u003c/p>\u003cp>为什么要先确立结果，再去定义行动呢？两点之间直线距离最短，要先明确自己达成什么样的目标，才能确定最高效的，有力的途径到达那个地方。所以一定要先定义结果，再确认行动。\u003c/p>\u003cp>那么要定义怎样的结果？什么才是真正需要的结果呢？如书中所说，需要让自己大脑对结果做出正面预期。只结果被明确定义了，才有可能找到最合适的下一步行动。\u003c/p>\u003cp>这里的结果是指真真正正可以落到实处的结果。可以是一个最小可执行/可交付产品；一个明确可落地的决策方案；或者达到沟通的目的，等等。是一种可以被审核交付的结果。是最终的某种收获。\u003c/p>\u003cp>比如，开完一个项目沟通会只是一个行动，但出一份让各部门认同确认的，可被跟踪执行结果的会议纪要，才可以算是一个初步的结果。\u003c/p>\u003cp>而如果目标指向过程，比如“目标是每天健身”。这个目标不能被审核，也就是说并不是一个定义好结果的目标。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>我以前很少关注到结果，而只是关注在行动层面上。\u003c/p>\u003cp>比如：我去年健身，给自己定的目标就是每周健身三次，每次1-1.5小时。我隐约知道自己健身的目的是为了健康和减脂，但那个画面并不明确，只是一个很模糊的意向。\u003c/p>\u003cp>后果是：这些目标虽然被执行了，但并不高效。最终达成的效果也并不十分理想。\u003c/p>\u003cp>说是说去健身，但当天去练什么，要训练到什么效果算完成，这些都是模糊的。或多或少会有些懈怠，有时候就是照着“过程化”的目标，随便练个1小时。\u003c/p>\u003cp>但如果真的对结果进行明确定义的话，比如在多少时间内减脂，达到体脂百分率多少，会更有针对性，会更积极主动，而且会多管齐下，同时关注饮食，睡眠，真正为了达到结果而去进行多方位的努力。\u003c/p>\u003cp>A2：\u003c/p>\u003cp>由于最近正好在听崔律的高效TODO日清单课程，也就是每天根据时间轴写下第二天的预期行动计划。待办事项其实是行动计划，而我后续每天除了在在日清单写下计划之外，针对工作部分的内容，还需要预先定义好结果，设置一个可以被审核/被交付的结果目标，达成结果预期之后，才可以对日清单里的具体行动置为完成。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1516800413000,"updated_at":1516800457000,"ria":true},{"id":4042,"topic":"掌控生活的横向管理工作流程","learn_goal":"学习横向管理工作的方法，提高工作效率。","remark":"","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"孙晶晶","city":"郑州"},"club":{"name":"郑州轩辕分舵","city":"郑州"},"prologue":"各位爱学习的小伙伴，上午好。我是晶晶，用三个标签介绍下我自己\r\n1:妈妈。我有一个4岁半的儿子。\r\n2:科学育儿传播者。因为渴望儿子成为他自己，我走进线下培训课堂，这个课堂让我打开了自己，让我从一个从不在公众面前讲话的人走向公众，让我拥有不完美的勇气.\r\n3:终身学习者。从此的余生要在知识的海洋里找回那个真正的自己。\r\n接下来，我用2分钟的时间为大家介绍下拆书帮的学习。\r\n“拆书”是一种学习方法论，适用于以提升能力、解决问题为目标的成人学习，它强调以学习者为中心而不是以知识为中心，然后把知识关联学习者的经验、规划具体的运用，让我们学以致用。\r\n这里有两种方法是：RIA便签读书法和组织学习法。RIA便签读书法，是个人应用这种方法可以让你不用读完一本书就能达到参加同主题培训的效果；组织学习法，由一个拆书家基于一本书加工出一场现场学习，引导和促进一群人把知识拆为己用，一个拆书家创造的价值不亚于一位培训师。\r\n拆书帮就是这样一群应用拆书法的学习爱好者的社群。在全国各地都有分舵。各分舵是公益性青年自组织，其使命是帮助更多学习爱好者成长为拆家。","ratings_count":0,"texts":[{"id":7001,"quote":"\u003cp>掌控生活：横向管理工作流程的5个步骤（搞定I &nbsp;P037）\u003c/p>\u003cp>轻松掌控知识工作的核心方法，是熟练掌握工作流程管理的5个阶段，这5个阶段也是我们经验的总结和体现。无论在什么情况下，我们在处理生活和工作中遇过的问题及持续发生的新事务和变化时都将经历这5个独立阶段。无论是私事还是公事，要想使事务处于你的控制之中，都需要经历这些阶段。而这些不同阶段各有其最佳方法和管理工具。它们必须作为一个整体发挥作用，你才能在复杂的工作环境中呈现出最佳状态，提高工作效率。这些管理方法不只限于“组织整理”或者“确定优先事项。”这些方法固然很好，但它们只是1应用这5个阶段所获得的结果，而不是阶段本身。我即将描述的这些阶段应该作为一个整体发挥作用，它们所产生结果的便利性和挑战性将出乎你的意料。\u003c/p>\u003cp>我们(1)收集引起我们注意的事务和信息；（2）理清每个项目的意义和相关措施；(3)组织整理结果，提出选项(4)进行思考回顾(5)选择行动。这些阶段共同构成了我们生活中的横向惯例系统，而且我们还可以随时向其中添加需要考虑的新事项。\u003c/p> &nbsp; &nbsp;这些并非主观或纯粹理论性的建议，当我们想控制并稳定某些事情，令其发挥建设性作用时，大家都会这么做。如果你打算为朋友做顿饭，但到家时发现厨房一团糟，你会怎样处理?首先要确认摆放不到位的所有东西(收集)；决定保留什么，扔掉什么(理清)；把东西归位——放回冰箱、扔进垃圾箱，或放进水池(整理)；然后核对你的食谱，以及已有的食材和厨具(回顾)，然后把黄油放进锅里融化，开始做饭(行动)。","explains":"\u003cp>在生活及工作中，我们要是想让事务按自己的计划进行，并且让自己保持最佳状态、提高工作效率。需要熟练掌握这5个阶段，并必须要把这5个阶段作为一个整体发挥作用，结果才会出乎你的意料。这5个阶段是：\u003c/p>\u003cp>1：收集工作或生活中的相关事务与信息；\u003c/p>\u003cp>2：理清每个项目中的意义与措施；\u003c/p>\u003cp>3：整理事务与信息，并做出选项；\u003c/p>\u003cp>4：回顾并思考；\u003c/p>\u003cp>5：行动。\u003c/p>","interaction":"\u003cp>A1:18号心理咨询师全国统一考试。10月份报名考试后开始复习，看过一遍书后就被压在其它书下面了。因为我定的目标是每周工作闲的时候就要看，然后就没闲下看它的时候了。当时10月份报名，老师说下个月月中考试，然后我脑子就记下了下个月的月中考试，也没在日程表上记下具体的日期。以至于11月了也记着是下个月月中考试。结果11号学校通知领取准考证时就蒙圈了，只有7天了，那枯燥的大书怎么复习，怎么可以考试通过。\u003c/p>\u003cp>A2:为了下周可以顺利通过考试，根据5阶段做了考前复习的规划：\u003c/p>\u003cp>1：周一上午10：00去收集为了能通过考试，都有哪些渠道可以帮助我学习。教材书、练习题集及学校提供的历年真题、老师授课视频、考前串讲音频，还有群里同学的讨论；\u003c/p>\u003cp>2：理清这些渠道：教材书（枯燥，太厚有压力，自己看觉得哪里都不是重点）\u003c/p>\u003cp>练习题集（可以一边练习，一边翻书，可以熟悉出题的规律还可以全面的了解）\u003c/p>\u003cp>学校提供的历年真题（综合应试能力训练，考前恶补）\u003c/p>\u003cp>老师授课视频、考前串讲音频（虽然很有针对性，但听讲自己不太专注，可以做为复习补充）\u003c/p>\u003cp>还有群里同学的讨论（分散精力，不考虑）\u003c/p>\u003cp>3：整理出自己的复习方式：周一下午做练习题3小时；周二做练习题2小时；周三做练习题早9点—晚4点；周四早9点—晚4点做历年真题3套；周五早9点—晚4点听老师串讲音频2小时，历年真题2套；周六去考试。\u003c/p>\u003cp>4：教材书、习题集这两个是现成的，原来买的。历年真题今天13点前下载好存在一个文件夹里。把资料都放在一个资料袋，随身携带。\u003c/p>5：开始行动。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1511151391000,"updated_at":1511152168000,"ria":true},{"id":3773,"topic":"《搞定1——无压力的工作艺术》","learn_goal":"搞定1——无压力的工作艺术","remark":"明明知道那么多事情堆在眼前：摊开的文件、散乱的衣橱或者只是一个该打的电话、一封该发出去的邮件，还有自己焦虑不安的小心脏，可你还是边咬着手指甲想，再待一会儿，就一下下……\r\n   你每天都很焦虑，惦记着要做的事，然后却不停看网页直到半夜，你成了焦虑的”拖拉机”，怎么办？\r\n   本周四，来西二旗，果粒带你一起告别拖延，做高效行动者","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"果粒","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"开场：分发拆页，分组，打开录音笔\r\n【图书介绍】大家好，我是果粒，今天我带拆的片段选自《搞定1》这本书，副标题\u003c无压力工作的艺术>\r\n【事件】：大家会不会有这样的时候， 领导交代一个重要文件，你从周一拖到周六，周日早晨你打开电脑开始行动，一会儿刷个朋友圈，一会儿看个电视剧，最后通宵达旦至天明也没完成。这时候你给自己贴上一个标签——“拖拉机”\r\n【提问】：大家遇到过类似的场景吗？你是怎么处理呢？是不是还没找到一个解决的办法？\r\n【影响】：遇到这类沾染拖延症的问题，如果找不到解决办法的话，你会变得焦虑不安，工作和生活混乱不堪，甚至，你内心会涌现出生无可恋这个词。\r\n【解决】：今天，我们一起搞定它。世界知名时间管理大师戴维•艾伦写了《搞定》1、2、3册书，运用GTD的原则提供一套自我管理工具和无压力工作的艺术，让我们每个人都有机会战胜拖延、做高效行动者。今天我带拆的片段选自《搞定1》。","ratings_count":1,"texts":[{"id":6686,"quote":"\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003c/strong>1、通过本次RIA现场学习后，当学习者面对重要事情因为下一步行动不明确拖延时，能够运用今天我分享的“明确目标完成程度-&gt;设定最后期限-&gt;列出详细步骤-&gt;对比筛选紧急重要项”4个步骤找出下一步行动。\u003c/p>\u003cp>2、说出拖延的定义\u003c/p>\u003cp>&nbsp; &nbsp;3、学习者在面对重要事情拖延时，能够追问出导致自己拖延的真正原因，并根据原因讨论出解决的具体方案。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>下面大家花1分钟阅读下手中拆页一R的内容，看完请抬头示意一下\u003c/strong>\u003cbr>\u003c/p>","explains":"\u003cp>大家都看完了哈，可以把目光聚过来听我讲。 \u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp;【微互动】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>问\u003c/strong>：原文讲到我们处理问题关键的一个步骤是什么？\u003c/p>\u003cp>\u003cstrong>现场小伙伴回答\u003c/strong>：&nbsp;&nbsp; 下一步行动&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;（非常好！都能找到）\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;\u003c/strong>那么什么是真正的下一步行动呢？真正的下一步行动必须符合两个点：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp; 这部分的行动是我们必须率先完成的（紧急的）\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp; 这个行动是其他行动的关键（最重要的，只有这件最重要的做完才能做其他的）\u003c/p>\u003cp>\u003cstrong>【How和举例讲解】\u003c/strong>\u003c/p>\u003cp>那么，当我们在生活中遇到一些重要事情时，该如何去找到真正的下一步行动来推动我们开始着手呢？\u003c/p>\u003cp>举个例子，我今天要完成TF3-3的拆书\u003c/p>\u003cp>\u003cstrong>首先，明确目标的完成程度\u003c/strong>是写完拆书预备表，不是初稿，是最终定稿\u003c/p>\u003cp>明确目标后，\u003cstrong>第二步，设定最后期限，\u003c/strong>用时间紧迫感督促自己\u003cstrong>。\u003c/strong>周四拆书，周三必须完成。\u003c/p>\u003cp>然后，\u003cstrong>列出详细的步骤，\u003c/strong>分解任务让它看起来更容易完成。写拆书预备表分为定主题、选书、看拆书预备表的技能点、选拆页、写预备表，师父指导，自己再次修改。\u003cbr>\u003c/p>\u003cp>最后，\u003cstrong>对比筛选出紧急重要项\u003c/strong>就是真正的下一步行动。先确定主题后才能进行看书找拆页，拆页找到了才能写预备表。对比分析出真正紧急重要的下一步行动是确定主题\u003c/p>\u003cp>当我们能对一项重要事情时，停下来分析真正的下一步行动之后我们就更容易行动起来！\u003c/p>\u003cp>&nbsp;\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>这个方法适用于处理因下一步行动不具体、目标模糊、期限不明确、或者事情有难度的而对重要不紧急事情拖延的情况。如果你由于自己完美主义、恐惧害怕而拖延，你就得重新找办法。\u003c/p>","interaction":"\u003cp>好的，刚才讲解了当我们在生活中遇到一些重要事情时，因为下一步行动不明确而拖延时可以运用4个步骤来推动我们行动起来。\u003c/p>\u003cp>接下来请在小组内自己编一个小故事，设计一段人物角色的对话，其中部分对话运用\u003cstrong>“明确目标的完成程度\u003c/strong>-&gt;\u003cstrong>列出详细的步骤\u003c/strong>-&gt;\u003cstrong>对比筛选出紧急重要项“\u003c/strong>的方法，确定下一步行动推进整件事的进程\u003c/p>\u003cp>故事灵感可以来源于你经历过的拖延重要事情时的焦虑感受，那么未来一个月或者一个周还会发生的拖延的事情你将会怎样解决，结合今天的知识点，把它改写成一个故事。\u003c/p>\u003cp>可以参照示范的下面表格的故事结构，使用第二页的空白表格，写下一段对话。\u003c/p>\u003cp>请小组两人商量着写剧本，按照摘要的形式将你们的剧本写在片段最下面空白处。时间为5分钟哦，5分钟后我们请小伙伴跟大家分享他的剧本。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>\u003cstrong>鼓和二毛 分享：&nbsp;\u003c/strong>\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>时间\u003c/p>\u003c/td>\u003ctd>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 2017年9月下半旬\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>地点\u003c/p>\u003c/td>\u003ctd>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 办公室\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物\u003c/p>\u003c/td>\u003ctd>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 莉莉 和 朋友\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>事件背景\u003c/p>\u003c/td>\u003ctd>导师要求莉莉9月底上交2万字书本初稿，一直拖延着，目前一各字没写，异常焦虑，找朋友倾诉找办法\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物对话\u003c/p>\u003c/td>\u003ctd>\u003cp>主人公A\u003c/p>\u003c/td>\u003ctd>\u003cp>主人公B\u003c/p>\u003c/td>\u003ctd>\u003cp>情节发展\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>完啦！导师要求我下周四交一份书稿的资料，现在一个字没写，拖延症犯了，好焦虑！\u003cbr>\u003c/p>\u003c/td>\u003ctd>\u003cp>你因为拖延焦虑自责是吗？\u003c/p>\u003cp>好的，那你的书稿写作有目标吗？是一次性交还是分阶段，你下周主要完成的目标是什么呢？\u003c/p>\u003c/td>\u003ctd>\u003cp>起因\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>&nbsp; &nbsp;我下周就只用交第一章，大约2万字。\u003c/p>\u003cp>&nbsp; &nbsp;找资料、构思写作的框架、找朋友帮忙整理资料、写作\u003c/p>\u003c/td>\u003ctd>\u003cp>&nbsp; &nbsp; 有目标了，截止日期也明确了，那你如何准备，有详细的计划和步骤吗？\u003c/p>\u003cp>&nbsp; &nbsp; 那你对比过目前你的这些步骤吗？哪一个部分是必须完成了才能进行下一步呢，就是最紧急最重要的部分。\u003c/p>\u003c/td>\u003ctd>\u003cp>经过\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>这样一分析，我只有框架构思完成才能进行其他的步骤\u003c/p>\u003cp>太好了！成功帮我找到了下一步具体行动，不那么焦虑了\u003c/p>\u003c/td>\u003ctd>\u003cp>&nbsp; 那就好，你现在就明确了最重要的部分，那今天拆书完成就回家构思吧\u003c/p>\u003c/td>\u003ctd>\u003cp>结果\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; 感谢鼓和二毛给我带了的精彩分享，鼓找到了她的下一步具体行动去对抗拖延，那么以后我们把今天学到的四个步骤真正用到工作生活中，相信大家也能找到你拖延着的事情的下一步行动\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":6687,"quote":"\u003cp>刚才我们学习了面对重要事情因为下一步行动不明确而拖延时，能够运用 “\u003cstrong>确目标完成程度\u003c/strong>-&gt;\u003cstrong>设定最后期限-&gt;\u003c/strong>\u003cstrong>列出详细步骤\u003c/strong>-&gt;\u003cstrong>对比筛选紧急重要项”\u003c/strong>4个步骤来确定下一步行动。\u003c/p>\u003cp>那么接下来我们就讨论一下因为其他原因导致的拖延该怎么解决？我们从拆页二一起找答案。\u003c/p>\u003cp>下面请大家做一个简单的测试，看看自己的行动力，1分代表完全不符合，5分代表完全符合。请根据自己的实际情况打分，测试完计算下总分。\u003c/p>\u003cp>【下一步行动自测量标题】\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>完全\u003c/p>\u003cp>不符合\u003c/p>\u003c/td>\u003ctd>\u003cp>不\u003c/p>\u003cp>符合\u003c/p>\u003c/td>\u003ctd>\u003cp>基本符合\u003c/p>\u003c/td>\u003ctd>\u003cp>符合\u003c/p>\u003c/td>\u003ctd>\u003cp>完全符合\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 在面对重要事情时， &nbsp; \u003c/p>\u003cp>&nbsp; 我的脑子能冒出各种理由：现在先做别的事，稍后做。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 在面对重要工作时，\u003c/p>\u003cp>我从不主动汇报，等着别人催\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 面对别人询问重要事情的进展时，\u003c/p>\u003cp>我总是说：“让我再看看，再调整下”\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4.&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 在面对重要事情时，\u003c/p>\u003cp>总是直到任务快到最后期限了，我才开始着手做。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5.&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; 在面对重要事情时，\u003c/p>\u003cp>我总是由于时间内紧迫，草草交差，结果被同事和老板嫌弃\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 总分：&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;\u003c/p>\u003cp>大家都测试完了哈，请问有10分以下的小伙伴吗？\u003c/p>\u003cp>\u003cstrong>π和二毛骄傲地举起手\u003c/strong>\u003c/p>\u003cp>&nbsp;非常棒！ 你们与拖延症距离很远，是高效行动派，要继续保持哦！\u003c/p>\u003cp>10-15分的呢\u003c/p>\u003cp>\u003cstrong>鼓举手\u003c/strong>\u003c/p>\u003cp>轻微的拖延，但也具备一定行动力\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;有15分以上的吗？\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;\u003cstrong>倩倩不好意思地举手\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;很不幸，你患上严重的拖延症。别担心，今天收获最大的可能就是你，你有机会找到治愈拖延症的独家秘诀，成为高效行动者！\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>下面请大家花1分钟时间看下拆页二R部分内容，看完请抬头示意下哦\u003c/strong>\u003c/p>","explains":"\u003cp>看到大家都看完了哈，可以把目光聚到这里听我讲。&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003c/p>\u003cp>\u003cstrong>【微互动】问：\u003c/strong>拆页中有提到一个词“最后关头式的紧急任务”大家的生和工作中会有这样的情况吗？\u003c/p>\u003cp>\u003cstrong>答：&nbsp; \u003c/strong>有&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;（有，是吧！） \u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【微互动】问：\u003c/strong>那么，大家想想为什么会出现“最后关头式的紧急任务”呢？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; \u003cstrong>答：&nbsp; &nbsp;&nbsp;\u003c/strong>拖延 &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>【概念对比和案例对比】\u003c/strong>\u003c/p>\u003cp>好，那么什么是拖延呢？\u003c/p>\u003cp>拖延是指自我调节失败，在能够预料后果有害的情况下，仍然把计划要做的重要的和有时限的事情，推到其他时间去做的一种行为。\u003c/p>\u003cp>（拖延有四个关键点：预料到后果有害、已计划要做的；重要的；有时限的事情）\u003c/p>\u003cp>&nbsp;有另一种&nbsp;类似拖延却不是拖延的行为——搁置，就是把某件重要事情，按照详细计划搁置到最后期限前的某个具体时间去做。\u003c/p>\u003cp>（搁置有几个关键点：有详细计划；重要的事情；已经确定具体实施时间）\u003c/p>\u003cp>比如：我们拆书家每周四拆书，在周一把预备表发给师父修改，这个师父时间观念很强，知道修改预备表很重要，但是他会把预备表在周三早晨才修改完给徒弟，徒弟在等的过程中很焦虑，会觉得师父在拖延。其实师父按照自己的时间计划，安排时间在周三早晨修改预备表，并不是拖延。\u003c/p>\u003cp>讲到这里，在我们是不是会想起在你的工作和生活中，有很多拖延重要事情的情况出现呢？\u003c/p>\u003cp>我们在拆页一学习了因下一步具体行动不明确导致拖延的解决办法，下面我们就讨论一下因为其他原因导致的拖延该怎么解决？\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】\u003c/strong>\u003cstrong>微行动学习\u003c/strong>\u003c/p>\u003cp>下面我们会进入到今天的重点部分“微行动学习”。在这个环节需要大家凝结你们的智慧、相互追问去找到你们目前面临的真正的困难，然后再根据大家经验，讨论出具体解决方案和行动步骤。\u003cbr>\u003c/p>\u003cp>首先，大家需要花8分钟的时间进行讨论，注意！讨论的问题是：\u003c/p>\u003cp>\u003cstrong>在我们的工作和生活中，我为什么总是拖延重要任务？\u003c/strong>\u003c/p>\u003cp>我们在小组中不断地追问和剖析，找到真正原因。最后每个小组选择一位小伙伴记录，8分钟后我们请小伙伴跟我们大家进行分享小组的战果。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; （\u003cstrong>现场学习者分组&nbsp;&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp; 第一组：\u003cstrong>二毛、\u003c/strong>倩倩；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; &nbsp; &nbsp; 第二组：莉莉，\u003cstrong>鼓\u003c/strong>）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp; \u003c/strong>初步最终讨论出的原因有：\u003c/p>\u003cp>\u003cstrong>&nbsp;1、畏难\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp;2、懒\u003c/strong>\u003c/p>\u003cp>\u003cb>&nbsp;3、期限太长\u003c/b>\u003c/p>\u003cp>\u003cb>&nbsp;4、不感兴趣\u003c/b>\u003c/p>\u003cp>\u003cb>&nbsp;5、不重视\u003c/b>\u003c/p>\u003cp>\u003cb>&nbsp;\u003c/b>\u003c/p>\u003cp>根据小组分享的结果对讨论出来的真正原因给与反馈\u003c/p>\u003cp>&nbsp; &nbsp; 拆书家提问引导出学习者总结出最本质的拖延的原因是：\u003c/p>\u003cp>&nbsp; &nbsp; 第一组：拖延原因——不重视\u003c/p>\u003cp>&nbsp; &nbsp; 第二组：拖延原因——畏难\u003c/p>\u003cp>&nbsp;接下来大家在你们刚才剖析出来的问题真正原因中一起结合各自的经验去找解决方案，并把解决办法形成具体的行动步骤写下来。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 第一组，解决\u003cstrong>不重视\u003c/strong>的步骤：&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;第二组，解决\u003cstrong>畏难\u003c/strong>的步骤：\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 1、通过愿景明确事情的具体意义&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 1、明确意义\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 2、定目标，SMART原则&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 2、根据最后期限定目标\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 3、找方法&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; 3、拆分目标\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 4、找伙伴监督提醒&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;4、找伙伴监督(自我监督、朋友监督、奖励)&nbsp; &nbsp;\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003cstrong>（催化应用）\u003c/strong>\u003c/p>\u003cp>大家的具体行动方案都找出来了，你可以再回到刚才的自测题看一下，是否有要修改分数的呢？如果有新的想法的话可以在拆书结束后发到我的邮箱，我们继续探讨学习。\u003c/p>\u003cp>&nbsp; 下面有个非常重要的作业，对你巩固应用知识很重要，对我更重要。哈哈~\u003c/p>\u003cp>&nbsp;&nbsp;今天回去后，请大家记录整理下今天在小组中讨论出的解决方案， &nbsp; 在一两天内找你的同事或者朋友分享一下，分享你今天剖析出来的你遇到的问题真正原因的解决方案。把你们的分享要点简单记录下来发到我的邮箱：[email] 我们再继续探讨学习。\u003c/p>\u003cp>\u003cstrong>学习者倩倩作业反馈：\u003c/strong>\u003c/p>\u003cp>每次报名拆书开始后都拖延着到最后时刻没写出拆书预备表，感觉自己很糟糕很沮丧，以后我会这样做：\u003c/p>\u003cp>第一，明确意义，完成三级拆书后能给自己带来的收获，比如自身逻辑思维的提升、结交新朋友、锻炼意志力\u003c/p>\u003cp>第二，每次报名后都知道自己的目标是：写完预备表就是目标\u003c/p>\u003cp>第三、拆分目标，具体什么时间定主题、选拆页、完成初稿、什么时候给师父修改都会有一个明确的时间点。\u003c/p>\u003cp>第四、找监督伙伴，跟同期的拆书家建立微信小群，相互提醒比较。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>&nbsp;\u003cstrong>【结语】\u003c/strong>\u003c/p>\u003cp>好，我们总结下今天花了近一个小时学习的知识点：\u003c/p>\u003cp>第一、我们学习了当我们面对重要事情因为下一步行动不具体拖延时，能够用 &nbsp; “\u003cstrong>确目标完成程度\u003c/strong>-&gt;\u003cstrong>设定最后期限-&gt;\u003c/strong>\u003cstrong>列出详细步骤\u003c/strong>-&gt;\u003cstrong>对比筛选紧急重要项”\u003c/strong>4个步骤来确定下一步行动而推动任务开始。\u003c/p>\u003cp>第二、找到了为什么拖延重要任务的原因，还找到了解决方案。在以后的生活工作中把自己学到的知识点应用起来吧，相信我们也能成为高效行动派！谢谢大家！\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1506685323000,"updated_at":1521007608000,"ria":true},{"id":3772,"topic":"解除精神负担，高效工作","learn_goal":"解除精神负担，高效工作","remark":"从你今天早晨醒来到现在 ,你是否想到了一些需要处理但未动手解决的事情呢? \r\n你是不是不止一次地想到了它们呢? 为什么？\r\n    不断地考虑那些毫无进展的事情纯粹是浪费时间和精力，而这往往会使你更加焦虑不安。\r\n相信么？\r\n解除精神上的负担，在轻松的状态下，你也能跟随内心的承诺，权衡取舍，高效平衡工作和生活。\r\n本周四，相约如果咖啡，一起和果粒学习一小时~","level":"TF3-3","duration":60,"status":0,"type":0,"chaishujia":{"username":"果粒","city":"北京市"},"club":{"name":"北京紫禁之巅分舵","city":"北京市"},"prologue":"【学习目标】通过本次RIA现场学习后，当学习者下一次因为生活中悬而未解决的事情产生焦虑时，能够运用今天我分享的“记录收集->明确意义->下一步行动->清除”的四个步骤列出应对的新计划。\r\n【图书介绍】家好，我是果粒，今天我带拆的片段选自《搞定1》这本书，副标题\u003c无压力的工作艺术>\r\n事件：你会不会有这样的时候，好不容易熬完五个工作日到周末，可以放松下看个电影啥的，却时刻被一些需要处理但未动手解决的事情搞得焦虑不安；或者当你眼前摆着一堆重要事情却因找不到下一步的具体行动而一拖再拖、一动不动呢。\r\n提问：大家遇到过类似的场景吗？你是怎么处理呢？是不是还没找到一个解决的办法？\r\n影响：遇到这样的问题，如果找不到一个合理有效的解决办法的话，你会变得焦虑不安、喜怒无常，重要的事情耽误了，休息时间也浪费了，此刻的你，内心涌现出生无可恋这个词。\r\n解决：没关系，世界知名时间管理大师戴维•艾伦写了《搞定》1、2、3册书，运用GTD的原则提供一套自我管理工具，让繁忙的人们解除精神负担，让我们每个人都有机会做高效行动者。今天我带拆的片段选自《搞定1》。","ratings_count":0,"texts":[{"id":6685,"quote":"\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>下面大家花1分钟阅读下手中拆页一R的内容，看完请抬头示意一下\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>","explains":"\u003cp>大家都看完了哈，可以把目光聚过来听我讲。 \u003c/p>\u003cp>\u003cstrong>【微互动】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>问\u003c/strong>：原文说大脑会不由自主、自动帮助我们记住什么？\u003c/p>\u003cp>\u003cstrong>答\u003c/strong>：&nbsp;&nbsp; 未尽事宜&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;（非常好！都能找到）\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【微互动】问：\u003c/strong>那么什么是未尽事宜？大家如何理解呢？\u003c/p>\u003cp>\u003cstrong>答：\u003c/strong>未处理完的、有意义的、必须要完成的事情（大家都能有各自的想法，很好！）\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【概念讲解】\u003c/strong>\u003c/p>\u003cp>今天我们讲的未尽事宜是指我们给某项任务贴上“需要做”或者“应当做”的标签，对你来说潜在着某种意义并且已经有所计划，但因尚未付出行动，它就藏匿在你脑中的某个角落消磨你精力的一些相对琐碎而不紧急的事情。 \u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【How和举例讲解】\u003c/strong>\u003c/p>\u003cp>那么，当我们在生活中遇到这类未尽事宜，该怎样去清除它给你带来的精神负担，从而有一个轻松的内在自我去专注其他重要的事情呢？\u003c/p>\u003cp>举个例子，我近期需要调整汽车发动机和看牙医，但迟迟没有完成，它们又总是在我的脑海挥之不尽。\u003c/p>\u003cp>首先，\u003cstrong>记录收集未尽事宜\u003c/strong> ；一想到就找记事本或者app罗列记录下来\u003c/p>\u003cp>第二步\u003cstrong>，明确事情的意义\u003c/strong> ；调整汽车发动机解决我出行困难问题；看牙医方便吃东西、有益于健康\u003c/p>\u003cp>接着，\u003cstrong>确定下一步行动\u003c/strong> ；好多未尽事宜关键问题不在于没时间，而是不清楚下一步该做什么。所以，给每件确定的事情规划处下一步具体的行动促使自己去完成很重要。预约调整发动机的时间；预约看牙医的时间。\u003c/p>\u003cp>最后，\u003cstrong>把这些事务清除出大脑 。\u003c/strong>根据下一步行动做起来，然后把它们通通清除出大脑，\u003cstrong>【预防异议】\u003c/strong>即使你担心忘记某件事，只需要回顾你的第一步的记录表去检查，不用一悬在心里惴惴不安。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>刚才讲解的方法适用于处理一些相对琐碎、有一定意义却不紧急的未尽事宜，比如写报告等需要我们经过长时间思考和周密计划事就不适合用这个方法。\u003c/p>\u003cp>刚才提到的看牙医，如果是在牙疼得你生无可恋的情况下，你就得马上去看，这时候看牙医也成了紧急重要的事情，就不再是未尽事宜，这个方法也不适用。\u003c/p>","interaction":"\u003cp>好的，刚才讲解了当我们在生活中遇到一些未尽事宜让我们一度焦虑时，可以运用4个步骤来处理。\u003c/p>\u003cp>接下来请在小组内自己编一个小故事，设计一段人物角色的对话，其中部分对话运用“\u003cstrong>记录收集\u003c/strong>-&gt;\u003cstrong>明确意义\u003c/strong>-&gt;\u003cstrong>确定下一步行动\u003c/strong>-&gt;\u003cstrong>清除出大脑\u003c/strong>”的方法，使人物对问题的回应产生情节变化（有起因、经过、结果） 。\u003c/p>\u003cp>故事灵感可以来源于你经历过的未尽事宜缠身时的焦虑，你当时是怎样处理的，结合今天的知识点，把它改写成一个故事。\u003c/p>\u003cp>可以参照示范的下面表格的故事结构，使用第二页的空白表格，写下一段对话。\u003c/p>\u003cp>请小组两人商量着写剧本，按照摘要的形式将你们的剧本写在片段最下面空白处。时间为5分钟哦，5分钟后我们请小伙伴跟大家分享他的剧本。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>时间\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>地点\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>事件背景\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>人物对话\u003c/p>\u003c/td>\u003ctd>\u003cp>主人公A\u003c/p>\u003c/td>\u003ctd>\u003cp>主人公B\u003c/p>\u003c/td>\u003ctd>\u003cp>情节发展\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>起因\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>经过\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003ctd>\u003cp>结果\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1506684869000,"updated_at":1506684869000,"ria":true},{"id":1601,"topic":"如何建立组织整理系统","learn_goal":"学完后，学习者能够建立一个完整的、没有漏洞的组织整理系统。","remark":" 戴维·艾伦的《搞定Ⅰ-无压工作的艺术》(Getting things Done)已经成为时间管理领域最具影响力的著作之一，书中介绍的GTD(Getting Things Done)时间管理方法也成为全球千万读者用来轻松高效完成工作与个人事务的最佳工具。GTD看似简单易行，其背后却有深刻的洞见。","level":"TF3-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"郑先鹏","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":"事件场景 ： 大家在平时的生活工作中，有没有遇到自己因为某项工作没有完成被领导批评，或者发现自己到了晚上睡觉的时候发现还有好多事没有完成，每天都在忙忙碌碌的生活。但是大都数人都没有进行改变，日复一日的重复上面的场景。提问：大家认为不去改变，继续这样的生活方式好吗？影响：如果我们继续这样下去，我们就会越来越焦虑，每天都很忙但又不知道自己在忙些什么，升职加薪的机会离我们越来越远。解决：《搞定Ⅰ：无压工作的艺术》这本书中的五个核心原则是：收集、整理、组织、回顾、执行，可以很好的帮你解决问题，甚至比你想象的还要好。","ratings_count":0,"texts":[{"id":4155,"quote":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 一个完整的、没有漏洞的组织整理系统，可以赋予你无穷无尽的力量，因为它可以让大脑彻底摆脱那些低层次的思维，把精力投入到更重要的事情中，并且不会留下任何未经处理的事物来分散你的精力。但是，你的组织整理系统一定要比你自己的大脑更可靠，这样你才能信任它、依赖它，这也是实现上述目标的基本前提。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 组织整理意味着让某个事项所处的位置与其意义相匹配。如果你决定把某事项保存为参考资料，把它存放在必要的位置，这就是组织整理。如果你认为需要提醒自己打一个很重要的电话，只要你把提示内容存放在适当的位置，你就是在进行组织整理。人们试图组织整理的很多事项都不够明确，而且即使这些事项足够明确，也有可能存在细微的区别，从而对你的创造力和控制力提出了更高要求。\u003c/p>","explains":"\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在这个拆页，我们看过了“组织整理系统”的重要性。怎么样才是一个完整的、没有漏洞的组织整理系统呢？你今天把脑子里想的事情放进了工作篮，但是没有下一步行动，这叫好的组织整理系统吗？不是，因为你没有行动。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 你把脑子里的事情放进了工作篮，也对里面的事情进行了分类，确定了下一步行动，当你拿出清单的时候发现今天要做的事情都已经做完了，可以松一口气的时候，却突然发现你还有一件重要的事情忘记去做。这叫好的组织整理系统吗？这不是，因为你的收集不完整，存在漏洞，不会让你去信任它、依赖它。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 你的工作篮收集的很完整，事情也都按照安排全部完成，但是完成的结果让人很不满意，请问这叫好的组织整理系统吗，这也不是，因为你没有关注结果，所以做事效率很低。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 所以，我们从组织管理系统的要点和原则，能够归纳出建立一个好的组织整理系统最核心的步骤：第一步，将大脑中的所有事情进行收集，放进我们的工作篮中，在收集过程我们一定要确保我们的收集要完整，另外养成一个经常收集的好习惯；第二步，对工作篮中的事情进行分类清空，根据我们是否需要采取行动进行分类，如果是否的话，我们可以将它放入垃圾箱、将来也许清单或者参考资料中，如果是是的话，我们需要再进行判断，根据这件事是否两分钟完成，如果可以两分钟完成的马上执行，如果不能的话，我们可以选择委派他人、放入日程表或者下一步行动清单中；第三步，定期回顾你的系统，反思其内容，保持其时效功能；第四步，选择最合适的行动，如何来选择行动我们可以根据四象限法则以及六层次法来进行判定。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我们拿一个简化的具体例子来看一下：我的收集篮中的事项有：练习书法、看《美丽心灵》、学习前端开发、考MBA、请朋友吃饭、整理读书笔记、做PPT、开会、写工作报告、统计工时、登月球、看《关键对话》；然后我对收集篮进行清空，里面没有一项可以在两分钟内完成，把登月球放进垃圾箱，有些人认为有些事没有必要写进收集篮，这个很有必要，因为你不写下来，你的大脑就会想到它，就会影响你做事，练习书法、考MBA放进将来也许清单中剩下的都放进下一步行动中，对下一步行动再进行分类，其中开会和请朋友吃饭是指定时间去做的，将它放进日程表，另外做PPT、写报告和统计工时是工作上的事情，我会放进工作清单中，可以在上班的时候完成，看《关键对话》、看《美丽心灵》、学习前端开发是业余时间去做的事，我会放进在家时清单；剩下的就是经常看我们整理的清单系统，根据我们的情景选择合适的行动。\u003c/p>","interaction":"\u003cp>\u003cstrong>拆书家提问设计：\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;下面请大家编一个故事，在这个故事中，有人物角色、情节变化（包括：起因、经过、结果）以及双方的对话&nbsp;，要求其中一方讲述了他在生活中遇到的难题（工作生活无法得到平衡），另一方运用今天学到的GTD思想帮他解决。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;请大家以小组讨论的形式来进行，可以把其中的一些关键词写在一张纸上。时间是5分钟。&nbsp;5分钟后，我将请一位代表来讲述他们小组编出的故事。&nbsp;&nbsp;&nbsp;&nbsp;\u003c/p>\u003cp>\u003cstrong>学习者分享：\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 学习者01：我经常做事容易丢三落四，原因是我总喜欢用大脑记忆要做事项。我运用今天学到的知识将我今天一天的事情都收集下来：洗衣服、给爸妈打个电话、写一篇读后感、复习高数 。其中给爸妈打个电话可以在2分钟左右完成，我就马上给爸妈打个电话，然后在上午将衣服洗完，再写完读后感；其中复习高数是一个项目，我将其进行分解，每天复习一章，安排在下午完成。\u003c/p>\u003cp>\u003cstrong>结语：\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 今天我们学习了如何了如何建立属于自己的组织整理系统，希望大家回去以后多加练习，相信当你运用之后，一定可以给你的生活带来巨大的变化！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1481631700000,"updated_at":1481631720000,"ria":true},{"id":1007,"topic":"高效2分钟！","learn_goal":"用2min提高效率","remark":"未批复的文件堆积如山，未处理的邮件越来越多，紧急事件仍接踵而至，原来的计划全部被打乱，不满情绪开始蔓延，如何从容不迫，大唐带你用“高效2分钟”走出泥潭。","level":"TF2-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"大唐","city":"北京市"},"club":{"name":"北京宇宙中心分舵","city":"北京市"},"prologue":"大家好，我叫大唐。","ratings_count":0,"texts":[{"id":3189,"quote":"\u003cp>\u003cstrong>高效\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>分钟\u003c/strong>\u003cstrong>&nbsp; \u003c/strong>摘自《搞定I》193-194页\u003c/p>\u003cp>即使你面对的并不是什么重要任务，如果你能在两分钟之内完成，那就应该立即完成将其完成。这个“两分钟原则”的原理是：对于任何任务，保留、跟踪、最后完成它所花费的时间，要比立刻完成它花费的时间更长——换句话说，这是一条提高效率的捷径。如果一件事情根本不值得你去完成，那么就把它丢入垃圾桶；但只要这件事情是你迟早要做的，那就需要考虑到“效率”这个因素。\u003c/p>\u003cp>许多人发现，遵守“两分钟原则”并养成习惯后，他们的工作效率有了大幅度的提高。一位软件公司副总经理告诉我，这个原则让他每天多出了1小时的自由时间！他每天要在工作时间处理300封电子邮件，还要完成大量的企业日常事务。这些电子邮件几乎都是他的下属发来的，大部分是向他汇报工作，需要他对某些事情做出批示。但是因为这些邮件并不是他每天工作的重点，所以他任由它们堆积在收件箱中，等待“稍后处理”。当堆积下来的邮件达到几千封之多的时候，他就不得不花费整个周末的时间来处理完这些邮件，这样才能赶上工作的进度。如果他是个二十六七岁的小伙子，这也许不是什么问题，但是他已经三十好几了，并且有了自己的孩子，周末加班几乎是不可能的了。在我辅导他的时候，我和他一起处理了收件箱中的800多封邮件，结果发现其中大部分是可以直接删除的，个别邮件需要作为参考资料归档，剩下的大部分可以在两分钟之内简短回复一下。一年以后我和他取得了联系，两分钟原则对他依旧管用！他邮箱中堆积的邮件再也没有塞满整个屏幕。他说，这个简单的“两分钟原则”大大缩短了他的任务响应时间，让他的工作方式和态度大大改观。他的同事都说他是由“特富龙” 那样的高性能材料制成的。\u003c/p>\u003cp>上面这个例子似乎有点夸张，但它的确向我们揭示了这些简单的处理原则是多么的重要，特别是当你接受的任务越来越多、速度也越来越快的时候。\u003c/p>","explains":"\u003cp>\u003cstrong>学习目标\u003c/strong>：在跟随我完成本次RIA现场学习后：\u003c/p>\u003cp>1、学习者能够理解：要事优先的原则，与2分钟法则，并不矛盾；\u003c/p>\u003cp>2、学习者能够学习到：对于2分钟内能完成的任务，不去考虑这件事的重要紧急程度，立即完成。\u003c/p>\u003cp>\u003cstrong>F\u003c/strong>：《搞定》的作者是世界知名时间管理大师戴维·艾伦，全球数以千万计的人在按他的GTD原则处理事情，很多大腕明星高管都将自己生活和工作的巨大成就归功于GTD，GTD这个单词正是从这套书的英文名“Get Things Done”而来。\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>：《搞定》这套书的特点是有成体系的解决方案，你可以系统性采纳，里面也有大量处事原则与零散建议，你也可以独立运用，另外这套书也一直紧随现今科技的快速发展一直更新改版，与时俱进。\u003c/p>\u003cp>\u003cstrong>B\u003c/strong>：当你想维持工作与生活的平衡，但整日事务缠身，顾此失彼时，这套书能极大提高你的效率。我们有什么好的办法处理耗费时间不多，也难于分清“紧急”与否的事情呢？今天我分享的片段提供了答案。\u003c/p>\u003cp>\u003cstrong>&lt;I：拆书家讲解部分&gt;\u003c/strong>这个片段讲述的是当你面对的并不是重要任务时，如果你能在两分钟内完成，那就立即将其完成。但我们知道管理学大师彼得·德鲁克也有个“要事优先”原则，简单来说，这两位大师都说，要把重要的事放在前面先做。这两套理论，似有矛盾之处，但我们的理解不能停留在字面上。彼得·德鲁克同时也说过要弄清楚哪些事情必须优先，有四条法则来决策，不能轻易延缓任何工作，并且其中有一条是：摆脱已经不再有价值的过去。换句话来说，彼得德鲁克认为一项工作来了后，要先决策重要性，再去做重要的事。那这跟戴维艾伦的“两分钟原则”并不矛盾，因为决策过程就包含在这两分钟内，并且如果决策出这件事需要做，而且2分钟就能完成，那就立即完成它，因为将来保留及将来追踪这件事的成本都会超过这2分钟。\u003c/p>\u003cp> &nbsp;&nbsp;\u003cstrong>&lt;\u003c/strong>\u003cstrong>给出更贴近学习者的例子&gt;\u003c/strong>如果事情都延期到集中时间处理呢？我这有个刚刚发生的例子。最近因为事情比较多，我有个我认为目前是重要的程序没写完，于是在周五的下午，就专心写程序，一切其他事务一概不管，结果一下午有2个人向我要系统数据，有3个人问我项目进展，有4个人问我合同到款情况，有5封邮件让我确认。我都置之不理，实际上我也被这些事干扰了，邮件、QQ、微信一直在闪。等到周五快下班时，有一位同事在QQ上给我发振动，震的我吓一跳，另外两位同事将邮件抄送给了更高的领导，我还是置之不理。结果，下班后的晚上，一位同事居然委托另外部门平时不怎么沟通的领导问我的情况，我不得不回复下说等周一早上马上处理。然后，今天我一早就来到公司，把可以马上处理的事都处理了，其实大部分事都是2分钟内就能完成的，比如查询合同到款情况，但我需要把那些事一个一个找出来 ，多花了些时间，然后因为多了几个领导的关注，又额外多花了些时间。最后算下来，差不多比不延缓处理那些事情加起来的总时间多了一倍，而且显然同事对我的不满情绪增加了。\u003c/p>\u003cp>&nbsp;&nbsp;\u003cstrong>&lt;强调不这么做的坏处&gt;\u003c/strong>如果不这样做，像我这样造成的后果是：1、因为区分是否“紧急”的标准不一致，导致紧急的任务被延误；2、延期后花费的总时间超过立即解决需要花费的时间。3、个人绩效下降。实在是得不偿失！\u003c/p>","interaction":"\u003cp>\u003cstrong>A1：\u003c/strong>那大家看到了我只根据我认为的事情重要程度优先级来做事，导致的坏处。接下来，请你们回想下，你们在工作和生活中，通常是如何处理2分钟任务的？设想这样一个场景：有没有这样一件小事，比如打个电话，取个快递，回封邮件，明明2分钟就可以处理完，你却觉得它无关紧要，一直拖着不做，却还心里一直挂念耗费精力，甚至最后产生更严重的后果？以小组为单位讨论下，告诉大家你曾经拖着不做，然后造成不良后果的事。每4个人一组，用时2分钟。\u003cbr>\u003c/p>\u003cp>\u003cstrong>&nbsp; 学习者设计君\u003c/strong>：这几次参加完拆书帮活动后，本来要做的笔记，其实2分钟就可以做好，但一直拖着没做。\u003c/p>\u003cp>\u003cstrong>&nbsp; 学习者欠费姐\u003c/strong>：公司又一次组织游园的活动邮件，当时没处理，其实处理下很简单只需要花30秒时间，等几个星期后，花了好长时间去找到这封邮件，等找到时活动已经过期了。\u003c/p>\u003cp>\u003cstrong>&nbsp; 学习者叶子\u003c/strong>：在花钱记账或是敷面膜的时候，有时比较纠结。\u003c/p>\u003cp>\u003cstrong>A1+\u003c/strong>\u003cstrong>：\u003c/strong>刚小伙伴分享的很好。其实2分钟只是一个原则，当你有足够充裕的时间时，可以把这个“2分钟”限制延长到5或是10分钟，如果时间不充裕时，可以把时段压缩到30秒或1分钟。请小伙伴们考虑下,自己刚才失败的A1，如何用这个行动建议完成？\u003c/p>\u003cp>\u003cstrong>&nbsp; 学习者叶子\u003c/strong>：花钱记账的时候，我用随手记app，每次其实很简单，都用不了2分钟。\u003c/p>\u003cp>好，今天拆解的内容，就是在日常工作生活，当各位遇到一些2分钟内能解决的事情时，不要纠结于这个事是否重要，而是马上去完成它，这样可以减轻日后的维护成本与心理负担，让各位轻松踏上工作与生活的旅程，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1475205198000,"updated_at":1500088828000,"ria":true},{"id":644,"topic":"确定某一时刻具体行动的“四标准法”","learn_goal":"通过情境、时间、精力及重要性等四要素来选择某一时刻的具体行动","remark":"这本《搞定1 无压工作的艺术》的作者是戴维.艾伦，他被誉为世界最具影响力的工作效率问题思想家。书中的横向管理工作流程的5个步骤和纵向管理项目的5个阶段，可以帮助人们轻松高效地完成工作。这本书是亚马逊畅销榜前列的个人事务管理经典，是全球数千万人在学习使用的管理个人事务的最佳工具，它风靡全球十余年，是全球工作者都在学习使用的具体的时间管理系统。\r\n","level":"TF2-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"兰","city":"上饶"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"在跟随我完成本次RIA现场学习后，学习者能够根据情境、时间、精力、以及事情的重要性四个标准，来确定某一时刻的具体行动，以提高时间管理效率。\r\n这本《搞定1 无压工作的艺术》的作者是戴维.艾伦，他被誉为世界最具影响力的工作效率问题思想家。书中的横向管理工作流程的5个步骤和纵向管理项目的5个阶段，可以帮助人们轻松高效地完成工作。\r\n这本书是亚马逊畅销榜前列的个人事务管理经典，是全球数千万人在学习使用的管理个人事务的最佳工具，它风靡全球十余年，是全球工作者都在学习使用的具体的时间管理系统。\r\n你是否希望自己能在任何情况下，任何时间内都能够随心所欲地控制自己的一切事务？是否希望把100%的精力投入到自己选择的工作中而不受任何外界的干扰？是否希望能通过掌握一个难以置信的实用方法，轻松高效完成工作，让繁忙的你重新掌握自己的生活？如果是的话，那么这本书可以有效地帮助到你。","ratings_count":0,"texts":[{"id":1929,"quote":"\u003cp>确定某一时刻具体行动的&quot;四标准法&quot;。\u003c/p>\u003cp>在星期三下午3点22分时，你如何选择下一步行动呢？这个时候，你可以按顺序采用下面4个标准：情境、有多少时间、有多少精力和重要性。\u003c/p>\u003cp>前3个标准描述了你每次采取行动的制约因素，第四个标准则是评估行动的价值大小。\u003c/p>\u003cp>情景&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;每时每刻，你都会受限于自己的行动能力。只有很少一部分事情对地点没有特别要求（像拿一支钢笔和一张纸就可起草对一个项目的想法），但是，大多数事情都只能在特定的地点完成（在家或办公室），或者需要借助某些特定的工具（如一部电话、一部电脑），而这正是限制我们行动选择的首要因素。\u003c/p>\u003cp>有多少时间&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;你所能支配的时间长短也是一个重要的限制因素。如果5分钟后你必须去开会，你现在就不可能去执行那些耗时更久的行动。\u003c/p>\u003cp>有多少精力&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;你有多少精力呢？某些事情需要你头脑清醒，思路清晰，富于创造力，而另一些只要求你具备充沛的体力。还有一些事情则对这两方面都没有特别要求。\u003c/p>\u003cp>重要性&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;当你考虑了情境、时间、精力这3个条件后，最后你就要判断哪个行动选项会给你最高的回报了。现在你有一个小时的时间，你坐在办公室里守着电脑和电话，你的精力指数为7.3，你应该做些什么呢？给客户回个电话，考虑一下新的提案，处理一下语音信箱里的留言和电子邮件，或者联系一下你的朋友，看一看他今天过得怎么样？\u003c/p>","explains":"\u003cp>在生活中，大多数人很有可能会在某个具体时刻，面对一长串的待办事项清单，却不知道下一步该做哪件事，或者做了却没有在正确的时间做正确的事情，从而无法使自己进入最高办事效率状态。\u003c/p>\u003cp>那我们该如何高效地确定某一时刻的具体行动呢？从刚才的原文片段获知，可以根据下面四个标准来确定。\u003c/p>\u003cp>首先，情境，即根据你所处的地点及周围的环境来决定你该做什么。\u003c/p>\u003cp>然后，时间，根据现在所能支配的时间判断适合做哪件事。\u003c/p>\u003cp>接着，精力，根据你的精力指数来进行事项选择。\u003c/p>\u003cp>最后，事项的重要性，经过前面的3个标准的筛选，再根据事项的重要性的先后顺序，就可以确定具体行动了。\u003c/p>\u003cp>跟大家分享一个我的例子，某个早上9点到10点，孩子在上围棋课，我一人在家，有很多事情要做：1.洗衣服，打扫卫生；（在家，40分钟，精力指数2.0以上，需要做但不重要）2.每日共读100字以上的分享；（在家，40分钟以上，精力指数8.0以上，重要指数8.0）3.有一个非常好的微课要爬楼；（随时都可以，40分钟左右，精力指数6.0以上，需要但不重要）4.拆书预备表的修改；（随时，40分钟，精力指数8.0以上，重要指数10）5.超市购物（外出，1小时，精力指数4.0，重要指数4.0）\u003c/p>\u003cp>如果我不根据原文片段的“四标准法”来确定我下一步该做什么？那么我会挑选简单易操作的事情来做，比如，洗衣服，整理房间，再看看微信群聊，直到9：50匆匆忙忙去接孩子。接下来我又会在自己精疲力尽时，加上熊孩子的骚扰等等这样的时间来完成诸如100字分享等等事项，或者直接被其他接踵而来的事情而耽误以致于无法如约完成，因为有些事的确需要一整段且精力较好的时间来完成。\u003c/p>\u003cp>那么如果我能稍作思考，按照原文片段的“四标准法’来理清这些事项，确定下一步行动，那又会怎么样呢？请大家注意，这个时间，是早上9点到10点，是一个不会被熊孩子打扰的时刻，也是我精力最好的时候。\u003c/p>\u003cp>首先，情境（在家），没有熊孩子在身边，除去超市购物，其他事项都可以做。\u003c/p>\u003cp>其次，时间一个小时。我可以修改拆书预备表、100字分享或微课爬楼等。\u003c/p>\u003cp>接着，精力指数8.0。非常适合完成拆书预备表和共读分享。\u003c/p>\u003cp>最后，按事项重要性确定下一步行动。那么我应该做得应该是完成拆书预备表。\u003c/p>\u003cp>如此，完成了一天中的”大石头“，那么其他”小沙粒“也能顺势在其他碎片时间得以完成。\u003c/p>","interaction":"\u003cp>拆书家提问设计：\u003c/p>\u003cp>有没有在某个时间段过去后，你会发出这样的感叹：其实我本应该可以做先做那件事的，其实我可以趁着那个时候来完成某件事的，其实……\u003c/p>\u003cp>或者你也有这样的一个经历，孩子上兴趣班，前后一个小时，你一人坐在教室外的长廊里，虽然外面艳阳高照，但里面有wifi，空调开放，非常舒服惬意，你的精力指数是8.2。然后你可以做很多事情，比如，回家洗衣服，打扫卫生；打开有道云修改三天后要用的拆书预备表或者其他对时间、精力要求较高的事情；或者轻松片刻，参与手机群聊，刷朋友圈、看电视，玩游戏等等或者其他你会做的事情？\u003c/p>\u003cp>请小伙伴们试着在脑海中想一想，你一般情况下会怎么来打发这么一个时间段？而且这样的一个时间过后，会让你感觉到你本应该做某件事却没有做，或者本应该先做某件事却没有这样做的？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者1：上次我陪孩子上游泳课，本是可以完成当天的拆书任务的，但后面却把时间话费在看手机微信，然后和其他孩子家长闲聊上。\u003c/p>\u003cp>学习者2：前些天我本是打算完成拆书预备表的，可一直把这件事往后推，希望可以在孩子睡下来之后再开始，但真正等到孩子睡下后，自己也筋疲力尽了，最后事情没有如约完成。\u003c/p>\u003cp>A1+（反思加工）\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>那么，如果上帝再给我们一次重来的机会，那么我们该如何通过思考，理清待办事项，根据原文片段的‘四标准法’来确定下一步行动呢？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>&nbsp;学习者1：如果实在避免不了的话，我可以简单寒暄几句，然后借故离开，找个清静的地方完成拆书练习，因为我觉得做好这件事比闲聊更重要。\u003c/p>\u003cp>学习者2：其实我可以在孩子看书或做其他事情时来完成我的拆书预备表，而不是做些无足轻重的事情，把重要的事情推到最后。因为时间太晚，精力不足的情况下去做预备表的效率太低。\u003c/p>\u003cp>结语：或许你有着你自己的做事方式方法，自己的打算，但如果你能练习使用今天的四标准法来确定你某一具体时刻的行动会让你变得更加非凡高效。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1469431564000,"updated_at":1469432644000,"ria":true},{"id":455,"topic":"2分钟思考带来的平和","learn_goal":"构建以结果和行为为导向的思维方式","remark":"世界知名时间管理大师戴维艾伦的经典著作，全球千万人正在轻松适用的GTD个人事务管理系统。","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"熊媛","city":"上饶市"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家好，我叫熊媛，是二个孩子的妈妈，我用三个标签介绍一下我自己：1.新手拆书家，介绍海量阅读的这2年让我在寻找更好的读书方法，有幸遇上了拆书帮。 2. 基督徒 我是十年前读到圣经，认识真理，成为基督徒。 3. 我喜欢旅行和阅读。 读万卷书，行万里路是我喜欢的一句话。 \r\n 今天是我的《拆书家成长手册》V3 TF1-1的训练项目：是用10分钟时间当众表达我的一套RIA便签。我选的片段来自我最近在读和实践的书籍《搞定》I.这是时间管理大师戴维艾伦的一本经典著作，他致力于探索和提炼无压工作的原则，希望帮助人们消除压力和焦虑，从而在存在的每一刻都致力于最想追求的目标。\r\n 先谢谢大家为我付出的宝贵时间，希望能给你们带来启发和收获。","ratings_count":0,"texts":[{"id":1060,"quote":"《搞定》I P19 检验这种模式的一个重要训练\r\n 我建议你拿笔记下目前盘踞在你大脑中的那些最重要的工作或状况。哪一件事最让你心烦意乱？哪一种情况最容易分散你的注意力？哪一个问题令你兴趣浓厚？或者哪一种局面以哪种方式消耗了你大量的精力？也许，正是”摆在你面前的“某项工作或者某种状况必须要处理，而且越早处理越好。\r\n 也许，你马上就要背上行囊外出度假。出发之前，你还有几个重大决策要敲定。你刚刚收到的电子邮件事关部门某个亟待解决的新问题。或许你刚刚继承了一笔600万美元的遗产，而你不知道该如何处置它，等等。 \r\n 明白了吗？好，请用简单的一句话来描述一下，你希望得到的理想结果是什么。换句话说，事情怎样才算得上是完成了呢？这可能非常简单，就像”去夏威夷度假“、”处理有关客户X的事情“、”与苏珊协调大学里的情况“、”弄清新的部门管理结构“、”实施新的投资策略“，或者”研究关于曼纽尔阅读问题的解决方案“。你现在都清楚了吗？好极了。\r\n 现在，请写下为了推动事情的进展，你需要采取的下一步实际行动。假设你手头没有其他事情，只有这一件事情需要立即完成，那么你下一步的具体行动是什么？你会不会给某人打电话或者发短信？会不会写一封电子邮件？会不会取出纸和笔，来一场头脑风暴？会不会去上网搜索数据？会不会去五金店买钉子？有没有可能与你的伙伴、助手、律师或你的老板面对面地谈上一会儿呢？你会怎么样呢？\r\n 你找到答案了，是吗？好极了。\r\n 你能从这短短2分钟的思考中挖掘出什么有价值的东西吗？如果你同那些在研讨会上完成此项训练的大多数人一样，那么，你就会体验到，至少你的控制力增强了一点，精神放松了一些，注意力也更集中了。此外，对于某些长久以来一团乱麻的局面，你似乎也有了动手解决它的冲动。设想一下，在生活和工作中，这种驱动力放大1000倍时将会是怎样一番景象。\r\n 如果这个小试验能对你产生一些积极影响，请你想一想：究竟是什么发生了变化？根据你的经验，是什么促使局面得到了改观？形势本身并不会向前发展，至少在这个物质世界中这一点是千真万确的。有所改变的，只是你更加明确了所期盼的结果，并确定了下一步需要采取的行动方案。真正发生改变的，是有关梳理、关注与平和心态的重要因素：你如何处理自身的状况。\r\n 然而，是什么创造了这一切呢？答案不是”进行组织整理“或者”确定优先事项“，而是”思考“。 你不需要进行太多思考，你只需要几分钟，就能排除无关压力，集中精力利用必要的机会和资源。人们会进行很多思考，但大多数思考只涉及某个问题、项目或者某种状况----而不涉及思考本身。如果你真的采用了书中建议的措施，你就需要构建以结果和行动为导向的思维方式，而这种思维方式需要你有意识地进行培养。因为人的反应是自发的，而思维不是。","explains":"这个片段向我们展示的是核心知识点是“有意识地去构建以结果和行动为导向的思维方式。”第一部分作者描绘了2分钟思考的过程：将大脑中的想法记下，让大脑集中于思考，用一句话来描述理想结果，从而找出下一步具体的行动。第二部分是在体验后的感受：控制力增强了，精神放松了，注意力集中了。第三部分得出结论：客观思考后，形势本身没有向前发展，但我们自身发生了变化。而这种无压的变化是思考本身带来的。所以我们需要有意识地构建以结果和行动为导向的思维方式。","interaction":"A1: 我在5月对如何进行下一步的拆书有很多困惑和想法，我无法平衡个人目标-三级拆书家，和组织目标-分舵转正，特别纠结。每天大脑中盘旋着许多悬而未决的想法：去南昌参加拆书活动？什么时候开始召集线下活动？有多少人愿意参加拆书活动？大家希望怎样的线下活动？。。。。。。我感到筹备拆书帮没有方向。读到这个片段后，我开始尝试2分钟思考：用一句话来描述我对拆书帮的正面期望：分舵转正，我在分舵中继续成长。这样一下平衡了我的个人目标和组织目标。下一步行动是什么？召集线下活动，打造友好接纳的学习氛围。经过2分钟这样的思考，我完全轻松了，非常明确我的目标和我的行动方案。\r\n 在6月1日的线下活动时，我也有意识地去构建这种思维方式：为推动5-8人练级，我的下一步行动是定下3个人的30拆线下辅导，这样我在当时约好了小伙伴的时间，推动了这件事情的进展。 \r\nA2: 在生活和工作中有意识地培养和构建以结果和行为为导向的思考模式。\r\n1.每天早上6点，晚上9点在B5本子上写下大脑中的各种想法。\u003c清空大脑，让大脑做擅长的思考>\r\n2.用一句话描述希望的理想结果，也就是正面的期望。\u003c专注聚焦思考你的结果>\r\n3.为了推动事情的进展，你需要采取的下一步行动是什么？\u003c思考为实现这个目标，你要采取的下一步行动>\r\n4.找出了下一步行动，立刻执行“2分钟规则”模块，写出A2便签。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1465430061000,"updated_at":1465430061000,"ria":true}]};